try:
    from pypinyin import lazy_pinyin, Style
    def _generate_pinyin(text):
        """Generate full pinyin and first-letter initials for Chinese text."""
        try:
            full = ' '.join(lazy_pinyin(text, style=Style.NORMAL))
            first = ''.join(lazy_pinyin(text, style=Style.FIRST_LETTER))
            return full, first
        except Exception:
            return '', ''
except ImportError:
    def _generate_pinyin(text):
        return '', ''
