                    ("purchase_orders.extra_json", "ALTER TABLE purchase_orders ADD COLUMN extra_json TEXT DEFAULT ''"),
                    ("sale_orders.customer_po_no", "ALTER TABLE sale_orders ADD COLUMN customer_po_no TEXT DEFAULT ''"),
                    ("sale_orders.promise_date", "ALTER TABLE sale_orders ADD COLUMN promise_date TEXT DEFAULT ''"),
                    ("sale_orders.tax_rate", "ALTER TABLE sale_orders ADD COLUMN tax_rate REAL DEFAULT 0"),
                    ("sale_orders.tax_amount", "ALTER TABLE sale_orders ADD COLUMN tax_amount REAL DEFAULT 0"),
                    ("sale_order_items.batch_id", "ALTER TABLE sale_order_items ADD COLUMN batch_id INTEGER DEFAULT 0"),
                    ("inbound_orders", "CREATE TABLE IF NOT EXISTS inbound_orders (id INTEGER PRIMARY KEY AUTOINCREMENT, order_no TEXT NOT NULL UNIQUE, supplier_id INTEGER DEFAULT 0, warehouse_id INTEGER DEFAULT 1, status TEXT DEFAULT 'draft', remark TEXT DEFAULT '', created_at TEXT DEFAULT (datetime('now','localtime')), received_at TEXT DEFAULT '')"),
                    ("inbound_order_items", "CREATE TABLE IF NOT EXISTS inbound_order_items (id INTEGER PRIMARY KEY AUTOINCREMENT, inbound_id INTEGER DEFAULT 0, product_id INTEGER DEFAULT 0, quantity REAL DEFAULT 0, batch_no TEXT DEFAULT '', expiry_date TEXT DEFAULT '', cost REAL DEFAULT 0)"),
                    # v109: 报单映射本人仓强绑定 —— 员工↔个人仓（车销/访销随车仓）
                    ("hr_employees.warehouse_id", "ALTER TABLE hr_employees ADD COLUMN warehouse_id INTEGER DEFAULT 0"),
                    # v159b: 报单对象 → 取价渠道（绑定第二层，0 = 继承默认渠道）
                    ("report_mapping.channel_id", "ALTER TABLE report_mapping ADD COLUMN channel_id INTEGER DEFAULT 0"),
                    # v317: 报单主体轴 —— 报单人 = 员工 **或** 外部客户（见上方 _safe_migrate 的长注释）。
