def cash_overview():
    """资金概况（Hermes 工具入口）：各账户余额 + 今日收支 + 应收应付。"""
    from db.queries.finance import account_summary, cash_flow_list
    s = account_summary()
    recent = cash_flow_list(limit=20)
    lines = ["💵 资金概况："]
    for a in s.get("accounts", []):
        lines.append(f"{a.get('name','')}: {a.get('current_balance',0)}")
    lines.append(f"今日收入: {s.get('today_income',0)} / 今日支出: {s.get('today_expense',0)}")
    lines.append(f"应收未收: {s.get('total_ar',0)} / 应付未付: {s.get('total_ap',0)}")
    lines.append(f"最近流水: {len(recent.get('items',[]))} 条")
    return {"text": "\n".join(lines), "accounts": s.get("accounts", []),
            "today_income": s.get("today_income", 0), "today_expense": s.get("today_expense", 0),
            "total_ar": s.get("total_ar", 0), "total_ap": s.get("total_ap", 0)}


def receivable_overdue_list(days=0):
    """应收逾期清单（Hermes 工具入口）。"""
    with get_db() as db:
        sql = "SELECT * FROM receivables WHERE type='ar' AND status NOT IN ('paid','written_off')"
        params = []
        if days > 0:
            sql += " AND date(due_date) < date('now','localtime','-' || ? || ' days')"
            params.append(str(days))
        sql += " ORDER BY due_date ASC LIMIT 50"
        rows = [dict(r) for r in db.execute(sql, params).fetchall()]
        for r in rows:
            try:
                c = db.execute("SELECT name FROM contacts WHERE id=?", (r["contact_id"],)).fetchone()
                r["contact_name"] = c["name"] if c else f"客户{r['contact_id']}"
            except Exception:
                r["contact_name"] = ""
            r["due_amount"] = round((r.get("amount") or 0) - (r.get("paid_amount") or 0), 2)
        return {"items": rows, "total": len(rows)}
def report_trend(days=7):
    """返回最近N天的收入/支出趋势数据"""
    days = int(days)  # v90: enforce integer to prevent injection
    with get_db() as db:
        result = {"labels":[], "income":[], "expense":[]}
        for i in range(days-1, -1, -1):
            label = db.execute("SELECT strftime('%m/%d',date('now','localtime','-' || ? || ' days'))",(str(i),)).fetchone()[0]
            inc = db.execute("SELECT COALESCE(SUM(amount),0) FROM cash_flow WHERE type='income' AND date(created_at)=date('now','localtime','-' || ? || ' days')",(str(i),)).fetchone()[0]
            exp = db.execute("SELECT COALESCE(SUM(amount),0) FROM cash_flow WHERE type='expense' AND date(created_at)=date('now','localtime','-' || ? || ' days')",(str(i),)).fetchone()[0]
            result["labels"].append(label)
            result["income"].append(float(inc))
            result["expense"].append(float(exp))
        return result

def report_sales_summary(date_from='', date_to='', salesperson=''):
    with get_db() as db:
        where,params = ["so.status!='cancelled'"],[]
        if date_from: where.append("so.order_date>=?"); params.append(date_from)
        if date_to: where.append("so.order_date<=?"); params.append(date_to)
        if salesperson: where.append("so.operator_id=?"); params.append(salesperson)
        w = " WHERE "+" AND ".join(where) if where else ""
        r = db.execute(f"""
            SELECT COUNT(*) as count, COALESCE(SUM(total_amount),0) as total_amount, COALESCE(SUM(received_amount),0) as total_received,
                   COALESCE(SUM(discount),0) as total_discount
            FROM sale_orders so{w}
        """,params).fetchone()
        return dict(r) if r else {}

