def get_daily_report():
    today = datetime.now().strftime("%Y-%m-%d")
    with get_db() as db:
        income = db.execute("SELECT COALESCE(SUM(amount),0) FROM cash_flow WHERE type='income' AND date(created_at)=?",(today,)).fetchone()[0]
        expense = db.execute("SELECT COALESCE(SUM(amount),0) FROM cash_flow WHERE type='expense' AND date(created_at)=?",(today,)).fetchone()[0]
        sales = db.execute("SELECT COALESCE(SUM(total_amount),0),COUNT(*) FROM sale_orders WHERE date(order_date)=?",(today,)).fetchone()
        payments = db.execute("SELECT COALESCE(SUM(amount),0),COUNT(*) FROM cash_flow WHERE type='income' AND date(created_at)=?",(today,)).fetchone()
        new_cust = db.execute("SELECT COUNT(*) FROM contacts WHERE type='customer' AND date(created_at)=?",(today,)).fetchone()[0]
        low_stock = db.execute("SELECT COUNT(*) FROM inventory i JOIN products p ON i.product_id=p.id WHERE i.quantity<=p.safety_stock AND p.safety_stock>0").fetchone()[0]
        pending = db.execute("SELECT COUNT(*) FROM sale_orders WHERE approval_status='pending'").fetchone()[0]
        expired = db.execute("SELECT COUNT(*) FROM inventory WHERE expiry_date!='' AND date(expiry_date)<=date('now') AND quantity>0").fetchone()[0]
        return {'today':today,'income':income,'expense':expense,'sales_total':sales[0],'sales_count':sales[1],'payments_total':payments[0],'payments_count':payments[1],'new_customers':new_cust,'low_stock':low_stock,'pending_approval':pending,'expired_stock':expired}

