def get_inventory_with_expiry(limit=100, offset=0, keyword='', low_stock=False):
    with get_db() as db:
        where,params = [],[]
        if keyword: where.append("p.name LIKE ?"); params.append(f"%{keyword}%")
        if low_stock: where.append("i.quantity<=p.safety_stock AND p.safety_stock>0")
        w = " WHERE "+" AND ".join(where) if where else ""
        rows = db.execute(f"SELECT i.*,p.name,p.spec,p.brand,p.category,p.purchase_price,p.sale_price,p.safety_stock FROM inventory i JOIN products p ON i.product_id=p.id{w} ORDER BY i.expiry_date ASC LIMIT ? OFFSET ?",params+[limit,offset]).fetchall()
        total = db.execute(f"SELECT COUNT(*) FROM inventory i JOIN products p ON i.product_id=p.id{w}",params).fetchone()[0]
        return {'items':[dict(r) for r in rows],'total':total}

