def get_statement(contact_id, year_month=''):
    if not year_month:
        year_month = datetime.now().strftime("%Y-%m")
    start = year_month + "-01"
    # end of month
    import calendar
    y,m = int(year_month[:4]), int(year_month[5:7])
    end = year_month + "-" + str(calendar.monthrange(y,m)[1])
    with get_db() as db:
        orders = [dict(r) for r in db.execute("SELECT * FROM sale_orders WHERE customer_id=? AND order_date>=? AND order_date<=? ORDER BY order_date",
                                               (contact_id,start,end)).fetchall()]
        payments = [dict(r) for r in db.execute("SELECT * FROM cash_flow WHERE contact_id=? AND created_at>=? AND created_at<=? ORDER BY created_at",
                                                 (contact_id,start,end)).fetchall()]
        opening_ar = db.execute("SELECT COALESCE(SUM(amount-paid_amount),0) FROM receivables WHERE contact_id=? AND type='ar' AND created_at<?",(contact_id,start)).fetchone()[0]
        total_sales = sum(o['total_amount'] for o in orders)
        total_received = sum(p['amount'] for p in payments if p['type']=='income')
        closing_ar = opening_ar + total_sales - total_received
        return {'year_month':year_month,'orders':orders,'payments':payments,'opening_ar':opening_ar,'total_sales':total_sales,'total_received':total_received,'closing_ar':closing_ar}

def get_salesperson_report():
	"""员工业绩排行 —— v168 起改走唯一实现 sales_operator_stats()。
	（旧实现：名单读租户库陈旧 users + `operator_id=CAST(users.id AS TEXT)` → 恒全 0）
	对旧契约保持兼容：name / total_sales / order_count / received / customer_count / recovery_rate。"""
	rows = sales_operator_stats()
	results = []
	for r in rows:
		sales = r['sales']
		received = r['order_received']
		results.append({
			'name': r['name'],
			'total_sales': sales,
			'order_count': r['orders'],
			'received': received,
			'customer_count': r['customers'],
			'recovery_rate': round(received/sales*100, 1) if sales > 0 else 0,
			# v168 新增（旧前端忽略；新调用方据此区分「未绑定账号」「未填写经手人」）
			'bound': r['bound'],
			'account_username': r['username'],
			'account_id': r['uid'],
			'role': r['role'],
			'account_active': bool(r['is_active']),
			'cash_income': r['cash_income'],
		})
	return results

def get_profit_report():
    """商品维度毛利报表 —— Dashboard 三张毛利图（品牌/商品/品类）读它。

    🔴 v497 修正两处口径缺陷（此前被「purchase_price 恒 0」掩盖，v494 补价后立刻现形）：
      ① **status 过滤空转**（真 bug）：原写法
         `LEFT JOIN sale_orders so ON soi.order_id=so.id AND so.status IN ('delivered','signed')`
         —— `so.*` 一列都没 select，这个 JOIN **只放大行数、不过滤任何东西**
         ⇒ draft / cancelled 单的销量也混进 sold_qty。
         ⇒ 改**子查询**：先按 `so.status` 过滤，再按商品聚合。
      ② **收入用目录价、不是实际成交价**：原 `revenue = sold_qty × p.sale_price`
         —— `sale_price` 是商品档案的**标准售价（目录价）**，不是这单的真实成交价。
         实测生产：目录价口径收入 ¥802 万 vs 实际成交 ¥879 万（差约 9%，因为相当一部分
         单是折价成交的）。⇒ 改 `SUM(soi.amount)`（明细实际成交金额）。

    ⚠️ 收入/成本**故意不对齐到「活跃客户」口径**（`get_customer_profitability` 那样）：
       本函数是**商品维度全量**统计，包含 251 张零金额出库单（赠品 / 内部领用）的成本
       ¥51.8 万 —— 那批单有货出去（有成本）但没收款（金额 0），是本函数**应当**体现的
       真实成本。客户利润表只统计 `contacts` 里的活跃客户，两者的 ¥51.8 万之差是
       **维度差异、不是缺陷**；强行对齐会掩盖赠品成本或破坏客户表语义，故不动。
    """
    with get_db() as db:
        prods = [dict(r) for r in db.execute("""
            SELECT p.id, p.name, p.brand, p.category, p.sale_price, p.purchase_price,
                   COALESCE(s.sold_qty,0) as sold_qty,
                   COALESCE(s.sold_amt,0) as sold_amt
            FROM products p
            LEFT JOIN (
                SELECT soi.product_id AS pid,
                       SUM(soi.quantity) AS sold_qty,
                       SUM(soi.amount)   AS sold_amt
                FROM sale_order_items soi
                JOIN sale_orders so ON soi.order_id = so.id
                WHERE so.status IN ('delivered','signed')
                GROUP BY soi.product_id
            ) s ON s.pid = p.id
            WHERE p.is_active=1
            GROUP BY p.id
        """).fetchall()]
        for p in prods:
            sold = p.pop('sold_qty')
            amt = p.pop('sold_amt')
            p['revenue'] = amt                      # 实际成交金额（非「目录价 × 销量」）
            p['cost'] = sold * p['purchase_price']  # 净销量 × 进价（退货负数量自然扣减）
            p['profit'] = p['revenue'] - p['cost']
            p['margin'] = round(p['profit']/p['revenue']*100,1) if p['revenue']>0 else 0
        # Breakdown by brand
        by_brand = {}
        for p in prods:
            b = p.get('brand','') or '未分类'
            if b not in by_brand: by_brand[b] = {'brand':b,'revenue':0,'cost':0,'profit':0,'count':0}
            by_brand[b]['revenue'] += p['revenue']; by_brand[b]['cost'] += p['cost']; by_brand[b]['profit'] += p['profit']; by_brand[b]['count'] += 1
        for b in by_brand.values(): b['margin'] = round(b['profit']/b['revenue']*100,1) if b['revenue']>0 else 0
        # Breakdown by category
        by_cat = {}
        for p in prods:
            c = p.get('category','') or '未分类'
            if c not in by_cat: by_cat[c] = {'category':c,'revenue':0,'cost':0,'profit':0,'count':0}
            by_cat[c]['revenue'] += p['revenue']; by_cat[c]['cost'] += p['cost']; by_cat[c]['profit'] += p['profit']; by_cat[c]['count'] += 1
        for c in by_cat.values(): c['margin'] = round(c['profit']/c['revenue']*100,1) if c['revenue']>0 else 0
        return {
            'products': sorted(prods, key=lambda x: x['profit'], reverse=True),
            'by_brand': sorted(by_brand.values(), key=lambda x: x['profit'], reverse=True),
            'by_category': sorted(by_cat.values(), key=lambda x: x['profit'], reverse=True),
            'total_revenue': sum(p['revenue'] for p in prods),
            'total_cost': sum(p['cost'] for p in prods),
            'total_profit': sum(p['profit'] for p in prods)
        }

