def get_bundles():
    with get_db() as db:
        bundles = [dict(r) for r in db.execute("SELECT * FROM bundles WHERE is_active=1").fetchall()]
        if not bundles:
            return []
        bundle_ids = [b['id'] for b in bundles]
        placeholders = ','.join('?' for _ in bundle_ids)
        all_items = db.execute(
            f"SELECT bi.*,p.name,p.sale_price FROM bundle_items bi JOIN products p ON bi.product_id=p.id WHERE bi.bundle_id IN ({placeholders})",
            bundle_ids
        ).fetchall()
        items_by_bundle = {}
        for it in all_items:
            it = dict(it)
            items_by_bundle.setdefault(it['bundle_id'], []).append(it)
        for b in bundles:
            b['items'] = items_by_bundle.get(b['id'], [])
