def get_supplier_prices(product_name=''):
    with get_db() as db:
        if product_name:
            prods = [dict(r) for r in db.execute("SELECT id,name FROM products WHERE name LIKE ? AND is_active=1",(f"%{product_name}%",)).fetchall()]
        else:
            prods = [dict(r) for r in db.execute("SELECT id,name FROM products WHERE is_active=1").fetchall()]
        if not prods:
            return []
        prod_ids = [p['id'] for p in prods]
        placeholders = ','.join('?' for _ in prod_ids)
        rows = db.execute(
            f"SELECT poi.product_id, po.supplier_id, c.name as supplier_name, MIN(poi.unit_price) as best_price, AVG(poi.unit_price) as avg_price FROM purchase_order_items poi JOIN purchase_orders po ON poi.order_id=po.id JOIN contacts c ON po.supplier_id=c.id WHERE poi.product_id IN ({placeholders}) AND po.status='confirmed' GROUP BY poi.product_id, po.supplier_id ORDER BY best_price",
            prod_ids
        ).fetchall()
        supp_by_prod = {}
        for r in rows:
            r = dict(r)
            supp_by_prod.setdefault(r['product_id'], []).append(r)
        result = []
        for p in prods:
            if p['id'] in supp_by_prod:
                result.append({'product_id': p['id'], 'name': p['name'], 'suppliers': supp_by_prod[p['id']]})
        return result

def get_purchase_suggestions():
    with get_db() as db:
        prods = [dict(r) for r in db.execute("""
            SELECT p.*, COALESCE(SUM(i.quantity),0) as stock,
                   COALESCE(s30.recent_qty, 0) as daily_avg
            FROM products p
            LEFT JOIN inventory i ON p.id = i.product_id
            LEFT JOIN (
                SELECT soi.product_id, SUM(soi.quantity)*1.0/30 as recent_qty
                FROM sale_order_items soi
                JOIN sale_orders so ON soi.order_id = so.id
                WHERE so.order_date >= date('now','-30 days')
                GROUP BY soi.product_id
            ) s30 ON p.id = s30.product_id
            WHERE p.is_active=1 AND p.safety_stock>0
            GROUP BY p.id
            HAVING stock < p.safety_stock OR stock < p.safety_stock*3
        """).fetchall()]
        suggestions = []
        for pd in prods:
            suggest_qty = max(0, round((pd['safety_stock'] - pd['stock']) + pd['daily_avg'] * 7))
            if suggest_qty > 0:
                pd['daily_avg'] = round(pd['daily_avg'], 1)
                pd['suggest_qty'] = suggest_qty
                pd['stock'] = int(pd['stock'])
                suggestions.append(pd)
        return sorted(suggestions, key=lambda x: x['suggest_qty'], reverse=True)

