# ============================================================
# v288（2026-09-27）：改登录账号名（users.username）—— **唯一实现**
# ------------------------------------------------------------
# 为什么必须只有一份：账号名有两个写入口 ——
#   ① 本人自助：`PUT /api/auth/profile`（routers/auth.py）
#   ② 老板代改：`PUT /api/users/{uid}/username`（server.py，v288 新增）
# 两处都调本函数，避免「同一动作两份实现」各带一半副作用（下面 3 条副作用最易漏）。
#
# 🔴 库的判据（本轮实测，别靠推理）：
#   `users` 是**主库全局表**。`/api/users` 与 `/api/auth` 都在 `_TENANT_MASTER_PREFIXES`
#   / `_TENANT_PUBLIC_PREFIXES` 里 ⇒ 两个入口请求期间 `set_tenant_context(None)` ⇒
#   `db.get_db()` 走主库。但**不能依赖调用方**始终满足这个前提（后台任务/调度器就在
#   租户上下文里）⇒ 本函数**显式用 `_master_db()`**，与 `staff_account_create` 同一条路。
#   （实测对照：主库 users 8 行=真实账号；tenant_1.db 也有一份 users 6 行=另一批种子
#     数据。读写一旦分家就是「改了不生效」的静默失效，所以这里必须写死主库。）
#
# 改名要跟着动的三处（漏任一条都是"看起来对、其实留了半截"）：
#   ① `phone` —— `staff_account_create` 会写 `phone=username`。**仅当 phone 与旧账号名
#      逐字相同**（说明它只是拷贝、不是真实手机号）才跟随；是真实手机号则**不动**。
#   ② `password_reset_codes.username` —— 一次性重置码是**按 `username COLLATE NOCASE`
#      查的**（password_reset.py）。已发出、还没用的码若不同步，员工拿码自助改密会
#      报「用户名或重置码不对」。码是发给"这个人"的，改个名不该让它作废 ⇒ 同步。
#   ③ 审计 —— 记「旧名 → 新名」。原 profile 只写「修改个人资料」，查不出改了哪个字段。
#
# **不动**的（历史事实，改了才是篡改）：
#   `login_logs` / `login_attempts` / `audit_logs` / `mp_events` 里的 username 一律保留 ——
#   它们记的是"当时用哪个账号登录的"。
# ============================================================
def _open_master():
	"""显式打开主库连接（users / user_tenants / sessions 等全局表的权威连接）。"""
	from core import _master_db
	return _master_db()


def _conn_is_master(conn):
	"""这个连接指向主库吗？（`users` 是主库表 —— 写错库=改完读不到，必须能判）"""
	try:
		rows = {r[1]: r[2] for r in conn.execute("PRAGMA database_list")}
	except Exception:
		return False
	main = rows.get("main") or ""
	if not main:
		return False
	try:
		# 🔴 必须用 realpath 而不是 abspath：SQLite 的 `PRAGMA database_list` 回的是
		# **解析过符号链接**的路径（实测 macOS：传 /var/... 收到 /private/var/...），
		# abspath 不解析 symlink ⇒ 同一文件判成"不是主库"，改动会被静默挪到另一条连接。
		return os.path.realpath(main) == os.path.realpath(DB_PATH)
	except Exception:
		return False


def user_rename(uid, new_username, actor="", conn=None):
	"""把 user id=`uid` 的登录账号改成 `new_username`。返回 dict。

	`conn` 可选：不传（默认）自己开**主库**连接并提交；传了则复用调用方的事务 ——
	但会先断言它确实指向主库，不是主库就改用自己的连接（宁可多开一条，也不要把
	改动写进租户库那份 `users` 副本）。

	返回形状：{success, changed, uid, old, new, phone_synced, codes_synced}
	失败：{success: False, detail: "..."}（调用方据此回 400，不抛异常 —— 与
	`staff_account_create` 的既有约定一致）。
	"""
	import sqlite3 as _sqlite3
	from core import validate_username, USERNAME_IMMUTABLE
	uid = int(uid or 0)
	nu = (new_username or "").strip()
	if uid <= 0:
		return {"success": False, "detail": "缺少用户 id"}
	ok, msg = validate_username(nu)
	if not ok:
		return {"success": False, "detail": msg}
	own = None
	if conn is None or not _conn_is_master(conn):
		own = _open_master()
		conn = own
	try:
		cur = conn.execute("SELECT id, username, phone FROM users WHERE id=?", (uid,)).fetchone()
		if not cur:
			return {"success": False, "detail": "账号不存在"}
		old = str(cur["username"] or "")
		if old == nu:
			# 同名 = 空操作。**不报错** —— 前端"点开看一眼又点保存"不该被当成失败。
			return {"success": True, "changed": False, "uid": uid, "old": old, "new": nu,
			        "phone_synced": False, "codes_synced": 0}
		# 🔴 目标账号**本身**就叫 admin ⇒ 一律拒。
		#    `validate_username` 只拦得住「把别人改成 admin」，拦不住「把 admin 改成别的」——
		#    而后者同样会触发 core 的启动初始化：`SELECT id FROM users WHERE username='admin'`
		#    查不到 ⇒ **重启后凭空建一个随机密码的管理员**（密码只打进日志、谁也不知道）。
		#    单测 C13 实测就是这一条：admin→admin2 之后，users 里再无 'admin' 行。
		if old.lower() in USERNAME_IMMUTABLE:
			return {"success": False,
			        "detail": "「%s」是系统内置账号，不可修改" % old}
		# 唯一性：用 COLLATE NOCASE。
		# 🔴 为什么不是精确匹配：一次性重置码那条路是 `username = ? COLLATE NOCASE` ——
		# 若允许 `LiuShantao` 与 `liushantao` 并存，老板用大写名发码、员工敲小写名，
		# 会命中**另一个人**。所以按不区分大小写判重（现网账号名全小写，零误伤）。
		dup = conn.execute(
			"SELECT id FROM users WHERE username = ? COLLATE NOCASE AND id != ?", (nu, uid)
		).fetchone()
		if dup:
			return {"success": False, "detail": "该登录账号已被占用，请换一个"}
		conn.execute("UPDATE users SET username=? WHERE id=?", (nu, uid))
		# ① phone 跟随（仅当它只是旧账号名的拷贝）
		phone_synced = False
		if str(cur["phone"] or "").strip() == old:
			conn.execute("UPDATE users SET phone=? WHERE id=?", (nu, uid))
			phone_synced = True
		# ② 未用完的一次性重置码跟着走
		codes_synced = 0
		try:
			if conn.execute(
				"SELECT 1 FROM sqlite_master WHERE type='table' AND name='password_reset_codes'"
			).fetchone():
				c = conn.execute(
					"UPDATE password_reset_codes SET username=? "
					"WHERE user_id=? AND (used_at IS NULL OR used_at='')",
					(nu, uid))
				codes_synced = int(c.rowcount or 0)
		except _sqlite3.Error as e:
			# 码表不同步属于**次要**副作用，不能连累改名本身；但要留痕，不能静默。
			logging.getLogger("hergent").warning(
				"[user_rename] uid=%s 重置码同步失败（改名已生效）: %s", uid, e)
		# 自开连接 ⇒ 自己收尾（提交+关闭）；复用调用方连接 ⇒ 两者都交给它 ——
		# 调用方（`PUT /api/auth/profile`）仍在自己的 `with` 事务里，随后统一 commit，
		# 这样"改显示名 + 改账号名"要么一起成功、要么一起回滚（保持原实现的原子性）。
		if own is not None:
			conn.commit()
	finally:
		if own is not None:
			conn.close()
	return {"success": True, "changed": True, "uid": uid, "old": old, "new": nu,
	        "phone_synced": phone_synced, "codes_synced": codes_synced}


