def get_expiring_soon(days=30):
    days = int(days)  # v90: prevent SQL injection — enforce integer
    with get_db() as db:
        rows = db.execute("SELECT i.*,p.name,p.spec FROM inventory i JOIN products p ON i.product_id=p.id WHERE i.expiry_date!='' AND i.quantity>0 AND date(i.expiry_date)<=date('now','+' || ? || ' days') AND date(i.expiry_date)>=date('now') ORDER BY i.expiry_date LIMIT 20",(str(days),)).fetchall()
        return [dict(r) for r in rows]

