def get_budget_vs_actual(month=''):
    if not month: month = datetime.now().strftime("%Y-%m")
    with get_db() as db:
        budgets = db.execute("SELECT * FROM expense_budgets WHERE month=?",(month,)).fetchall()
        result = []
        for b in budgets:
            bd = dict(b)
            actual = db.execute("SELECT COALESCE(SUM(eo.amount),0) FROM expense_orders eo JOIN expense_categories ec ON eo.category_id=ec.id WHERE ec.name=? AND substr(eo.order_date,1,7)=?",(bd['category_name'],month)).fetchone()[0]
            bd['actual'] = actual
            bd['usage_pct'] = round(actual/bd['amount']*100,1) if bd['amount']>0 else 0
            result.append(bd)
        return result

