def calculate_commissions(month=''):
	"""业务员提成 —— v168 起改走唯一实现 sales_operator_stats()。
	（旧实现：名单读租户库陈旧 users + `operator_id=str(users.id)` → 恒全 0）
	契约不变：name / sales / rate_pct / fixed / commission。"""
	if not month: month = datetime.now().strftime("%Y-%m")
	rules = get_commission_rules()
	results = []
	for r in sales_operator_stats(month=month):
		sales = r['sales']
		applicable = [x for x in rules if sales >= (x['min_sales'] or 0)]
		best = max(applicable, key=lambda x: (x['rate_pct'] or 0)*sales + (x['fixed_amount'] or 0)) if applicable else None
		commission = sales*(best['rate_pct'] or 0)/100 + (best['fixed_amount'] or 0) if best else 0
		results.append({'name': r['name'], 'sales': sales,
		                'rate_pct': best['rate_pct'] if best else 0,
		                'fixed': best['fixed_amount'] if best else 0,
		                'commission': round(commission, 2),
		                # v168 新增（旧前端忽略）
		                'bound': r['bound'], 'account_id': r['uid'], 'rule': best['name'] if best else ''})
	return sorted(results, key=lambda x: x['commission'], reverse=True)

