def trace_batch(batch_no):
    with get_db() as db:
        inv = [dict(r) for r in db.execute("SELECT i.*,p.name,p.spec FROM inventory i JOIN products p ON i.product_id=p.id WHERE i.batch_no=? AND (i.quantity>0 OR i.id IN (SELECT DISTINCT ref_id FROM inventory_logs WHERE product_id=i.product_id))",(batch_no,)).fetchall()]
        if not inv: return None
        traces = []
        for i in inv:
            pid = i['product_id']; wid = i['warehouse_id']
            in_logs = [dict(r) for r in db.execute("SELECT il.*,po.order_no FROM inventory_logs il LEFT JOIN purchase_orders po ON il.ref_id=po.id WHERE il.product_id=? AND il.ref_type='purchase' AND il.warehouse_id=? ORDER BY il.created_at",(pid,wid)).fetchall()]
            out_logs = [dict(r) for r in db.execute("SELECT il.*,so.order_no,c.name as customer_name FROM inventory_logs il LEFT JOIN sale_orders so ON il.ref_id=so.id LEFT JOIN contacts c ON so.customer_id=c.id WHERE il.product_id=? AND il.ref_type='sale' AND il.warehouse_id=? ORDER BY il.created_at",(pid,wid)).fetchall()]
            traces.append({'product':i,'in':in_logs,'out':out_logs})
        return {'batch_no':batch_no,'items':inv,'traces':traces}

def get_demand_forecast(days=90):
    with get_db() as db:
        rows = db.execute(f"SELECT soi.product_id,p.name,date(so.order_date) as day,SUM(soi.quantity) as qty FROM sale_order_items soi JOIN sale_orders so ON soi.order_id=so.id JOIN products p ON soi.product_id=p.id WHERE so.order_date>=date('now','-{days} days') AND so.status IN ('delivered','signed') GROUP BY soi.product_id,date(so.order_date) ORDER BY day").fetchall()
        data = {}
        for r in rows:
            rd = dict(r); pid = rd['product_id']
            if pid not in data: data[pid] = {'name':rd['name'],'daily':[],'total':0,'avg30':0,'forecast':0}
            data[pid]['daily'].append({'day':rd['day'],'qty':rd['qty']})
            data[pid]['total'] += rd['qty']
        for pid in data:
            d = data[pid]; recent = [x['qty'] for x in d['daily'][-30:]]
            d['avg30'] = round(sum(recent)/30,1) if recent else 0
            d['forecast'] = round(d['avg30']*1.1*30)
            d['trend'] = 'up' if len(recent)>=14 and sum(recent[-14:])>sum(recent[:14]) else 'down' if len(recent)>=14 else 'stable'
        return list(data.values())

def get_mrp_suggestions():
    with get_db() as db:
        prods = db.execute("SELECT p.*,COALESCE(SUM(i.quantity),0) as stock FROM products p LEFT JOIN inventory i ON p.id=i.product_id WHERE p.is_active=1 AND p.safety_stock>0 GROUP BY p.id").fetchall()
        suggestions = []
        for p in prods:
            pd = dict(p)
            recent = db.execute("SELECT COALESCE(AVG(qty),0) FROM (SELECT SUM(soi.quantity) as qty FROM sale_order_items soi JOIN sale_orders so ON soi.order_id=so.id WHERE soi.product_id=? AND so.order_date>=date('now','-30 days') AND so.status IN ('delivered','signed') GROUP BY date(so.order_date))",(pd['id'],)).fetchone()[0]
            daily_avg = round(recent,1); lead_time = 7
            reorder_point = daily_avg * lead_time + pd['safety_stock']
            if pd['stock'] < reorder_point and daily_avg > 0:
                pd['daily_avg'] = daily_avg; pd['reorder_point'] = round(reorder_point); pd['suggest_qty'] = round(reorder_point - pd['stock'] + daily_avg * lead_time); pd['stock'] = int(pd['stock'])
                suggestions.append(pd)
        return sorted(suggestions, key=lambda x: x['suggest_qty'], reverse=True)

# === v87: Advanced Demand Forecasting — exponential smoothing, Holt-Winters, promotion uplift ===

def exp_smoothing(series, alpha=0.3):
    """Single exponential smoothing. Returns forecast array + next-period forecast."""
    if not series: return {"forecast": [], "next": 0, "alpha": alpha}
    level = series[0]
    forecast = [level]
    for i in range(1, len(series)):
        level = alpha * series[i] + (1 - alpha) * level
        forecast.append(level)
    next_val = forecast[-1]
    return {"forecast": forecast, "next": round(next_val, 2), "alpha": alpha, "method": "SES", "series_name": ""}

def double_exp_smoothing(series, alpha=0.3, beta=0.1):
    """Double exponential smoothing (Holt's linear trend)."""
    if len(series) < 2:
        return {"forecast": [], "next": series[0] if series else 0, "trend": [], "method": "Holt", "error": "需要至少2个数据点"}
    level = series[0]
    trend = series[1] - series[0]
    forecast = [level]
    trends = [trend]
    for i in range(1, len(series)):
        prev_level = level
        level = alpha * series[i] + (1 - alpha) * (level + trend)
        trend = beta * (level - prev_level) + (1 - beta) * trend
        forecast.append(level)
        trends.append(trend)
    next_val = level + trend
    return {"forecast": forecast, "trend_list": trends, "next": round(max(0, next_val), 2),
            "level": round(level, 2), "trend": round(trend, 2),
            "alpha": alpha, "beta": beta, "method": "Holt"}

def holt_winters(series, period=12, alpha=0.3, beta=0.1, gamma=0.1, seasonal_type="additive", forecast_periods=3):
    """Holt-Winters triple exponential smoothing with trend and seasonality.
    period: number of observations per seasonal cycle (12=monthly, 7=weekly, 4=quarterly)
    Returns: {forecast, level, trend, seasonal, next_values, method, mape}"""
    if len(series) < period + 2:
        return {"forecast": [], "next": [], "method": "Holt-Winters", "error": f"需要至少 {period+2} 个数据点，当前只有 {len(series)} 个"}

    # Initialize level, trend, seasonal
    level = sum(series[:period]) / period
    trend = (sum(series[period:2*period]) - sum(series[:period])) / (period * period) if len(series) >= 2*period else 0

    if seasonal_type == "multiplicative":
        seasonal = [series[i] / level if level != 0 else 1.0 for i in range(period)]
    else:
        seasonal = [series[i] - level for i in range(period)]

    # Train
    forecast = []
    for t in range(len(series)):
        s_idx = t % period
        if seasonal_type == "multiplicative":
            fc = (level + trend) * seasonal[s_idx]
            if t < len(series) - 1:
                new_level = alpha * (series[t] / seasonal[s_idx]) + (1 - alpha) * (level + trend)
            else:
                new_level = level
        else:
            fc = level + trend + seasonal[s_idx]
            if t < len(series) - 1:
                new_level = alpha * (series[t] - seasonal[s_idx]) + (1 - alpha) * (level + trend)
            else:
                new_level = level

        forecast.append(round(fc, 2))

        if t < len(series) - 1:
            if seasonal_type == "multiplicative" and level != 0:
                seasonal[s_idx] = gamma * (series[t] / new_level) + (1 - gamma) * seasonal[s_idx]
            else:
                seasonal[s_idx] = gamma * (series[t] - new_level) + (1 - gamma) * seasonal[s_idx]
            new_trend = beta * (new_level - level) + (1 - beta) * trend
            level = new_level
            trend = new_trend if new_trend is not None else 0

    # Forecast next periods
    next_values = []
    current_level = level
    current_trend = trend
    for i in range(forecast_periods):
        s_idx = (len(series) + i) % period
        if seasonal_type == "multiplicative":
            next_val = (current_level + current_trend * (i+1)) * seasonal[s_idx]
        else:
            next_val = current_level + current_trend * (i+1) + seasonal[s_idx]
        next_values.append(round(max(0, next_val), 2))

    # Calculate MAPE (Mean Absolute Percentage Error)
    errors = []
    for i in range(len(series)):
        if series[i] > 0:
            errors.append(abs(forecast[i] - series[i]) / series[i] * 100)
    mape = round(sum(errors) / len(errors), 1) if errors else 0

    return {"forecast": forecast, "next_values": next_values,
            "level": round(level, 2), "trend": round(trend, 2),
            "seasonal": [round(s, 2) for s in seasonal],
            "period": period, "seasonal_type": seasonal_type,
            "alpha": alpha, "beta": beta, "gamma": gamma,
            "mape_pct": mape, "method": "Holt-Winters"}

def demand_forecast_advanced(product_id=0, days_history=365, forecast_periods=30, method="auto"):
    """Advanced demand forecasting with best-fit method selection.
    Returns daily-level forecast for the next N periods with accuracy metrics."""
    with get_db() as db:
        w = "WHERE soi.product_id=?" if product_id else ""
        params = [product_id, days_history] if product_id else [days_history]
        rows = db.execute(
            f"SELECT date(so.order_date) as day, SUM(soi.quantity) as qty "
            f"FROM sale_order_items soi JOIN sale_orders so ON soi.order_id=so.id "
            f"WHERE so.order_date>=date('now','-{days_history} days') AND so.status IN ('delivered','signed') "
            f"{'AND soi.product_id=?' if product_id else ''} "
            f"GROUP BY date(so.order_date) ORDER BY day",
            params
        ).fetchall()

    if not rows:
        return {"error": "无历史销售数据"}

    series = [r["qty"] for r in rows]
    dates = [r["day"] for r in rows]

    # Auto-select best method by comparing MAPE
    results = {}

    # SES
    ses = exp_smoothing(series, 0.3)
    results["ses"] = ses

    # Holt (double)
    if len(series) >= 2:
        holt = double_exp_smoothing(series, 0.3, 0.1)
        results["holt"] = holt

    # Holt-Winters with period detection
    if len(series) >= 14:
        hw7 = holt_winters(series, period=7, alpha=0.3, beta=0.1, gamma=0.1, forecast_periods=forecast_periods)
        results["hw7"] = hw7
    if len(series) >= 30:
        hw30 = holt_winters(series, period=30, alpha=0.3, beta=0.1, gamma=0.1, forecast_periods=forecast_periods)
        results["hw30"] = hw30

    # Simple moving average (existing, for comparison)
    if len(series) >= 30:
        avg30 = sum(series[-30:]) / 30
        sma_next = [round(avg30 * 1.1)] * min(3, forecast_periods)
    else:
        sma_next = [round(sum(series)/len(series) * 1.1)] * min(3, forecast_periods)

    # Select best method
    best_method = "ses"
    best_mape = 999
    if method == "auto":
        for name, result in results.items():
            mape = result.get("mape_pct", 999)
            if mape < best_mape:
                best_mape = mape
                best_method = name
    else:
        best_method = method

    best = results.get(best_method, ses)
    next_vals = best.get("next_values", [best.get("next", 0)])

    # Apply promotion uplift if applicable
    uplift_factor = _calculate_promotion_uplift(product_id) if product_id else 1.0
    if uplift_factor > 1.0:
        next_vals = [round(v * uplift_factor, 2) for v in next_vals]

    return {
        "product_id": product_id, "history_days": len(series),
        "dates": dates[-30:], "series": series[-30:],
        "best_method": best_method,
        "methods_tested": list(results.keys()),
        "forecast": next_vals[:forecast_periods],
        "forecast_total": round(sum(next_vals[:forecast_periods]), 2),
        "mape_pct": best.get("mape_pct", 0),
        "uplift_factor": uplift_factor,
        "params": {"alpha": best.get("alpha", 0.3), "beta": best.get("beta", 0.1), "gamma": best.get("gamma", 0.1)},
        "accuracy": "excellent" if best.get("mape_pct", 100) < 10 else ("good" if best.get("mape_pct", 100) < 20 else ("fair" if best.get("mape_pct", 100) < 50 else "poor"))
    }

def _calculate_promotion_uplift(product_id):
    """Calculate expected uplift factor based on active promotions for a product.

    🔴 v254 修复（2026-09-23 实测）：**当前 schema 的 `promotions` 表没有 `product_id` 列**
    （主库 DDL + 全部租户库实测皆无）⇒ 原实现的按商品查促销**每次必然抛
    `no such column: product_id`**，被 except 吞掉、恒返回 1.0，并且**每次调用刷一条
    WARNING**（生产日志实证）—— 商品级促销提升系数实际从未生效，属「静默失效」。
    本次不改业务数值（仍然返回 1.0，避免悄悄改变预报建议量），只做两件事：
      ① 用 PRAGMA 先判列是否存在，避免对**已知的 schema 事实**反复告警（刷屏会训练人忽略告警）；
      ② 保留原逻辑分支 —— 将来补上 `product_id` 列即自动生效，无需再改代码。
    是否要支持「商品级促销」属产品决策（见上线报告 P2）。
    """
    with get_db() as db:
        try:
            try:
                _cols = {r[1] for r in db.execute("PRAGMA table_info(promotions)").fetchall()}
            except Exception:
                _cols = set()
            if "product_id" not in _cols:
                logging.getLogger("hergent").debug(
                    "promotion uplift: promotions.product_id 不存在（当前 schema 不支持商品级促销），按 1.0 处理")
                return 1.0
            # Check if product has active promotions
            promos = db.execute(
                "SELECT discount_pct, promo_type FROM promotions WHERE is_active=1 AND product_id=?",
                (product_id,)
            ).fetchall()
            if not promos:
                # Check global promotions
                promos = db.execute(
                    "SELECT discount_pct, promo_type FROM promotions WHERE is_active=1 AND product_id=0"
                ).fetchall()
            if not promos:
                return 1.0

            # Estimate uplift: discount% × category factor
            uplift = 1.0
            for p in promos:
                pd = dict(p)
                discount = pd.get("discount_pct", 0) or 0
                promo_type = pd.get("promo_type", "discount")
                # FMCG uplift rules of thumb:
                # 10% discount → ~20% volume uplift
                # 20% discount → ~50% volume uplift
                # Buy-get → ~40% uplift
                # Gift → ~25% uplift
                if promo_type == "buy-get":
                    uplift += 0.40
                elif promo_type == "gift":
                    uplift += 0.25
                else:
                    uplift += discount / 100 * 2.0  # elasticity ~2.0
            return round(min(uplift, 3.0), 2)  # Cap at 3x
        except Exception as e:
            logging.getLogger("hergent").warning(f"promotion uplift query failed: {e}")
            return 1.0

def _parse_promo_date(s):
    """促销日期解析（v536）：接受 YYYY-MM-DD 或带时间的 ISO 串，失败返回 None。

    窗口边界在 Python 侧算好再以字面量传进 SQL——不在 SQL 里对可能非法的
    start_date/end_date 套 date() 修饰符（date('') 返回 NULL 会让条件恒空、
    静默丢数据）。
    """
    try:
        return datetime.strptime(str(s)[:10], "%Y-%m-%d").date()
    except (TypeError, ValueError):
        return None


def get_promotion_impact_analysis(days=90):
    """促销影响分析（v536 P2-1 第一期：促销 ROI）——真实数据口径，无估算。

    🔴 背景：原实现主 SQL 与 fallback 都 JOIN 了 schema 里不存在的
       promotions.product_id（真实关联在 junction 表 promotion_items(promotion_id,
       product_id)）⇒ /api/promotion-impact 恒 500；且 estimated_uplift_pct /
       recommended_stock_increase_pct 是硬编码经验值（discount/100*2.0、买赠+40%、
       赠品+25%）——假数，已删除。

    口径：
      · gift_cost：近 days 天 soi.amount=0 且 delivered/signed 的零价出库明细
        = 赠品 ∪ 内部领用 ∪ 其他零价出库单（系统未打标无法拆分，note 如实说明）。
        成本 = 数量 × 进价：批次成本优先（inventory.cost_price>0 取 MAX）、档案进价
        回落、再回落 0——与 v534 库存周转（db/queries/reports.py）同源。
      · activities：每个促销活动「窗口前 14 天 / 活动期 / 后 14 天」的活动商品
        集合销量、成交额、毛利对比。对比不是因果结论（季节性等未剥离）。
      · days：统计窗口天数，默认 90；非数字或 ≤0 回落 90（唯一源内净化，
        分发层不过 int()，参照 hermes_core._monthly_profit_ranking）。
    """
    try:
        days = int(days)
    except (TypeError, ValueError):
        days = 90
    if days <= 0:
        days = 90

    with get_db() as db:
        _gift_base = (
            "FROM sale_order_items soi "
            "JOIN sale_orders so ON soi.order_id = so.id "
            "LEFT JOIN products p ON soi.product_id = p.id "
            "LEFT JOIN (SELECT product_id, MAX(cost_price) AS cost_price FROM inventory "
            "           WHERE cost_price > 0 GROUP BY product_id) ic ON ic.product_id = soi.product_id "
            "WHERE soi.amount = 0 AND so.status IN ('delivered', 'signed') "
            "AND so.order_date >= date('now', ?)"
        )
        _gift_cols = ("SELECT COUNT(DISTINCT so.id) AS order_count, COUNT(*) AS item_count, "
            "COALESCE(SUM(soi.quantity * COALESCE(NULLIF(ic.cost_price, 0), p.purchase_price, 0)), 0) AS total_cost ")
        _ds = ("-%d days" % days,)
        # v537：gift_cost 拆「已标 / 未标」两栏（按 soi.note 是否为空）。tagged+untagged 必等于 total，harness 验证。
        gift = db.execute(_gift_cols + _gift_base, _ds).fetchone()
        gift_tagged = db.execute(_gift_cols + _gift_base + " AND (soi.note IS NOT NULL AND soi.note != '')", _ds).fetchone()
        gift_untagged = db.execute(_gift_cols + _gift_base + " AND (soi.note IS NULL OR soi.note = '')", _ds).fetchone()

        by_product = db.execute(
            "SELECT soi.product_id AS product_id, COALESCE(p.name, '') AS name, "
            "SUM(soi.quantity) AS qty, "
            "SUM(soi.quantity * COALESCE(NULLIF(ic.cost_price, 0), p.purchase_price, 0)) AS cost "
            "FROM sale_order_items soi "
            "JOIN sale_orders so ON soi.order_id = so.id "
            "LEFT JOIN products p ON soi.product_id = p.id "
            "LEFT JOIN (SELECT product_id, MAX(cost_price) AS cost_price FROM inventory "
            "           WHERE cost_price > 0 GROUP BY product_id) ic ON ic.product_id = soi.product_id "
            "WHERE soi.amount = 0 AND so.status IN ('delivered', 'signed') "
            "AND so.order_date >= date('now', ?) "
            "GROUP BY soi.product_id ORDER BY cost DESC LIMIT 20",
            ("-%d days" % days,)
        ).fetchall()

        promos = db.execute(
            "SELECT id, name, start_date, end_date, promo_type, discount_pct "
            "FROM promotions ORDER BY start_date DESC, id DESC LIMIT 50"
        ).fetchall()

    # 每个活动的商品名：promotion_items JOIN products，Python 侧聚合去重
    # （不用 GROUP_CONCAT——商品名可能含逗号等分隔符；promos 为空则整段跳过）
    promo_products = {}
    if promos:
        with get_db() as db:
            rows = db.execute(
                "SELECT pi.promotion_id AS promotion_id, p.name AS name "
                "FROM promotion_items pi JOIN products p ON pi.product_id = p.id "
                "WHERE pi.promotion_id IN (%s)" % ",".join("?" * len(promos)),
                [p["id"] for p in promos]
            ).fetchall()
        for r in rows:
            names = promo_products.setdefault(r["promotion_id"], [])
            if r["name"] and r["name"] not in names:
                names.append(r["name"])

    def _zero_window():
        return {"qty": 0, "amount": 0, "profit": 0}

    activities = []
    for p in promos:
        sd = _parse_promo_date(p["start_date"])
        ed = _parse_promo_date(p["end_date"])
        windows = {"before": _zero_window(), "during": _zero_window(), "after": _zero_window()}
        if sd and ed and ed >= sd:
            b_lo, b_hi = (sd - timedelta(days=14)).isoformat(), (sd - timedelta(days=1)).isoformat()
            d_lo, d_hi = sd.isoformat(), ed.isoformat()
            a_lo, a_hi = (ed + timedelta(days=1)).isoformat(), (ed + timedelta(days=14)).isoformat()
            with get_db() as db:
                row = db.execute(
                    "SELECT "
                    "COALESCE(SUM(CASE WHEN date(so.order_date) >= ? AND date(so.order_date) <= ? THEN soi.quantity ELSE 0 END), 0) AS b_qty, "
                    "COALESCE(SUM(CASE WHEN date(so.order_date) >= ? AND date(so.order_date) <= ? THEN soi.amount ELSE 0 END), 0) AS b_amt, "
                    "COALESCE(SUM(CASE WHEN date(so.order_date) >= ? AND date(so.order_date) <= ? "
                    "THEN soi.amount - soi.quantity * COALESCE(NULLIF(ic.cost_price, 0), p.purchase_price, 0) ELSE 0 END), 0) AS b_prf, "
                    "COALESCE(SUM(CASE WHEN date(so.order_date) >= ? AND date(so.order_date) <= ? THEN soi.quantity ELSE 0 END), 0) AS d_qty, "
                    "COALESCE(SUM(CASE WHEN date(so.order_date) >= ? AND date(so.order_date) <= ? THEN soi.amount ELSE 0 END), 0) AS d_amt, "
                    "COALESCE(SUM(CASE WHEN date(so.order_date) >= ? AND date(so.order_date) <= ? "
                    "THEN soi.amount - soi.quantity * COALESCE(NULLIF(ic.cost_price, 0), p.purchase_price, 0) ELSE 0 END), 0) AS d_prf, "
                    "COALESCE(SUM(CASE WHEN date(so.order_date) >= ? AND date(so.order_date) <= ? THEN soi.quantity ELSE 0 END), 0) AS a_qty, "
                    "COALESCE(SUM(CASE WHEN date(so.order_date) >= ? AND date(so.order_date) <= ? THEN soi.amount ELSE 0 END), 0) AS a_amt, "
                    "COALESCE(SUM(CASE WHEN date(so.order_date) >= ? AND date(so.order_date) <= ? "
                    "THEN soi.amount - soi.quantity * COALESCE(NULLIF(ic.cost_price, 0), p.purchase_price, 0) ELSE 0 END), 0) AS a_prf "
                    "FROM sale_order_items soi "
                    "JOIN sale_orders so ON soi.order_id = so.id "
                    "LEFT JOIN products p ON p.id = soi.product_id "
                    "LEFT JOIN (SELECT product_id, MAX(cost_price) AS cost_price FROM inventory "
                    "           WHERE cost_price > 0 GROUP BY product_id) ic ON ic.product_id = soi.product_id "
                    "WHERE so.status IN ('delivered', 'signed') "
                    "AND soi.product_id IN (SELECT product_id FROM promotion_items WHERE promotion_id = ?) "
                    "AND date(so.order_date) >= ? AND date(so.order_date) <= ?",
                    (b_lo, b_hi, b_lo, b_hi, b_lo, b_hi,
                     d_lo, d_hi, d_lo, d_hi, d_lo, d_hi,
                     a_lo, a_hi, a_lo, a_hi, a_lo, a_hi,
                     p["id"], b_lo, a_hi)
                ).fetchone()
            for wname, pre in (("before", "b"), ("during", "d"), ("after", "a")):
                windows[wname] = {
                    "qty": int(row[pre + "_qty"] or 0),
                    "amount": round(row[pre + "_amt"] or 0, 2),
                    "profit": round(row[pre + "_prf"] or 0, 2),
                }
        activities.append({
            "id": p["id"],
            "name": p["name"] or "",
            "start_date": p["start_date"] or "",
            "end_date": p["end_date"] or "",
            "promo_type": p["promo_type"] or "discount",
            "discount_pct": p["discount_pct"] or 0,
            "products": promo_products.get(p["id"], []),
            "before": windows["before"],
            "during": windows["during"],
            "after": windows["after"],
        })

    return {
        "success": True,
        "days": days,
        "gift_cost": {
            "order_count": int(gift["order_count"] or 0),
            "item_count": int(gift["item_count"] or 0),
            "total_cost": round(gift["total_cost"] or 0, 2),
            "tagged": {
                "order_count": int(gift_tagged["order_count"] or 0),
                "item_count": int(gift_tagged["item_count"] or 0),
                "total_cost": round(gift_tagged["total_cost"] or 0, 2),
            },
            "untagged": {
                "order_count": int(gift_untagged["order_count"] or 0),
                "item_count": int(gift_untagged["item_count"] or 0),
                "total_cost": round(gift_untagged["total_cost"] or 0, 2),
            },
            "by_product": [
                {"product_id": r["product_id"], "name": r["name"] or "",
                 "qty": int(r["qty"] or 0), "cost": round(r["cost"] or 0, 2)}
                for r in by_product
            ],
            "note": "零价出库=赠品∪内部领用∪其他零价出库单的混合；2026-10 起新单强制打标（厂家赠品/买赠活动/内部领用/临期处理/其他），历史单未追补，已标/未标由此拆分。成本=数量×进价（批次成本优先、档案进价回落）",
        },
        "activities": activities,
        "activity_note": (
            "以下为活动窗口前后 14 天对比——不是因果结论，季节性等同类因素未剥离。"
            if activities else
            "系统内暂无促销活动记录。启用促销活动（如买赠）后，此处展示活动窗口前/中/后的销量、成交额、毛利对比——对比不是因果结论，季节性等同类因素未剥离。"
        ),
        "generated_at": datetime.now().isoformat(timespec="seconds"),
    }

# get_rebate_contracts → db/queries/ (working module)
CONTRACT_TYPES = ("revenue", "purchase")


def _valid_year(y):
    import re as _re
    s = str(y or "").strip()
    return bool(_re.fullmatch(r"\d{4}", s)) if s else False


def _coerce_contract_args(contact_id, year, target_amount, rebate_pct, contact_name="", contract_type="revenue", brand_id=0,
                          scale_type="graduated", rounding_mode="half_up", rounding_digits=2):
    """合同入参校验与规整（v112 R29）。返回 (ok, err, cleaned)。

    brand_id（v113）：合同挂载的品牌（brands 表 id），0 = 不限/未指定品牌。
    年度返利合同 = 厂家 × 品牌 × 年度，品牌可后续在品牌档案补录后回填。
    scale_type / rounding_*（v113）：阶梯计法与舍入策略，默认累进 + 四舍五入 2 位
    （与 v112 及以前行为一致，存量合同零变化）。
    """
    if not _valid_year(year):
        return False, "年份必须是 4 位数字（如 2026）", None
    try:
        target_amount = float(target_amount or 0)
    except (TypeError, ValueError):
        return False, "目标金额必须是数字", None
    if target_amount < 0:
        return False, "目标金额不能为负数", None
    try:
        rebate_pct = float(rebate_pct or 0)
    except (TypeError, ValueError):
        return False, "返利比例必须是数字", None
    if not (0 <= rebate_pct <= 100):
        return False, "返利比例须在 0~100 之间（百分点，如 3 表示 3%）", None
    if contract_type not in CONTRACT_TYPES:
        contract_type = "revenue"
    try:
        brand_id = int(brand_id or 0)
    except (TypeError, ValueError):
        return False, "品牌 ID 必须是数字", None
    if brand_id < 0:
        return False, "品牌 ID 不能为负数", None
    # v113: 计法 / 舍入（非法值静默回落默认，避免老调用方未传参时被 400 打断）
    try:
        from domain.rebate_calc import (SCALE_TYPES as _ST, ROUNDING_MODES as _RM,
                                        DEFAULT_SCALE_TYPE_CONTRACT as _DS,
                                        DEFAULT_ROUNDING_MODE as _DR,
                                        DEFAULT_ROUNDING_DIGITS as _DD, _norm_digits as _nd)
    except Exception:  # pragma: no cover
        _ST, _RM, _DS, _DR, _DD = ("graduated", "non_graduated"), ("half_up", "up", "down"), "graduated", "half_up", 2
        _nd = lambda v, d=2: d
    scale_type = str(scale_type or "").strip() or _DS
    if scale_type not in _ST:
        scale_type = _DS
    rounding_mode = str(rounding_mode or "").strip() or _DR
    if rounding_mode not in _RM:
        rounding_mode = _DR
    try:
        rounding_digits = _nd(rounding_digits, _DD)
    except Exception:
        rounding_digits = _DD
    return True, "", {
        "contact_id": int(contact_id or 0),
        "year": str(year).strip(),
        "target_amount": round(target_amount, 2),
        "rebate_pct": round(rebate_pct, 2),
        "contact_name": str(contact_name or ""),
        "contract_type": contract_type,
        "brand_id": brand_id,
        "scale_type": scale_type,
        "rounding_mode": rounding_mode,
        "rounding_digits": rounding_digits,
    }


