def get_rebate_contracts():
    # LEFT JOIN：contact_id 悬空（合作方记录已删/未建）时合同仍应返回，
    # 否则 INNER JOIN 会静默吞掉该合同（如 contact_id=1 无对应 contacts 的老数据）。
    # v113: LEFT JOIN brands 带回 brand_name（合同挂品牌后列表直接展示品牌名）。
    with get_db() as db:
        return [dict(r) for r in db.execute(
            "SELECT rc.*,c.name as customer_name,b.name as brand_name FROM rebate_contracts rc "
            "LEFT JOIN contacts c ON rc.contact_id=c.id "
            "LEFT JOIN brands b ON rc.brand_id=b.id "
            "ORDER BY rc.id DESC").fetchall()]

def update_rebate_contract(cid, contact_id, year, target_amount, rebate_pct, contact_name, contract_type="revenue", brand_id=0,
                           scale_type="graduated", rounding_mode="half_up", rounding_digits=2):
    """更新年度返利合同（v112 R29 校验 + R31 年份变更同步迁移月度行，避免孤儿月份；v113 支持挂品牌 + 计法/舍入）。"""
    ok, err, c = _coerce_contract_args(contact_id, year, target_amount, rebate_pct, contact_name, contract_type, brand_id,
                                       scale_type, rounding_mode, rounding_digits)
    if not ok:
        return {"success": False, "error": err}
    with get_db() as db:
        old = db.execute("SELECT year FROM rebate_contracts WHERE id=?", (cid,)).fetchone()
        if not old:
            return {"success": False, "error": "合同不存在"}
        old_year = str(old["year"] or "").strip()
        if old_year and old_year != c["year"]:
            # R31: 年份变更 → 旧年份 12 个月度行整体迁到新年份（同月序号），先清目标年份可能残留的行
            for m in range(1, 13):
                db.execute("DELETE FROM rebate_contract_months WHERE contract_id=? AND month=?",
                           (cid, f"{c['year']}-{m:02d}"))
                db.execute("UPDATE rebate_contract_months SET month=? WHERE contract_id=? AND month=?",
                           (f"{c['year']}-{m:02d}", cid, f"{old_year}-{m:02d}"))
        db.execute(
            "UPDATE rebate_contracts SET contact_id=?,year=?,target_amount=?,rebate_pct=?,contact_name=?,contract_type=?,brand_id=?,"
            "scale_type=?,rounding_mode=?,rounding_digits=? "
            "WHERE id=?",
            (c["contact_id"], c["year"], c["target_amount"], c["rebate_pct"], c["contact_name"], c["contract_type"],
             c["brand_id"], c["scale_type"], c["rounding_mode"], c["rounding_digits"], cid))
        db.commit()
        return {"success": True}

def delete_rebate_contract(cid):
    """删除合同（v112 R4）：已结算合同拒绝删除（财务留痕）；事务内级联清理月度分解与计提。

    合同下挂的目标规则**回置为独立规则**（contract_id=0，保留配置，不再参与合同计提），
    不物理删除 —— 规则是独立资产，可能被其它合同复用。
    """
    with get_db() as db:
        ct = db.execute("SELECT settled FROM rebate_contracts WHERE id=?", (cid,)).fetchone()
        if not ct:
            return {"success": False, "error": "合同不存在"}
        if int(ct["settled"] or 0):
            return {"success": False, "error": "已结算合同不能删除（财务留痕），如需删除请先反结算"}
        db.execute("DELETE FROM rebate_contract_months WHERE contract_id=?", (cid,))
        db.execute("DELETE FROM rebate_accruals WHERE contract_id=?", (cid,))
        try:  # 表缺 contract_id 列时安全降级（老库）
            db.execute("UPDATE rebate_target_rules SET contract_id=0 WHERE contract_id=?", (cid,))
        except Exception:
            pass
        db.execute("DELETE FROM rebate_contracts WHERE id=?", (cid,))
        db.commit()
        return {"success": True, "removed": True}

def get_rebate_progress():
    """未结算合同的达成进度（AI 返利卡 / 报表消费）。

    LEFT JOIN：按名称直录的合同(contact_id 悬空)不能被静默吞掉。
    达成口径 (v112 R9)：统一走 _contract_year_achieved() —— 全年达成：
    挂目标规则的合同按「规则 × 周期键」去重取达成填报合计；无规则的旧合同
    退回 sale_orders 当年销售额。
    此前"有计提就用 SUM(rebate_accruals.achieved_amount)"只统计已计提月份，
    未计提月份达成被漏算、进度偏低。计提是逐月确认动作，不改变"当年达成"数字。
    """
    with get_db() as db:
        contracts = [dict(r) for r in db.execute(
            "SELECT rc.*, c.name as customer_name FROM rebate_contracts rc "
            "LEFT JOIN contacts c ON rc.contact_id=c.id WHERE rc.settled=0").fetchall()]
        ach_idx = _achievement_index(db)
        for rc in contracts:
            rc["achieved"] = _contract_year_achieved(db, rc, ach_idx)
        return sorted(contracts, key=lambda x: x.get("achieved", 0), reverse=True)

