        yellow = [dict(r) for r in db.execute("SELECT i.*,p.name,p.spec,p.unit FROM inventory i JOIN products p ON i.product_id=p.id WHERE i.expiry_date!='' AND i.quantity>0 AND date(i.expiry_date)>date('now','+30 days') AND date(i.expiry_date)<=date('now','+60 days') ORDER BY i.expiry_date").fetchall()]
