def get_health_score():
    with get_db() as db:
        # Cash flow: cash/total_assets
        cash = db.execute("SELECT COALESCE(SUM(current_balance),0) FROM accounts").fetchone()[0]
        ar = db.execute("SELECT COALESCE(SUM(amount-paid_amount),0) FROM receivables WHERE type='ar' AND status!='paid'").fetchone()[0]
        ap = db.execute("SELECT COALESCE(SUM(amount-paid_amount),0) FROM receivables WHERE type='ap' AND status!='paid'").fetchone()[0]
        # Sales today vs 7-day avg
        today_sales = db.execute("SELECT COALESCE(SUM(total_amount),0) FROM sale_orders WHERE date(order_date)=date('now') AND status IN ('delivered','signed')").fetchone()[0]
        avg7_sales = db.execute("SELECT COALESCE(AVG(daily),0) FROM (SELECT SUM(total_amount) as daily FROM sale_orders WHERE order_date>=date('now','-7 days') AND status IN ('delivered','signed') GROUP BY date(order_date))").fetchone()[0]
        # Profit margin
        sales_total = db.execute("SELECT COALESCE(SUM(soi.amount),0) FROM sale_order_items soi JOIN sale_orders so ON soi.order_id=so.id WHERE so.status IN ('delivered','signed')").fetchone()[0]
        cost_total = db.execute("SELECT COALESCE(SUM(soi.quantity*p.purchase_price),0) FROM sale_order_items soi JOIN sale_orders so ON soi.order_id=so.id JOIN products p ON soi.product_id=p.id WHERE so.status IN ('delivered','signed')").fetchone()[0]
        margin = (sales_total-cost_total)/sales_total*100 if sales_total>0 else 0
        # AR turnover
        ar_turnover = sales_total/ar if ar>0 else 100
        # Stock days
        stock_val = db.execute("SELECT COALESCE(SUM(i.quantity*p.purchase_price),0) FROM inventory i JOIN products p ON i.product_id=p.id").fetchone()[0]
        daily_cost = cost_total/30 if cost_total>0 else 1
        stock_days = stock_val/daily_cost if daily_cost>0 else 0
        # Composite score
        cash_score = min(30,max(0,30*(cash/(cash+ap+1))))
        ar_score = min(25,max(0,25*(1-ar/(sales_total+1))))
        margin_score = min(20,max(0,20*margin/30)) if margin>0 else 10
        stock_score = min(15,max(0,15*(1-stock_days/60)))
        sales_score = min(10,max(0,10*(today_sales/(avg7_sales+1))))
        total = round(cash_score+ar_score+margin_score+stock_score+sales_score)
        return {'total':total,'cash':round(cash_score),'ar_health':round(ar_score),'margin':round(margin_score),'stock':round(stock_score),'sales_trend':round(sales_score),'details':{'cash':round(cash),'ar':round(ar),'ap':round(ap),'today_sales':today_sales,'avg7_sales':round(avg7_sales),'margin':round(margin,1),'stock_days':round(stock_days)}}

