def get_credit_auto_rating():
    with get_db() as db:
        custs = db.execute("SELECT * FROM contacts WHERE type='customer' AND is_active=1").fetchall()
        results = []
        for c in custs:
            cd = dict(c)
            total_orders = db.execute("SELECT COUNT(*) FROM sale_orders WHERE customer_id=? AND settlement_method='赊账'",(cd['id'],)).fetchone()[0]
            paid_on_time = db.execute("SELECT COUNT(*) FROM sale_orders WHERE customer_id=? AND status='signed' AND received_amount>=total_amount",(cd['id'],)).fetchone()[0]
            overdue = db.execute("SELECT COUNT(*) FROM receivables WHERE contact_id=? AND type='ar' AND status!='paid' AND date(due_date)<date('now')",(cd['id'],)).fetchone()[0]
            on_time_pct = round(paid_on_time/total_orders*100) if total_orders>0 else 100
            if on_time_pct>=95 and overdue==0: rating='A'
            elif on_time_pct>=80: rating='B'
            else: rating='C'
            cd['rating']=rating; cd['on_time_pct']=on_time_pct; cd['overdue_count']=overdue
            results.append(cd)
        return results

def get_anomalies():
    anomalies = []
    with get_db() as db:
        # Sales drop >50%
        today = db.execute("SELECT COALESCE(SUM(total_amount),0) FROM sale_orders WHERE date(order_date)=date('now') AND status IN ('delivered','signed')").fetchone()[0]
        avg7 = db.execute("SELECT COALESCE(AVG(daily),0) FROM (SELECT SUM(total_amount) as daily FROM sale_orders WHERE order_date>=date('now','-7 days') AND status IN ('delivered','signed') GROUP BY date(order_date))").fetchone()[0]
        if avg7>0 and today<avg7*0.5: anomalies.append({'type':'sales_drop','msg':'今日销售额比7日均值低'+str(round((1-today/(avg7+1))*100))+'%','severity':'high'})
        # AR > 80% of monthly sales
        ar = db.execute("SELECT COALESCE(SUM(amount-paid_amount),0) FROM receivables WHERE type='ar' AND status!='paid'").fetchone()[0]
        monthly = db.execute("SELECT COALESCE(SUM(total_amount),0) FROM sale_orders WHERE order_date>=date('now','-30 days') AND status IN ('delivered','signed')").fetchone()[0]
        if monthly>0 and ar>monthly*0.8: anomalies.append({'type':'ar_high','msg':'应收款占月销售额'+str(round(ar/(monthly+1)*100))+'%','severity':'high'})
        # Expired stock
        expired = db.execute("SELECT COUNT(*) FROM inventory WHERE expiry_date!='' AND date(expiry_date)<date('now') AND quantity>0").fetchone()[0]
        if expired>0: anomalies.append({'type':'expired','msg':str(expired)+'个商品已过期未处理','severity':'medium'})
        # Customer hasn't ordered in 30+ days
        silent = db.execute("SELECT COUNT(*) FROM contacts c WHERE c.type='customer' AND c.is_active=1 AND (SELECT MAX(order_date) FROM sale_orders WHERE customer_id=c.id)<date('now','-30 days')").fetchone()[0]
        if silent>0: anomalies.append({'type':'silent_cust','msg':str(silent)+'个客户超过30天未下单','severity':'medium'})
    return anomalies

