def analyze_bank_diff(unmatched_rows):
    suggestions = []
    for row in unmatched_rows:
        amount = abs(float(row.get('amount',0)))
        date = row.get('date','')
        reasons = []
        # Check if similar amount exists on adjacent dates
        with get_db() as db:
            near = db.execute("SELECT * FROM cash_flow WHERE ABS(amount-?)<10 AND ABS(julianday(created_at)-julianday(?))<=3",(amount,date)).fetchall()
            if near: reasons.append('可能存在±3天内的相近金额记录(日期差异)')
            dup = db.execute("SELECT * FROM cash_flow WHERE ABS(amount-?)<0.01 AND ABS(julianday(created_at)-julianday(?))<=1",(amount,date)).fetchall()
            if len(dup)>1: reasons.append('可能存在重复记账(同金额同日多条记录)')
            if not near and not dup: reasons.append('该笔银行流水在系统中未找到匹配记录，可能是银行扣款或未记账支出')
        suggestions.append({'row':row,'reasons':reasons})
    return suggestions

