def save_monthly_snapshot(month=''):
    if not month: month = (datetime.now().replace(day=1) - __import__('datetime').timedelta(days=1)).strftime("%Y-%m")
    # v710：快照与「报表页」同口径（权责发生制 GL 版）。
    # 改前存的是简化版：`get_balance_sheet()` 用「权益 = 资产 − 负债」残差凑等式、
    # 且返回体**没有** `balanced` 字段；而 `/api/reports/balance-sheet` 自 v708 起
    # 只留 GL 版 ⇒ 同一个月「报表页」和「快照页」会给出两个资产数。
    # 现金流量表本身属收付实现制，`get_cashflow()` 保持不动。
    import calendar as _cal
    _y, _m = int(month[:4]), int(month[5:7])
    _as_of = "%s-%02d" % (month, _cal.monthrange(_y, _m)[1])
    from db.queries.finance import get_pnl_gl as _get_pnl_gl, get_balance_sheet_gl as _get_bs_gl
    pnl = _get_pnl_gl(month)
    bs = _get_bs_gl(_as_of)
    cf = get_cashflow()
    with get_db() as db:
        db.execute("INSERT OR REPLACE INTO monthly_snapshots (month,pnl_json,bs_json,cf_json) VALUES (?,?,?,?)",
                   (month, json.dumps(pnl), json.dumps(bs), json.dumps(cf)))
        db.commit()

def get_monthly_snapshots(limit=12):
    with get_db() as db:
        return [dict(r) for r in db.execute("SELECT month,pnl_json,bs_json,cf_json FROM monthly_snapshots ORDER BY month DESC LIMIT ?",(limit,)).fetchall()]

