# P0-② 每日经营日志：跨会话回忆「昨天/上周」的真实经营快照
# ============================================================
def _ensure_daily_logs(db):
    """惰性建表（租户库；init_db 只在主库跑迁移，租户库请求时兜底，同 wastage/forecast 范式）。"""
    db.execute(
        """CREATE TABLE IF NOT EXISTS daily_logs(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            log_date TEXT NOT NULL,
            metric TEXT NOT NULL,
            value REAL DEFAULT 0,
            note TEXT DEFAULT '',
            created_at TEXT DEFAULT (datetime('now','localtime')),
            UNIQUE(log_date, metric)
        )"""
    )

def log_daily_metric(log_date, metric, value, note=''):
    """写入/覆盖某天某指标（幂等：同一天同指标 INSERT OR REPLACE 只保留最新）。"""
    with get_db() as db:
        _ensure_daily_logs(db)
        db.execute(
            "INSERT OR REPLACE INTO daily_logs (log_date, metric, value, note) VALUES (?,?,?,?)",
            (log_date, metric, float(value or 0), note)
        )
        db.commit()

def get_daily_logs(days=30):
    """查询最近 N 天经营日志（按日期升序），返回 [{log_date, metric, value, note}]。"""
    with get_db() as db:
        _ensure_daily_logs(db)
        rows = db.execute(
            "SELECT log_date, metric, value, note FROM daily_logs "
            "WHERE log_date >= date('now','localtime',?) ORDER BY log_date ASC, id ASC",
            (f'-{int(days)} days',)
        ).fetchall()
        return [dict(r) for r in rows]

def create_api_token(user_id, name=''):
    """G11 (2026-07-25): 新 token 默认带过期时间（ERP_TOKEN_TTL_DAYS，默认90天）。
    存量库若尚未补齐 expires_at 列，回退到不带该列的写入，保证兼容。"""
    import secrets
    from datetime import datetime, timedelta
    token = secrets.token_urlsafe(24)
    try:
        ttl = int(os.environ.get("ERP_TOKEN_TTL_DAYS", "90"))
    except (ValueError, TypeError):
        ttl = 90
    exp = (datetime.now() + timedelta(days=ttl)).strftime("%Y-%m-%d %H:%M:%S")
    with get_db() as db:
        try:
            db.execute("INSERT INTO api_tokens (user_id,token,name,expires_at) VALUES (?,?,?,?)",(user_id,token,name,exp))
        except Exception:
            db.execute("INSERT INTO api_tokens (user_id,token,name) VALUES (?,?,?)",(user_id,token,name))
        db.commit()
    return token

def list_api_tokens(user_id):
    with get_db() as db:
        return [dict(r) for r in db.execute("SELECT id,name,token,created_at,is_active FROM api_tokens WHERE user_id=? ORDER BY id DESC",(user_id,)).fetchall()]

def revoke_api_token(token_id, user_id):
    with get_db() as db:
        db.execute("UPDATE api_tokens SET is_active=0 WHERE id=? AND user_id=?",(token_id,user_id))
        db.commit()

