def update_promotion(pid, name=None, start_date=None, end_date=None, product_ids=None,
                     discount_pct=0, bonus_qty=0, promo_type='discount', buy_qty=0,
                     free_qty=0, gift_product_name='', gift_qty=0):
    """全量更新促销活动（v537 P2-1 二期）。先清后插 promotion_items，保持关联与新建一致。"""
    with get_db() as db:
        db.execute(
            "UPDATE promotions SET name=?,start_date=?,end_date=?,discount_pct=?,bonus_qty=?,"
            "promo_type=?,buy_qty=?,free_qty=?,gift_product_name=?,gift_qty=? WHERE id=?",
            (name, start_date, end_date, discount_pct, bonus_qty, promo_type, buy_qty, free_qty,
             gift_product_name, gift_qty, pid))
        db.execute("DELETE FROM promotion_items WHERE promotion_id=?", (pid,))
        for p in (product_ids or []):
            db.execute("INSERT INTO promotion_items (promotion_id,product_id) VALUES (?,?)", (pid, p))
        db.commit()
        return True

def delete_promotion(pid):
    """删除促销活动（v537 P2-1 二期）。连带删 promotion_items；已落库归因 sale_order_promos 是快照，不动。"""
    with get_db() as db:
        db.execute("DELETE FROM promotion_items WHERE promotion_id=?", (pid,))
        db.execute("DELETE FROM promotions WHERE id=?", (pid,))
        db.commit()
        return True


def get_yoy_comparison():
    with get_db() as db:
        this_month = datetime.now().strftime("%Y-%m")
        last_month = (datetime.now().replace(day=1) - __import__('datetime').timedelta(days=1)).strftime("%Y-%m")
        last_year = (datetime.now().replace(year=datetime.now().year-1)).strftime("%Y-%m")
        def month_sales(m): return db.execute("SELECT COALESCE(SUM(total_amount),0) FROM sale_orders WHERE substr(order_date,1,7)=? AND status IN ('delivered','signed')",(m,)).fetchone()[0]
        def month_payments(m): return db.execute("SELECT COALESCE(SUM(amount),0) FROM cash_flow WHERE type='income' AND substr(created_at,1,7)=?",(m,)).fetchone()[0]
        tm = month_sales(this_month); lm = month_sales(last_month); ly = month_sales(last_year)
        return {'this_month':tm,'last_month':lm,'last_year':ly,'mom_pct':round((tm-lm)/(lm+1)*100),'yoy_pct':round((tm-ly)/(ly+1)*100),'this_month_payments':month_payments(this_month)}

def get_credit_utilization():
    with get_db() as db:
        custs = db.execute("SELECT * FROM contacts WHERE type='customer' AND credit_limit>0 AND is_active=1").fetchall()
        results = []
        for c in custs:
            cd = dict(c)
            used = db.execute("SELECT COALESCE(SUM(amount-paid_amount),0) FROM receivables WHERE contact_id=? AND type='ar' AND status!='paid'",(cd['id'],)).fetchone()[0]
            cd['used'] = used; cd['util_pct'] = round(used/cd['credit_limit']*100) if cd['credit_limit']>0 else 0
            results.append(cd)
        total_limit = sum(r['credit_limit'] for r in results); total_used = sum(r['used'] for r in results)
        return {'customers':sorted(results, key=lambda x: x['util_pct'], reverse=True),'total_limit':total_limit,'total_used':total_used,'total_pct':round(total_used/(total_limit+1)*100)}

