def check_goal_celebration():
    with get_db() as db:
        goals = db.execute("SELECT * FROM goals WHERE is_active=1").fetchall()
        for g in goals:
            gd = dict(g)
            if gd['current_value']>=gd['target_value'] and gd['target_value']>0:
                already = db.execute("SELECT id FROM goal_celebrations WHERE goal_id=? AND month=?",(gd['id'],datetime.now().strftime("%Y-%m"))).fetchone()
                if not already:
                    db.execute("INSERT INTO goal_celebrations (goal_id,month) VALUES (?,?)",(gd['id'],datetime.now().strftime("%Y-%m")))
                    db.commit()
                    return {'celebrate':True,'goal_name':gd['name'],'pct':round(gd['current_value']/gd['target_value']*100)}
    return {'celebrate':False}

