# v22: AI现金流预测、自动采购、龙虎榜、客户健康度、经营建议、对账建议
# ============================================================
def get_cash_forecast(days=30):
    with get_db() as db:
        cash = db.execute("SELECT COALESCE(SUM(current_balance),0) FROM accounts").fetchone()[0]
        ar = db.execute("SELECT COALESCE(SUM(amount-paid_amount),0) FROM receivables WHERE type='ar' AND status!='paid'").fetchone()[0]
        ap = db.execute("SELECT COALESCE(SUM(amount-paid_amount),0) FROM receivables WHERE type='ap' AND status!='paid'").fetchone()[0]
        daily_sales = db.execute("SELECT COALESCE(AVG(daily),0) FROM (SELECT SUM(total_amount) as daily FROM sale_orders WHERE order_date>=date('now','-30 days') AND status IN ('delivered','signed') GROUP BY date(order_date))").fetchone()[0]
        daily_expense = db.execute("SELECT COALESCE(AVG(daily),0) FROM (SELECT SUM(amount) as daily FROM cash_flow WHERE type='expense' AND created_at>=date('now','-30 days') GROUP BY date(created_at))").fetchone()[0]
        daily_income = db.execute("SELECT COALESCE(AVG(daily),0) FROM (SELECT SUM(amount) as daily FROM cash_flow WHERE type='income' AND created_at>=date('now','-30 days') GROUP BY date(created_at))").fetchone()[0]
        forecast = []; balance = cash
        for i in range(days):
            balance += daily_income - daily_expense + daily_sales*0.3
            forecast.append({'day':i+1,'balance':round(balance),'daily_in':round(daily_income+daily_sales*0.3),'daily_out':round(daily_expense)})
        threshold_day = next((i+1 for i,f in enumerate(forecast) if f['balance']<0),None)
        return {'current_cash':cash,'ar':ar,'ap':ap,'forecast':forecast,'warning_days':threshold_day,'avg_daily_in':round(daily_income+daily_sales*0.3),'avg_daily_out':round(daily_expense)}

