def do_day_close(operator_id=''):
    today = datetime.now().strftime("%Y-%m-%d")
    with get_db() as db:
        undel = db.execute("SELECT COUNT(*) FROM sale_orders WHERE date(order_date)=? AND status='draft'",(today,)).fetchone()[0]
        unsig = db.execute("SELECT COUNT(*) FROM sale_orders WHERE date(order_date)=? AND status='delivered'",(today,)).fetchone()[0]
        signed = db.execute("SELECT COUNT(*) FROM sale_orders WHERE date(order_date)=? AND status='signed'",(today,)).fetchone()[0]
        income = db.execute("SELECT COALESCE(SUM(amount),0) FROM cash_flow WHERE type='income' AND date(created_at)=?",(today,)).fetchone()[0]
        expense = db.execute("SELECT COALESCE(SUM(amount),0) FROM cash_flow WHERE type='expense' AND date(created_at)=?",(today,)).fetchone()[0]
        sales_total = db.execute("SELECT COALESCE(SUM(total_amount),0) FROM sale_orders WHERE date(order_date)=?",(today,)).fetchone()[0]
        pending_deliver = [dict(r) for r in db.execute("SELECT so.order_no,c.name as customer_name,so.total_amount FROM sale_orders so JOIN contacts c ON so.customer_id=c.id WHERE date(so.order_date)=? AND so.status='draft' LIMIT 10",(today,)).fetchall()]
        pending_sign = [dict(r) for r in db.execute("SELECT so.order_no,c.name as customer_name,so.total_amount FROM sale_orders so JOIN contacts c ON so.customer_id=c.id WHERE date(so.order_date)=? AND so.status='delivered' LIMIT 10",(today,)).fetchall()]
        low_stock = db.execute("SELECT COUNT(*) FROM inventory i JOIN products p ON i.product_id=p.id WHERE i.quantity<=p.safety_stock AND p.safety_stock>0").fetchone()[0]
        return {
            'ok': undel==0 and unsig==0,
            'sales_total': sales_total, 'income': income, 'expense': expense,
            'order_count': signed+undel+unsig, 'signed_count': signed,
            'undelivered': undel, 'unsigned': unsig,
            'pending_deliver': pending_deliver, 'pending_sign': pending_sign,
            'low_stock': low_stock, 'issues': undel+unsig
        }

def get_diagnostic_report():
    with get_db() as db:
        h = get_health_score()
        churn = db.execute("SELECT COUNT(*) FROM contacts c WHERE c.type='customer' AND c.is_active=1 AND (SELECT MAX(order_date) FROM sale_orders WHERE customer_id=c.id)<date('now','-30 days')").fetchone()[0]
        highlights,improvements = [],[]
        if h['total']>=75: highlights.append('经营健康评分良好('+str(h['total'])+'分)')
        if h['ar_health']<15: improvements.append('应收周转偏慢')
        if h['stock']<10: improvements.append('库存周转偏慢')
        if churn>0: improvements.append(str(churn)+'个客户超30天未下单')
        return {'health_score':h['total'],'grade':'A' if h['total']>=75 else 'B' if h['total']>=50 else 'C','highlights':highlights,'improvements':improvements,'churn':churn}

