def get_seasonal_analysis():
    with get_db() as db:
        prods = db.execute("SELECT id,name FROM products WHERE is_active=1 LIMIT 10").fetchall()
        results = []
        for p in prods:
            monthly={}
            for m in range(1,13):
                qty = db.execute("SELECT COALESCE(SUM(soi.quantity),0) FROM sale_order_items soi JOIN sale_orders so ON soi.order_id=so.id WHERE soi.product_id=? AND CAST(substr(so.order_date,6,2) AS INTEGER)=? AND so.status IN ('delivered','signed')",(p['id'],m)).fetchone()[0]
                monthly[m]=qty
            if sum(monthly.values())>0:
                avg=sum(monthly.values())/12; peak=max(monthly,key=monthly.get); trough=min(monthly,key=monthly.get)
                results.append({'name':p['name'],'peak_month':peak,'trough_month':trough,'seasonality':round(monthly[peak]/(monthly[trough]+1),1),'avg':round(avg)})
        return sorted(results,key=lambda x: x['seasonality'],reverse=True)

def get_clv_ranking():
    with get_db() as db:
        custs = db.execute("SELECT * FROM contacts WHERE type='customer' AND is_active=1").fetchall()
        results = []
        for c in custs:
            cd = dict(c)
            total = db.execute("SELECT COALESCE(SUM(total_amount),0),COUNT(*),MAX(order_date) FROM sale_orders WHERE customer_id=?",(cd['id'],)).fetchone()
            avg_o = total[0]/total[1] if total[1]>0 else 0
            months = 1
            if total[2]:
                first = db.execute("SELECT MIN(order_date) FROM sale_orders WHERE customer_id=?",(cd['id'],)).fetchone()[0]
                if first:
                    from datetime import datetime as dt
                    months = max(1,(dt.now()-dt.strptime(first[:10],"%Y-%m-%d")).days/30)
            monthly = total[0]/months if months>0 else 0
            cd['total_spent']=total[0]; cd['orders']=total[1]; cd['avg_order']=avg_o; cd['monthly_avg']=monthly; cd['clv']=round(monthly*36); cd['months_active']=round(months)
            results.append(cd)
        return sorted(results,key=lambda x: x['clv'],reverse=True)

def compare_products(ids):
    with get_db() as db:
        ph = ",".join(["?"]*len(ids))
        prods = [dict(r) for r in db.execute(f"SELECT * FROM products WHERE id IN ({ph})",ids).fetchall()]
        for p in prods:
            sold = db.execute("SELECT COALESCE(SUM(soi.quantity),0) FROM sale_order_items soi JOIN sale_orders so ON soi.order_id=so.id WHERE soi.product_id=? AND so.status IN ('delivered','signed')",(p['id'],)).fetchone()[0]
            rev = db.execute("SELECT COALESCE(SUM(soi.amount),0) FROM sale_order_items soi JOIN sale_orders so ON soi.order_id=so.id WHERE soi.product_id=? AND so.status IN ('delivered','signed')",(p['id'],)).fetchone()[0]
            stk = db.execute("SELECT COALESCE(SUM(quantity),0) FROM inventory WHERE product_id=?",(p['id'],)).fetchone()[0]
            p['sold']=sold; p['revenue']=rev; p['stock']=stk; p['profit']=rev-sold*p['purchase_price']
        return prods

