def ai_query(question):
    q = question.lower()
    with get_db() as db:
        if any(w in q for w in ["哪个客户","谁买","客户买","大客户","最多","top"]):
            rows = db.execute("SELECT c.name,COALESCE(SUM(so.total_amount),0) as total FROM contacts c LEFT JOIN sale_orders so ON c.id=so.customer_id WHERE c.type=\"customer\" AND so.status IN (\"delivered\",\"signed\") GROUP BY c.id ORDER BY total DESC LIMIT 3").fetchall()
            return {"type":"ranking","title":"销售TOP3客户","data":[{"name":r["name"],"value":"¥"+str(int(r["total"]))} for r in rows]}
        if any(w in q for w in ["欠钱","欠款","谁欠","应收","没给钱"]):
            rows = db.execute("SELECT c.name,r.amount-r.paid_amount as balance FROM receivables r JOIN contacts c ON r.contact_id=c.id WHERE r.type=\"ar\" AND r.status!=\"paid\" AND r.amount>r.paid_amount ORDER BY balance DESC LIMIT 5").fetchall()
            return {"type":"debtors","data":[{"name":r["name"],"balance":"¥"+str(int(r["balance"]))} for r in rows]}
        if any(w in q for w in ["库存","缺货","不够","快没了","低库存"]):
            rows = db.execute("SELECT p.name,i.quantity,p.safety_stock FROM inventory i JOIN products p ON i.product_id=p.id WHERE i.quantity<=p.safety_stock AND p.safety_stock>0 ORDER BY i.quantity LIMIT 5").fetchall()
            return {"type":"low_stock","data":[{"name":r["name"],"qty":r["quantity"],"safety":r["safety_stock"]} for r in rows]}
        return {"type":"unknown","msg":"试试问：哪个客户买得最多？库存哪些不够了？谁欠钱最多？"}

