# ---- Tenant Membership ----
def init_tenant_membership():
    """Create user_tenants table and seed admin access to tenant 1."""
    with get_db() as db:
        db.executescript("""
            CREATE TABLE IF NOT EXISTS user_tenants (
                user_id INTEGER NOT NULL,
                tenant_id INTEGER NOT NULL,
                PRIMARY KEY (user_id, tenant_id)
            );
        """)
        # Bind admin ONLY to its own operator tenant (tenant 1) — never to every
        # tenant, which would let the superuser cross into demo/other customers'
        # data. Idempotent; no-op if tenant 1 does not exist yet.
        db.execute(
            "INSERT OR IGNORE INTO user_tenants (user_id, tenant_id) "
            "SELECT u.id, 1 FROM users u WHERE u.username='admin' "
            "AND EXISTS (SELECT 1 FROM tenants WHERE id=1)"
        )
        db.commit()

def check_user_tenant(user_id, tenant_id):
    """Check if a user has access to a specific tenant. Returns True/False.

    Access is governed STRICTLY by the user_tenants membership table — there is
    NO role-based bypass (admin included). This keeps tenants isolated: the
    operator's admin account can only reach tenants it is explicitly a member of
    (its own tenant_1), never demo / other customers' data. Cross-tenant support
    access, if ever needed, must be an explicit, audited impersonation feature —
    not a blanket role shortcut.
    """
    if not user_id or not tenant_id:
        return False
    # 🔴 v254 安全修复：`user_tenants` 是**主库表**，此处必须**绕过租户上下文直连主库只读**。
    # 原来用 `get_db()`，而 `get_db()` 是上下文敏感的（`_tenant_db.get() or DB_PATH`）——
    # 一旦当前已有租户上下文（中间件在后续路径、或同一任务内切过租户），这句会连到
    # `tenant_N.db`，读到该租户库里**残留的旧 user_tenants 行**，于是「某人是否属于某租户」
    # 得到错误答案。这是鉴权判定，错的方向就是**越权放行**，且**零报错**（只是读到另一个库）。
    # 只读 URI 打开：既不可能误写客户库，也不存在库缺失时凭空建空文件的问题。
    con = sqlite3.connect("file:%s?mode=ro" % DB_PATH, uri=True)
    try:
        con.row_factory = sqlite3.Row
        r = con.execute("SELECT 1 FROM user_tenants WHERE user_id=? AND tenant_id=?", (user_id, tenant_id)).fetchone()
        return r is not None
    finally:
        con.close()

def get_user_tenants(user_id):
    """Return list of tenant_ids accessible by user.

    同 `check_user_tenant`：主库表，必须直连主库只读，不能跟随调用者租户上下文。
    """
    con = sqlite3.connect("file:%s?mode=ro" % DB_PATH, uri=True)
    try:
        con.row_factory = sqlite3.Row
        rows = con.execute("SELECT tenant_id FROM user_tenants WHERE user_id=?", (user_id,)).fetchall()
        return [r["tenant_id"] for r in rows]
    finally:
        con.close()

def users_in_tenants(tenant_ids):
    """返回同属这些租户的 user_id 集合（主库只读，绕过租户上下文）。

    🔴 v254 用途：把「账号管理」类接口收口到调用者自己的企业。
    `users` / `user_tenants` 都是**主库全局表**，而账号接口此前只判
    `role in (admin,boss)`、不判归属 ⇒ 任一租户的老板可按 uid 改**任意租户**
    乃至平台管理员账号的密码/角色/状态（跨租户接管）。本函数供收口判据使用。
    传空列表返回空集合（fail-closed：拿不到范围就不放行）。
    """
    ids = []
    for t in (tenant_ids or []):
        try:
            ids.append(int(t))
        except (ValueError, TypeError):
            continue
    if not ids:
        return set()
    con = sqlite3.connect("file:%s?mode=ro" % DB_PATH, uri=True)
    try:
        con.row_factory = sqlite3.Row
        q = "SELECT DISTINCT user_id FROM user_tenants WHERE tenant_id IN (%s)" % ",".join("?" * len(ids))
        return {r["user_id"] for r in con.execute(q, tuple(ids)).fetchall()}
    finally:
        con.close()


def generate_journal_entry(ref_type, ref_id, date_str, entries, operator_id="", db_conn=None):
    """Generate a journal entry. If db_conn is provided, uses it (caller manages transaction)."""
    if db_conn is not None:
        db = db_conn
        own = False
    else:
        _cm = get_db()
        db = _cm.__enter__()
        own = True
    try:
        no = db.execute("SELECT COUNT(*)+1 FROM journal_entries WHERE substr(created_at,1,7)=?",(date_str[:7],)).fetchone()[0]
        vno = "J"+date_str.replace("-","")+str(no).zfill(4)
        for e in entries:
            db.execute("INSERT INTO journal_entries (voucher_no,date,account_code,account_name,debit,credit,ref_type,ref_id,summary,operator_id) VALUES (?,?,?,?,?,?,?,?,?,?)",
                       (vno,date_str,e.get("code"),e.get("name",""),e.get("debit",0),e.get("credit",0),ref_type,ref_id,e.get("summary",""),operator_id))
        if own:
            db.commit()
        return vno
    finally:
        if own:
            _cm.__exit__(None, None, None)

def get_journal_entries(date_from="", date_to="", limit=100):
    with get_db() as db:
        where = []; params = []
        if date_from: where.append("date(date)>=?"); params.append(date_from)
        if date_to: where.append("date(date)<=?"); params.append(date_to)
        w = "WHERE " + " AND ".join(where) if where else ""
        return [dict(r) for r in db.execute(f"SELECT * FROM journal_entries {w} ORDER BY date DESC,id DESC LIMIT ?", params + [limit]).fetchall()]


# GL functions → db/queries/gl.py
from db.queries.gl import (init_gl, gl_post, get_gl_balance)
def _ledger_codes(codes, balances):
    """返回「真正记账的那一层」科目 code（父科目余额是派生 ⇒ 不计入合计）。

    判据与 `db/queries/finance.py::get_balance_sheet_gl._eff` 保持一致：
    有非零余额子科目 ⇒ 递归往下；子科目全零 ⇒ 父自己就是记账层
    （本账套 `1122 应收账款` 527 万就是这种形态）。
    """
    codes = list(codes)
    out = []

    def walk(code, depth):
        if depth > 8:
            out.append(code)
            return
        kids = [c for c in codes if c != code and c.startswith(code)]
        if not kids:
            out.append(code)
            return
        live = [c for c in kids if abs(balances.get(c, 0.0)) > 0.005]
        if not live:
            out.append(code)  # 子科目全零 ⇒ 钱记在父科目上
            return
        for c in live:
            walk(c, depth + 1)

    for top in [c for c in codes if not any(c != x and c.startswith(x) for x in codes)]:
        walk(top, 0)
    return out


def get_trial_balance(month=""):
    if not month: month = datetime.now().strftime("%Y-%m")
    with get_db() as db:
        coa = get_coa()
        tb = []
        dc = {}
        codes = [c["code"] for c in coa]
        for c in coa:
            de = db.execute("SELECT COALESCE(SUM(debit),0) as d,COALESCE(SUM(credit),0) as c FROM journal_entries WHERE account_code=? AND substr(date,1,7)=?",(c["code"],month)).fetchone()
            dc[c["code"]] = (de[0], de[1])
            cd = dict(c); cd["debit"]=de[0]; cd["credit"]=de[1]
            balance = de[0]-de[1]
            if c["category"] in ("资产","成本","费用"): cd["balance"]=balance
            else: cd["balance"]=-balance
            cd["balance_dir"]="借" if cd["balance"]>=0 else "贷"
            cd["balance"]=abs(cd["balance"])
            tb.append(cd)
        # v708：合计只加「记账层」科目。父科目余额是子科目的派生，
        # 父子同加会把同一笔钱算两次（实测 1002 银行存款 = 其 7 个子科目之和）。
        # rows 明细一行不动 —— 父科目行照常显示它自己的数，只是不进合计。
        keep = _ledger_codes(codes, {k: v[0] - v[1] for k, v in dc.items()})
        total_debit = sum(dc[c][0] for c in keep)
        total_credit = sum(dc[c][1] for c in keep)
        return {"rows":tb,"total_debit":total_debit,"total_credit":total_credit,"balanced":money_balanced(total_debit,total_credit),"month":month}

