def auto_journal_for_cogs(order_id, db_conn=None):
    """Post COGS journal entry on delivery: Dr COGS(6401) / Cr Inventory(1405).
    Uses actual batch cost from batch_trace when available, falls back to weighted average."""
    if db_conn is not None:
        db = db_conn; own = False
    else:
        _cm = get_db(); db = _cm.__enter__(); own = True
    try:
        o = db.execute("SELECT * FROM sale_orders WHERE id=?",(order_id,)).fetchone()
        if not o: return
        if db.execute("SELECT id FROM journal_entries WHERE ref_type='cogs' AND ref_id=?",(order_id,)).fetchone(): return
        # Try batch_trace first for actual batch-level cost
        items = db.execute(
            "SELECT bt.quantity, COALESCE(inv.cost_price, p.purchase_price, 0) as unit_cost "
            "FROM batch_trace bt "
            "JOIN products p ON bt.product_id=p.id "
            "LEFT JOIN inventory inv ON bt.batch_no=inv.batch_no AND inv.quantity>0 "
            "WHERE bt.ref_type='sale_order' AND bt.ref_id=?",
            (order_id,)
        ).fetchall()
        # Fallback: use sale_order_items × product purchase_price
        if not items:
            items = db.execute(
                "SELECT soi.quantity, COALESCE(p.purchase_price, 0) as unit_cost "
                "FROM sale_order_items soi JOIN products p ON soi.product_id=p.id "
                "WHERE soi.order_id=?", (order_id,)
            ).fetchall()
        total_cost = sum(it["quantity"] * (it["unit_cost"] or 0) for it in items)
        # v716：判据必须是「成本恰为 0」（按整数分，v705 精度口径）。
        # 退货单金额为负 ⇒ 成本也为负；原判据 `<= 0` 会把退货成本整单跳过 ⇒
        # 只冲收入、不冲成本，成本虚增、毛利被低估（副本试算实测差 2.79 个百分点）。
        if to_cents(total_cost) == 0: return
        date_str = o["order_date"][:10]
        # v711：凭证模板优先（默认模板取 `cost_amount`），否则回落硬编码。
        _entries = _voucher_entries_for("cogs", {
            "cost_amount": round(total_cost, 2), "total_cost": round(total_cost, 2),
            "order_no": o["order_no"], "ref_id": order_id,
        }, db)
        if _entries is None:
            _entries = [
                {"code": "6401", "name": "主营业务成本", "debit": round(total_cost, 2), "credit": 0,
                 "summary": f"结转销售成本 订单#{o['order_no']}"},
                {"code": "1405", "name": "库存商品", "debit": 0, "credit": round(total_cost, 2),
                 "summary": f"结转销售成本 订单#{o['order_no']}"},
            ]
        generate_journal_entry("cogs", order_id, date_str, _entries, db_conn=db)
    finally:
        if own:
            try: db.commit()
            except Exception as e: logging.getLogger("hergent").error(f"operation failed: {e}", exc_info=True)
            _cm.__exit__(None, None, None)


def gl_compensation_sweep(date_from="", date_to="", dry_run=True):
    """M2 (2026-07-25): GL 补偿扫描。

    扫描业务单据与 journal_entries 对账，凡业务表有记录而 journal_entries 缺
    对应 ref_type/ref_id 分录者，调用对应 auto_journal_* 补写（这些函数自带
    幂等检查，重复调用安全）。

    覆盖四类核心单据：
      - sale     : sale_orders(status='delivered'/'signed') 缺 'sale' 分录
      - purchase : purchase_orders(status='received'/'partial') 缺 'purchase' 分录
      - payment  : cash_flow 缺 'payment' 分录
      - cogs     : sale_orders(delivered/signed) 缺 'cogs' 分录

    Args:
        date_from/date_to: 限定业务单据日期范围(YYYY-MM-DD)，空=不限。
        dry_run: True=只报告缺失不写分录；False=实际补写。
    Returns:
        {scanned: {sale:n,...}, missing: {sale:[ids],...}, posted: {sale:m,...}, dry_run}
    """
    result = {"scanned": {}, "missing": {}, "posted": {}, "dry_run": dry_run}
    with get_db() as db:
        tbls = {r[0] for r in db.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        if 'journal_entries' not in tbls:
            return {**result, "error": "journal_entries 表不存在"}

        def _date_w(col):
            w, p = "", []
            if date_from:
                w += f" AND date({col})>=?"; p.append(date_from)
            if date_to:
                w += f" AND date({col})<=?"; p.append(date_to)
            return w, p

        # --- sale ---
        if 'sale_orders' in tbls:
            w, p = _date_w("so.order_date")
            rows = db.execute(
                f"SELECT so.id FROM sale_orders so "
                f"LEFT JOIN journal_entries je ON je.ref_type='sale' AND je.ref_id=so.id "
                f"WHERE so.status IN ('delivered','signed') AND je.id IS NULL{w}", p).fetchall()
            ids = [r["id"] for r in rows]
            result["scanned"]["sale"] = len(ids); result["missing"]["sale"] = ids
        # --- purchase ---
        if 'purchase_orders' in tbls:
            w, p = _date_w("po.order_date")
            rows = db.execute(
                f"SELECT po.id FROM purchase_orders po "
                f"LEFT JOIN journal_entries je ON je.ref_type='purchase' AND je.ref_id=po.id "
                f"WHERE po.status IN ('received','partial') AND je.id IS NULL{w}", p).fetchall()
            ids = [r["id"] for r in rows]
            result["scanned"]["purchase"] = len(ids); result["missing"]["purchase"] = ids
        # --- payment ---
        if 'cash_flow' in tbls:
            w, p = _date_w("cf.created_at")
            rows = db.execute(
                f"SELECT cf.id FROM cash_flow cf "
                f"LEFT JOIN journal_entries je ON je.ref_type='payment' AND je.ref_id=cf.id "
                f"WHERE je.id IS NULL{w}", p).fetchall()
            ids = [r["id"] for r in rows]
            result["scanned"]["payment"] = len(ids); result["missing"]["payment"] = ids
        # --- cogs ---
        if 'sale_orders' in tbls:
            w, p = _date_w("so.order_date")
            rows = db.execute(
                f"SELECT so.id FROM sale_orders so "
                f"LEFT JOIN journal_entries je ON je.ref_type='cogs' AND je.ref_id=so.id "
                f"WHERE so.status IN ('delivered','signed') AND je.id IS NULL{w}", p).fetchall()
            ids = [r["id"] for r in rows]
            result["scanned"]["cogs"] = len(ids); result["missing"]["cogs"] = ids

    if dry_run:
        return result

    # 实际补写（auto_journal_* 幂等，逐个独立事务，单条失败不阻塞其余）。
    logger = logging.getLogger("hergent")
    posted = {"sale": 0, "purchase": 0, "payment": 0, "cogs": 0}
    for oid in result["missing"].get("sale", []):
        try:
            auto_journal_for_sale(oid); posted["sale"] += 1
        except Exception as e:
            logger.warning(f"[GL sweep] sale#{oid}: {e}")
    for oid in result["missing"].get("purchase", []):
        try:
            auto_journal_for_purchase(oid); posted["purchase"] += 1
        except Exception as e:
            logger.warning(f"[GL sweep] purchase#{oid}: {e}")
    for pid in result["missing"].get("payment", []):
        try:
            auto_journal_for_payment(pid); posted["payment"] += 1
        except Exception as e:
            logger.warning(f"[GL sweep] payment#{pid}: {e}")
    for oid in result["missing"].get("cogs", []):
        try:
            auto_journal_for_cogs(oid); posted["cogs"] += 1
        except Exception as e:
            logger.warning(f"[GL sweep] cogs#{oid}: {e}")
    result["posted"] = posted
    return result


def recalculate_weighted_average_cost(product_id, db_conn=None):
    """Update product purchase_price to weighted average of inventory batches.
    Only updates if there are inventory batches with cost_price > 0."""
    if db_conn is not None:
        db = db_conn; own = False
    else:
        _cm = get_db(); db = _cm.__enter__(); own = True
    try:
        total_qty = db.execute(
            "SELECT COALESCE(SUM(quantity),0) FROM inventory WHERE product_id=? AND quantity>0",
            (product_id,)
        ).fetchone()[0]
        if total_qty <= 0: return
        total_cost = db.execute(
            "SELECT COALESCE(SUM(quantity * cost_price),0) FROM inventory WHERE product_id=? AND quantity>0",
            (product_id,)
        ).fetchone()[0]
        if total_cost <= 0: return
        avg_cost = round(total_cost / total_qty, 2)
        db.execute("UPDATE products SET purchase_price=? WHERE id=?", (avg_cost, product_id))
        if own:
            db.commit()
    finally:
        if own:
            try: db.commit()
            except Exception as e: logging.getLogger("hergent").error(f"operation failed: {e}", exc_info=True)
            _cm.__exit__(None, None, None)

# Accounting period management
def set_accounting_period(month, status="open"):
    with get_db() as db:
        db.execute("INSERT OR REPLACE INTO accounting_periods (month,status) VALUES (?,?)",(month,status)); db.commit()

def get_accounting_periods():
    with get_db() as db:
        return [dict(r) for r in db.execute("SELECT * FROM accounting_periods ORDER BY month DESC LIMIT 12").fetchall()]

def is_period_closed(month):
    with get_db() as db:
        r = db.execute("SELECT status FROM accounting_periods WHERE month=?",(month,)).fetchone()
        return r and r["status"]=="closed"

def check_period_open(month=None):
    """Raise Exception if the target accounting period is closed.
    Controlled by system_config key 'period_lock_enforced' (default '0').
    Returns the effective month string."""
    if not month:
        month = datetime.now().strftime("%Y-%m")
    # Check if lock is enforced
    try:
        with get_db() as db:
            r = db.execute("SELECT value FROM system_config WHERE key='period_lock_enforced'").fetchone()
            enforced = (r[0] == "1") if r else False
    except Exception as e:
        logging.getLogger("hergent").warning(f"query failed: {e}")
        enforced = False
    if not enforced:
        return month
    if is_period_closed(month):
        raise Exception(f"会计期间 {month} 已关闭，无法操作")
    return month

def get_tax_summary(month=""):
    """Tax summary grouped by tax_rate. If month is empty, uses current month."""
    if not month:
        month = datetime.now().strftime("%Y-%m")
    with get_db() as db:
        rows = db.execute(
            "SELECT p.tax_rate, COUNT(DISTINCT so.id) as order_count, "
            "COALESCE(SUM(soi.quantity * soi.unit_price), 0) as subtotal, "
            "COALESCE(SUM(soi.quantity * soi.unit_price * p.tax_rate / 100.0), 0) as tax_total "
            "FROM sale_order_items soi "
            "JOIN sale_orders so ON soi.order_id=so.id "
            "JOIN products p ON soi.product_id=p.id "
            "WHERE so.status IN ('delivered','signed') AND substr(so.order_date,1,7)=? "
            "GROUP BY p.tax_rate ORDER BY p.tax_rate",
            (month,)
        ).fetchall()
        return {"month": month, "rates": [dict(r) for r in rows]}

# Direct method cash flow statement
# get_cashflow_direct → db/queries/ (working module)
def get_financial_ratios():
    with get_db() as db:
        revenue = db.execute("SELECT COALESCE(SUM(total_amount),0) FROM sale_orders WHERE status IN ('delivered','signed')").fetchone()[0]
        cost = db.execute("SELECT COALESCE(SUM(soi.quantity*p.purchase_price),0) FROM sale_order_items soi JOIN sale_orders so ON soi.order_id=so.id JOIN products p ON soi.product_id=p.id WHERE so.status IN ('delivered','signed')").fetchone()[0]
        net_profit = db.execute("SELECT COALESCE(SUM(current_balance),0) FROM accounts").fetchone()[0]
        ar = db.execute("SELECT COALESCE(SUM(amount-paid_amount),0) FROM receivables WHERE type='ar' AND status!='paid'").fetchone()[0]
        ap = db.execute("SELECT COALESCE(SUM(amount-paid_amount),0) FROM receivables WHERE type='ap' AND status!='paid'").fetchone()[0]
        inventory_val = db.execute("SELECT COALESCE(SUM(i.quantity*p.purchase_price),0) FROM inventory i JOIN products p ON i.product_id=p.id").fetchone()[0]
        stock_cost = db.execute("SELECT COALESCE(SUM(soi.quantity*p.purchase_price),0) FROM sale_order_items soi JOIN sale_orders so ON soi.order_id=so.id JOIN products p ON soi.product_id=p.id WHERE so.status IN ('delivered','signed') AND so.order_date>=date('now','-30 days')").fetchone()[0]
        gross_margin = round((revenue-cost)/revenue*100,1) if revenue>0 else 0
        net_margin = round(net_profit/revenue*100,1) if revenue>0 else 0
        ar_turnover_days = round(ar/(revenue/30)) if revenue>0 else 0
        inventory_turnover_days = round(inventory_val/(stock_cost/30)) if stock_cost>0 else 0
        current_ratio = round((inventory_val+ar+net_profit)/(ap+1),1)
        return {"gross_margin":gross_margin,"net_margin":net_margin,"ar_turnover_days":ar_turnover_days,"inventory_turnover_days":inventory_turnover_days,"current_ratio":current_ratio,"revenue":revenue,"net_profit":net_profit}

# Customer profitability ranking
def get_customer_profitability():
    with get_db() as db:
        custs = db.execute("SELECT id,name FROM contacts WHERE type='customer' AND is_active=1").fetchall()
        results = []
        for c in custs:
            cd = dict(c)
            revenue = db.execute("SELECT COALESCE(SUM(so.total_amount),0) FROM sale_orders so WHERE so.customer_id=? AND so.status IN ('delivered','signed')",(cd["id"],)).fetchone()[0]
            cost = db.execute("SELECT COALESCE(SUM(soi.quantity*p.purchase_price),0) FROM sale_order_items soi JOIN sale_orders so ON soi.order_id=so.id JOIN products p ON soi.product_id=p.id WHERE so.customer_id=? AND so.status IN ('delivered','signed')",(cd["id"],)).fetchone()[0]
            profit = revenue - cost - (cd.get("allocated_cost",0) or 0)
            margin = round(profit/revenue*100,1) if revenue>0 else 0
            cd["revenue"]=revenue; cd["cost"]=cost; cd["profit"]=profit; cd["margin"]=margin
            results.append(cd)
        return sorted(results,key=lambda x: x["profit"],reverse=True)

# ============================================================
# P1: Bad debt provision, multi-currency revaluation, fixed assets
# ============================================================

def calculate_bad_debt_provision(as_of=""):
    """按账龄自动计提坏账准备。
    计提比例: 1-30天 0%, 31-60天 2%, 61-90天 5%, 91-180天 20%, 181-365天 50%, 365+天 100%"""
    if not as_of: as_of = datetime.now().strftime("%Y-%m-%d")
    from db.queries.finance import get_ar_aging
    aging = get_ar_aging()
    rates = {
        '1_30': 0.0, '31_60': 0.02, '60_plus': 0.05  # default buckets
    }
    provision = 0.0
    details = []
    for bucket, items in aging.items():
        bucket_total = sum(it.get("balance", it.get("amount", 0) - it.get("paid_amount", 0)) for it in items)
        rate = rates.get(bucket, 0.5)  # fallback for very old
        bucket_provision = round(bucket_total * rate, 2)
        provision += bucket_provision
        details.append({"bucket": bucket, "total": round(bucket_total, 2), "rate": rate, "provision": bucket_provision})
    return {"as_of": as_of, "total_provision": round(provision, 2), "details": details}

def post_bad_debt_provision(month=""):
    """计提坏账并生成分录: Dr 6602 管理费用(坏账) / Cr 1122 应收账款(坏账准备)
    注: 应在COA中新增 112201 坏账准备(资产-贷方) 科目，此处简化直接冲减1122"""
    if not month: month = datetime.now().strftime("%Y-%m")
    result = calculate_bad_debt_provision()
    provision = result["total_provision"]
    if provision <= 0: return result
    # Check + post atomically to prevent race conditions
    date_str = month + "-01"
    with get_db_tx() as db:
        existing = db.execute(
            "SELECT id FROM journal_entries WHERE ref_type='bad_debt' AND substr(date,1,7)=?",
            (month,)
        ).fetchone()
        if existing:
            return {**result, "skipped": True, "reason": f"already posted for {month}"}
        generate_journal_entry("bad_debt", 0, date_str, [
            {"code": "6602", "name": "管理费用", "debit": provision, "credit": 0, "summary": f"{month} 坏账准备计提"},
            {"code": "1122", "name": "应收账款", "debit": 0, "credit": provision, "summary": f"{month} 坏账准备计提"},
        ], db_conn=db)
    return {**result, "posted": True, "month": month}

def currency_revaluation(as_of=""):
    """多币种重估: 对有外币余额的AR/AP/银行账户按最新汇率重估，生成未实现汇兑损益分录。"""
    if not as_of: as_of = datetime.now().strftime("%Y-%m-%d")
    # Idempotency guard: skip if already generated for this month
    month = as_of[:7]
    with get_db() as check_db:
        existing = check_db.execute("SELECT id FROM journal_entries WHERE ref_type='fx_reval' AND substr(date,1,7)=?", (month,)).fetchone()
        if existing:
            return {"as_of": as_of, "total_gain_loss": 0, "items": [], "note": "本月已重估，跳过"}
    with get_db() as db:
        # Get latest exchange rates
        rates = {}
        for r in db.execute("SELECT from_currency, to_currency, rate FROM exchange_rates WHERE effective_date<=? ORDER BY effective_date DESC", (as_of,)).fetchall():
            key = (r["from_currency"], r["to_currency"])
            if key not in rates:
                rates[key] = r["rate"]

        results = []
        total_gain_loss = 0.0

        # Revalue AR (unpaid foreign currency receivables)
        ar_items = db.execute(
            "SELECT r.*, c.name FROM receivables r JOIN contacts c ON r.contact_id=c.id "
            "WHERE r.type='ar' AND r.status!='paid' AND r.amount>r.paid_amount AND r.currency_code IS NOT NULL AND r.currency_code!='' AND r.currency_code!='CNY'"
        ).fetchall()
        for item in ar_items:
            d = dict(item)
            balance = d["amount"] - d["paid_amount"]
            rate_key = (d["currency_code"], "CNY")
            if rate_key in rates:
                new_value = round(balance * rates[rate_key], 2)
                old_value = d.get("cny_amount", balance)
                diff = round(new_value - old_value, 2)
                if abs(diff) > 0.01:
                    total_gain_loss += diff
                    results.append({"type": "AR", "contact": d["name"], "currency": d["currency_code"],
                                    "balance": balance, "old_cny": old_value, "new_cny": new_value, "diff": diff})

        # Revalue AP (unpaid foreign currency payables)
        ap_items = db.execute(
            "SELECT r.*, c.name FROM receivables r JOIN contacts c ON r.contact_id=c.id "
            "WHERE r.type='ap' AND r.status!='paid' AND r.amount>r.paid_amount AND r.currency_code IS NOT NULL AND r.currency_code!='' AND r.currency_code!='CNY'"
        ).fetchall()
        for item in ap_items:
            d = dict(item)
            balance = d["amount"] - d["paid_amount"]
            rate_key = (d["currency_code"], "CNY")
            if rate_key in rates:
                new_value = round(balance * rates[rate_key], 2)
                old_value = d.get("cny_amount", balance)
                diff = round(new_value - old_value, 2)
                if abs(diff) > 0.01:
                    total_gain_loss -= diff
                    results.append({"type": "AP", "contact": d["name"], "currency": d["currency_code"],
                                    "balance": balance, "old_cny": old_value, "new_cny": new_value, "diff": -diff})

        if abs(total_gain_loss) > 0.01:
            date_str = as_of
            if total_gain_loss > 0:
                # Net gain: Dr AR / Cr 6051 (other revenue)
                generate_journal_entry("fx_reval", 0, date_str, [
                    {"code": "1122", "name": "应收账款", "debit": round(total_gain_loss, 2), "credit": 0,
                     "summary": f"外币重估汇兑收益 {as_of}"},
                    {"code": "6051", "name": "其他业务收入", "debit": 0, "credit": round(total_gain_loss, 2),
                     "summary": f"外币重估汇兑收益 {as_of}"},
                ])
            else:
                loss = -total_gain_loss
                generate_journal_entry("fx_reval", 0, date_str, [
                    {"code": "6603", "name": "财务费用", "debit": round(loss, 2), "credit": 0,
                     "summary": f"外币重估汇兑损失 {as_of}"},
                    {"code": "1122", "name": "应收账款", "debit": 0, "credit": round(loss, 2),
                     "summary": f"外币重估汇兑损失 {as_of}"},
                ])

        return {"as_of": as_of, "total_gain_loss": round(total_gain_loss, 2), "items": results, "rates_used": len(rates)}

def asset_disposal(asset_id, sale_price=0, date_str=""):
    """处置固定资产，计算处置损益并生成分录。"""
    if not date_str: date_str = datetime.now().strftime("%Y-%m-%d")
    with get_db_tx() as db:
        a = db.execute("SELECT * FROM fixed_assets WHERE id=?", (asset_id,)).fetchone()
        if not a: return {"error": "资产不存在"}
        ad = dict(a)
        book_value = ad.get("current_value", ad.get("purchase_price", 0))
        gain_loss = round(sale_price - book_value, 2)

        # Remove asset record
        db.execute("DELETE FROM fixed_assets WHERE id=?", (asset_id,))

        # Journal entries
        entries = [
            {"code": "1002", "name": "银行存款", "debit": sale_price, "credit": 0,
             "summary": f"资产处置收入 {ad['name']}"},
            {"code": "1602", "name": "累计折旧", "debit": ad.get("purchase_price", 0) - book_value, "credit": 0,
             "summary": f"冲销累计折旧 {ad['name']}"},
            {"code": "1601", "name": "固定资产", "debit": 0, "credit": ad.get("purchase_price", 0),
             "summary": f"处置固定资产 {ad['name']}"},
        ]
        if gain_loss > 0:
            entries.append({"code": "6051", "name": "其他业务收入", "debit": 0, "credit": gain_loss,
                           "summary": f"资产处置收益 {ad['name']}"})
        elif gain_loss < 0:
            entries.append({"code": "6602", "name": "管理费用", "debit": -gain_loss, "credit": 0,
                           "summary": f"资产处置损失 {ad['name']}"})

        generate_journal_entry("asset_disposal", asset_id, date_str, entries, db_conn=db)

        # Cash flow record
        if sale_price > 0:
            db.execute("INSERT INTO cash_flow (account,type,amount,category,note) VALUES ('银行','income',?,'资产处置',?)",
                      (sale_price, ad.get("name", "")))

        return {"asset": ad, "book_value": book_value, "sale_price": sale_price, "gain_loss": gain_loss}

