def init_deferred_tables():
    """Create deferred revenue/expense schedule tables."""
    with get_db() as db:
        db.executescript("""
            CREATE TABLE IF NOT EXISTS deferred_revenue (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                contract_no TEXT DEFAULT '',
                contact_id INTEGER,
                description TEXT DEFAULT '',
                total_amount REAL DEFAULT 0,
                start_date TEXT,
                end_date TEXT,
                recognized_amount REAL DEFAULT 0,
                periods INTEGER DEFAULT 12,
                period_type TEXT DEFAULT 'month',
                is_active INTEGER DEFAULT 1,
                operator_id TEXT DEFAULT '',
                created_at TEXT DEFAULT (datetime('now','localtime'))
            );
            CREATE TABLE IF NOT EXISTS deferred_expense (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                contract_no TEXT DEFAULT '',
                contact_id INTEGER,
                description TEXT DEFAULT '',
                total_amount REAL DEFAULT 0,
                start_date TEXT,
                end_date TEXT,
                recognized_amount REAL DEFAULT 0,
                periods INTEGER DEFAULT 12,
                period_type TEXT DEFAULT 'month',
                is_active INTEGER DEFAULT 1,
                operator_id TEXT DEFAULT '',
                created_at TEXT DEFAULT (datetime('now','localtime'))
            );
        """)
        db.commit()

def deferred_revenue_create(contact_id, total_amount, description='', start_date='', end_date='', periods=12, period_type='month', contract_no='', operator_id=''):
    init_deferred_tables()
    with get_db() as db:
        cid = db.execute(
            "INSERT INTO deferred_revenue (contract_no,contact_id,description,total_amount,start_date,end_date,periods,period_type,operator_id) VALUES (?,?,?,?,?,?,?,?,?)",
            (contract_no, contact_id, description, total_amount, start_date, end_date, periods, period_type, operator_id)
        ).lastrowid
        db.commit()
        return cid

def deferred_expense_create(contact_id, total_amount, description='', start_date='', end_date='', periods=12, period_type='month', contract_no='', operator_id=''):
    init_deferred_tables()
    with get_db() as db:
        cid = db.execute(
            "INSERT INTO deferred_expense (contract_no,contact_id,description,total_amount,start_date,end_date,periods,period_type,operator_id) VALUES (?,?,?,?,?,?,?,?,?)",
            (contract_no, contact_id, description, total_amount, start_date, end_date, periods, period_type, operator_id)
        ).lastrowid
        db.commit()
        return cid

def deferred_recognize(schedule_type, schedule_id, period=""):
    """Recognize one period of deferred revenue or expense.
    schedule_type: 'revenue' or 'expense'
    Generates journal entries: Dr 2203(预收账款)/Cr 6001(收入) or Dr 6602(费用)/Cr 1123(预付账款)"""
    if not period: period = datetime.now().strftime("%Y-%m")
    table = "deferred_revenue" if schedule_type == "revenue" else "deferred_expense"
    with get_db_tx() as db:
        s = db.execute(f"SELECT * FROM {table} WHERE id=? AND is_active=1", (schedule_id,)).fetchone()
        if not s: return {"error": "摊销计划不存在或已停用"}
        sd = dict(s)
        # Calculate per-period amount
        monthly = round(sd["total_amount"] / sd["periods"], 2)
        # Check if already recognized this period
        existing = db.execute(
            "SELECT id FROM journal_entries WHERE ref_type=? AND ref_id=? AND substr(date,1,7)=?",
            (f"deferred_{schedule_type}", schedule_id, period)
        ).fetchone()
        if existing: return {"skipped": True, "reason": f"already recognized for {period}"}
        # Check if fully recognized
        if sd["recognized_amount"] + monthly > sd["total_amount"]:
            monthly = round(sd["total_amount"] - sd["recognized_amount"], 2)
        if monthly <= 0: return {"skipped": True, "reason": "fully recognized"}
        # Update recognized amount
        db.execute(f"UPDATE {table} SET recognized_amount=recognized_amount+? WHERE id=?", (monthly, schedule_id))
        # Generate journal entry
        date_str = period + "-01"
        if schedule_type == "revenue":
            generate_journal_entry(f"deferred_revenue", schedule_id, date_str, [
                {"code": "2203", "name": "预收账款", "debit": monthly, "credit": 0, "summary": f"递延收入确认 {sd['description']}"},
                {"code": "6001", "name": "主营业务收入", "debit": 0, "credit": monthly, "summary": f"递延收入确认 {sd['description']}"},
            ], db_conn=db)
        else:
            generate_journal_entry(f"deferred_expense", schedule_id, date_str, [
                {"code": "6602", "name": "管理费用", "debit": monthly, "credit": 0, "summary": f"递延费用摊销 {sd['description']}"},
                {"code": "1123", "name": "预付账款", "debit": 0, "credit": monthly, "summary": f"递延费用摊销 {sd['description']}"},
            ], db_conn=db)
        return {"schedule_id": schedule_id, "type": schedule_type, "period": period, "recognized": monthly,
                "remaining": round(sd["total_amount"] - sd["recognized_amount"] - monthly, 2)}

def deferred_run_all(period=""):
    """Run recognition for all active deferred revenue/expense schedules."""
    if not period: period = datetime.now().strftime("%Y-%m")
    results = []
    with get_db() as db:
        for t in ["deferred_revenue", "deferred_expense"]:
            try:
                rows = db.execute(f"SELECT id FROM {t} WHERE is_active=1 AND recognized_amount < total_amount").fetchall()
                for r in rows:
                    stype = "revenue" if t == "deferred_revenue" else "expense"
                    res = deferred_recognize(stype, r["id"], period)
                    results.append(res)
            except Exception as e:
                results.append({"error": str(e)[:100], "table": t})
    return {"period": period, "results": results}

def get_deferred_schedules(schedule_type="revenue", limit=50):
    table = "deferred_revenue" if schedule_type == "revenue" else "deferred_expense"
    with get_db() as db:
        rows = db.execute(f"SELECT * FROM {table} ORDER BY id DESC LIMIT ?", (limit,)).fetchall()
        return [dict(r) for r in rows]

# ============================================================
# P1-9: RFQ (Request for Quotation) — 询价→报价→比价→转PO
# ============================================================

def _init_rfq_tables():
    try:
        with get_db() as db:
            db.executescript("""
                CREATE TABLE IF NOT EXISTS rfq_requests (id INTEGER PRIMARY KEY AUTOINCREMENT,description TEXT DEFAULT '',status TEXT DEFAULT 'open',operator_id TEXT DEFAULT '',created_at TEXT DEFAULT (datetime('now','localtime')));
                CREATE TABLE IF NOT EXISTS rfq_items (id INTEGER PRIMARY KEY AUTOINCREMENT,rfq_id INTEGER,product_name TEXT,quantity INTEGER,unit TEXT DEFAULT '',spec TEXT DEFAULT '');
                CREATE TABLE IF NOT EXISTS rfq_quotes (id INTEGER PRIMARY KEY AUTOINCREMENT,rfq_id INTEGER,supplier_id INTEGER,delivery_days INTEGER DEFAULT 0,note TEXT DEFAULT '',total_amount REAL DEFAULT 0,status TEXT DEFAULT 'submitted',created_at TEXT DEFAULT (datetime('now','localtime')));
                CREATE TABLE IF NOT EXISTS rfq_quote_items (id INTEGER PRIMARY KEY AUTOINCREMENT,quote_id INTEGER,product_name TEXT,quantity INTEGER,unit_price REAL DEFAULT 0,amount REAL DEFAULT 0);
            """)
            db.commit()
    except Exception: pass  # table may not exist yet (migration)

def rfq_create(description, items, operator_id=''):
    _init_rfq_tables()
    with get_db() as db:
        rid = db.execute("INSERT INTO rfq_requests (description,status,operator_id) VALUES (?,?,?)", (description, 'open', operator_id)).lastrowid
        for it in items:
            db.execute("INSERT INTO rfq_items (rfq_id,product_name,quantity,unit,spec) VALUES (?,?,?,?,?)",
                      (rid, it.get('product_name',''), it.get('quantity',0), it.get('unit',''), it.get('spec','')))
        db.commit(); return rid

def rfq_list(status='', limit=50):
    _init_rfq_tables()
    with get_db() as db:
        w = "WHERE status=?" if status else ""
        rows = db.execute(f"SELECT * FROM rfq_requests {w} ORDER BY id DESC LIMIT ?", (status, limit) if status else (limit,)).fetchall()
        result = []
        for r in rows:
            rd = dict(r)
            rd['items'] = [dict(it) for it in db.execute("SELECT * FROM rfq_items WHERE rfq_id=?", (rd['id'],)).fetchall()]
            rd['quote_count'] = db.execute("SELECT COUNT(*) FROM rfq_quotes WHERE rfq_id=?", (rd['id'],)).fetchone()[0]
            result.append(rd)
        return result

def rfq_get(rid):
    _init_rfq_tables()
    with get_db() as db:
        r = db.execute("SELECT * FROM rfq_requests WHERE id=?", (rid,)).fetchone()
        if not r: return {"error": "RFQ不存在"}
        rd = dict(r)
        rd['items'] = [dict(it) for it in db.execute("SELECT * FROM rfq_items WHERE rfq_id=?", (rid,)).fetchall()]
        rd['quotes'] = rfq_compare(rid)
        return rd

def rfq_quote_add(rid, supplier_id, items, delivery_days=0, note=''):
    _init_rfq_tables()
    with get_db() as db:
        total = sum(it.get('unit_price',0) * it.get('quantity',1) for it in items)
        qid = db.execute("INSERT INTO rfq_quotes (rfq_id,supplier_id,delivery_days,note,total_amount) VALUES (?,?,?,?,?)",
                        (rid, supplier_id, delivery_days, note, total)).lastrowid
        for it in items:
            db.execute("INSERT INTO rfq_quote_items (quote_id,product_name,quantity,unit_price,amount) VALUES (?,?,?,?,?)",
                      (qid, it.get('product_name',''), it.get('quantity',0), it.get('unit_price',0), it.get('unit_price',0)*it.get('quantity',1)))
        db.commit(); return qid

def rfq_compare(rid):
    _init_rfq_tables()
    with get_db() as db:
        quotes = [dict(q) for q in db.execute(
            "SELECT q.*, c.name as supplier_name FROM rfq_quotes q JOIN contacts c ON q.supplier_id=c.id WHERE q.rfq_id=? ORDER BY q.total_amount ASC", (rid,)
        ).fetchall()]
        for q in quotes:
            q['items'] = [dict(it) for it in db.execute("SELECT * FROM rfq_quote_items WHERE quote_id=?", (q['id'],)).fetchall()]
        return sorted(quotes, key=lambda x: x['total_amount'])

def rfq_convert_to_po(rid, qid):
    _init_rfq_tables()
    with get_db() as db:
        r = db.execute("SELECT * FROM rfq_requests WHERE id=? AND status='open'", (rid,)).fetchone()
        if not r: return {"error": "RFQ不存在或已关闭"}
        q = db.execute("SELECT * FROM rfq_quotes WHERE id=? AND rfq_id=?", (qid, rid)).fetchone()
        if not q: return {"error": "报价不存在"}
        items = [dict(it) for it in db.execute("SELECT * FROM rfq_quote_items WHERE quote_id=?", (qid,)).fetchall()]
        # Convert to purchase order. RFQ 询价商品可能尚未建档——采购转单前自动建档
        # （区别于销售/采购手工录单：那里商品缺失是数据错误必须显式报错；RFQ 的
        # 业务语义就是"为新商品询价"，故此处建档是合理默认，非静默错配）。
        # 注意：先在本连接内完成建档+状态更新并 commit，再调 purchase_order_create
        # （其自建连接），避免嵌套写连接导致 database is locked。
        from db.queries.purchases import purchase_order_create
        po_items = []
        for it in items:
            prod = db.execute("SELECT id FROM products WHERE name=? LIMIT 1", (it["product_name"],)).fetchone()
            if prod:
                pid = prod["id"]
            else:
                pid = db.execute(
                    "INSERT INTO products (name,unit,purchase_price,sale_price) VALUES (?,?,?,?)",
                    (it["product_name"], it.get("unit", "件"), it["unit_price"], it["unit_price"])).lastrowid
            po_items.append({"product_id": pid, "product_name": it["product_name"],
                             "quantity": it["quantity"], "unit_price": it["unit_price"]})
        # Close RFQ（先提交建档与状态，释放写锁）
        db.execute("UPDATE rfq_requests SET status='awarded' WHERE id=?", (rid,))
        db.execute("UPDATE rfq_quotes SET status='awarded' WHERE id=?", (qid,))
        db.commit()
        po = purchase_order_create(q['supplier_id'], po_items, note=f"RFQ#{rid} 报价#{qid}")
        return po

# ============================================================
# P1-10: 3-Way Invoice Matching — AP Invoices
# ============================================================

def _init_ap_invoice_tables():
    try:
        with get_db() as db:
            db.executescript("""
                CREATE TABLE IF NOT EXISTS ap_invoices (id INTEGER PRIMARY KEY AUTOINCREMENT,invoice_no TEXT,supplier_id INTEGER,po_id INTEGER DEFAULT 0,amount REAL DEFAULT 0,tax_amount REAL DEFAULT 0,total_amount REAL DEFAULT 0,invoice_date TEXT,note TEXT,operator_id TEXT,match_status TEXT DEFAULT 'pending',match_detail TEXT DEFAULT '',created_at TEXT DEFAULT (datetime('now','localtime')));
            """)
            db.commit()
    except Exception: pass  # table may not exist yet (migration)

def ap_invoice_create(supplier_id, po_id, invoice_no, amount, tax_amount=0, invoice_date='', note='', operator_id=''):
    _init_ap_invoice_tables()
    total = round(amount + tax_amount, 2)
    with get_db() as db:
        iid = db.execute(
            "INSERT INTO ap_invoices (invoice_no,supplier_id,po_id,amount,tax_amount,total_amount,invoice_date,note,operator_id) VALUES (?,?,?,?,?,?,?,?,?)",
            (invoice_no, supplier_id, po_id, amount, tax_amount, total, invoice_date, note, operator_id)
        ).lastrowid
        db.commit()
        # Auto-run 3-way matching
        ap_invoice_match(iid)
        return iid

def ap_invoice_match(inv_id):
    """3-way match: PO amount vs Received amount vs Invoice amount."""
    _init_ap_invoice_tables()
    with get_db() as db:
        inv = db.execute("SELECT * FROM ap_invoices WHERE id=?", (inv_id,)).fetchone()
        if not inv: return {"error": "发票不存在"}
        ind = dict(inv)
        # PO total
        po = db.execute("SELECT total_amount, status FROM purchase_orders WHERE id=?", (ind["po_id"],)).fetchone()
        po_amount = po["total_amount"] if po else 0
        po_status = po["status"] if po else "unknown"
        # Received amount (sum of received purchase_order_items × unit_price)
        recv = db.execute(
            "SELECT COALESCE(SUM(poi.received_qty * poi.unit_price),0) as received FROM purchase_order_items poi WHERE poi.order_id=?",
            (ind["po_id"],)
        ).fetchone()
        received_amount = recv[0] if recv else 0
        # Invoice amount
        invoice_amount = ind["total_amount"]
        # Matching logic
        tolerance = 0.02  # 2% tolerance
        po_match = abs(invoice_amount - po_amount) <= po_amount * tolerance if po_amount > 0 else False
        recv_match = abs(invoice_amount - received_amount) <= received_amount * tolerance if received_amount > 0 else False
        details = []
        if po_match: details.append("PO匹配")
        else: details.append(f"PO差异: PO=¥{po_amount:.2f} 发票=¥{invoice_amount:.2f}")
        if recv_match: details.append("收货匹配")
        else: details.append(f"收货差异: 已收=¥{received_amount:.2f} 发票=¥{invoice_amount:.2f}")
        match_status = "matched" if (po_match and recv_match) else ("partial" if (po_match or recv_match) else "mismatch")
        db.execute("UPDATE ap_invoices SET match_status=?, match_detail=? WHERE id=?",
                  (match_status, "; ".join(details), inv_id))
        db.commit()
        return {"invoice_id": inv_id, "match_status": match_status, "details": details,
                "po_amount": po_amount, "received_amount": received_amount, "invoice_amount": invoice_amount}

def ap_invoice_list(status='', limit=50):
    _init_ap_invoice_tables()
    with get_db() as db:
        w = "WHERE i.match_status=?" if status else ""
        params = (status, limit) if status else (limit,)
        rows = db.execute(
            f"SELECT i.*, c.name as supplier_name FROM ap_invoices i LEFT JOIN contacts c ON i.supplier_id=c.id {w} ORDER BY i.id DESC LIMIT ?",
            params
        ).fetchall()
        return [dict(r) for r in rows]

