def _init_serial_numbers():
    try:
        with get_db() as db:
            db.executescript("""
                CREATE TABLE IF NOT EXISTS serial_numbers (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    product_id INTEGER NOT NULL,
                    serial_no TEXT NOT NULL UNIQUE,
                    batch_no TEXT DEFAULT '',
                    status TEXT DEFAULT 'in_stock',
                    warehouse_id INTEGER DEFAULT 1,
                    po_id INTEGER DEFAULT 0,
                    so_id INTEGER DEFAULT 0,
                    received_date TEXT,
                    sold_date TEXT,
                    warranty_expiry TEXT,
                    note TEXT DEFAULT '',
                    created_at TEXT DEFAULT (datetime('now','localtime'))
                );
                CREATE INDEX IF NOT EXISTS idx_serial_product ON serial_numbers(product_id);
                CREATE INDEX IF NOT EXISTS idx_serial_status ON serial_numbers(status);
            """)
            db.commit()
    except Exception: pass  # table may not exist yet (migration)

def serial_receive_batch(product_id, serials, batch_no='', po_id=0, warehouse_id=1):
    """Receive a batch of serial numbers on purchase."""
    _init_serial_numbers()
    with get_db() as db:
        count = 0
        today = datetime.now().strftime("%Y-%m-%d")
        for sn in serials:
            try:
                db.execute(
                    "INSERT INTO serial_numbers (product_id,serial_no,batch_no,status,warehouse_id,po_id,received_date) VALUES (?,?,?,?,?,?,?)",
                    (product_id, sn.strip(), batch_no, 'in_stock', warehouse_id, po_id, today)
                )
                count += 1
            except Exception as e:
                logging.getLogger("hergent").debug(f"skipping row: {e}")
                # duplicate serial_no
        db.commit()
        return {"received": count, "total": len(serials)}

def serial_assign_to_sale(so_id, items):
    """Assign serial numbers to a sale order: items = [{product_id, serial_no}]."""
    _init_serial_numbers()
    with get_db() as db:
        assigned = 0
        for it in items:
            r = db.execute("UPDATE serial_numbers SET status='sold', so_id=?, sold_date=datetime('now','localtime') WHERE product_id=? AND serial_no=? AND status='in_stock'",
                          (so_id, it['product_id'], it['serial_no'].strip())).rowcount
            assigned += r
        db.commit()
        return {"assigned": assigned}

def serial_get_by_product(product_id, status='', limit=100):
    _init_serial_numbers()
    with get_db() as db:
        w = ["product_id=?"]
        params = [product_id]
        if status:
            w.append("status=?")
            params.append(status)
        where = " AND ".join(w)
        return [dict(r) for r in db.execute(f"SELECT * FROM serial_numbers WHERE {where} ORDER BY id DESC LIMIT ?", params + [limit]).fetchall()]

def serial_trace(serial_no):
    """Full lifecycle trace for a serial number."""
    _init_serial_numbers()
    with get_db() as db:
        sn = db.execute("SELECT * FROM serial_numbers WHERE serial_no=?", (serial_no,)).fetchone()
        if not sn: return {"error": "序列号不存在"}
        sd = dict(sn)
        # Get product info
        prod = db.execute("SELECT name FROM products WHERE id=?", (sd["product_id"],)).fetchone()
        sd["product_name"] = prod["name"] if prod else ""
        # Get PO/order info
        if sd.get("po_id"):
            po = db.execute("SELECT order_no FROM purchase_orders WHERE id=?", (sd["po_id"],)).fetchone()
            sd["po_no"] = po["order_no"] if po else ""
        if sd.get("so_id"):
            so = db.execute("SELECT order_no FROM sale_orders WHERE id=?", (sd["so_id"],)).fetchone()
            sd["so_no"] = so["order_no"] if so else ""
        return sd

# ============================================================
# P2-13: ABC Analysis + Cycle Counting
# ============================================================

def abc_analysis():
    """ABC classification by annual COGS (Amount×Consumption)."""
    with get_db() as db:
        # Get all active products with annual sales quantity and COGS
        rows = db.execute("""
            SELECT p.id, p.name, p.sale_price, p.purchase_price,
                   COALESCE(SUM(soi.quantity), 0) as annual_qty,
                   COALESCE(SUM(soi.quantity * soi.unit_price), 0) as annual_revenue,
                   COALESCE(SUM(soi.quantity * p.purchase_price), 0) as annual_cogs
            FROM products p
            LEFT JOIN sale_order_items soi ON p.id=soi.product_id
            LEFT JOIN sale_orders so ON soi.order_id=so.id AND so.order_date>=date('now','-1 year') AND so.status IN ('delivered','signed')
            WHERE p.is_active=1
            GROUP BY p.id
            ORDER BY annual_cogs DESC
        """).fetchall()

        items = [dict(r) for r in rows]
        total_cogs = sum(it["annual_cogs"] for it in items)
        cumulative = 0
        result = []
        for it in items:
            cumulative += it["annual_cogs"]
            pct = round(cumulative / total_cogs * 100, 1) if total_cogs > 0 else 0
            if pct <= 80:
                klass = "A"
                cycle_freq = "月度"
            elif pct <= 95:
                klass = "B"
                cycle_freq = "季度"
            else:
                klass = "C"
                cycle_freq = "年度"
            it["abc_class"] = klass
            it["cumulative_pct"] = pct
            it["cycle_count_frequency"] = cycle_freq
            result.append(it)

        a_count = sum(1 for i in result if i["abc_class"] == "A")
        b_count = sum(1 for i in result if i["abc_class"] == "B")
        c_count = sum(1 for i in result if i["abc_class"] == "C")
        return {"items": result, "total_cogs": round(total_cogs, 2),
                "class_a": a_count, "class_b": b_count, "class_c": c_count}

def generate_cycle_count_plan():
    """Generate cycle counting plan based on ABC classification."""
    abc = abc_analysis()
    plan = []
    for item in abc["items"]:
        if item["abc_class"] == "A":
            plan.append({"product_id": item["id"], "product_name": item["name"],
                        "abc_class": item["abc_class"], "frequency": "月度", "last_counted": ""})
        elif item["abc_class"] == "B":
            plan.append({"product_id": item["id"], "product_name": item["name"],
                        "abc_class": item["abc_class"], "frequency": "季度", "last_counted": ""})
        # C class: annual — skip for quarterly plans
    return {"plan": plan, "a_items": abc["class_a"], "b_items": abc["class_b"], "c_items": abc["class_c"]}

