def wave_create(warehouse_id=1, picker_id=''):
	_init_wms_tables()
	with get_db() as db:
		no = f"WAVE{datetime.now().strftime('%Y%m%d%H%M%S')}"
		wid = db.execute("INSERT INTO pick_waves (wave_no,warehouse_id,picker_id) VALUES (?,?,?)",
				(no, warehouse_id, picker_id)).lastrowid
		orders = db.execute(
			"SELECT id FROM sale_orders WHERE warehouse_id=? AND status='draft' ORDER BY order_date",
			(warehouse_id,)
		).fetchall()
		count = 0
		for o in orders:
			items = db.execute(
				"SELECT soi.product_id, soi.quantity, COALESCE(inv.bin_location,'') as bin "
				"FROM sale_order_items soi LEFT JOIN inventory inv ON soi.product_id=inv.product_id AND inv.warehouse_id=? "
				"WHERE soi.order_id=?",
				(warehouse_id, o["id"])
			).fetchall()
			for it in items:
				db.execute(
					"INSERT INTO pick_wave_items (wave_id,sale_order_id,product_id,quantity,bin_location) VALUES (?,?,?,?,?)",
					(wid, o["id"], it["product_id"], it["quantity"], it["bin"] or "")
				)
