def pick_wave_create(warehouse_id=1, order_ids=None, picker_id='', auto_reserve=True):
    """④ 仓配闭环 W1：从待拣销售单聚合生成拣货波次，并（可选）为每张单建立库存预留(W2)。

    与既有 `wave_create` 的区别：
      · 支持「指定订单」(order_ids) 而不是只能全仓 draft 一把抓；
      · 生成波次的同时按**小单位**为每张单预留库存（防超卖 / 防同一库存被多个波次重复占用）；
      · 预留失败（库存不足）⇒ 抛 ValueError ⇒ 被 get_db_tx 整波回滚（不留下半截波次）。

    order_ids 为空 ⇒ 聚合该仓全部 pickable 单（draft/confirmed/approved，与
    sale_order_deliver 发货闸门一致）。
    预留口径：用 `_qty_to_base` 折小单位，与 fefo_deduct 扣减口径一致（否则预留量错位）。
    """
    _init_wms_tables()
    from db.queries.sales import _qty_to_base
    from db.queries.reserve import reserve_stock
    with get_db_tx() as db:
        if order_ids:
            oids = [int(x) for x in order_ids]
            ph = ','.join('?' for _ in oids)
            orders = db.execute(
                "SELECT id, order_no, warehouse_id FROM sale_orders "
                "WHERE id IN (%s) AND status IN ('draft','confirmed','approved')" % ph,
                oids,
            ).fetchall()
        else:
            orders = db.execute(
                "SELECT id, order_no, warehouse_id FROM sale_orders "
                "WHERE warehouse_id=? AND status IN ('draft','confirmed','approved')",
                (warehouse_id,),
            ).fetchall()
        if not orders:
            raise ValueError("没有可拣货的订单（需 draft/confirmed/approved 状态）")
        no = _gen_no("WAVE")
        wid = db.execute(
            "INSERT INTO pick_waves (wave_no, warehouse_id, picker_id, status) VALUES (?,?,?,?)",
            (no, warehouse_id, picker_id, 'picking'),
        ).lastrowid
        item_count = 0
        for o in orders:
            items = db.execute(
                "SELECT soi.product_id, soi.quantity, soi.base_qty, soi.unit, "
                "       COALESCE(inv.bin_location,'') as bin "
                "FROM sale_order_items soi LEFT JOIN inventory inv "
                "  ON soi.product_id=inv.product_id AND inv.warehouse_id=? "
                "WHERE soi.order_id=?",
                (o['warehouse_id'], o['id']),
            ).fetchall()
            for it in items:
                db.execute(
                    "INSERT INTO pick_wave_items (wave_id, sale_order_id, product_id, quantity, bin_location, status) "
                    "VALUES (?,?,?,?,?,?)",
                    (wid, o['id'], it['product_id'], it['quantity'], it['bin'] or '', 'pending'),
                )
                item_count += 1
                if auto_reserve:
                    need = _qty_to_base(db, it['product_id'], it['quantity'], it)
                    res = reserve_stock(db, it['product_id'], o['warehouse_id'], need,
                                        'sale_order', o['id'])
                    if not res.get('ok'):
                        raise ValueError(res.get('error', '库存预留失败'))
        return {
            "wave_id": wid, "wave_no": no, "order_count": len(orders),
            "item_count": item_count, "reserved": auto_reserve,
        }


