def pick_wave_list(warehouse_id=0, status='', limit=200):
    """仓配-挑货明细：列出拣货波次及其汇总（项数/已拣/总量）。

    防御：历史租户库的 pick_wave_items 可能缺 picked_qty 列（旧 DDL 创建），
    此时已拣量按 0 计，避免 SUM 报错。缺失列由 _ensure_tenant_module_tables 的
    self-heal 补齐，补齐后本函数即可正常统计。
    """
    _init_wms_tables()  # v706：读之前先 ensure（懒建表，否则首次访问 no such table）
    with get_db() as db:
        _cols = [r[1] for r in db.execute("PRAGMA table_info(pick_wave_items)").fetchall()]
        _has_picked = "picked_qty" in _cols
        where = []
        params = []
        if warehouse_id:
            where.append("warehouse_id=?"); params.append(warehouse_id)
        if status:
            where.append("status=?"); params.append(status)
        w = " AND ".join(where) if where else "1=1"
        waves = [dict(r) for r in db.execute(
            f"SELECT * FROM pick_waves WHERE {w} ORDER BY id DESC LIMIT ?", params + [limit]).fetchall()]
        for wv in waves:
            if _has_picked:
                row = db.execute(
                    "SELECT COUNT(*) as cnt, COALESCE(SUM(picked_qty),0) as picked, COALESCE(SUM(quantity),0) as total "
                    "FROM pick_wave_items WHERE wave_id=?", (wv["id"],)).fetchone()
            else:
                row = db.execute(
                    "SELECT COUNT(*) as cnt, 0 as picked, COALESCE(SUM(quantity),0) as total "
                    "FROM pick_wave_items WHERE wave_id=?", (wv["id"],)).fetchone()
            wv["item_count"] = row["cnt"]
            wv["picked_count"] = row["picked"]
            wv["total_qty"] = row["total"]
        return waves

