_BI_MEASURES = {
	# v534（2026-10-17）：收入/利润口径对齐权威 get_profit_report（erp_db.py:3536）——
	#   一律走**明细成交额 soi.amount**。
	#   🔴 旧口径 SUM(so.total_amount) 在「订单 LEFT JOIN 明细」的**行粒度**上聚合 ⇒ 多明细
	#      订单的订单总额被按行数重复累加。生产 tenant_1 实测（22505 单/142858 行/18038 单
	#      多明细）：JOIN 口径收入 1.179 亿 vs 真实 878.6 万，**虚增 1241.8%**；商品维度最
	#      夸张一条虚增 382 万（442 万 vs 真实 60.4 万）。均单分析（AvgOrder.vue）与 ERP 面
	#      BI 仪表盘的商品/客户/月维度收入、利润、毛利率、均单全线虚高，属已上线数据错误。
	#   avg_order_value 分子同病（分母 COUNT(DISTINCT so.id) 不放大 ⇒ 均单虚高约 6.3 倍）。
	"revenue": "COALESCE(SUM(CASE WHEN so.status IN ('delivered','signed') THEN soi.amount ELSE 0 END),0)",
	"cost": "COALESCE(SUM(CASE WHEN so.status IN ('delivered','signed') THEN soi.quantity * COALESCE(p.purchase_price,0) ELSE 0 END),0)",
	"profit": "COALESCE(SUM(CASE WHEN so.status IN ('delivered','signed') THEN soi.amount - soi.quantity * COALESCE(p.purchase_price,0) ELSE 0 END),0)",
	"quantity": "COALESCE(SUM(CASE WHEN so.status IN ('delivered','signed') THEN soi.quantity ELSE 0 END),0)",
	"order_count": "COUNT(DISTINCT CASE WHEN so.status IN ('delivered','signed') THEN so.id ELSE NULL END)",
	"avg_order_value": "CASE WHEN COUNT(DISTINCT so.id)>0 THEN COALESCE(SUM(soi.amount)/COUNT(DISTINCT so.id),0) ELSE 0 END",
	"margin_pct": "CASE WHEN COALESCE(SUM(soi.amount),0)>0 THEN ROUND(100.0*COALESCE(SUM(soi.amount-soi.quantity*COALESCE(p.purchase_price,0)),0)/SUM(soi.amount),1) ELSE 0 END",
	"customer_count": "COUNT(DISTINCT so.customer_id)",
	# v534 删除 ar_balance：该指标语义是「客户级应收余额」，放在订单×明细行粒度引擎里
	#   既按行重复累加、每行又全表扫 receivables 子查询，任何维度下都无正确表达；
	#   且全仓 grep 无任何调用方（static/app.js 等命中均为 contacts 列表的同名字段）。
	#   ⚠️ 删除而非留错：留一个恒错的口径比没有更危险（会被当成真数用）。
}

_BI_DIMS = {
	"customer_name": ("c.name", "contacts c ON so.customer_id=c.id"),
	"customer_id": ("so.customer_id", ""),
	# p already in base FROM — no extra join
	"product_name": ("p.name", ""),
	"product_id": ("soi.product_id", ""),
	"brand": ("COALESCE(p.brand,'未分类')", ""),
	"category": ("COALESCE(p.category,'未分类')", ""),
	"salesperson": ("COALESCE(so.operator_id,'未分配')", ""),
	"warehouse": ("COALESCE(so.warehouse_id,1)", ""),
	"month": ("substr(so.order_date,1,7)", ""),
	"year": ("substr(so.order_date,1,4)", ""),
	"quarter": ("(substr(so.order_date,1,4)||'-Q'||((CAST(substr(so.order_date,6,2) AS INTEGER)+2)/3))", ""),
	"week": ("strftime('%Y-W%W', so.order_date)", ""),
	"date": ("date(so.order_date)", ""),
}

def _bi_from_join():
	"""Base FROM: sale_orders + items + products. Contacts joined only when needed by dimension."""
	return ("sale_orders so LEFT JOIN sale_order_items soi ON so.id=soi.order_id "
		"LEFT JOIN products p ON soi.product_id=p.id")

def _bi_where(filters):
	where, params = ["so.status IN ('delivered','signed')"], []
	fd = filters or {}
	if fd.get("date_from"):
		where.append("date(so.order_date)>=?"); params.append(fd["date_from"])
	if fd.get("date_to"):
		where.append("date(so.order_date)<=?"); params.append(fd["date_to"])
	if fd.get("customer_id"):
		where.append("so.customer_id=?"); params.append(fd["customer_id"])
	if fd.get("product_id"):
		where.append("soi.product_id=?"); params.append(fd["product_id"])
	if fd.get("brand"):
		where.append("p.brand=?"); params.append(fd["brand"])
	if fd.get("category"):
		where.append("p.category=?"); params.append(fd["category"])
	if fd.get("salesperson"):
		where.append("so.operator_id=?"); params.append(fd["salesperson"])
	return " WHERE " + " AND ".join(where), params

def bi_pivot(dimensions, measures, filters=None, limit=50, order_by=""):
	dim_cols, joins = [], []
	for dim in (dimensions or []):
		if dim in _BI_DIMS:
			col, join_sql = _BI_DIMS[dim]
			dim_cols.append(f"{col} as {dim}")
			if join_sql: joins.append(join_sql)
	meas_cols = []
	for m in (measures or ["revenue"]):
		if m in _BI_MEASURES: meas_cols.append(f"{_BI_MEASURES[m]} as {m}")
	from_clause = _bi_from_join()
	for j in [j for j in joins if j]: from_clause += " LEFT JOIN " + j
	where_sql, params = _bi_where(filters)
	dim_sel = ", ".join(dim_cols) if dim_cols else "1"
	# GROUP BY uses raw column expression (no 'as alias' — SQLite doesn't support it)
	_raw_cols = []
	for d in dim_cols:
		parts = d.rsplit(" as ", 1)
		_raw_cols.append(parts[0] if len(parts) > 1 else d)
	dim_grp = ", ".join(_raw_cols) if _raw_cols else "1"
	sql = f"SELECT {dim_sel}, {', '.join(meas_cols)} FROM {from_clause}{where_sql} GROUP BY {dim_grp}"
	# Validate order_by: only allow measure name + optional ASC/DESC
	if order_by:
		parts = order_by.split()
		if parts[0] not in _BI_MEASURES:
			order_by = f"{measures[0]} DESC" if measures else "1"
		elif len(parts) > 1 and parts[1].upper() not in ("ASC", "DESC"):
			order_by = parts[0]
	ob = order_by or (f"{measures[0]} DESC" if measures else "1")
	sql += f" ORDER BY {ob} LIMIT ?"
	params.append(limit)
	with get_db() as db:
		return [dict(r) for r in db.execute(sql, params).fetchall()]

def bi_trend(period, measures, filters=None):
	period_dim = period if period in _BI_DIMS else "month"
	col, _ = _BI_DIMS[period_dim]
	period_label = f"{col} as period"
	meas_cols = []
	for m in (measures or ["revenue", "profit"]):
		if m in _BI_MEASURES: meas_cols.append(f"{_BI_MEASURES[m]} as {m}")
	from_clause = _bi_from_join()
	where_sql, params = _bi_where(filters)
	sql = f"SELECT {period_label}, {', '.join(meas_cols)} FROM {from_clause}{where_sql} GROUP BY {col} ORDER BY {col}"
	with get_db() as db:
		return [dict(r) for r in db.execute(sql, params).fetchall()]

def bi_top_n(dimension, measure, n=10, direction="desc", filters=None):
	dim = dimension if dimension in _BI_DIMS else "customer_name"
	col, join_sql = _BI_DIMS[dim]
	meas = measure if measure in _BI_MEASURES else "revenue"
	from_clause = _bi_from_join()
	if join_sql: from_clause += " LEFT JOIN " + join_sql
	where_sql, params = _bi_where(filters)
	sql = f"SELECT {col} as {dim}, {_BI_MEASURES[meas]} as {meas} FROM {from_clause}{where_sql} GROUP BY {col} ORDER BY {meas} {'DESC' if direction=='desc' else 'ASC'} LIMIT ?"
	params.append(n)
	with get_db() as db:
		return [dict(r) for r in db.execute(sql, params).fetchall()]

def bi_breakdown(dimension, measure, filters=None):
	dim = dimension if dimension in _BI_DIMS else "category"
	col, join_sql = _BI_DIMS[dim]
	meas = measure if measure in _BI_MEASURES else "revenue"
	from_clause = _bi_from_join()
	if join_sql: from_clause += " LEFT JOIN " + join_sql
	where_sql, params = _bi_where(filters)
	sql = f"SELECT {col} as name, {_BI_MEASURES[meas]} as value FROM {from_clause}{where_sql} GROUP BY {col} ORDER BY value DESC"
	with get_db() as db:
		rows = [dict(r) for r in db.execute(sql, params).fetchall()]
		total = sum(r["value"] for r in rows)
		for r in rows: r["pct"] = round(r["value"]/total*100, 1) if total > 0 else 0
		return {"items": rows, "total": round(total, 2)}

def bi_compare(current_period, compare_type, measures):
	if not current_period: current_period = datetime.now().strftime("%Y-%m")
	curr_f = {"date_from": current_period+"-01"}
	from datetime import timedelta
	cd = datetime.strptime(current_period+"-01", "%Y-%m-%d")
	if compare_type == "mom":
		d2 = cd - timedelta(days=1)
		prev = d2.strftime("%Y-%m")
		prev_f = {"date_from": prev+"-01", "date_to": current_period+"-01"}
	elif compare_type == "yoy":
		prev = f"{int(current_period[:4])-1}-{current_period[5:]}"
		prev_f = {"date_from": prev+"-01", "date_to": prev+"-28"}
	else:
		return {"error": "compare_type must be mom or yoy"}
	curr_vals = {}
	for m in (measures or ["revenue"]):
		r = bi_trend("month", [m], curr_f)
		curr_vals[m] = round(sum(row[m] for row in r), 2) if r else 0
	prev_vals = {}
	for m in (measures or ["revenue"]):
		r = bi_trend("month", [m], prev_f)
		prev_vals[m] = round(sum(row[m] for row in r), 2) if r else 0
	changes = {}
	for m in measures:
		pv = prev_vals.get(m, 0)
		cv = curr_vals.get(m, 0)
		changes[m] = {"current": cv, "previous": pv, "change": round(cv-pv, 2),
			"change_pct": round((cv-pv)/pv*100, 1) if pv else (100 if cv>0 else 0)}
	return {"current_period": current_period, "compare_type": compare_type, "changes": changes}

def bi_kpi_dashboard(period="month", filters=None):
	from datetime import timedelta
	now = datetime.now()
	this_month = now.strftime("%Y-%m")
	last_month = (now - timedelta(days=now.day+1)).strftime("%Y-%m")
	mf = dict(filters or {}); mf["date_from"] = this_month+"-01"
	lmf = dict(filters or {}); lmf["date_from"] = last_month+"-01"; lmf["date_to"] = this_month+"-01"

	rev_curr = bi_trend("month", ["revenue"], mf)
	rev_last = bi_trend("month", ["revenue"], lmf)
	rev_val = round(sum(r["revenue"] for r in rev_curr), 2)
	rev_prev = round(sum(r["revenue"] for r in rev_last), 2)

	profit_curr = bi_trend("month", ["profit"], mf)
	profit_val = round(sum(r["profit"] for r in profit_curr), 2)

	top_cust = bi_top_n("customer_name", "revenue", 5, "desc", mf)

	with get_db() as db:
		ar_total = db.execute("SELECT COALESCE(SUM(amount-paid_amount),0) FROM receivables WHERE type='ar' AND status!='paid'").fetchone()[0]
		cash_total = db.execute("SELECT COALESCE(SUM(current_balance),0) FROM accounts").fetchone()[0]
		inventory_val = db.execute("SELECT COALESCE(SUM(i.quantity*p.purchase_price),0) FROM inventory i JOIN products p ON i.product_id=p.id").fetchone()[0]
		active_orders = db.execute("SELECT COUNT(*) FROM sale_orders WHERE status IN ('draft','delivered')").fetchone()[0]
		overdue_ar = db.execute("SELECT COALESCE(SUM(amount-paid_amount),0) FROM receivables WHERE type='ar' AND status!='paid' AND due_date!='' AND date(due_date)<date('now')").fetchone()[0]

	return {
		"period": this_month,
		"revenue": {"value": rev_val, "prev": rev_prev, "trend": "up" if rev_val>rev_prev else "down", "change_pct": round((rev_val-rev_prev)/rev_prev*100,1) if rev_prev else 0},
		"profit": {"value": profit_val},
		"margin": {"value": round(profit_val/rev_val*100,1) if rev_val>0 else 0},
		"ar_total": {"value": round(ar_total,2), "overdue": round(overdue_ar,2)},
		"cash": {"value": round(cash_total,2)},
		"inventory_value": {"value": round(inventory_val,2)},
		"active_orders": {"value": active_orders},
		"top_customers": top_cust,
	}

def _init_bi_tables():
	try:
		with get_db() as db:
			db.executescript("""
				CREATE TABLE IF NOT EXISTS bi_dashboards (
					id INTEGER PRIMARY KEY AUTOINCREMENT,
					name TEXT NOT NULL,
					config_json TEXT DEFAULT '{}',
					layout_json TEXT DEFAULT '[]',
					widgets_json TEXT DEFAULT '[]',
					is_default INTEGER DEFAULT 0,
					operator_id TEXT DEFAULT '',
					created_at TEXT DEFAULT (datetime('now','localtime'))
				);
			""")
			db.commit()
	except Exception: pass  # table may not exist yet (migration)

def bi_dashboard_save(name, config, layout, widgets, dashboard_id=0):
	_init_bi_tables()
	with get_db() as db:
		if dashboard_id:
			db.execute("UPDATE bi_dashboards SET name=?, config_json=?, layout_json=?, widgets_json=? WHERE id=?",
				   (name, json.dumps(config,ensure_ascii=False), json.dumps(layout,ensure_ascii=False), json.dumps(widgets,ensure_ascii=False), dashboard_id))
			db.commit(); return {"dashboard_id": dashboard_id}
		did = db.execute("INSERT INTO bi_dashboards (name,config_json,layout_json,widgets_json) VALUES (?,?,?,?)",
			   (name, json.dumps(config,ensure_ascii=False), json.dumps(layout,ensure_ascii=False), json.dumps(widgets,ensure_ascii=False))).lastrowid
		db.commit(); return {"dashboard_id": did}

def bi_dashboard_list():
	_init_bi_tables()
	with get_db() as db:
		return [dict(r) for r in db.execute("SELECT id, name, is_default, created_at FROM bi_dashboards ORDER BY id DESC").fetchall()]

def bi_dashboard_get(did):
	_init_bi_tables()
	with get_db() as db:
		r = db.execute("SELECT * FROM bi_dashboards WHERE id=?", (did,)).fetchone()
		if not r: return {"error": "仪表盘不存在"}
		rd = dict(r)
		try: rd["config"] = json.loads(rd.pop("config_json", "{}"))
		except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}"); rd["config"] = {}
		try: rd["layout"] = json.loads(rd.pop("layout_json", "[]"))
		except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}"); rd["layout"] = []
		try: rd["widgets"] = json.loads(rd.pop("widgets_json", "[]"))
		except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}"); rd["widgets"] = []
		return rd

def bi_dashboard_delete(did):
	_init_bi_tables()
	with get_db() as db:
		db.execute("DELETE FROM bi_dashboards WHERE id=?", (did,))
		db.commit()


