def seed_fmcg_template():
    """Seed FMCG industry template: categories, brands, attributes, promotions, COA.
    Idempotent — skips if already seeded."""
    from datetime import datetime, timedelta

    # Ensure required tables exist before seeding
    with get_db() as db:
        db.execute("CREATE TABLE IF NOT EXISTS product_categories (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,parent_id INTEGER DEFAULT 0,sort_order INTEGER DEFAULT 0,is_active INTEGER DEFAULT 1)")
        db.execute("CREATE TABLE IF NOT EXISTS promotions (id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT,start_date TEXT,end_date TEXT,discount_pct REAL DEFAULT 0,bonus_qty INTEGER DEFAULT 0,promo_type TEXT DEFAULT 'discount',buy_qty INTEGER DEFAULT 0,free_qty INTEGER DEFAULT 0,gift_product_name TEXT DEFAULT '',gift_qty INTEGER DEFAULT 0,is_active INTEGER DEFAULT 1)")
        db.execute("CREATE TABLE IF NOT EXISTS promotion_items (id INTEGER PRIMARY KEY AUTOINCREMENT,promotion_id INTEGER,product_id INTEGER)")
        db.commit()

    # Check if already seeded
    try:
        with get_db() as db:
            r = db.execute("SELECT value FROM system_config WHERE key='fmcg_seeded'").fetchone()
            if r and r["value"] == "1":
                return {"seeded": False, "message": "FMCG template already applied"}
    except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}")

    count = {"categories": 0, "brands": 0, "attributes": 0, "promotions": 0, "coa": 0, "expiry_rules": 0, "units": 0}

    # 1. Seed categories (each batch in its own TX to avoid rollback cascade)
    for parent, children in FMCG_CATEGORIES:
        try:
            with get_db() as db:
                r = db.execute("SELECT id FROM product_categories WHERE name=?", (parent,)).fetchone()
                pid = r[0] if r else db.execute("INSERT INTO product_categories (name) VALUES (?)", (parent,)).lastrowid
                for child in children:
                    db.execute("INSERT OR IGNORE INTO product_categories (name,parent_id) VALUES (?,?)", (child, pid))
                    count["categories"] += 1
                db.commit()
        except Exception: pass

    # 2. Seed brands
    for name, description in FMCG_BRANDS:
        try:
            with get_db() as db:
                r = db.execute("SELECT id FROM brands WHERE name=?", (name,)).fetchone()
                if not r:
                    db.execute("INSERT INTO brands (name,description) VALUES (?,?)", (name, description))
                    count["brands"] += 1
                    db.commit()
        except Exception: pass

    # 3. Seed COA additions
    for code, name, category, active in FMCG_COA_ADDITIONS:
        try:
            with get_db() as db:
                db.execute("INSERT OR IGNORE INTO chart_of_accounts (code,name,category,is_active) VALUES (?,?,?,?)", (code, name, category, active))
                count["coa"] += 1
                db.commit()
        except Exception: pass

    # 4. Seed promotion templates
    today = datetime.now().strftime("%Y-%m-%d")
    far_future = (datetime.now() + timedelta(days=365*10)).strftime("%Y-%m-%d")
    for tmpl in FMCG_PROMOTION_TEMPLATES:
        try:
            with get_db() as db:
                db.execute("INSERT INTO promotions (name,start_date,end_date,discount_pct,promo_type,buy_qty,free_qty,gift_product_name,gift_qty,is_active) VALUES (?,?,?,?,?,?,?,?,?,1)",
                       (tmpl["name"], today, far_future, tmpl.get("discount_pct",0), tmpl["promo_type"], tmpl.get("buy_qty",0), tmpl.get("free_qty",0), tmpl.get("gift_product_name",""), tmpl.get("gift_qty",0)))
                count["promotions"] += 1
                db.commit()
        except Exception: pass

    # 5. Mark as seeded
    with get_db() as db:
        db.execute("INSERT OR REPLACE INTO system_config (key,value) VALUES ('fmcg_seeded','1')")
        db.commit()
    return {"seeded": True, "message": f"FMCG template seeded: {count['categories']} categories, {count['brands']} brands, {count['coa']} COA accounts, {count['promotions']} promotions"}


