def offer_accept(oid):
    app_name, app_position = None, None
    with get_db_tx() as db:
        off = db.execute("SELECT * FROM hr_offers WHERE id=?", (oid,)).fetchone()
        if not off: return {"error": "Offer不存在"}
        db.execute("UPDATE hr_offers SET status='accepted', accepted_at=datetime('now','localtime') WHERE id=?", (oid,))
        db.execute("UPDATE hr_applications SET stage='hired' WHERE id=?", (off["application_id"],))
        app = db.execute("SELECT candidate_name FROM hr_applications WHERE id=?", (off["application_id"],)).fetchone()
        if app:
            app_name = app["candidate_name"]
            app_position = off["position"]
    # Create employee outside TX to avoid nested connection deadlock
    if app_name:
        try:
            eid = employee_create(app_name, position=app_position)
            return {"offer_id": oid, "status": "accepted", "employee_id": eid}
        except Exception: pass
    return {"offer_id": oid, "status": "accepted"}

