DIMENSIONS_360 = {
    "work_quality": "工作质量", "work_efficiency": "工作效率", "teamwork": "团队协作",
    "communication": "沟通能力", "initiative": "主动性", "professionalism": "职业素养",
    "leadership": "领导力", "problem_solving": "解决问题",
}

def appraisal_create(employee_id, cycle='', appraisal_type='360', evaluator_id=0):
    if not cycle: cycle = datetime.now().strftime("%Y")
    _init_recruitment_tables()
    with get_db() as db:
        aid = db.execute("INSERT INTO hr_appraisals (employee_id,cycle,appraisal_type,evaluator_id) VALUES (?,?,?,?)",
                         (employee_id, cycle, appraisal_type, evaluator_id)).lastrowid
        # Create dimension items for 360
        if appraisal_type == "360":
            for dim, label in DIMENSIONS_360.items():
                db.execute("INSERT INTO hr_appraisal_items (appraisal_id,dimension,weight) VALUES (?,?,?)",
                          (aid, label, 1.0))
        db.commit(); return aid

def appraisal_score(aid, scores, comment=''):
    """scores: {dimension_label: score}"""
    with get_db_tx() as db:
        for dim, score in scores.items():
            db.execute("UPDATE hr_appraisal_items SET score=? WHERE appraisal_id=? AND dimension=?", (float(score), aid, dim))
        total = db.execute("SELECT COALESCE(SUM(score*weight)/SUM(weight),0) FROM hr_appraisal_items WHERE appraisal_id=?", (aid,)).fetchone()[0]
        db.execute("UPDATE hr_appraisals SET scores_json=?, total_score=?, comment=? WHERE id=?",
                  (json.dumps(scores, ensure_ascii=False), round(total, 1), comment, aid))

def appraisal_finalize(aid):
    with get_db() as db:
        r = db.execute("SELECT total_score FROM hr_appraisals WHERE id=?", (aid,)).fetchone()
        if not r: return {"error": "考核不存在"}
        total = r[0]
        if total >= 90: grade = "S"; description = "卓越"
        elif total >= 80: grade = "A"; description = "优秀"
        elif total >= 70: grade = "B"; description = "良好"
        elif total >= 60: grade = "C"; description = "合格"
        else: grade = "D"; description = "需改进"
        db.execute("UPDATE hr_appraisals SET status='finalized', finalized_at=datetime('now','localtime') WHERE id=?", (aid,))
        db.commit()
        return {"appraisal_id": aid, "total_score": total, "grade": grade, "description": description}

