def ic_transaction_eliminate(tid):
    with get_db_tx() as db:
        t = db.execute("SELECT * FROM ic_transactions WHERE id=?", (tid,)).fetchone()
        if not t: return {"error": "交易不存在"}
        if t["status"] == "eliminated": return {"error": "已消除"}
        db.execute("UPDATE ic_transactions SET status='eliminated', eliminated_at=datetime('now','localtime') WHERE id=?", (tid,))
        # Generate elimination journal entries
        td = dict(t)
        date_str = td.get("trans_date", datetime.now().strftime("%Y-%m-%d"))
        # For goods/service: Dr Revenue(Cr entity from) / Cr COGS(Dr entity from) — simplified as single elimination
        if td["transaction_type"] in ("goods", "service"):
            generate_journal_entry("ic_elim", tid, date_str, [
                {"code": "6001", "name": "主营业务收入", "debit": td["amount"], "credit": 0, "summary": f"内部交易消除 #{tid}: {td['description']}"},
                {"code": "6401", "name": "主营业务成本", "debit": 0, "credit": td["amount"], "summary": f"内部交易消除 #{tid}: {td['description']}"},
            ], db_conn=db)
        elif td["transaction_type"] == "funding":
            generate_journal_entry("ic_elim", tid, date_str, [
                {"code": "1002", "name": "银行存款", "debit": 0, "credit": td["amount"], "summary": f"资金调拨消除 #{tid}"},
                {"code": "1002", "name": "银行存款", "debit": td["amount"], "credit": 0, "summary": f"资金调拨消除 #{tid}"},
            ], db_conn=db)
        return {"transaction_id": tid, "status": "eliminated"}

# ---- Consolidation ----
def _entity_total(entity_id, field, table, where_extra="", field_sum="total_amount"):
    """Helper: sum a field for a specific entity."""
    with get_db() as db:
        w = "WHERE entity_id=?" + (" AND " + where_extra if where_extra else "")
        return db.execute(f"SELECT COALESCE(SUM({field_sum}),0) FROM {table} {w}", [entity_id]).fetchone()[0] or 0

def consolidate(period="", as_of="", entity_ids=None):
    """Run full consolidation for a set of entities."""
    if not period: period = datetime.now().strftime("%Y-%m")
    if not as_of: as_of = datetime.now().strftime("%Y-%m-%d")

    entities = entity_list()
    if entity_ids:
        entities = [e for e in entities if e["id"] in entity_ids]
    if not entities:
        return {"error": "没有有效的实体"}

    # 1. Aggregate P&L from all entities
    pnl_items = []
    total_revenue, total_cogs, total_expense, total_net = 0.0, 0.0, 0.0, 0.0
    for e in entities:
        try:
            from db.queries.finance import get_pnl_gl
            ep = get_pnl_gl(period)
            pnl_items.append({"entity": e["name"], "entity_id": e["id"],
                              "revenue": ep.get("revenue", 0), "gross_profit": ep.get("gross_profit", 0),
                              "total_expense": ep.get("total_expense", 0), "net_profit": ep.get("net_profit", 0)})
            total_revenue += ep.get("revenue", 0)
            total_cogs += ep.get("cogs", 0)
            total_expense += ep.get("total_expense", 0)
            total_net += ep.get("net_profit", 0)
        except Exception as e:
            logging.getLogger("hergent").error(f"operation failed: {e}", exc_info=True)
            pnl_items.append({"entity": e["name"], "entity_id": e["id"], "revenue": 0, "gross_profit": 0, "total_expense": 0, "net_profit": 0})

    # 2. IC eliminations: total eliminated IC goods + funding
    with get_db() as db:
        ic_goods = db.execute(
            "SELECT COALESCE(SUM(amount),0) FROM ic_transactions WHERE transaction_type IN ('goods','service') AND status='eliminated' AND trans_date LIKE ?",
            (period + "%",)
        ).fetchone()[0] or 0
        ic_funding = db.execute(
            "SELECT COALESCE(SUM(amount),0) FROM ic_transactions WHERE transaction_type='funding' AND status='eliminated' AND trans_date LIKE ?",
            (period + "%",)
        ).fetchone()[0] or 0

    # 3. Consolidated BS
    bs_items = []
    total_assets, total_liabilities, total_equity = 0.0, 0.0, 0.0
    for e in entities:
        try:
            from db.queries.finance import get_balance_sheet_gl
            eb = get_balance_sheet_gl(as_of)
            assets = eb.get("assets", {}).get("total", 0)
            liab = eb.get("liabilities", {}).get("total", 0)
            eq = eb.get("equity", {}).get("total", 0)
            bs_items.append({"entity": e["name"], "entity_id": e["id"], "assets": assets, "liabilities": liab, "equity": eq})
            total_assets += assets
            total_liabilities += liab
            total_equity += eq
        except Exception as e:
            logging.getLogger("hergent").error(f"operation failed: {e}", exc_info=True)
            bs_items.append({"entity": e["name"], "entity_id": e["id"], "assets": 0, "liabilities": 0, "equity": 0})

    # 4. IC eliminations for BS: eliminate intercompany AR/AP and investments
    ic_receivable = 0.0
    with get_db() as db:
        r = db.execute("SELECT COALESCE(SUM(amount),0) FROM ic_transactions WHERE transaction_type IN ('goods','service','funding','loan') AND status='eliminated'").fetchone()
        ic_receivable = r[0] or 0

    # Eliminate IC from consolidated totals
    elim_revenue = round(ic_goods, 2)
    elim_cogs = round(ic_goods, 2)
    elim_assets = round(ic_receivable, 2)
    elim_liabilities = round(ic_receivable, 2)

    consolidated_np = round(total_net - elim_revenue + elim_cogs, 2)  # net revenue effect = 0; cost effect = 0; net profit unchanged for goods

    return {
        "period": period, "as_of": as_of, "entities": len(entities),
        "pnl": {
            "details": pnl_items,
            "aggregate": {"revenue": total_revenue, "cogs": total_cogs, "expense": total_expense, "net_profit": total_net},
            "eliminations": {"ic_revenue": elim_revenue, "ic_cogs": elim_cogs, "notes": "内部销售/服务收入与成本对销"},
            "consolidated": {"revenue": round(total_revenue - elim_revenue, 2),
                             "cogs": round(total_cogs - elim_cogs, 2),
                             "expense": total_expense,
                             "net_profit": consolidated_np}
        },
        "balance_sheet": {
            "details": bs_items,
            "aggregate": {"assets": total_assets, "liabilities": total_liabilities, "equity": total_equity},
            "eliminations": {"ic_ar_ap": round(ic_receivable, 2), "ic_investment": 0, "notes": "内部应收应付/投资对销"},
            "consolidated": {"assets": round(total_assets - elim_assets, 2),
                             "liabilities": round(total_liabilities - elim_liabilities, 2),
                             "equity": round(total_equity, 2)}
        }
    }

def consolidated_pnl(month="", entity_ids=None):
    result = consolidate(period=month, entity_ids=entity_ids)
    return result.get("pnl", {})

def consolidated_balance_sheet(as_of="", entity_ids=None):
    result = consolidate(as_of=as_of, entity_ids=entity_ids)
    return result.get("balance_sheet", {})


