def _init_project_tables():
    try:
        with get_db() as db:
            db.executescript("""
                CREATE TABLE IF NOT EXISTS proj_accounting (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    customer_id INTEGER DEFAULT 0,
                    description TEXT DEFAULT '',
                    budget REAL DEFAULT 0,
                    actual_cost REAL DEFAULT 0,
                    start_date TEXT,
                    end_date TEXT,
                    currency TEXT DEFAULT 'CNY',
                    status TEXT DEFAULT 'planning',
                    billed_amount REAL DEFAULT 0,
                    created_at TEXT DEFAULT (datetime('now','localtime'))
                );
                CREATE TABLE IF NOT EXISTS wbs_items (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    project_id INTEGER,
                    name TEXT NOT NULL,
                    parent_id INTEGER DEFAULT 0,
                    budget REAL DEFAULT 0,
                    actual_cost REAL DEFAULT 0,
                    progress_pct REAL DEFAULT 0,
                    assigned_to TEXT DEFAULT '',
                    start_date TEXT,
                    end_date TEXT,
                    status TEXT DEFAULT 'pending',
                    sort_order INTEGER DEFAULT 0,
                    created_at TEXT DEFAULT (datetime('now','localtime'))
                );
                CREATE TABLE IF NOT EXISTS timesheets (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    project_id INTEGER,
                    wbs_id INTEGER DEFAULT 0,
                    employee_id INTEGER,
                    hours REAL DEFAULT 0,
                    hourly_rate REAL DEFAULT 0,
                    cost REAL DEFAULT 0,
                    log_date TEXT,
                    description TEXT DEFAULT '',
                    status TEXT DEFAULT 'draft',
                    created_at TEXT DEFAULT (datetime('now','localtime'))
                );
                CREATE TABLE IF NOT EXISTS proj_milestones (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    project_id INTEGER,
                    name TEXT NOT NULL,
                    amount REAL DEFAULT 0,
                    due_date TEXT,
                    status TEXT DEFAULT 'pending',
                    invoice_id INTEGER DEFAULT 0,
                    invoiced_at TEXT,
                    created_at TEXT DEFAULT (datetime('now','localtime'))
                );
            """)
            db.commit()
    except Exception: pass  # table may not exist yet (migration)

# ---- Projects ----
def project_create(name, customer_id=0, description='', budget=0, start_date='', end_date='', currency='CNY', status='planning'):
    _init_project_tables()
    with get_db() as db:
        pid = db.execute("INSERT INTO proj_accounting (name,customer_id,description,budget,start_date,end_date,currency,status) VALUES (?,?,?,?,?,?,?,?)",
                         (name, customer_id, description, budget, start_date, end_date, currency, status)).lastrowid
        db.commit(); return pid

def project_list(status='', limit=50):
    _init_project_tables()
    with get_db() as db:
        w = "WHERE p.status=?" if status else ""
        params = (status, limit) if status else (limit,)
        return [dict(r) for r in db.execute(
            f"SELECT p.*, c.name as customer_name FROM proj_accounting p LEFT JOIN contacts c ON p.customer_id=c.id {w} ORDER BY p.id DESC LIMIT ?",
            params
        ).fetchall()]

def project_get(pid):
    _init_project_tables()
    with get_db() as db:
        p = db.execute("SELECT p.*, c.name as customer_name FROM proj_accounting p LEFT JOIN contacts c ON p.customer_id=c.id WHERE p.id=?", (pid,)).fetchone()
        if not p: return {"error": "项目不存在"}
        rd = dict(p)
        rd["wbs"] = wbs_list(pid)
        rd["milestones"] = milestone_list(pid)
        rd["timesheets"] = timesheet_list(pid)
        rd["budget_usage_pct"] = round(rd["actual_cost"]/rd["budget"]*100, 1) if rd["budget"] > 0 else 0
        rd["billing_pct"] = round(rd["billed_amount"]/rd["budget"]*100, 1) if rd["budget"] > 0 else 0
        return rd

def project_update_status(pid, status):
    with get_db() as db:
        db.execute("UPDATE proj_accounting SET status=? WHERE id=?", (status, pid))
        db.commit()

# ---- WBS ----
def wbs_create(project_id, name, parent_id=0, budget=0, assigned_to='', start_date='', end_date=''):
    _init_project_tables()
    with get_db() as db:
        wid = db.execute("INSERT INTO wbs_items (project_id,name,parent_id,budget,assigned_to,start_date,end_date) VALUES (?,?,?,?,?,?,?)",
                         (project_id, name, parent_id, budget, assigned_to, start_date, end_date)).lastrowid
        db.commit(); return wid

def wbs_list(project_id):
    _init_project_tables()
    with get_db() as db:
        items = [dict(r) for r in db.execute("SELECT * FROM wbs_items WHERE project_id=? ORDER BY sort_order, id", (project_id,)).fetchall()]
        # Compute WBS tree
        return _wbs_tree(items)

def _wbs_tree(items, parent_id=0):
    result = []
    for it in items:
        if it.get("parent_id", 0) == parent_id:
            node = dict(it)
            children = _wbs_tree(items, it["id"])
            if children: node["children"] = children
            result.append(node)
    return result

def wbs_update_progress(wid, progress_pct, actual_cost=0):
    with get_db() as db:
        wbs = db.execute("SELECT * FROM wbs_items WHERE id=?", (wid,)).fetchone()
        if not wbs: return
        db.execute("UPDATE wbs_items SET progress_pct=?, actual_cost=COALESCE(actual_cost,0)+?, status=CASE WHEN ?>=100 THEN 'completed' ELSE 'in_progress' END WHERE id=?",
                  (progress_pct, actual_cost, progress_pct, wid))
        # Roll up to project
        project_id = wbs["project_id"]
        total_actual = db.execute("SELECT COALESCE(SUM(actual_cost),0) FROM wbs_items WHERE project_id=?", (project_id,)).fetchone()[0]
        avg_progress = db.execute("SELECT COALESCE(AVG(progress_pct),0) FROM wbs_items WHERE project_id=? AND budget>0", (project_id,)).fetchone()[0]
        db.execute("UPDATE proj_accounting SET actual_cost=?, status=CASE WHEN ?>=100 THEN 'completed' WHEN ?>0 THEN 'in_progress' ELSE status END WHERE id=?",
                  (total_actual, avg_progress, avg_progress, project_id))
        db.commit()

# ---- Timesheets ----
def timesheet_log(project_id, employee_id=0, wbs_id=0, hours=0, log_date='', description='', hourly_rate=50):
    if not log_date: log_date = datetime.now().strftime("%Y-%m-%d")
    _init_project_tables()
    cost = round(hours * hourly_rate, 2)
    with get_db() as db:
        tid = db.execute("INSERT INTO timesheets (project_id,wbs_id,employee_id,hours,hourly_rate,cost,log_date,description) VALUES (?,?,?,?,?,?,?,?)",
                         (project_id, wbs_id, employee_id, hours, hourly_rate, cost, log_date, description)).lastrowid
        db.commit()
        # Update WBS actual cost
        if wbs_id:
            wbs_update_progress(wbs_id, 0, cost)
        return tid

def timesheet_list(project_id, employee_id=0):
    _init_project_tables()
    _init_payroll_tables()  # ensure hr_employees exists
    with get_db() as db:
        w, p = ["t.project_id=?"], [project_id]
        if employee_id: w.append("t.employee_id=?"); p.append(employee_id)
        where = " AND ".join(w)
        return [dict(r) for r in db.execute(
            f"SELECT t.*, e.name as employee_name, w.name as wbs_name FROM timesheets t LEFT JOIN hr_employees e ON t.employee_id=e.id LEFT JOIN wbs_items w ON t.wbs_id=w.id WHERE {where} ORDER BY t.log_date DESC",
            p
        ).fetchall()]

