def milestone_invoice(mid, operator_id=''):
    with get_db_tx() as db:
        m = db.execute("SELECT * FROM proj_milestones WHERE id=?", (mid,)).fetchone()
        if not m: return {"error": "里程碑不存在"}
        if m["status"] == "invoiced": return {"error": "已开票"}
        md = dict(m)
        project = db.execute("SELECT customer_id, name FROM proj_accounting WHERE id=?", (md["project_id"],)).fetchone()
        if not project: return {"error": "项目不存在"}
        # Ensure a service product exists for non-inventory billing
        svc = db.execute("SELECT id FROM products WHERE name='项目服务' LIMIT 1").fetchone()
        if not svc:
            # Q2 (2026-07-25): 不静默回退 pid=1（会把里程碑开票错配到商品1）。
            return {"error": "缺少'项目服务'商品，请先在商品档案新增名为'项目服务'的商品"}
        svc_pid = svc["id"]
        from db.queries.sales import sale_order_create
        so = sale_order_create(project["customer_id"], [
            {"product_id": svc_pid, "product_name": f"项目里程碑: {md['name']}", "quantity": 1, "unit_price": md["amount"]}
        ], note=f"项目#{md['project_id']} {project['name']} 里程碑开票")
        db.execute("UPDATE proj_milestones SET status='invoiced', invoice_id=?, invoiced_at=datetime('now','localtime') WHERE id=?",
                  (so.get("order_id", 0), mid))
        # Update project billed_amount
        total_billed = db.execute("SELECT COALESCE(SUM(amount),0) FROM proj_milestones WHERE project_id=? AND status='invoiced'", (md["project_id"],)).fetchone()[0]
        db.execute("UPDATE proj_accounting SET billed_amount=? WHERE id=?", (total_billed, md["project_id"]))
        return {"milestone_id": mid, "sale_order_id": so.get("order_id"), "amount": md["amount"]}

