def get_tags(table, record_id):
    with get_db() as db:
        r = db.execute("SELECT tags FROM dimension_tags WHERE ref_type=? AND ref_id=?",(table,record_id)).fetchone()
        return r["tags"] if r else "{}"

def get_pivot_report(metric, row_dim, col_dim, month=""):
    if not month: month = datetime.now().strftime("%Y-%m")
    with get_db() as db:
        # Get all dimension tags for sale orders in this month
        rows = db.execute("SELECT so.id,so.total_amount,soi.quantity FROM sale_orders so LEFT JOIN sale_order_items soi ON so.id=soi.order_id WHERE substr(so.order_date,1,7)=? AND so.status IN ('delivered','signed')",(month,)).fetchall()
        # Build pivot from tags
        pivot = {}
        for r in rows:
            tags = json.loads(get_tags("sale_order",r["id"]) or "{}")
            rv = tags.get(row_dim,"未分类"); cv = tags.get(col_dim,"未分类")
            key = rv+"|"+cv
            val = r["total_amount"] if metric=="amount" else r["quantity"]
            if key not in pivot: pivot[key] = 0
            pivot[key] += val
        # Convert to matrix
        row_vals = sorted(set(k.split("|")[0] for k in pivot))
        col_vals = sorted(set(k.split("|")[1] for k in pivot))
        matrix = []
        for rv in row_vals:
            row_data = {"label":rv,"values":[]}
            for cv in col_vals:
                row_data["values"].append(pivot.get(rv+"|"+cv,0))
            matrix.append(row_data)
        return {"rows":matrix,"col_labels":col_vals,"row_labels":row_vals,"metric":metric}

