def vehicle_sale_create(vehicle_id, driver_id, date_str, items, operator_id=""):
    with get_db() as db:
        total = sum(it.get("quantity",0)*it.get("unit_price",0) for it in items)
        vsid = db.execute("INSERT INTO vehicle_sales (vehicle_id,driver_id,sale_date,total_amount,status,operator_id) VALUES (?,?,?,?,?,?)",
                          (vehicle_id,driver_id,date_str,total,"loading",operator_id)).lastrowid
        for it in items:
            db.execute("INSERT INTO vehicle_sale_items (vs_id,product_id,load_qty,return_qty,sold_qty,unit_price) VALUES (?,?,?,0,0,?)",
                       (vsid,it.get("product_id",0),it.get("quantity",0),it.get("unit_price",0)))
        db.commit(); return {"id":vsid,"total":total}

