def visit_check_in(contact_id, lat, lng, note="", operator_id=""):
    db = _connect(); c = db.cursor()
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    c.execute("INSERT INTO visit_logs (contact_id,note,operator_id,lat,lng,check_in_time,created_at) VALUES (?,?,?,?,?,?,?)",
              (contact_id, note, operator_id, float(lat), float(lng), now, now))
    db.commit(); vid = c.lastrowid
    c.execute("INSERT INTO visit_tracks (visit_id,lat,lng) VALUES (?,?,?)", (vid, float(lat), float(lng)))
    db.commit(); db.close()
    return {"visit_id": vid, "check_in_time": now}

def visit_check_out(visit_id):
    db = _connect(); c = db.cursor()
    now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    c.execute("UPDATE visit_logs SET check_out_time=? WHERE id=?", (now, visit_id))
    c.execute("UPDATE visit_logs SET duration_min=ROUND((julianday(check_out_time)-julianday(check_in_time))*24*60) WHERE id=?", (visit_id,))
    db.commit(); db.close()
    return {"visit_id": visit_id, "check_out_time": now}

