# Brand management
def get_brands(include_inactive=False):
    with get_db() as db:
        sql = """
            SELECT b.*, (SELECT COUNT(*) FROM products p WHERE p.brand=b.name) as product_count
            FROM brands b
        """
        if not include_inactive:
            sql += " WHERE b.is_active=1"
        sql += " ORDER BY b.id"
        return [dict(r) for r in db.execute(sql).fetchall()]

def _ensure_brand_pending_table(db):
    """v130: 运行期懒建表 —— 历史租户库（如 tenant_1）未跑过 v28 迁移时补齐，避免 no such table -> 500。"""
    try:
        db.execute(BRAND_PENDING_DDL)
        db.commit()
        return True
    except Exception as e:
        if not _is_idempotent_migration_error(str(e)):
            logging.getLogger("hergent").warning(f"[brand_pending] ensure table failed: {e}")
        return False


def add_brand_pending(raw_name, source='', ref_count=1):
    """导入/ connectors 遇到未匹配到已有品牌的名称时入队待审（决策②：待审而非自动建）。

    v197（P2-3）：**已被忽略（dismissed）的品牌不再回队**。
      改前去重条件只有 `raw_name=? AND status='pending'`，而 `dismiss` 把行标成 'resolved'
      ⇒ 下一次 track_brand 查不到 pending 行，就**重新 INSERT 一条**：
      用户刚点过「忽略」，下次一保存同一个品牌又冒出来（实测待审队列里反复回魂）。
      而品牌档案页的忽略弹窗明确写着「这条会从待审队列移除，不再反复提示」——
      做不到就等于这句话是假的，用户只好一条条反复点，最后干脆不看这个队列。
      ⇒ 判据扩到 `status IN ('pending','dismissed')`：
        · pending   → 累加 ref_count（原语义不变）
        · dismissed → **什么都不做**（尊重用户决定，且不复活到待审列表）
      想反悔仍然通：去「档案管理 → 品牌档案」点「+ 添加品牌」手工建，
      建完 `brands` 表里就有它 ⇒ `track_brand` 第一道查询即命中、永不回队。两条路互不冲突。
    """
    raw_name = (raw_name or '').strip()
    if not raw_name:
        return None
    ref_count = int(ref_count or 1)
    with get_db() as db:
        _ensure_brand_pending_table(db)
        # pending 优先于 dismissed：理论上同一 raw_name 不该同时有两种未终态行，
        # 但历史数据（旧版 dismiss 写的是 'resolved'）可能留下歧义，故用 CASE 显式排序定序，
        # 不依赖 SQLite 的行返回顺序。
        row = db.execute(
            "SELECT id,status FROM brand_pending WHERE raw_name=? AND status IN ('pending','dismissed') "
            "ORDER BY CASE status WHEN 'pending' THEN 0 ELSE 1 END, id LIMIT 1",
            (raw_name,)).fetchone()
        if row:
            if row['status'] == 'dismissed':
                return row['id']      # 已忽略 ⇒ 保持沉默：不回队、不累加 ref_count
            db.execute("UPDATE brand_pending SET ref_count=ref_count+? WHERE id=?", (ref_count, row['id']))
            db.commit()
            return row['id']
        cur = db.execute(
            "INSERT INTO brand_pending (raw_name,source,ref_count,status,created_at) VALUES (?,?,?,'pending',datetime('now','localtime'))",
            (raw_name, source, ref_count))
        db.commit()
        return cur.lastrowid

def list_brand_pending():
    with get_db() as db:
        _ensure_brand_pending_table(db)
        return [dict(r) for r in db.execute(
            "SELECT * FROM brand_pending WHERE status='pending' ORDER BY ref_count DESC, id").fetchall()]

def resolve_brand_pending(pid, action, target_name=None):
    """处理待审品牌：create=新建为品牌并改挂商品；merge=合并到已有/新建目标品牌并改挂；dismiss=忽略。

    v197（P2-3）：`dismiss` 落**独立状态 'dismissed'**（改前是直接落到 'resolved'）。
      为什么必须与 create/merge 分开：'resolved' 的语义是「已建 / 已合并进 `brands` 表」，
      而 dismissed 的品牌**恰恰不在** `brands` 表里。两者混用一个状态，会同时坏掉两件事：
        ① `add_brand_pending` 无法判断「行存在但没有 brands 记录」到底是"用户主动忽略的"
           还是"建品牌时半途失败"——前者该沉默，后者该重试。口径混在一起只能二选一，必错一边；
        ② 任何「品牌表里有几条 / 待审还剩几条」的核查都再也算不清（同「一个状态两个含义」的经典坑）。
      'dismissed' 是 `brand_pending.status` 的**第三种取值**，列本身是 TEXT、无需迁移。
    """
    with get_db() as db:
        _ensure_brand_pending_table(db)
        row = db.execute("SELECT * FROM brand_pending WHERE id=?", (pid,)).fetchone()
        if not row:
            return {'success': False, 'error': '记录不存在'}
        raw = row['raw_name']
        canonical = raw
        if action in ('create', 'merge'):
            canonical = (target_name or raw).strip() or raw
            exist = db.execute("SELECT id FROM brands WHERE name=?", (canonical,)).fetchone()
            if not exist:
                db.execute("INSERT INTO brands (name) VALUES (?)", (canonical,))
            # 商品品牌归一：把历史脏值改挂到规范品牌（决策③：逐步归一）
            db.execute("UPDATE products SET brand=? WHERE brand=?", (canonical, raw))
        elif action == 'dismiss':
            canonical = raw      # 不建品牌、不动商品品牌 —— 只是把"这个不是品牌"这个决定记下来
        else:
            return {'success': False, 'error': '未知操作'}
        _st = 'dismissed' if action == 'dismiss' else 'resolved'
        db.execute("UPDATE brand_pending SET status=?, resolved_at=datetime('now','localtime') WHERE id=?", (_st, pid))
        db.commit()
        return {'success': True, 'canonical': canonical, 'status': _st}


def normalize_brand(raw):
    """轻量品牌归一：去首尾空白、全角空格转半角、折叠中间多空白为单空格。决策①：只做文本标准化，不强制外键。"""
    if raw is None:
        return ''
    s = str(raw).replace('\u3000', ' ').strip()
    return ' '.join(s.split())


def track_brand(raw, source=''):
    """归一品牌名；若归一后不在 brands 表中，登记到待审队列（按 raw_name+status=pending 去重累加 ref_count）。
    返回归一后的品牌名。登记失败不影响主写入流程。决策②：未匹配品牌进待审，不自动建。"""
    nb = normalize_brand(raw)
    if not nb:
        return ''
    try:
        with get_db() as db:
            row = db.execute("SELECT name FROM brands WHERE name=?", (nb,)).fetchone()
            if not row:
                add_brand_pending(nb, source=source or 'write', ref_count=1)
    except Exception as e:
        # v130: 不再静默吞异常 —— 缺表/写失败必须留痕，否则待审队列永远空而无人知晓
        logging.getLogger("hergent").warning(
            f"[track_brand] pending enqueue failed (brand={nb!r}, source={source!r}): {e}")
    return nb


