def check_duplicate_contact(name, phone):
    with get_db() as db:
        name_match = db.execute("SELECT id,name,phone FROM contacts WHERE name=? AND is_active=1",(name,)).fetchall()
        phone_match = db.execute("SELECT id,name,phone FROM contacts WHERE phone=? AND is_active=1 AND name!=?",(phone,name)).fetchall() if phone else []
