def get_archive_relations(table, record_id):
    with get_db() as db:
        relations = {}
        if table == "product":
            relations["suppliers"] = [dict(r) for r in db.execute("SELECT ps.*,c.name FROM product_suppliers ps JOIN contacts c ON ps.supplier_id=c.id WHERE ps.product_id=?",(record_id,)).fetchall()]
            relations["sales"] = [dict(r) for r in db.execute("SELECT soi.*,so.order_no,so.customer_id,c.name as customer_name FROM sale_order_items soi JOIN sale_orders so ON soi.order_id=so.id JOIN contacts c ON so.customer_id=c.id WHERE soi.product_id=? ORDER BY so.id DESC LIMIT 10",(record_id,)).fetchall()]
            relations["purchases"] = [dict(r) for r in db.execute("SELECT poi.*,po.order_no,po.supplier_id,c.name as supplier_name FROM purchase_order_items poi JOIN purchase_orders po ON poi.order_id=po.id JOIN contacts c ON po.supplier_id=c.id WHERE poi.product_id=? ORDER BY po.id DESC LIMIT 10",(record_id,)).fetchall()]
            relations["variants"] = [dict(r) for r in db.execute("SELECT * FROM product_variants WHERE product_id=? AND is_active=1",(record_id,)).fetchall()]
        elif table == "contact":
            c = db.execute("SELECT type FROM contacts WHERE id=?",(record_id,)).fetchone()
            if c and c["type"]=="customer":
                relations["orders"] = [dict(r) for r in db.execute("SELECT * FROM sale_orders WHERE customer_id=? ORDER BY id DESC LIMIT 10",(record_id,)).fetchall()]
                relations["visits"] = [dict(r) for r in db.execute("SELECT * FROM visit_logs WHERE contact_id=? ORDER BY id DESC LIMIT 10",(record_id,)).fetchall()]
            elif c and c["type"]=="supplier":
                relations["orders"] = [dict(r) for r in db.execute("SELECT * FROM purchase_orders WHERE supplier_id=? ORDER BY id DESC LIMIT 10",(record_id,)).fetchall()]
            relations["persons"] = [dict(r) for r in db.execute("SELECT * FROM contact_persons WHERE contact_id=?",(record_id,)).fetchall()]
            relations["addresses"] = [dict(r) for r in db.execute("SELECT * FROM delivery_addresses WHERE contact_id=?",(record_id,)).fetchall()]
        return relations


