def get_numbering_rules():
    with get_db() as db:
        rules = [dict(r) for r in db.execute("SELECT * FROM numbering_rules WHERE is_active=1").fetchall()]
        if not rules:
            # Default rules
            defaults = [
                ("sale_order","SO","YYYYMMDD",4),
                ("purchase_order","PO","YYYYMMDD",4),
                ("quotation","QT","YYYYMMDD",4),
                ("expense","EXP","YYYYMMDD",4),
            ]
            for d in defaults:
                db.execute("INSERT INTO numbering_rules (doc_type,prefix,date_format,seq_length) VALUES (?,?,?,?)",d)
            db.commit()
            return get_numbering_rules()
        return rules

def save_numbering_rule(doc_type, prefix, date_format, seq_length):
    with get_db() as db:
        db.execute("INSERT OR REPLACE INTO numbering_rules (doc_type,prefix,date_format,seq_length) VALUES (?,?,?,?)",(doc_type,prefix,date_format,seq_length))
        db.commit()

def gen_number(doc_type):
    with get_db() as db:
        rule = db.execute("SELECT * FROM numbering_rules WHERE doc_type=?",(doc_type,)).fetchone()
        if not rule: return doc_type.upper()+datetime.now().strftime("%Y%m%d")+"0001"
        r = dict(rule)
        now = datetime.now()
        if r["date_format"]=="YYYYMMDD": date_str = now.strftime("%Y%m%d")
        elif r["date_format"]=="YYMM": date_str = now.strftime("%y%m")
        else: date_str = now.strftime("%Y%m%d")
        count = db.execute("SELECT last_seq FROM numbering_series WHERE prefix=? AND date_str=?",(r["prefix"],date_str)).fetchone()
        seq = (count["last_seq"]+1) if count else 1
        db.execute("INSERT OR REPLACE INTO numbering_series (prefix,date_str,last_seq) VALUES (?,?,?)",(r["prefix"],date_str,seq))
        db.commit()
        return r["prefix"]+"-"+date_str+"-"+str(seq).zfill(r["seq_length"])

