# Warehouse management
def create_warehouse(name, address="", contact_name="", contact_phone="", is_default=0):
    with get_db() as db:
        wid = db.execute("INSERT INTO warehouses (name,address,contact_name,contact_phone,is_default) VALUES (?,?,?,?,?)",(name,address,contact_name,contact_phone,is_default)).lastrowid
        db.commit(); return wid
def get_warehouses_full():
    with get_db() as db:
        return [dict(r) for r in db.execute("SELECT * FROM warehouses WHERE is_default>=0 ORDER BY id").fetchall()]
def update_warehouse(wid, name=None, address=None, contact_name=None, contact_phone=None):
    """局部更新仓库主档：**None = 不动这一列，'' = 清空这一列**。

    🔴 v294（2026-09-27）：原实现四个字段一律 `COALESCE(NULLIF(?,''), 原值)` ⇒
    **空串被当成"没传"** ⇒ 在「档案管理 → 仓库档案」里把「地址」删空、点保存，
    值原样回来 —— 一个改不掉的输入框（正是本项目反复在修的那族"假"）。
    现在语义显式二分。
    ⚠️ 调用方只有 `routers/inventory.py::update_warehouse_api` 一处；
    `WarehouseUpdate` 的缺省字段是 None ⇒ 老的「只传名字」调用行为一字不变。
    """
    sets, params = [], []
    for col, val in (("name", name), ("address", address),
                     ("contact_name", contact_name), ("contact_phone", contact_phone)):
        if val is None:
            continue
        # 仓库名 NOT NULL 且有业务语义 —— 空值一律视为"没传"，绝不把它清没
        # （同时避开 NOT NULL 约束抛 IntegrityError）。
        if col == "name" and not str(val).strip():
            continue
        sets.append(f"{col}=?")
        params.append(val)
    if not sets:
        return
    params.append(wid)
    with get_db() as db:
        db.execute(f"UPDATE warehouses SET {','.join(sets)} WHERE id=?", params)
        db.commit()

def delete_warehouse(wid):
    """Delete warehouse — only if it's not the default and has no inventory."""
    with get_db() as db:
        wh = db.execute("SELECT * FROM warehouses WHERE id=?",(wid,)).fetchone()
        if not wh: return {"error": "仓库不存在"}
        if wh['is_default']: return {"error": "不能删除默认仓库"}
        inv = db.execute("SELECT COUNT(*) as cnt FROM inventory WHERE warehouse_id=? AND quantity!=0",(wid,)).fetchone()
        if inv and inv['cnt']>0: return {"error": f"仓库中还有{inv['cnt']}条库存记录，请先转移库存"}
        db.execute("DELETE FROM warehouses WHERE id=?",(wid,))
        db.commit()
        return {"success": True}

# Category tree management
def get_category_tree():
    with get_db() as db:
        cats = [dict(r) for r in db.execute("SELECT * FROM product_categories WHERE is_active=1 ORDER BY parent_id,sort_order").fetchall()]
        # Build tree
        tree = []
        for c in cats:
            if c["parent_id"]==0:
                c["children"] = [x for x in cats if x["parent_id"]==c["id"]]
                tree.append(c)
        return tree

