def _build_fts_index():
    """Build initial FTS5 index from existing data. Called once at startup."""
    try:
        with get_db() as db:
            # Check if FTS tables exist and are empty
            cnt = db.execute("SELECT COUNT(*) FROM products_fts").fetchone()[0]
            if cnt > 0:
                return  # Already indexed

            # Index products
            rows = db.execute("SELECT id, name, spec, barcode, brand, category, alias FROM products WHERE is_active=1").fetchall()
            for r in rows:
                pid = r[0]
                name = r[1] or ''
                spec = r[2] or ''
                barcode = r[3] or ''
                brand = r[4] or ''
                category = r[5] or ''
                alias = r[6] or ''
                full_py, first_py = _generate_pinyin(name)
                # Update pinyin columns
                db.execute("UPDATE products SET pinyin=?, pinyin_first=? WHERE id=?",
                          (full_py, first_py, pid))
                db.execute("INSERT INTO products_fts(name, spec, barcode, brand, category, alias, pinyin, pinyin_first, product_id) VALUES (?,?,?,?,?,?,?,?,?)",
                          (name, spec, barcode, brand, category, alias, full_py, first_py, pid))
            db.commit()

            # Index contacts
            rows = db.execute("SELECT id, name, phone FROM contacts WHERE is_active=1").fetchall()
            for r in rows:
                cid = r[0]
                name = r[1] or ''
                phone = r[2] or ''
                full_py, first_py = _generate_pinyin(name)
                db.execute("UPDATE contacts SET pinyin=?, pinyin_first=? WHERE id=?",
                          (full_py, first_py, cid))
                db.execute("INSERT INTO contacts_fts(name, phone, pinyin, pinyin_first, contact_id) VALUES (?,?,?,?,?)",
                          (name, phone, full_py, first_py, cid))
            db.commit()
    except Exception as e:
        logging.getLogger("hergent").debug(f"skipping row: {e}")
        # FTS not critical for startup


def _is_chinese(ch):
    """Check if character is in common CJK range."""
    return '一' <= ch <= '鿿'


def fts_search(query, limit=10):
    """Full-text search across products and contacts using FTS5 + pinyin."""
    results = {"products": [], "contacts": [], "sales": [], "purchases": [], "search_type": "fts"}
    if not query or len(query.strip()) < 1:
        return results

    q = query.strip()
    has_chinese = any(_is_chinese(ch) for ch in q)

    try:
        with get_db() as db:
            if has_chinese:
                # Chinese query: use LIKE (reliable for CJK, no FTS5 ICU tokenizer)
                like_q = f"%{q}%"
                prod_rows = db.execute(
                    "SELECT *, 0 as _rank FROM products WHERE is_active=1 AND "
                    "(name LIKE ? OR spec LIKE ? OR barcode LIKE ? OR brand LIKE ? OR category LIKE ?) LIMIT ?",
                    (like_q, like_q, like_q, like_q, like_q, limit)
                ).fetchall()
                results["products"] = [dict(r) for r in prod_rows]

                # Contacts: LIKE for Chinese
                contact_rows = db.execute(
                    "SELECT * FROM contacts WHERE is_active=1 AND (name LIKE ? OR phone LIKE ?) LIMIT ?",
                    (like_q, like_q, limit)
                ).fetchall()
                results["contacts"] = [dict(r) for r in contact_rows]
            else:
                # Latin/pinyin query: search FTS5 pinyin columns + name fields
                # Use prefix matching (*) to match partial pinyin input like "nfsq"
                safe_q = q.replace('"', '""').replace('*', '')

                # Products via FTS5 — prefix match on pinyin_first + name
                query_term = safe_q + '*'
                try:
                    prod_rows = db.execute(
                        "SELECT p.*, bm25(products_fts) as rank FROM products p "
                        "JOIN products_fts fts ON p.id = fts.product_id "
                        "WHERE products_fts MATCH ? ORDER BY rank LIMIT ?",
                        (query_term, limit)
                    ).fetchall()
                except Exception as e:
                    logging.getLogger("hergent").debug(f"skipping row: {e}")
                    prod_rows = []
                products = []
                for r in prod_rows:
                    d = dict(r)
                    d.pop('rank', None)
                    products.append(d)
                results["products"] = products

                # Contacts via FTS5
                try:
                    contact_rows = db.execute(
                        "SELECT c.*, bm25(contacts_fts) as rank FROM contacts c "
                        "JOIN contacts_fts fts ON c.id = fts.contact_id "
                        "WHERE contacts_fts MATCH ? ORDER BY rank LIMIT ?",
                        (query_term, limit)
                    ).fetchall()
                except Exception as e:
                    logging.getLogger("hergent").debug(f"skipping row: {e}")
                    contact_rows = []
                results["contacts"] = [dict(r) for r in contact_rows]

            # Also search sales/purchases via LIKE for backward compat
            try:
                like_q = f"%{q}%"
                sales = [dict(r) for r in db.execute(
                    "SELECT * FROM sale_orders WHERE order_no LIKE ? OR customer_name LIKE ? LIMIT 5",
                    (like_q, like_q)).fetchall()]
                results["sales"] = sales
                purchases = [dict(r) for r in db.execute(
                    "SELECT * FROM purchase_orders WHERE order_no LIKE ? OR supplier_name LIKE ? LIMIT 5",
                    (like_q, like_q)).fetchall()]
                results["purchases"] = purchases
            except Exception as e:
                logging.getLogger("hergent").debug(f"skipping row: {e}")

            # If FTS5 returned nothing for Latin queries, fallback to LIKE
            if not has_chinese and not results["products"] and not results["contacts"]:
                like_q = f"%{q}%"
                if not products:
                    prod_rows = db.execute(
                        "SELECT * FROM products WHERE is_active=1 AND "
                        "(name LIKE ? OR barcode LIKE ? OR brand LIKE ? OR pinyin LIKE ? OR pinyin_first LIKE ?) LIMIT ?",
                        (like_q, like_q, like_q, like_q, like_q, limit)
                    ).fetchall()
                    results["products"] = [dict(r) for r in prod_rows]
                if not results["contacts"]:
                    contact_rows = db.execute(
                        "SELECT * FROM contacts WHERE is_active=1 AND "
                        "(name LIKE ? OR phone LIKE ? OR pinyin LIKE ? OR pinyin_first LIKE ?) LIMIT ?",
                        (like_q, like_q, like_q, like_q, limit)
                    ).fetchall()
                    results["contacts"] = [dict(r) for r in contact_rows]

    except Exception as e:
        logging.getLogger("hergent").warning(f"query failed: {e}")
        # Return empty results on error

    return results


# Rebuild FTS index on startup (in background, non-blocking)
def _rebuild_fts_async():
    try:
        _build_fts_index()
    except Exception as e:
        logging.getLogger("hergent").debug(f"skipping row: {e}")


