# v41: 重复检测、字段验证、批量操作、归档、通知渠道、行级权限
# ============================================================

# 1. Duplicate detection (v23: fuzzy matching)
def _jaccard_bigram(s1, s2):
    """Jaccard similarity on character bigrams. Good for Chinese short texts."""
    if not s1 or not s2:
        return 0.0
    def bigrams(s):
        return set(s[i:i+2] for i in range(len(s)-1)) if len(s) >= 2 else {s}
    b1, b2 = bigrams(s1), bigrams(s2)
    if not b1 or not b2:
        return 0.0
    return len(b1 & b2) / len(b1 | b2)

def _levenshtein_norm(s1, s2):
    """Normalized Levenshtein similarity: 1 - edit_distance / max_len."""
    if not s1 or not s2:
        return 0.0
    if len(s1) > len(s2):
        s1, s2 = s2, s1
    prev = list(range(len(s2) + 1))
    for i, c1 in enumerate(s1, 1):
        curr = [i]
        for j, c2 in enumerate(s2, 1):
            curr.append(min(
                prev[j] + 1,
                curr[j-1] + 1,
                prev[j-1] + (0 if c1 == c2 else 1)
            ))
        prev = curr
    dist = prev[-1]
    max_len = max(len(s1), len(s2))
    return 1.0 - (dist / max_len)

def _fuzzy_score_names(name1, name2, phone1='', phone2=''):
    """Combined similarity score for two names. Returns 0.0-1.0."""
    jac = _jaccard_bigram(name1, name2)
    lev = _levenshtein_norm(name1, name2)
    # Pinyin similarity: compare first letters
    py1_full, py1_first = _generate_pinyin(name1)
    py2_full, py2_first = _generate_pinyin(name2)
    py_score = 1.0 if (py1_first and py2_first and py1_first == py2_first) else 0.0
    # Phone exact match
    phone_score = 1.0 if (phone1 and phone2 and phone1 == phone2) else 0.0
    # Weighted combination
    return 0.25 * jac + 0.15 * lev + 0.15 * py_score + 0.45 * phone_score

def find_duplicates(table, threshold=0.6):
    """Find fuzzy duplicate pairs. Cache results for 5 minutes."""
    import time
    cache_key = f'_dup_cache_{table}_{threshold}'
    now = time.time()
    cached = getattr(find_duplicates, cache_key, None)
    if cached and now - cached['time'] < 300:
        return cached['data']

    results = []
    try:
        with get_db() as db:
            if table == "contacts":
                rows = db.execute(
                    "SELECT id, name, phone FROM contacts WHERE is_active=1 ORDER BY name"
                ).fetchall()
                # Compare within same first-character groups
                groups = {}
                for r in rows:
                    key = r[1][0] if r[1] else '_'
                    groups.setdefault(key, []).append(r)
                for grp in groups.values():
                    for i in range(len(grp)):
                        for j in range(i+1, len(grp)):
                            rid, rname, rphone = grp[i]
                            oid, oname, ophone = grp[j]
                            score = _fuzzy_score_names(rname, oname, rphone or '', ophone or '')
                            if score >= threshold:
                                results.append({
                                    'id1': rid, 'name1': rname, 'phone1': rphone,
                                    'id2': oid, 'name2': oname, 'phone2': ophone,
                                    'score': round(score, 2), 'table': 'contacts'
                                })
            else:  # products
                rows = db.execute(
                    "SELECT id, name, barcode FROM products WHERE is_active=1 ORDER BY name"
                ).fetchall()
                groups = {}
                for r in rows:
                    key = r[1][0] if r[1] else '_'
                    groups.setdefault(key, []).append(r)
                for grp in groups.values():
                    for i in range(len(grp)):
                        for j in range(i+1, len(grp)):
                            rid, rname, rbarcode = grp[i]
                            oid, oname, obarcode = grp[j]
                            score = _fuzzy_score_names(rname, oname, rbarcode or '', obarcode or '')
                            if score >= threshold:
                                results.append({
                                    'id1': rid, 'name1': rname, 'barcode1': rbarcode,
                                    'id2': oid, 'name2': oname, 'barcode2': obarcode,
                                    'score': round(score, 2), 'table': 'products'
                                })
        # Sort by score descending, limit to 50
        results.sort(key=lambda x: x['score'], reverse=True)
        results = results[:50]
    except Exception as e:
        logging.getLogger("hergent").warning(f"query failed: {e}")

    setattr(find_duplicates, cache_key, {'time': now, 'data': results})
    return results

def get_merge_preview(table, master_id, dup_id):
    """Return side-by-side comparison of two records for merge preview."""
    try:
        with get_db() as db:
            if table == "contacts":
                m = db.execute("SELECT * FROM contacts WHERE id=? AND is_active=1", (master_id,)).fetchone()
                d = db.execute("SELECT * FROM contacts WHERE id=? AND is_active=1", (dup_id,)).fetchone()
                if not m or not d:
                    return None
                # Count related records
                related = {}
                for tname, col in [("sale_orders","customer_id"),("visit_logs","contact_id"),
                                   ("cash_flow","contact_id"),("receivables","contact_id"),
                                   ("delivery_addresses","contact_id"),("contact_persons","contact_id")]:
                    cnt = db.execute(f"SELECT COUNT(*) FROM {tname} WHERE {col}=?", (dup_id,)).fetchone()[0]
                    if cnt > 0:
                        related[tname] = cnt
                return {
                    "master": dict(m), "duplicate": dict(d),
                    "related_records": related, "table": "contacts"
                }
            else:
                m = db.execute("SELECT * FROM products WHERE id=? AND is_active=1", (master_id,)).fetchone()
                d = db.execute("SELECT * FROM products WHERE id=? AND is_active=1", (dup_id,)).fetchone()
                if not m or not d:
                    return None
                related = {}
                for tname, col in [("sale_order_items","product_id"),("purchase_order_items","product_id"),
                                   ("inventory","product_id"),("product_suppliers","product_id")]:
                    cnt = db.execute(f"SELECT COUNT(*) FROM {tname} WHERE {col}=?", (dup_id,)).fetchone()[0]
                    if cnt > 0:
                        related[tname] = cnt
                return {
                    "master": dict(m), "duplicate": dict(d),
                    "related_records": related, "table": "products"
                }
    except Exception as e:
        logging.getLogger("hergent").warning(f"query failed: {e}")
        return None

def merge_contacts(master_id, duplicate_id, operator_id=''):
    with get_db() as db:
        # Merge non-empty fields from duplicate into master
        dup = db.execute("SELECT * FROM contacts WHERE id=?", (duplicate_id,)).fetchone()
        mast = db.execute("SELECT * FROM contacts WHERE id=?", (master_id,)).fetchone()
        if dup and mast:
            fields_to_merge = ['phone', 'phone2', 'address', 'region', 'settlement_method',
                              'credit_days', 'industry', 'wechat', 'tax_id', 'tags', 'note', 'email']
            for f in fields_to_merge:
                dup_val = dict(dup).get(f, '')
                mast_val = dict(mast).get(f, '')
                if dup_val and not mast_val:
                    try:
                        db.execute(f"UPDATE contacts SET {f}=? WHERE id=?", (dup_val, master_id))
                    except Exception as e:
                        logging.getLogger("hergent").debug(f"skipping row: {e}")
        # Move all related records to master
        for t, col in [("sale_orders","customer_id"),("visit_logs","contact_id"),
                       ("cash_flow","contact_id"),("receivables","contact_id"),
                       ("delivery_addresses","contact_id"),("contact_persons","contact_id")]:
            try:
                db.execute(f"UPDATE {t} SET {col}=? WHERE {col}=?", (master_id, duplicate_id))
            except Exception as e:
                logging.getLogger("hergent").debug(f"skipping row: {e}")
        db.execute("UPDATE contacts SET is_active=0 WHERE id=?", (duplicate_id,))
        # Log merge
        try:
            db.execute(
                "INSERT INTO merge_log (table_name, master_id, duplicate_id, operator_id) VALUES ('contacts',?,?,?)",
                (master_id, duplicate_id, operator_id or ''))
        except Exception as e:
            logging.getLogger("hergent").debug(f"skipping row: {e}")
        db.commit()
    return {"success": True, "master_id": master_id}

def merge_products(master_id, duplicate_id, operator_id=''):
    with get_db() as db:
        # Merge non-empty fields from duplicate into master
        dup = db.execute("SELECT * FROM products WHERE id=?", (duplicate_id,)).fetchone()
        mast = db.execute("SELECT * FROM products WHERE id=?", (master_id,)).fetchone()
        if dup and mast:
            fields_to_merge = ['spec', 'barcode', 'brand', 'category', 'description',
                              'image_url', 'image_url2', 'image_url3', 'alias', 'mnemonic',
                              'weight_kg', 'volume_m3', 'tax_code_id',
                              # v233：`order_unit`（报单单位）与 `alias`/`mnemonic` 同类 ——
                              #   都是「人工在档案里维护的、不覆盖已有值」的字段。不列进来
                              #   ⇒ 合并两个重复商品时，重复品上人工指定的报单单位被**静默丢弃**
                              #   （master 侧为空 → 合并后仍为空 → 无人报错、无从察觉）。
                              'order_unit']
            for f in fields_to_merge:
                dup_val = dict(dup).get(f, '')
                mast_val = dict(mast).get(f, '')
                if dup_val and not mast_val:
                    try:
                        db.execute(f"UPDATE products SET {f}=? WHERE id=?", (dup_val, master_id))
                    except Exception as e:
                        logging.getLogger("hergent").debug(f"skipping row: {e}")
        # Move related records
        for t, col in [("sale_order_items","product_id"),("purchase_order_items","product_id"),
                       ("inventory","product_id"),("product_suppliers","product_id")]:
            try:
                db.execute(f"UPDATE {t} SET {col}=? WHERE {col}=?", (master_id, duplicate_id))
            except Exception as e:
                logging.getLogger("hergent").debug(f"skipping row: {e}")
        db.execute("UPDATE products SET is_active=0 WHERE id=?", (duplicate_id,))
        try:
            db.execute(
                "INSERT INTO merge_log (table_name, master_id, duplicate_id, operator_id) VALUES ('products',?,?,?)",
                (master_id, duplicate_id, operator_id or ''))
        except Exception as e:
            logging.getLogger("hergent").debug(f"skipping row: {e}")
        db.commit()
    return {"success": True, "master_id": master_id}

def check_quick_duplicate(table, name, phone=''):
    """Quick single-record fuzzy check. Returns top matches above threshold."""
    results = []
    threshold = 0.65
    try:
        with get_db() as db:
            if table == "contacts":
                rows = db.execute(
                    "SELECT id, name, phone FROM contacts WHERE is_active=1 AND id != (SELECT MAX(id) FROM contacts) LIMIT 500"
                ).fetchall()
                for r in rows:
                    score = _fuzzy_score_names(name, r[1], phone or '', r[2] or '')
                    if score >= threshold:
                        results.append({'id': r[0], 'name': r[1], 'phone': r[2], 'score': round(score, 2)})
            else:
                rows = db.execute(
                    "SELECT id, name, barcode FROM products WHERE is_active=1 LIMIT 500"
                ).fetchall()
                for r in rows:
                    score = _fuzzy_score_names(name, r[1], phone or '', r[2] or '')
                    if score >= threshold:
                        results.append({'id': r[0], 'name': r[1], 'barcode': r[2], 'score': round(score, 2)})
        results.sort(key=lambda x: x['score'], reverse=True)
        results = results[:5]
    except Exception as e:
        logging.getLogger("hergent").warning(f"query failed: {e}")
    return results

