# --- Product Options ---
def set_product_options(product_id, option_type_ids):
    """Set option dimensions for a product. option_type_ids = [1, 2] = flavor x size."""
    with get_db() as db:
        db.execute("DELETE FROM product_options WHERE product_id=?", (product_id,))
        for oid in option_type_ids:
            db.execute("INSERT INTO product_options (product_id, option_type_id) VALUES (?,?)",
                      (product_id, oid))
        db.commit()

def get_product_options(product_id):
    """Get option dimensions for a product."""
    with get_db() as db:
        return [dict(r) for r in db.execute(
            "SELECT ot.* FROM option_types ot JOIN product_options po ON ot.id=po.option_type_id "
            "WHERE po.product_id=? ORDER BY ot.sort_order",
            (product_id,)
        ).fetchall()]

# --- Variant Matrix ---
def generate_variant_matrix(product_id, base_sale_price=None, base_purchase_price=None):
    """Auto-generate all variant combinations for a product's option dimensions."""
    import json, itertools
    with get_db() as db:
        # Get product base prices if not provided
        if base_sale_price is None or base_purchase_price is None:
            prod = db.execute("SELECT sale_price, purchase_price FROM products WHERE id=?",
                            (product_id,)).fetchone()
            if prod:
                if base_sale_price is None:
                    base_sale_price = prod[0] or 0
                if base_purchase_price is None:
                    base_purchase_price = prod[1] or 0

        option_types = get_product_options(product_id)
        if not option_types:
            return {"success": False, "error": "请先设置商品的选项维度"}

        # Collect values per option type
        values_per_type = []
        for ot in option_types:
            vals = [dict(r) for r in db.execute(
                "SELECT * FROM option_values WHERE option_type_id=? ORDER BY sort_order",
                (ot["id"],)
            ).fetchall()]
            if vals:
                values_per_type.append({"type_name": ot["name"], "values": vals})

        if not values_per_type:
            return {"success": False, "error": "选项类型未定义可选值"}

        # Cartesian product
        all_values = [v["values"] for v in values_per_type]
        combinations = list(itertools.product(*all_values))

        created, skipped = 0, 0
        for combo in combinations:
            name_parts, option_pairs = [], {}
            for i, vt in enumerate(values_per_type):
                name_parts.append(combo[i]["value"])
                option_pairs[vt["type_name"]] = combo[i]["value"]

            variant_name = " ".join(name_parts)
            existing = db.execute(
                "SELECT id FROM product_variants WHERE product_id=? AND name=?",
                (product_id, variant_name)
            ).fetchone()
            if existing:
                skipped += 1
                continue

            db.execute(
                "INSERT INTO product_variants (product_id, name, sale_price, purchase_price, option_values) "
                "VALUES (?,?,?,?,?)",
                (product_id, variant_name, base_sale_price, base_purchase_price,
                 json.dumps(option_pairs, ensure_ascii=False))
            )
            created += 1

        db.commit()
        return {"success": True, "created": created, "skipped": skipped,
                "combinations": len(combinations), "product_id": product_id}

def get_product_variants_full(product_id):
    """Get all variants for a product with full detail."""
    with get_db() as db:
        return [dict(r) for r in db.execute(
            "SELECT * FROM product_variants WHERE product_id=? AND is_active=1 ORDER BY id",
            (product_id,)
        ).fetchall()]

def update_variant(variant_id, **kw):
    """Update variant fields: sku, barcode, sale_price, purchase_price, image_url, is_active."""
    allowed = ['sku', 'barcode', 'sale_price', 'purchase_price', 'image_url', 'is_active']
    updates, params = [], []
    for k, v in kw.items():
        if k in allowed:
            updates.append(f"{k}=?")
            params.append(v)
    if not updates:
        return {"updated": 0}
    with get_db() as db:
        params.append(variant_id)
        db.execute(f"UPDATE product_variants SET {','.join(updates)} WHERE id=?", params)
        db.commit()
        return {"updated": 1}

# --- Customer Hierarchy ---
def set_customer_parent(contact_id, parent_id):
    """Set parent customer for a contact."""
    with get_db() as db:
        db.execute("UPDATE contacts SET parent_id=? WHERE id=?", (parent_id, contact_id))
        db.commit()
        return {"success": True}

def get_customer_children(parent_id):
    """Get direct children of a customer."""
    # v107.33 修复: ar_balance/last_order 是计算列(联表子查询), store_status 租户库可能无 —
    # 直接 SELECT 真实不存在列 → no such column 500; 前端仅用 id/name/phone/type/credit_limit
    with get_db() as db:
        return [dict(r) for r in db.execute(
            "SELECT id, name, phone, type, credit_limit "
            "FROM contacts WHERE parent_id=? AND is_active=1 ORDER BY name",
            (parent_id,)
        ).fetchall()]

def get_customer_tree():
    """Get customer hierarchy tree."""
    with get_db() as db:
        roots = [dict(r) for r in db.execute(
            "SELECT id, name, phone, type, credit_limit, price_level "
            "FROM contacts WHERE (parent_id=0 OR parent_id IS NULL) AND is_active=1 "
            "AND type IN ('customer','both') ORDER BY name"
        ).fetchall()]
        for node in roots:
            children = get_customer_children(node["id"])
            if children:
                node["children"] = [{
                    "id": c["id"], "name": c["name"], "phone": c.get("phone",""),
                    "type": c.get("type","customer"),
                    "credit_limit": c.get("credit_limit",0),
                    "store_status": c.get("store_status",""),
                } for c in children]
        return roots

def _collect_descendant_ids(parent_id, db):
    """Recursively collect all descendant IDs for hierarchy credit checking."""
    ids = [parent_id]
    children = db.execute(
        "SELECT id FROM contacts WHERE parent_id=? AND is_active=1", (parent_id,)
    ).fetchall()
    for c in children:
        ids.extend(_collect_descendant_ids(c[0], db))
    return ids

def get_hierarchy_ar(parent_id):
    """Get total AR across a hierarchy subtree."""
    with get_db() as db:
        all_ids = _collect_descendant_ids(parent_id, db) if parent_id > 0 else []
        if not all_ids:
            return {"parent_id": parent_id, "descendant_count": 0, "total_ar": 0}
        placeholders = ",".join("?" * len(all_ids))
        total_ar = db.execute(
            f"SELECT COALESCE(SUM(amount-paid_amount),0) FROM receivables "
            f"WHERE contact_id IN ({placeholders}) AND type='ar' AND status!='paid'",
            all_ids
        ).fetchone()[0] or 0
        return {"parent_id": parent_id, "descendant_count": len(all_ids)-1,
                "total_ar": round(float(total_ar), 2)}

def check_hierarchy_credit(customer_id, total_amount):
    """Check credit including hierarchy (parent's shared limit)."""
    with get_db() as db:
        cust = db.execute("SELECT * FROM contacts WHERE id=?", (customer_id,)).fetchone()
        if not cust:
            return True, ""
        cust = dict(cust)

        # Check own credit limit
        credit_limit = cust.get('credit_limit', 0) or 0
        if credit_limit > 0:
            current_ar = db.execute(
                "SELECT COALESCE(SUM(amount-paid_amount),0) FROM receivables "
                "WHERE contact_id=? AND type='ar' AND status!='paid'",
                (customer_id,)
            ).fetchone()[0] or 0
            if current_ar + total_amount > credit_limit:
                return False, f"超信用额度（可用¥{credit_limit - current_ar:.0f}，本次¥{total_amount:.0f}）"

        # Check parent hierarchy credit if shared
        parent_id = cust.get('parent_id', 0) or 0
        shared = cust.get('shared_credit_limit', 0) or 0
        if parent_id > 0 and shared == 1:
            parent = db.execute("SELECT * FROM contacts WHERE id=?", (parent_id,)).fetchone()
            if parent:
                plimit = parent['credit_limit'] or 0
                if plimit > 0:
                    all_ids = _collect_descendant_ids(parent_id, db)
                    placeholders = ",".join("?" * len(all_ids))
                    total_ar = db.execute(
                        f"SELECT COALESCE(SUM(amount-paid_amount),0) FROM receivables "
                        f"WHERE contact_id IN ({placeholders}) AND type='ar' AND status!='paid'",
                        all_ids
                    ).fetchone()[0] or 0
                    if total_ar + total_amount > plimit:
                        return False, f"总部信用额度不足（总限额¥{plimit:.0f}，已用¥{total_ar:.0f}）"

        return True, ""



