# ============================================================
# v25: 返利合同体系 + 批次追溯
# ============================================================

import json
from datetime import datetime

# --- Rebate Contract: Tier Management ---
def save_rebate_tiers(contract_id, tiers):
    """Save tiered rebate config. tiers = [{"min_amount":0,"max_amount":100000,"pct":3},...]"""
    with get_db() as db:
        db.execute("UPDATE rebate_contracts SET tiers_json=? WHERE id=?", (json.dumps(tiers), contract_id))
        db.commit()
        return {"success": True}

def calc_rebate_amount(contract, achieved):
    """年度合同阶梯累进返利。算法收敛到 domain/rebate_calc，保证口径唯一。

    注意：合同 tiers[].pct 与 rebate_pct 都是**百分点**（3 = 3%），
    与目标规则 rebate_rate（小数，0.03 = 3%）口径不同，勿混用。
    """
    from domain.rebate_calc import calc_contract_amount
    return calc_contract_amount(contract, achieved)


# --- Rebate Contract: 月度目标分解 (v111) ---
def get_rebate_contract_months(contract_id):
    """返回合同 12 个月的月度目标分解。

    未设置过的月份返回 target_amount=0 + saved=False，前端可直接编辑。
    business rule: 合同年度目标(target_amount) = 12 个月月度目标之和。
    """
    with get_db() as db:
        ct = db.execute("SELECT * FROM rebate_contracts WHERE id=?", (contract_id,)).fetchone()
        if not ct:
            return {"success": False, "error": "合同不存在"}
        ct = dict(ct)
        year = str(ct.get('year') or datetime.now().year).strip()
        stored = {}
        for r in db.execute(
                "SELECT * FROM rebate_contract_months WHERE contract_id=?", (contract_id,)).fetchall():
            stored[r['month']] = dict(r)
        months = []
        for i in range(1, 13):
            ym = f"{year}-{i:02d}"
            row = stored.get(ym) or {}
            months.append({
                "month": ym,
                "label": f"{i} 月",
                "target_amount": float(row.get('target_amount') or 0),
                "note": row.get('note') or '',
                "saved": bool(row),
            })
        return {
            "success": True,
            "contract_id": contract_id,
            "year": year,
            "months": months,
            "total_target": round(sum(m['target_amount'] for m in months), 2),
            "contract_target": float(ct.get('target_amount') or 0),
        }


def set_rebate_contract_months(contract_id, months):
    """Upsert 月度目标。months = [{"month":"2026-01","target_amount":1000,"note":""}, ...]

    显式传 0 的行会**更新为 0**（不是删除），避免"UI 清空了但计提仍按旧值算"。
    保存后回写合同年度目标 = 12 个月之和，保持"合同由月度构成"的口径一致。

    v112 R6 首次分解保护：老合同（创建时只有年度 target_amount、无任何月度行）首次
    填写部分月份时，前端曾把"未设置的月份"当 0 全量提交，导致年度目标被静默压成
    "已填月份之和"（如 1 月 10 万 → 全年 108 万变 10 万）。
    规则：**无历史月度行 且 本次提交月份数 < 12** 视为"分解未完成"，保留合同原年度目标，
    不覆盖；只有已填满 12 个月或已有月度行（非首次）时才按月度总和回写。
    """
    if not isinstance(months, list):
        return {"success": False, "error": "months 必须是数组"}
    with get_db() as db:
        ct = db.execute("SELECT id, target_amount FROM rebate_contracts WHERE id=?", (contract_id,)).fetchone()
        if not ct:
            return {"success": False, "error": "合同不存在"}
        prev_rows = (db.execute(
            "SELECT COUNT(*) AS c FROM rebate_contract_months WHERE contract_id=?",
            (contract_id,)).fetchone()["c"] or 0)
        n = 0
        for m in months or []:
            if not isinstance(m, dict):
                continue
            ym = str(m.get('month') or '').strip()
            if not ym:
                continue
            # v112 R30: 月份格式强校验 YYYY-MM（拒绝 2026-13 / abc 等脏键）
            import re as _re
            if not _re.fullmatch(r"\d{4}-(0[1-9]|1[0-2])", ym):
                return {"success": False, "error": f"月份格式必须为 YYYY-MM（如 2026-01）：{ym}"}
            amt = float(m.get('target_amount') or 0)
            note = str(m.get('note') or '')
            old = db.execute(
                "SELECT id FROM rebate_contract_months WHERE contract_id=? AND month=?",
                (contract_id, ym)).fetchone()
            if old:
                db.execute(
                    "UPDATE rebate_contract_months SET target_amount=?, note=?, "
                    "updated_at=datetime('now','localtime') WHERE id=?",
                    (amt, note, old['id']))
            else:
                db.execute(
                    "INSERT INTO rebate_contract_months (contract_id, month, target_amount, note) "
                    "VALUES (?,?,?,?)", (contract_id, ym, amt, note))
            n += 1
        total = db.execute(
            "SELECT COALESCE(SUM(target_amount),0) FROM rebate_contract_months WHERE contract_id=?",
            (contract_id,)).fetchone()[0] or 0
        if prev_rows == 0 and n < 12:
            # 首次部分分解：保留合同原年度目标（未被填写的月份不视为 0）
            contract_target = round(float(ct['target_amount'] or 0), 2)
        else:
            db.execute("UPDATE rebate_contracts SET target_amount=? WHERE id=?",
                       (round(float(total), 2), contract_id))
            contract_target = round(float(total), 2)
        db.commit()
        return {"success": True, "updated": n, "contract_target": contract_target,
                "first_partial": bool(prev_rows == 0 and n < 12)}


def _contract_rules(db, contract_id):
    """合同下挂的启用中目标规则。表缺列时安全降级为 []。"""
    try:
        return [dict(r) for r in db.execute(
            "SELECT * FROM rebate_target_rules WHERE contract_id=? AND is_active=1 "
            "ORDER BY priority DESC, id", (contract_id,)).fetchall()]
    except Exception:
        return []


def _rule_active_in_month(rule, year, month_no):
    """规则在指定月份是否适用 —— v186 起委托 domain.rebate_period.rule_covers_month。

    · 有月度分解（年度规则）⇒ 该月分解里有目标就适用；生效期**不再**逐月裁剪。
      真实事故：规则 12 个月分解齐全、生效期却只写了 9 月 ⇒ 计提/年达成/月表试算
      都只认 9 月，其余月份已填报的达成被静默丢弃（与前端"不画柱"同源）。
    · 单期规则 ⇒ 仍按 effective_start/effective_end 过滤（"蒙牛低温8月目标"只在
      2026-08 生效，计提 1 月时不能拿它算）。

    保留本函数名只为兼容既有三处调用点（accrue_rebate / _contract_year_achieved /
    get_rebate_contract_overview）。**口径一律以 domain 层为准，勿在此另写判断** ——
    这条门禁此前在前后端各写了多份，分叉就会同屏自相矛盾。
    """
    from domain.rebate_period import rule_covers_month as _rcm
    return bool(_rcm(rule, year, month_no))


def _achievement_index(db):
    """(period_month, dimension, scope_key.lower()) → 达成行。整表一次读入，避免逐月逐规则查库。"""
    idx = {}
    try:
        for a in db.execute("SELECT * FROM rebate_achievements").fetchall():
            idx[(str(a['period_month'] or '').strip(), a['dimension'],
                 str(a['scope_key'] or '').strip().lower())] = dict(a)
    except Exception:
        pass
    return idx

# ===========================================================================
# v114 (第二批 B2-1): 阶梯版本化链路辅助
# 解决"年中改了阶梯，历史月份到底按哪版算"——计提按计提月份锁定当时生效版本。
# ===========================================================================
def _month_prefix(s):
    """取 YYYY-MM-DD / YYYY-MM 的 YYYY-MM 前缀；无法解析返回 ''。"""
    s = (s or '').strip()
    if len(s) >= 7 and s[4] == '-':
        return s[:7]
    return ''


def _tier_version_window_match(eff_start, eff_end, month):
    """版本生效窗口（含端点）是否覆盖 month(YYYY-MM)。空=不限。"""
    s = _month_prefix(eff_start)
    e = _month_prefix(eff_end)
    if s and month < s:
        return False
    if e and month > e:
        return False
    return True


def _load_rule_tier_versions(db, rule_ids):
    """一次查询取回合同相关规则的全部阶梯版本，按 rule_id 分组（避免循环查询）。"""
    vmap = {}
    if not rule_ids:
        return vmap
    try:
        qmarks = ",".join("?" * len(rule_ids))
        for r in db.execute(
                f"SELECT * FROM rebate_tier_versions WHERE rule_id IN ({qmarks})", rule_ids
        ).fetchall():
            vmap.setdefault(r['rule_id'], []).append(dict(r))
    except Exception:
        pass
    return vmap


def _pick_tier_version(versions_list, month):
    """从版本列表中挑出适用 month 的最新版本（生效期最晚、id 最大）；无则 None。"""
    if not versions_list:
        return None
    best = None
    for r in versions_list:
        if not _tier_version_window_match(r.get('effective_start'), r.get('effective_end'), month):
            continue
        if best is None:
            best = r
            continue
        rs, bs = r.get('effective_start') or '', best.get('effective_start') or ''
        if rs > bs or (rs == bs and (r.get('id') or 0) > (best.get('id') or 0)):
            best = r
    return best


def _rule_with_versioned_tiers(rule, version_row):
    """返回 (应用版本后的规则副本, tier_version_id)。version_row 为空则原样返回。"""
    if not version_row:
        return rule, 0
    if not isinstance(rule, dict):
        rule = dict(rule)
    v = dict(rule)
    v['tiers_json'] = version_row.get('tiers_json') or v.get('tiers_json') or '[]'
    v['scale_type'] = version_row.get('scale_type') or v.get('scale_type') or 'non_graduated'
    v['rounding_mode'] = version_row.get('rounding_mode') or v.get('rounding_mode') or 'half_up'
    v['rounding_digits'] = (version_row.get('rounding_digits')
                            if version_row.get('rounding_digits') is not None
                            else v.get('rounding_digits', 2))
    return v, int(version_row.get('id') or 0)


def contact_rebate_balance(db, contact_id):
    """v114 (B2-4): 某联系人名下全部合同的未结算返利余额（应收 BV / 增量累积）。

    口径：该联系人所有合同里 receipt_id=0（未结转应收）的计提合计；已结算计提不计入。
    实时聚合，无需额外持久化表，避免与结算双写漂移。contact_id=0（按名称直录无主体）返回 0。
    """
    if not contact_id:
        return 0.0
    try:
        cids = [r['id'] for r in db.execute(
            "SELECT id FROM rebate_contracts WHERE contact_id=?", (contact_id,)).fetchall()]
        if not cids:
            return 0.0
        qmarks = ",".join("?" * len(cids))
        total = db.execute(
            f"SELECT COALESCE(SUM(accrued_rebate),0) FROM rebate_accruals "
            f"WHERE contract_id IN ({qmarks}) AND receipt_id=0", cids).fetchone()[0] or 0
        return round(float(total), 2)
    except Exception:
        return 0.0


def accrue_rebate(contract_id, month=None):
    """按月计提返利。

    口径修正 (v111)：达成数字取「达成填报」rebate_achievements（厂家合同目标由人工 /
    Excel 填报），**不再**取 sale_orders 卖给下游的销售额 —— 那是"我们卖给客户"，
    与"我们向厂家进货达量"是两回事，此前算出来的返利完全不对。

    算法：合同下挂的每条启用中目标规则分别试算（各自的目标/门槛/阶梯），返利累加。
    """
    from domain.rebate_calc import compute_rule_rebate, period_key_for
    if month is None:
        month = datetime.now().strftime("%Y-%m")
    month = str(month).strip()
    with get_db() as db:
        ct = db.execute("SELECT * FROM rebate_contracts WHERE id=?", (contract_id,)).fetchone()
        if not ct:
            return {"success": False, "error": "合同不存在"}
        ct = dict(ct)
        year = str(ct.get('year') or '').strip()
        if not year:
            return {"success": False, "error": "请先设置合同年份"}
        if not month.startswith(year):
            return {"success": False, "error": f"月份 {month} 不在合同年度 {year} 内"}
        try:
            m_no = int(month.split('-')[1])
        except Exception:
            return {"success": False, "error": f"月份格式应为 YYYY-MM，收到 {month}"}

        # 已结算的月份不允许重提（否则会把 receipt_id 冲掉，造成重复结算）
        old = db.execute(
            "SELECT * FROM rebate_accruals WHERE contract_id=? AND month=?",
            (contract_id, month)).fetchone()
        if old and (dict(old).get('receipt_id') or 0) != 0:
            return {"success": False,
                    "error": f"{month} 已结算（应收单 #{dict(old)['receipt_id']}），不能重复计提"}

        rules = _contract_rules(db, contract_id)
        if not rules:
            return {"success": False,
                    "error": "该合同下还没有挂目标规则，无法计提。请先到「目标规则」把品牌 / 单品规则归属到本合同。"}

        active_rules = [r for r in rules if _rule_active_in_month(r, year, m_no)]
        if not active_rules:
            return {"success": False,
                    "error": f"{month} 没有适用的目标规则（年度规则的月度分解里没有这一月，"
                             f"单期规则的生效期也不含这一月），无法计提。"
                             "请在「目标规则」里为该月填上月度目标，或调整生效期。"}

        # v114: 预载本合同规则的全部阶梯版本，计提时按月份锁定当时生效版本
        vmap = _load_rule_tier_versions(db, [r.get('id') for r in rules])

        ach_idx = _achievement_index(db)
        achieved = 0.0
        rebate_amt = 0.0
        details = []
        applied_versions = []
        for r in active_rules:
            # 锁定当月生效的阶梯版本（无版本则沿用规则当前阶梯，向后兼容）
            vrow = _pick_tier_version(vmap.get(r.get('id'), []), month)
            vrule, tvid = _rule_with_versioned_tiers(r, vrow)
            applied_versions.append({"rule_id": r.get('id'),
                                     "rule_name": r.get('rule_name'),
                                     "tier_version_id": tvid})
            pk = period_key_for(vrule.get('period_type'), year, m_no)
            if not pk:
                details.append({"rule": vrule.get('rule_name'), "tier_version_id": tvid,
                                "rebate": 0, "detail": "自定义周期不参与自动计提"})
                continue
            a = ach_idx.get((pk, vrule.get('dimension'),
                             str(vrule.get('scope_key') or '').strip().lower()))
            amount = float(a.get('actual_amount') or 0) if a else 0.0
            qty = float(a.get('actual_qty') or 0) if a else 0.0
            # v173：传 ref_date 走 v126 的按月投影 —— 达成是「当月」的，目标/返利率/阶梯也必须
            #   取「当月那一格」（monthly_view），否则会拿月度达成去比年度总额。period_key_for
            #   已恒返回月度键，pk 与 month 同值。此前此处两样都没有：pk 指向空桶（amount=0）、
            #   目标取年度总额，月度计提实际上从未算对过。
            calc = compute_rule_rebate(vrule, amount, qty, ref_date=pk)
            # 只有金额口径规则计入合同达成额，避免"金额 + 件数"混加
            if vrule.get('target_type') == 'amount':
                achieved += amount
            rebate_amt += calc['rebate']
            details.append({
                "rule": vrule.get('rule_name'),
                "scope": vrule.get('scope_name') or vrule.get('scope_key') or '全部',
                "tier_version_id": tvid,
                "achieved": round(amount, 2),
                "achievement_pct": calc['achievement_pct'],
                "triggered": calc['triggered'],
                "rebate": calc['rebate'],
                "detail": calc['detail'],
            })

        achieved = round(achieved, 2)
        rebate_amt = round(rebate_amt, 2)
        # v114: 记录当时采用的阶梯版本（多规则版本不一致时记 0，详情见 tiers_snapshot）
        tier_version_id = 0
        _vids = {av['tier_version_id'] for av in applied_versions}
        if len(_vids) == 1:
            tier_version_id = _vids.pop()
        tiers_snapshot = _json.dumps(applied_versions, ensure_ascii=False)
        if old:
            db.execute(
                "UPDATE rebate_accruals SET achieved_amount=?, accrued_rebate=?, "
                "tier_version_id=?, tiers_snapshot=? WHERE id=?",
                (achieved, rebate_amt, tier_version_id, tiers_snapshot, old['id']))
        else:
            db.execute(
                "INSERT INTO rebate_accruals "
                "(contract_id, month, achieved_amount, accrued_rebate, tier_version_id, tiers_snapshot) "
                "VALUES (?,?,?,?,?,?)",
                (contract_id, month, achieved, rebate_amt, tier_version_id, tiers_snapshot))
        db.commit()
        return {"success": True, "month": month, "achieved": achieved,
                "rebate": rebate_amt, "tier_version_id": tier_version_id,
                "details": details}

def get_rebate_accruals(contract_id):
    """Get accrual history for a contract."""
    with get_db() as db:
        return [dict(r) for r in db.execute(
            "SELECT * FROM rebate_accruals WHERE contract_id=? ORDER BY month DESC", (contract_id,)
        ).fetchall()]

def settle_rebate(contract_id):
    """结算返利：把未结算的计提汇总，生成一张**应收单(ar)**，并标记合同已结算。

    方向修正 (v111)：厂家返利是"厂家欠我们的钱"，属应收(ar)。
    此前生成的是应付(ap)——等于在系统里记成"我们欠厂家钱"，方向完全反了。

    v112 R32 并发保护：BEGIN IMMEDIATE 在函数入口即拿写锁，
    杜绝"双请求同时通过 settled=0 检查、各生成一张应收单"的窗口期。
    """
    with get_db() as db:
        db.execute("BEGIN IMMEDIATE")
        ct = db.execute("SELECT * FROM rebate_contracts WHERE id=?", (contract_id,)).fetchone()
        if not ct:
            return {"success": False, "error": "合同不存在"}
        ct = dict(ct)
        if ct.get('settled', 0) == 1:
            return {"success": False, "error": "合同已结算"}

        # Sum unpaid accruals
        total = db.execute(
            "SELECT COALESCE(SUM(accrued_rebate),0) FROM rebate_accruals WHERE contract_id=? AND receipt_id=0",
            (contract_id,)
        ).fetchone()[0] or 0

        if total <= 0:
            return {"success": False, "error": "无可结算的返利金额（先按月计提）"}

        # 联系人口径：按名称直录的合同 contact_id 可能为 0，此处按名称回查联系人，
        # 让应收单能挂到真实厂家主体上；查不到则退回原值（外键未开启，不会报错）。
        contact_id = ct.get('contact_id') or 0
        cname = str(ct.get('contact_name') or '').strip()
        if (not contact_id) and cname:
            hit = db.execute("SELECT id FROM contacts WHERE name=? LIMIT 1", (cname,)).fetchone()
            if hit:
                contact_id = hit['id']

        # Create AR receivable（应收：厂家欠我们）
        cid = db.execute(
            "INSERT INTO receivables (type, contact_id, amount, paid_amount, status, ref_type, ref_id, due_date) "
            "VALUES ('ar', ?, ?, 0, 'unpaid', 'rebate', ?, date('now','+30 days'))",
            (contact_id, total, contract_id)
        ).lastrowid

        # Update contract
        db.execute(
            "UPDATE rebate_contracts SET settled=1, settled_amount=?, settled_date=date('now'), receivable_id=? WHERE id=?",
            (total, cid, contract_id)
        )
        # Mark accruals as paid
        db.execute(
            "UPDATE rebate_accruals SET receipt_id=? WHERE contract_id=? AND receipt_id=0",
            (cid, contract_id)
        )
        db.commit()
        return {"success": True, "settled_amount": total, "receivable_id": cid}


def uns_settle_rebate(contract_id):
    """反结算 / 冲销（v112 R7）：把已结算合同回退为未结算态。

    - 作废结算生成的应收单（仅当应收单未收款 paid_amount=0 时允许；已收款需走财务冲销）；
    - 合同 settled=0、settled_amount=0、settled_date 清空、receivable_id=0；
    - 月度计提的 receipt_id 回退 0（回到"未结转"态，可重新结算）。
    """
    with get_db() as db:
        db.execute("BEGIN IMMEDIATE")
        ct = db.execute("SELECT * FROM rebate_contracts WHERE id=?", (contract_id,)).fetchone()
        if not ct:
            return {"success": False, "error": "合同不存在"}
        ct = dict(ct)
        if int(ct.get('settled', 0)) != 1:
            return {"success": False, "error": "合同未结算，无需反结算"}
        rid = int(ct.get('receivable_id') or 0)
        if rid:
            rec = db.execute("SELECT * FROM receivables WHERE id=?", (rid,)).fetchone()
            if rec:
                rec = dict(rec)
                if float(rec.get('paid_amount') or 0) > 0:
                    return {"success": False, "error": "结算应收单已有收款，不能反结算（请走财务冲销）"}
                db.execute("DELETE FROM receivables WHERE id=?", (rid,))
        db.execute("UPDATE rebate_accruals SET receipt_id=0 WHERE contract_id=? AND receipt_id=?",
                   (contract_id, rid))
        db.execute(
            "UPDATE rebate_contracts SET settled=0, settled_amount=0, settled_date=NULL, receivable_id=0 "
            "WHERE id=?", (contract_id,))
        db.commit()
        return {"success": True, "receivable_voided": rid}

def _contract_year_achieved(db, d, ach_idx=None, rules=None):
    """合同当年达成额。

    口径 (v111)：合同下挂了目标规则 → 取这些规则的「达成填报」合计；
    没挂规则的旧合同 → 退回 sale_orders 销售额（历史行为，保兼容）。

    v173：逐月累加，一年 12 个月的达成相加即为当年达成额。`period_key_for` 修好后
    （恒返回月度键）这条路径才真的读得到数据 —— 修之前年度规则拿 '2026' 去查一个
    从未有人写过的桶，本函数**恒返回 0**（合同有挂规则时），且不报错。
    下面 (规则, 周期键) 的去重保留为防御（同一规则重复出现时只计一次），
    但月度键下它不会再把 12 个月压成 1 个 —— 这是有意的，年达成就是 12 个月之和。

    v112 R28：可选 rules 参数由调用方批量预取（避免 N 合同 × M 规则逐次查询）。
    """
    from domain.rebate_calc import period_key_for
    year = str(d.get('year') or datetime.now().year).strip()
    rules = rules if rules is not None else _contract_rules(db, d.get('id'))
    if not rules:
        return float(db.execute(
            "SELECT COALESCE(SUM(total_amount),0) FROM sale_orders "
            "WHERE customer_id=? AND status IN ('delivered','signed') AND order_date LIKE ?",
            (d.get('contact_id'), f"{year}%")).fetchone()[0] or 0)
    idx = ach_idx if ach_idx is not None else _achievement_index(db)
    seen = set()
    total = 0.0
    for i in range(1, 13):
        for ru in rules:
            if not _rule_active_in_month(ru, year, i):
                continue
            pk = period_key_for(ru.get('period_type'), year, i)
            if not pk or ru.get('target_type') != 'amount':
                continue
            key = (ru.get('id'), pk)
            if key in seen:
                continue
            seen.add(key)
            a = idx.get((pk, ru.get('dimension'), str(ru.get('scope_key') or '').strip().lower()))
            if a:
                total += float(a.get('actual_amount') or 0)
    return total


def get_rebate_summary(contact_id=None):
    """返利合同汇总（含进度与预计返利）。

    注意：contacts.name 别名为 contact_ref_name —— 因为 rebate_contracts 自带
    contact_name 列，同名会让 sqlite3 的 dict(row) 后者覆盖前者，把按名称直录的
    合同名冲成 NULL。
    """
    with get_db() as db:
        where = "WHERE 1=1"
        params = []
        if contact_id:
            where += " AND rc.contact_id=?"
            params.append(contact_id)
        rows = db.execute(
            f"SELECT rc.*, c.name as contact_ref_name, b.name as brand_name FROM rebate_contracts rc "
            f"LEFT JOIN contacts c ON rc.contact_id=c.id "
            f"LEFT JOIN brands b ON rc.brand_id=b.id {where} ORDER BY rc.id DESC",
            params
        ).fetchall()
        ach_idx = _achievement_index(db)
        # v112 R28: 批量取全部启用规则一次查询（N+1 → 1），按 contract_id 分组供下面循环复用
        rules_by_cid = {}
        cids = [r["id"] for r in rows]
        if cids:
            try:
                qmarks = ",".join("?" * len(cids))
                for rr in db.execute(
                        f"SELECT * FROM rebate_target_rules WHERE contract_id IN ({qmarks}) AND is_active=1 "
                        f"ORDER BY priority DESC, id", cids).fetchall():
                    rules_by_cid.setdefault(rr["contract_id"], []).append(dict(rr))
            except Exception:
                pass
        results = []
        for r in rows:
            d = dict(r)
            cid = d.get('id')
            c_rules = rules_by_cid.get(cid, [])
            achieved = _contract_year_achieved(db, d, ach_idx, c_rules)
            d['achieved'] = round(float(achieved), 2)
            d['target'] = d.get('target_amount', 0) or 0
            d['progress_pct'] = round(d['achieved'] / max(d['target'], 1) * 100, 1)
            d['expected_rebate'] = calc_rebate_amount(d, d['achieved'])
            d['rule_count'] = len(c_rules)
            d['contact_rebate_balance'] = contact_rebate_balance(db, d.get('contact_id') or 0)
            results.append(d)
        return results


def get_rebate_contract_overview(contract_id):
    """合同月度全景：12 个月 × (月度目标 / 分品牌达成 / 试算返利 / 已计提 / 累计)。

    前端「年度合同」Tab 的月度表直接消费这个结构；已计提列取 rebate_accruals，
    试算列取「达成填报 + 目标规则」实时算，两者不同则说明该月还没计提。
    """
    from domain.rebate_calc import compute_rule_rebate, period_key_for
    with get_db() as db:
        ct = db.execute("SELECT * FROM rebate_contracts WHERE id=?", (contract_id,)).fetchone()
        if not ct:
            return {"success": False, "error": "合同不存在"}
        ct = dict(ct)
        year = str(ct.get('year') or datetime.now().year).strip()

        stored = {}
        try:
            for r in db.execute(
                    "SELECT * FROM rebate_contract_months WHERE contract_id=?",
                    (contract_id,)).fetchall():
                stored[r['month']] = dict(r)
        except Exception:
            pass

        rules = _contract_rules(db, contract_id)
        vmap = _load_rule_tier_versions(db, [r.get('id') for r in rules])
        ach_idx = _achievement_index(db)

        accruals = {}
        try:
            for r in db.execute(
                    "SELECT * FROM rebate_accruals WHERE contract_id=?", (contract_id,)).fetchall():
                accruals[r['month']] = dict(r)
        except Exception:
            pass

        rows = []
        cum_target = cum_achieved = cum_est = cum_accrued = 0.0
        for i in range(1, 13):
            ym = f"{year}-{i:02d}"
            m_target = float((stored.get(ym) or {}).get('target_amount') or 0)
            per_rule = []
            m_achieved = 0.0
            m_est = 0.0
            for r in rules:
                if not _rule_active_in_month(r, year, i):
                    continue
                # v114: 试算也按当月生效阶梯版本算，与计提口径一致（"说清当时按哪版算"）
                vrow = _pick_tier_version(vmap.get(r.get('id'), []), ym)
                vrule, tvid = _rule_with_versioned_tiers(r, vrow)
                pk = period_key_for(vrule.get('period_type'), year, i)
                if not pk:
                    continue
                a = ach_idx.get((pk, vrule.get('dimension'),
                                 str(vrule.get('scope_key') or '').strip().lower()))
                amount = float(a.get('actual_amount') or 0) if a else 0.0
                qty = float(a.get('actual_qty') or 0) if a else 0.0
                # v173：同 accrue_rebate —— 达成与目标都锁在 ym 那一格（v126 按月投影）
                calc = compute_rule_rebate(vrule, amount, qty, ref_date=ym)
                if vrule.get('target_type') == 'amount':
                    m_achieved += amount
                m_est += calc['rebate']
                per_rule.append({
                    "rule_id": vrule.get('id'),
                    "rule_name": vrule.get('rule_name'),
                    "scope": vrule.get('scope_name') or vrule.get('scope_key') or '全部',
                    "tier_version_id": tvid,
                    "target_value": vrule.get('target_value'),
                    "period_type": vrule.get('period_type'),
                    "actual_amount": round(amount, 2),
                    "achievement_pct": calc['achievement_pct'],
                    "triggered": calc['triggered'],
                    "rebate": calc['rebate'],
                    "detail": calc['detail'],
                })

            acc = accruals.get(ym)
            accrued = float(acc.get('accrued_rebate') or 0) if acc else 0.0
            # 计提快照里的达成（可能来自历史口径）与实时试算并存，优先用实时
            cum_target += m_target
            cum_achieved += m_achieved
            cum_est += m_est
            cum_accrued += accrued
            rows.append({
                "month": ym,
                "label": f"{i} 月",
                "target_amount": round(m_target, 2),
                "note": (stored.get(ym) or {}).get('note') or '',
                "achieved": round(m_achieved, 2),
                "achievement_pct": round(m_achieved / m_target, 4) if m_target > 0 else None,
                "est_rebate": round(m_est, 2),
                "accrued_rebate": round(accrued, 2),
                "accrual_id": acc.get('id') if acc else None,
                "settled": bool(acc and (acc.get('receipt_id') or 0) != 0),
                "pending": round(m_est - accrued, 2),
                "cum_target": round(cum_target, 2),
                "cum_achieved": round(cum_achieved, 2),
                "cum_est_rebate": round(cum_est, 2),
                "cum_accrued": round(cum_accrued, 2),
                "has_achievement": bool(per_rule) and any(p['actual_amount'] for p in per_rule),
                "rules": per_rule,
            })

        # v114 (B2-4): 该联系人未结算返利余额（跨合同实时累计）
        contact_balance = contact_rebate_balance(db, ct.get('contact_id') or 0)
        return {
            "success": True,
            "contract_id": contract_id,
            "contract_name": ct.get('contact_name') or ct.get('contact_ref_name') or '',
            "year": year,
            "contract_type": ct.get('contract_type') or 'revenue',
            "settled": bool(ct.get('settled')),
            "settled_amount": float(ct.get('settled_amount') or 0),
            "settled_date": ct.get('settled_date') or '',
            "receivable_id": ct.get('receivable_id') or 0,
            "rule_count": len(rules),
            "contact_rebate_balance": contact_balance,
            "months": rows,
            "totals": {
                "target": round(cum_target, 2),
                "achieved": round(cum_achieved, 2),
                "est_rebate": round(cum_est, 2),
                "accrued": round(cum_accrued, 2),
                "pending": round(cum_est - cum_accrued, 2),
                "contact_rebate_balance": contact_balance,
                "progress_pct": round(cum_achieved / cum_target * 100, 1) if cum_target > 0 else 0,
            },
        }


# ===========================================================================
# v114 (第二批 B2-2): 返利申领 + 审批状态机
# settled 0/1 升级为多状态：none / submitted / approved / rejected / reversed
# 申领审核通过 → 真正结算(settle_rebate)；冲销 → 反结算(uns_settle_rebate)。
# ===========================================================================
def get_rebate_claim(contract_id):
    """取合同当前申领状态；无记录返回 {claim_status:'none'}。"""
    with get_db() as db:
        try:
            row = db.execute("SELECT * FROM rebate_claims WHERE contract_id=?",
                             (contract_id,)).fetchone()
            if row:
                return dict(row)
        except Exception:
            pass
        return {"contract_id": contract_id, "claim_status": "none"}


def submit_rebate_claim(contract_id, note=""):
    """申领：提交待审。要求合同存在且未结算；申领金额=当前未结算计提合计。"""
    with get_db() as db:
        ct = db.execute("SELECT * FROM rebate_contracts WHERE id=?", (contract_id,)).fetchone()
        if not ct:
            return {"success": False, "error": "合同不存在"}
        ct = dict(ct)
        if int(ct.get('settled', 0)) == 1:
            return {"success": False, "error": "合同已结算，无需再申领"}
        claimed = db.execute(
            "SELECT COALESCE(SUM(accrued_rebate),0) FROM rebate_accruals "
            "WHERE contract_id=? AND receipt_id=0", (contract_id,)).fetchone()[0] or 0
        if float(claimed) <= 0:
            return {"success": False, "error": "暂无可申领的未结算返利（请先按月计提）"}
        now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        db.execute(
            "INSERT INTO rebate_claims (contract_id, claim_status, claimed_amount, submitted_at, note) "
            "VALUES (?, 'submitted', ?, ?, ?) "
            "ON CONFLICT(contract_id) DO UPDATE SET "
            "claim_status='submitted', claimed_amount=excluded.claimed_amount, "
            "submitted_at=excluded.submitted_at, reviewed_at='', reviewer='', note=excluded.note",
            (contract_id, float(claimed), now, note or ''))
        db.commit()
        return {"success": True, "claim_status": "submitted", "claimed_amount": round(float(claimed), 2)}


def review_rebate_claim(contract_id, action, reviewer="", note=""):
    """审核：approve→结算；reject→驳回；reverse→冲销。状态机门控。"""
    action = (action or '').strip().lower()
    with get_db() as db:
        ct = db.execute("SELECT * FROM rebate_contracts WHERE id=?", (contract_id,)).fetchone()
        if not ct:
            return {"success": False, "error": "合同不存在"}
        status = (get_rebate_claim(contract_id) or {}).get('claim_status') or 'none'
        now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        if action == 'approve':
            if status != 'submitted':
                return {"success": False, "error": f"仅 submitted 状态可审核通过（当前 {status}）"}
            r = settle_rebate(contract_id)
            if not r.get("success"):
                return r
            db.execute(
                "UPDATE rebate_claims SET claim_status='approved', reviewed_at=?, reviewer=?, note=? "
                "WHERE contract_id=?", (now, reviewer or '', note or '', contract_id))
            db.commit()
            return {"success": True, "claim_status": "approved",
                    "settled_amount": r.get("settled_amount"), "receivable_id": r.get("receivable_id")}
        if action == 'reject':
            if status != 'submitted':
                return {"success": False, "error": f"仅 submitted 状态可驳回（当前 {status}）"}
            db.execute(
                "UPDATE rebate_claims SET claim_status='rejected', reviewed_at=?, reviewer=?, note=? "
                "WHERE contract_id=?", (now, reviewer or '', note or '', contract_id))
            db.commit()
            return {"success": True, "claim_status": "rejected"}
        if action == 'reverse':
            if status != 'approved':
                return {"success": False, "error": f"仅 approved 状态可冲销（当前 {status}）"}
            r = uns_settle_rebate(contract_id)
            if not r.get("success"):
                return r
            db.execute(
                "UPDATE rebate_claims SET claim_status='reversed', reviewed_at=?, reviewer=?, note=? "
                "WHERE contract_id=?", (now, reviewer or '', note or '', contract_id))
            db.commit()
            return {"success": True, "claim_status": "reversed"}
        return {"success": False, "error": f"未知审核动作：{action}"}


def list_rebate_claims():
    """全部申领记录（审核队列）。"""
    with get_db() as db:
        try:
            return [dict(r) for r in db.execute(
                "SELECT * FROM rebate_claims ORDER BY id DESC").fetchall()]
        except Exception:
            return []


# ===========================================================================
# v114 (第二批 B2-3): 批量计提作业化
# 一次遍历租户全部合同调用 accrue_rebate(month)，单合同失败不影响其余。
# ===========================================================================
def batch_accrue_rebate(month=None):
    """全合同批量计提，返回逐合同结果与汇总。"""
    if month is None:
        month = datetime.now().strftime("%Y-%m")
    month = str(month).strip()
    results = []
    total_rebate = 0.0
    with get_db() as db:
        cids = [r['id'] for r in db.execute(
            "SELECT id FROM rebate_contracts ORDER BY id").fetchall()]
    for cid in cids:
        try:
            r = accrue_rebate(cid, month)
            if r.get("success"):
                total_rebate += float(r.get("rebate") or 0)
                results.append({"contract_id": cid, "success": True,
                                "month": r.get("month"), "rebate": r.get("rebate")})
            else:
                results.append({"contract_id": cid, "success": False, "error": r.get("error")})
        except Exception as e:
            results.append({"contract_id": cid, "success": False, "error": str(e)[:200]})
    return {"success": True, "month": month, "count": len(results),
            "ok_count": len([x for x in results if x["success"]]),
            "total_rebate": round(total_rebate, 2), "results": results}


# --- Batch Trace ---
def record_batch_trace(batch_no, direction, product_id, product_name, quantity, ref_type, ref_id, ref_no, contact_name, db_conn=None):
    """Record a batch trace entry. Never raises. If db_conn is provided, uses it directly."""
    try:
        if db_conn:
            db_conn.execute(
                "INSERT INTO batch_trace (batch_no, direction, product_id, product_name, quantity, ref_type, ref_id, ref_no, contact_name) "
                "VALUES (?,?,?,?,?,?,?,?,?)",
                (batch_no, direction, product_id, product_name, quantity, ref_type, ref_id, ref_no, contact_name)
            )
        else:
            with get_db() as db:
                db.execute(
                    "INSERT INTO batch_trace (batch_no, direction, product_id, product_name, quantity, ref_type, ref_id, ref_no, contact_name) "
                    "VALUES (?,?,?,?,?,?,?,?,?)",
                    (batch_no, direction, product_id, product_name, quantity, ref_type, ref_id, ref_no, contact_name)
                )
                db.commit()
    except Exception as e:
        # batch trace is non-critical auditing; must not block the calling transaction
        logging.getLogger("hergent").debug(f"skipping row: {e}")

def get_batch_full_trace(batch_no):
    """Get complete trace for a batch: inbound + outbound."""
    with get_db() as db:
        trace_in = [dict(r) for r in db.execute(
            "SELECT * FROM batch_trace WHERE batch_no=? AND direction='in' ORDER BY created_at DESC",
            (batch_no,)
        ).fetchall()]
        trace_out = [dict(r) for r in db.execute(
            "SELECT * FROM batch_trace WHERE batch_no=? AND direction='out' ORDER BY created_at DESC",
            (batch_no,)
        ).fetchall()]
        # Also check inventory for current batch status
        inv = db.execute(
            "SELECT p.name as product_name, i.quantity, i.batch_no, i.expiry_date, i.cost_price "
            "FROM inventory i JOIN products p ON i.product_id=p.id WHERE i.batch_no=? AND i.quantity>0",
            (batch_no,)
        ).fetchall()
        return {
            "batch_no": batch_no,
            "inbound": trace_in,
            "outbound": trace_out,
            "current_stock": [dict(r) for r in inv] if inv else [],
            "total_in": sum(t['quantity'] for t in trace_in),
            "total_out": sum(t['quantity'] for t in trace_out),
        }

def get_batch_forward_trace(batch_no):
    """Forward trace: who received this batch?"""
    with get_db() as db:
        return [dict(r) for r in db.execute(
            "SELECT * FROM batch_trace WHERE batch_no=? AND direction='out' ORDER BY created_at DESC",
            (batch_no,)
        ).fetchall()]

def get_batch_backward_trace(batch_no):
    """Backward trace: who supplied this batch?"""
    with get_db() as db:
        return [dict(r) for r in db.execute(
            "SELECT * FROM batch_trace WHERE batch_no=? AND direction='in' ORDER BY created_at DESC",
            (batch_no,)
        ).fetchall()]

def get_product_batch_history(product_id):
    """Get all batch history for a product."""
    with get_db() as db:
        return [dict(r) for r in db.execute(
            "SELECT * FROM batch_trace WHERE product_id=? ORDER BY created_at DESC LIMIT 100",
            (product_id,)
        ).fetchall()]

def get_recall_affected_customers(batch_no):
    """Get all customers who received a specific batch (for recall)."""
    with get_db() as db:
        return [dict(r) for r in db.execute(
            "SELECT bt.contact_name, bt.ref_no, bt.quantity, bt.created_at, c.phone "
            "FROM batch_trace bt LEFT JOIN contacts c ON bt.contact_name=c.name "
            "WHERE bt.batch_no=? AND bt.direction='out' ORDER BY bt.created_at DESC",
            (batch_no,)
        ).fetchall()]



