# --- Price Change Requests ---
def request_price_change(product_id, field_name, old_value, new_value, reason='', requested_by='', effective_date=''):
    """Submit a price change request for approval."""
    with get_db() as db:
        rid = db.execute(
            "INSERT INTO price_change_requests (product_id,field_name,old_value,new_value,reason,requested_by,effective_date) VALUES (?,?,?,?,?,?,?)",
            (product_id, field_name, old_value, new_value, reason, requested_by, effective_date)
        ).lastrowid
        db.commit()
        return {"success": True, "id": rid}

def get_price_change_requests(status='pending', limit=50):
    """List price change requests, optionally filtered by status."""
    with get_db() as db:
        rows = db.execute(
            "SELECT pcr.*, p.name as product_name, p.spec, p.brand "
            "FROM price_change_requests pcr LEFT JOIN products p ON pcr.product_id=p.id "
            "WHERE pcr.status=? ORDER BY pcr.id DESC LIMIT ?",
            (status, limit)
        ).fetchall()
        return [dict(r) for r in rows]

def approve_price_change(request_id, approved_by=''):
    """Approve a price change: apply the new price and log."""
    with get_db() as db:
        req = db.execute("SELECT * FROM price_change_requests WHERE id=? AND status='pending'", (request_id,)).fetchone()
        if not req:
            return {"success": False, "error": "请求不存在或已处理"}
        req = dict(req)
        # Apply price change
        field = req['field_name']
        new_val = req['new_value']
        pid = req['product_id']
        db.execute(f"UPDATE products SET {field}=?, updated_at=datetime('now','localtime') WHERE id=?", (new_val, pid))
        # Log to price_history
        db.execute(
            "INSERT INTO price_history (product_id, field_name, old_value, new_value, reason, operator_id) VALUES (?,?,?,?,?,?)",
            (pid, field, req['old_value'], new_val, req.get('reason',''), approved_by)
        )
        # Update request
        db.execute(
            "UPDATE price_change_requests SET status='approved', approved_by=?, approved_at=datetime('now','localtime') WHERE id=?",
            (approved_by, request_id)
        )
        db.commit()
        return {"success": True, "applied": True}

def reject_price_change(request_id, approved_by=''):
    """Reject a price change request."""
    with get_db() as db:
        db.execute(
            "UPDATE price_change_requests SET status='rejected', approved_by=? WHERE id=? AND status='pending'",
            (approved_by, request_id)
        )
        db.commit()
        return {"success": True}

def get_price_change_impact(items):
    """Preview impact of price changes. items = [{"product_id":1,"field":"sale_price","new_val":5.0},...]"""
    with get_db() as db:
        results = []
        total_revenue_impact = 0
        for it in items:
            pid = it['product_id']
            field = it.get('field', 'sale_price')
            new_val = it.get('new_val', 0)
            prod = db.execute("SELECT * FROM products WHERE id=?", (pid,)).fetchone()
            if not prod: continue
            old_val = prod[field] if field in prod.keys() else 0
            # Get monthly avg quantity
            monthly = db.execute(
                "SELECT COALESCE(AVG(daily_qty),0)*30 as monthly_qty FROM "
                "(SELECT SUM(soi.quantity) as daily_qty FROM sale_order_items soi "
                "JOIN sale_orders so ON soi.order_id=so.id "
                "WHERE soi.product_id=? AND so.order_date>=date('now','-30 days') AND so.status IN ('delivered','signed') "
                "GROUP BY date(so.order_date))",
                (pid,)
            ).fetchone()
            monthly_qty = monthly[0] if monthly else 0
            impact = (new_val - old_val) * monthly_qty
            total_revenue_impact += impact
            results.append({
                "product_id": pid, "name": prod.get('name','?'),
                "old_price": old_val, "new_price": new_val,
                "monthly_qty": round(monthly_qty, 2),
                "monthly_impact": round(impact, 2)
            })
        return {"items": results, "total_monthly_impact": round(total_revenue_impact, 2)}

# --- Price List Versioning ---
def clone_price_list(list_id, new_name):
    """Clone a price list with all its items."""
    with get_db() as db:
        src = db.execute("SELECT * FROM price_lists WHERE id=?", (list_id,)).fetchone()
        if not src:
            return {"success": False, "error": "源价目表不存在"}
        src = dict(src)
        new_ver = (src.get('version', 0) or 0) + 1
        new_id = db.execute(
            "INSERT INTO price_lists (name,type,effective_from,effective_to,is_active,version,status,based_on_id) VALUES (?,?,?,?,0,?,?,?)",
            (new_name, src.get('type',''), src.get('effective_from',''), src.get('effective_to',''), new_ver, 'draft', list_id)
        ).lastrowid
        # Clone items
        items = db.execute("SELECT * FROM price_list_items WHERE list_id=?", (list_id,)).fetchall()
        for it in items:
            db.execute(
                "INSERT INTO price_list_items (list_id,product_id,price,min_qty,tier_name) VALUES (?,?,?,?,?)",
                (new_id, it['product_id'], it['price'], it.get('min_qty',0), it.get('tier_name',''))
            )
        # Audit
        db.execute("INSERT INTO price_list_audit (list_id,action,detail) VALUES (?,?,?)",
                   (new_id, 'cloned', f'从价目表#{list_id}克隆 {len(items)} 项'))
        db.commit()
        return {"success": True, "id": new_id, "version": new_ver, "items_copied": len(items)}

def compare_price_lists(list_id_1, list_id_2):
    """Compare two price lists: show added/removed/changed items."""
    with get_db() as db:
        items_a = {r['product_id']: dict(r) for r in db.execute(
            "SELECT pli.*, p.name FROM price_list_items pli JOIN products p ON pli.product_id=p.id WHERE pli.list_id=?",
            (list_id_1,)
        ).fetchall()}
        items_b = {r['product_id']: dict(r) for r in db.execute(
            "SELECT pli.*, p.name FROM price_list_items pli JOIN products p ON pli.product_id=p.id WHERE pli.list_id=?",
            (list_id_2,)
        ).fetchall()}

        all_pids = set(list(items_a.keys()) + list(items_b.keys()))
        added, removed, changed, unchanged = [], [], [], []
        for pid in sorted(all_pids):
            a = items_a.get(pid)
            b = items_b.get(pid)
            if a and not b:
                removed.append({"product_id": pid, "name": a.get('name','?'), "price": a.get('price',0)})
            elif b and not a:
                added.append({"product_id": pid, "name": b.get('name','?'), "price": b.get('price',0)})
            elif a.get('price',0) != b.get('price',0):
                changed.append({"product_id": pid, "name": a.get('name','?'),
                               "old_price": a.get('price',0), "new_price": b.get('price',0),
                               "diff": round(b.get('price',0) - a.get('price',0), 2)})
            else:
                unchanged.append({"product_id": pid, "name": a.get('name','?'), "price": a.get('price',0)})
        return {"added": added, "removed": removed, "changed": changed, "unchanged": unchanged,
                "summary": f"新增{len(added)} 删除{len(removed)} 调价{len(changed)} 不变{len(unchanged)}"}

def activate_price_list(list_id):
    """Activate a price list (deactivate others of same type)."""
    with get_db() as db:
        pl = db.execute("SELECT * FROM price_lists WHERE id=?", (list_id,)).fetchone()
        if not pl:
            return {"success": False, "error": "价目表不存在"}
        # Deactivate other active lists of same type
        db.execute("UPDATE price_lists SET status='expired', is_active=0 WHERE type=? AND status='active' AND id!=?",
                   (pl['type'], list_id))
        # Activate this one
        db.execute("UPDATE price_lists SET status='active', is_active=1 WHERE id=?", (list_id,))
        # Audit
        db.execute("INSERT INTO price_list_audit (list_id,action,detail) VALUES (?,?,?)",
                   (list_id, 'activated', f'激活价目表 {pl.get("name","")}'))
        db.commit()
        return {"success": True, "name": pl.get('name','')}

def schedule_price_list_activation(list_id, activate_at):
    """Schedule a price list for future activation."""
    with get_db() as db:
        db.execute("UPDATE price_lists SET scheduled_activate=? WHERE id=?", (activate_at, list_id))
        db.commit()
        return {"success": True, "scheduled": activate_at}

def get_price_list_versions(list_type=''):
    """Get all versions of price lists."""
    with get_db() as db:
        where = "WHERE 1=1"
        params = []
        if list_type:
            where += " AND type=?"
            params.append(list_type)
        rows = db.execute(
            f"SELECT * FROM price_lists {where} ORDER BY type, version DESC",
            params
        ).fetchall()
        return [dict(r) for r in rows]

def check_scheduled_price_lists():
    """Check and activate scheduled price lists (called by scheduler)."""
    with get_db() as db:
        now = db.execute("SELECT datetime('now','localtime')").fetchone()[0]
        due = db.execute(
            "SELECT id, name FROM price_lists WHERE scheduled_activate!='' AND scheduled_activate<=? AND status='draft'",
            (now,)
        ).fetchall()
        activated = 0
        for d in due:
            activate_price_list(d[0])
            activated += 1
        return {"activated": activated}



