# 3. Batch operations
def batch_delete(table, ids):
    with get_db() as db:
        for rid in ids:
            try: db.execute(f"UPDATE {table} SET is_active=0 WHERE id=?",(rid,))
            except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}")
        db.commit()
    return {"deleted":len(ids)}

def batch_archive(table, ids):
    with get_db() as db:
        for rid in ids:
            db.execute("INSERT INTO archived_records (ref_type,ref_id,archived_data,archived_at) VALUES (?,?,?,datetime('now','localtime'))",(table,rid,""))
        db.commit()
    return {"archived":len(ids)}

def batch_update_status(ids, status):
    """Batch update product status (active/discontinued/seasonal)."""
    if not ids or not status:
        return {'updated': 0}
    with get_db() as db:
        placeholders = ",".join(["?"] * len(ids))
        db.execute(f"UPDATE products SET status=?,updated_at=datetime('now','localtime') WHERE id IN ({placeholders})", [status] + ids)
        db.commit()
        return {'updated': len(ids)}

def batch_contact_update(ids, **fields):
    """Batch update contact fields (region, channel, settlement_method, credit_days, price_level, assigned_salesperson)."""
    if not ids or not fields:
        return {'updated': 0}
    allowed = ['region', 'channel', 'settlement_method', 'credit_days', 'price_level', 'assigned_salesperson', 'tags']
    with get_db() as db:
        updates = []
        params = []
        for k, v in fields.items():
            if k in allowed and v:
                updates.append(f"{k}=?")
                params.append(v)
        if not updates:
            return {'updated': 0}
        placeholders = ",".join(["?"] * len(ids))
        params.extend(ids)
        db.execute(f"UPDATE contacts SET {','.join(updates)},updated_at=datetime('now','localtime') WHERE id IN ({placeholders})", params)
        db.commit()
        return {'updated': len(ids)}

# 4. Data archiving
def archive_old_data(days=365):
    cutoff = (datetime.now() - __import__('datetime').timedelta(days=days)).strftime("%Y-%m-%d")
    with get_db() as db:
        cnt = 0
        old_orders = db.execute("SELECT id FROM sale_orders WHERE status='signed' AND order_date<?",(cutoff,)).fetchall()
        for o in old_orders:
            db.execute("INSERT INTO archived_records (ref_type,ref_id) VALUES ('sale_order',?)",(o["id"],))
            cnt += 1
        db.commit()
    return {"archived":cnt,"cutoff":cutoff}

