# 6. Row-level security
def filter_by_owner(user, module):
    role = user.get("role","")
    uid = str(user.get("id",""))
    if role == "admin" or role == "boss": return ""
    if role == "sales":
        if module in ("sales","crm"):
            display_name = user.get('display_name','').replace("'","''")
            return f" AND (operator_id='{uid}' OR assigned_salesperson='{display_name}')"
    if role == "accountant":
        if module in ("accounts","reports"): return ""
    return ""

