def payment_batch_update(bid, **kw):
    with get_db() as db:
        sets = [f"{k}=?" for k in kw if k not in ("id","batch_id")]
        if not sets: return
        vals = [kw[k] for k in kw if k not in ("id","batch_id")] + [bid]
        db.execute(f"UPDATE payment_batches SET {', '.join(sets)}, updated_at=datetime('now','localtime') WHERE id=?", vals)
        db.commit()

