def _consignment_inv_upsert(db, agreement_id, product_id, warehouse_id, **deltas):
    """Upsert a consignment_inventory state row keyed by (agreement_id, product_id, warehouse_id)."""
    row = db.execute(
        "SELECT id, quantity_received, quantity_consumed, unit_price FROM consignment_inventory "
        "WHERE agreement_id=? AND product_id=? AND warehouse_id=?",
        (agreement_id, product_id, warehouse_id)).fetchone()
    if row:
        sets, vals = [], []
        if "quantity_received" in deltas:
            sets.append("quantity_received=COALESCE(quantity_received,0)+?")
            vals.append(deltas["quantity_received"])
        if "quantity_consumed" in deltas:
            sets.append("quantity_consumed=COALESCE(quantity_consumed,0)+?")
            vals.append(deltas["quantity_consumed"])
        if deltas.get("unit_price"):
            sets.append("unit_price=?")
            vals.append(deltas["unit_price"])
        if deltas.get("batch_no"):
            sets.append("batch_no=?")
            vals.append(deltas["batch_no"])
        if deltas.get("expiry_date"):
            sets.append("expiry_date=?")
            vals.append(deltas["expiry_date"])
        if sets:
            vals.append(row["id"])
            db.execute("UPDATE consignment_inventory SET %s WHERE id=?" % ", ".join(sets), vals)
    else:
        db.execute(
            "INSERT INTO consignment_inventory (agreement_id,product_id,warehouse_id,quantity_received,quantity_consumed,unit_price,batch_no,expiry_date) "
            "VALUES (?,?,?,?,?,?,?,?)",
            (agreement_id, product_id, warehouse_id,
             deltas.get("quantity_received", 0), deltas.get("quantity_consumed", 0),
             deltas.get("unit_price", 0), deltas.get("batch_no", ""), deltas.get("expiry_date", "")))

def consignment_receive(agreement_id, product_id, quantity, warehouse_id=1, unit_price=0, batch_no="", expiry_date=""):
    with get_db() as db:
        _consignment_inv_upsert(db, agreement_id, product_id, warehouse_id,
                                quantity_received=quantity, unit_price=unit_price,
                                batch_no=batch_no, expiry_date=expiry_date)
        db.commit()
    return {"success": True}

def consignment_consume(agreement_id, product_id, quantity, warehouse_id=1):
    with get_db() as db:
        _consignment_inv_upsert(db, agreement_id, product_id, warehouse_id, quantity_consumed=quantity)
        db.commit()
    return {"success": True}

def consignment_settle(agreement_id):
    with get_db() as db:
        ag = db.execute("SELECT * FROM consignment_agreements WHERE id=?", (agreement_id,)).fetchone()
        if not ag:
            return {"error": "Agreement not found"}
        if ag["status"] == "settled":
            return {"success": False, "error": "Agreement already settled"}
        row = db.execute(
            "SELECT COALESCE(SUM(quantity_consumed),0) AS qty, "
            "COALESCE(SUM(quantity_consumed*unit_price),0) AS amt "
            "FROM consignment_inventory WHERE agreement_id=?", (agreement_id,)).fetchone()
        consumed, total = row["qty"], row["amt"]
        db.execute(
            "INSERT INTO consignment_settlements (agreement_id,settlement_date,period_start,period_end,total_amount,status) "
            "VALUES (?,datetime('now','localtime'),NULL,NULL,?,'settled')",
            (agreement_id, total))
        db.execute("UPDATE consignment_agreements SET status='settled' WHERE id=?", (agreement_id,))
        db.commit()
    return {"success": True, "settled_qty": consumed, "total_amount": total}

