# ===== Safety Stock / ATP / WMS (v88) =====
def safety_stock_calculate(product_id=0, method="normal", service_level=0.95, lead_time_days=7, history_days=90):
    import math
    # Map service_level to z-score; min_max method uses absolute min/max
    Z_MAP = {0.90: 1.28, 0.95: 1.65, 0.99: 2.33}
    z = Z_MAP.get(service_level, 1.65)
    with get_db() as db:
        # FIX v91: use daily sales history (demand variability), NOT inventory quantity
        if product_id:
            rows = db.execute(
                "SELECT SUM(soi.quantity) as qty FROM sale_order_items soi "
                "JOIN sale_orders so ON soi.order_id=so.id "
                "WHERE soi.product_id=? AND so.order_date>=date('now','-{} days') "
                "AND so.status IN ('delivered','signed') "
                "GROUP BY date(so.order_date) ORDER BY date(so.order_date)".format(history_days),
                (product_id,)
            ).fetchall()
        else:
            rows = db.execute(
                "SELECT SUM(soi.quantity) as qty FROM sale_order_items soi "
                "JOIN sale_orders so ON soi.order_id=so.id "
                "WHERE so.order_date>=date('now','-{} days') "
                "AND so.status IN ('delivered','signed') "
                "GROUP BY date(so.order_date), soi.product_id ORDER BY date(so.order_date)".format(history_days)
            ).fetchall()
        demands = [r["qty"] for r in rows if r["qty"] and r["qty"] > 0] if rows else []
        if not demands:
            return {"product_id": product_id or 0, "method": method, "service_level": service_level, "avg_daily_demand": 0, "safety_stock": 0, "z": z, "lead_time_days": lead_time_days, "data_points": 0, "note": "无历史销量数据"}
        avg = sum(demands) / len(demands)
        std = 0
        if method == "min_max":
            ss = max(demands) - min(demands) if len(demands) > 1 else 0
        else:
            std = (sum((d - avg) ** 2 for d in demands) / len(demands)) ** 0.5 if len(demands) > 1 else 0
            ss = math.ceil(z * std * (lead_time_days ** 0.5))
        return {"product_id": product_id or 0, "method": method, "service_level": service_level, "avg_daily_demand": round(avg, 2), "safety_stock": ss, "z": z, "lead_time_days": lead_time_days, "data_points": len(demands), "std_dev": round(std, 2) if len(demands) > 1 else 0}

def atp_calculate(product_id, warehouse_id=1):
    with get_db() as db:
        inv = db.execute("SELECT COALESCE(SUM(quantity),0) as qty FROM inventory WHERE product_id=? AND warehouse_id=?", (product_id, warehouse_id)).fetchone()
        on_hand = inv["qty"] if inv else 0
        committed = db.execute("SELECT COALESCE(SUM(soi.quantity),0) as qty FROM sale_order_items soi JOIN sale_orders so ON soi.order_id=so.id WHERE soi.product_id=? AND so.warehouse_id=? AND so.status IN ('confirmed','delivered')", (product_id, warehouse_id)).fetchone()
        committed_qty = committed["qty"] if committed else 0
        incoming = db.execute("SELECT COALESCE(SUM(poi.quantity),0) as qty FROM purchase_order_items poi JOIN purchase_orders po ON poi.order_id=po.id WHERE poi.product_id=? AND po.warehouse_id=? AND po.status IN ('confirmed','shipped')", (product_id, warehouse_id)).fetchone()
        incoming_qty = incoming["qty"] if incoming else 0
        ss = safety_stock_calculate(product_id)
        atp = on_hand + incoming_qty - committed_qty - ss["safety_stock"]
        return {"product_id": product_id, "warehouse_id": warehouse_id, "on_hand": on_hand, "incoming": incoming_qty, "committed": committed_qty, "safety_stock": ss["safety_stock"], "atp": max(0, atp)}

def wms_pick_face_needs(warehouse_id=1):
    """拣货位补货需求：`拣货位现存量 < 下限(forward_min)` 的商品。

    🔴 v465f 修：原 SQL 引用 `pfc.pick_face_qty`/`pfc.min_qty`，而生产库实际列是
       `forward_min`/`forward_max`/`reserve_bin`（见 `_init` 的 DDL）；`IF NOT EXISTS`
       从不补列 ⇒ 每次请求 500 `no such column: pfc.pick_face_qty`，前端「补货需求」
       面板恒显「读取失败」（错误串还漏到界面）。

    现存量口径 = 该商品在该仓 **拣货位**（`bin_locations.zone='pick_face'`）的占用量
    （`bin_occupancy`）。无库位 / 无占用 ⇒ 0（= 已配下限即视为待补，符合 min/max 补货语义）。

    返回字段名保持 **`pick_face_qty` / `min_qty` / `max_qty`**（前端 `Strategy.vue` 契约），
    仅内部映射到生产列名 ⇒ 前端零改动。
    """
    _init_wms_depth_tables()  # 保证 bin_occupancy 存在（与 putaway_strategy 同款前置，幂等）
    with get_db() as db:
        rows = db.execute(
            "WITH face AS ("
            "  SELECT bo.product_id AS pid, bl.warehouse_id AS wid, SUM(bo.quantity) AS qty"
            "  FROM bin_occupancy bo JOIN bin_locations bl ON bo.bin_id=bl.id"
            "  WHERE LOWER(COALESCE(bl.zone,''))='pick_face'"
            "  GROUP BY bo.product_id, bl.warehouse_id"
            ") "
            "SELECT pfc.product_id AS product_id, COALESCE(p.name,'') AS product_name,"
            "       pfc.warehouse_id AS warehouse_id, pfc.reserve_bin AS reserve_bin,"
            "       pfc.forward_min AS min_qty, pfc.forward_max AS max_qty,"
            "       COALESCE(face.qty,0) AS pick_face_qty "
            "FROM pick_face_config pfc "
            "LEFT JOIN products p ON pfc.product_id=p.id "
            "LEFT JOIN face ON face.pid=pfc.product_id AND face.wid=pfc.warehouse_id "
            "WHERE pfc.warehouse_id=? AND COALESCE(face.qty,0) < pfc.forward_min "
            "ORDER BY (pfc.forward_min - COALESCE(face.qty,0)) DESC",
            (warehouse_id,)).fetchall()
        return [dict(r) for r in rows]

def wms_pick_face_config_save(product_id, forward_min, forward_max, warehouse_id=1, reserve_bin=""):
    """保存拣货位补货上下限（按 `product_id` UPSERT）。

    🔴 v465f 修：原实现写 `pick_face_qty/min_qty/max_qty/location_code` —— 生产库无这些列
    （表结构见 `_init` DDL）。参数名与 `routers/inventory.py::WmsReplenConfig`
    （`forward_min`/`forward_max`/`reserve_bin`）对齐；唯一调用方按**位置**传参，重命名无影响。
    """
    with get_db() as db:
        db.execute(
            "INSERT INTO pick_face_config (product_id,warehouse_id,forward_min,forward_max,reserve_bin) "
            "VALUES (?,?,?,?,?) "
            "ON CONFLICT(product_id) DO UPDATE SET "
            "warehouse_id=excluded.warehouse_id, forward_min=excluded.forward_min, "
            "forward_max=excluded.forward_max, reserve_bin=excluded.reserve_bin",
            (product_id, warehouse_id, forward_min, forward_max, reserve_bin))
        db.commit()
    return {"success": True}

