def barcode_scan_log_list(limit=50, offset=0, direction="", product_id=0):
    """List barcode scan events (newest first), optional direction/product filter."""
    with get_db() as db:
        where = []
        params = []
        if direction:
            where.append("l.direction=?")
            params.append(direction)
        if product_id:
            where.append("l.product_id=?")
