# ===== Inbound Orders (v108) — 入库单 =====
def _gen_inbound_no():
    return "RK" + datetime.now().strftime("%Y%m%d%H%M%S")

def create_inbound_order(supplier_id, warehouse_id, remark, items):
    """Create a draft inbound order with line items. items: [{product_id,quantity,batch_no,expiry_date,cost}]"""
    if not supplier_id:
        return {"success": False, "error": "请选择供应商"}
    if not items or not isinstance(items, list) or len(items) == 0:
        return {"success": False, "error": "请至少添加一行商品"}
    with get_db() as db:
        order_no = _gen_inbound_no()
        cur = db.execute(
            "INSERT INTO inbound_orders (order_no,supplier_id,warehouse_id,status,remark,created_at) VALUES (?,?,?,?,?,datetime('now','localtime'))",
            (order_no, int(supplier_id), int(warehouse_id or 1), 'draft', remark or '')
        )
        iid = cur.lastrowid
        saved = 0
        for it in items:
            pid = int(it.get("product_id", 0) or 0)
            qty = float(it.get("quantity", 0) or 0)
            if pid <= 0 or qty <= 0:
                continue
            db.execute(
                "INSERT INTO inbound_order_items (inbound_id,product_id,quantity,batch_no,expiry_date,cost) VALUES (?,?,?,?,?,?)",
                (iid, pid, qty, it.get("batch_no", "") or "", it.get("expiry_date", "") or "", float(it.get("cost", 0) or 0))
            )
            saved += 1
        if saved == 0:
            db.execute("DELETE FROM inbound_orders WHERE id=?", (iid,))
            db.commit()
            return {"success": False, "error": "没有有效的商品行"}
        db.commit()
    return {"success": True, "id": iid, "order_no": order_no}

def list_inbound_orders(status="", warehouse_id=0, limit=50, offset=0):
    with get_db() as db:
        where = []
        params = []
        if status:
            where.append("o.status=?")
            params.append(status)
        if warehouse_id:
            where.append("o.warehouse_id=?")
            params.append(int(warehouse_id))
        w = (" WHERE " + " AND ".join(where)) if where else ""
        rows = db.execute(
            f"SELECT o.*, c.name as supplier_name FROM inbound_orders o LEFT JOIN contacts c ON o.supplier_id=c.id {w} ORDER BY o.created_at DESC LIMIT ? OFFSET ?",
            params + [int(limit), int(offset)]
        ).fetchall()
        return [dict(r) for r in rows]

def get_inbound_order(iid):
    with get_db() as db:
        o = db.execute(
            "SELECT o.*, c.name as supplier_name FROM inbound_orders o LEFT JOIN contacts c ON o.supplier_id=c.id WHERE o.id=?",
            (iid,)
        ).fetchone()
        if not o:
            return None
        d = dict(o)
        items = db.execute(
            "SELECT it.*, p.name as product_name, p.spec as product_spec FROM inbound_order_items it LEFT JOIN products p ON it.product_id=p.id WHERE it.inbound_id=?",
            (iid,)
        ).fetchall()
        d["items"] = [dict(r) for r in items]
        return d

def receive_inbound_order(iid):
    with get_db() as db:
        o = db.execute("SELECT * FROM inbound_orders WHERE id=?", (iid,)).fetchone()
        if not o:
            return {"success": False, "error": "入库单不存在"}
        if o["status"] == "received":
            return {"success": False, "error": "该入库单已收货"}
        wid = o["warehouse_id"]
        items = db.execute("SELECT * FROM inbound_order_items WHERE inbound_id=?", (iid,)).fetchall()
        if not items:
            return {"success": False, "error": "入库单无明细，无法收货"}
        received = []
        for it in items:
            res = batch_in(it["product_id"], wid, it["quantity"], it["cost"], it["batch_no"], it["expiry_date"])
            received.append({"product_id": it["product_id"], "quantity": it["quantity"], "result": res})
        db.execute("UPDATE inbound_orders SET status='received', received_at=datetime('now','localtime') WHERE id=?", (iid,))
        db.commit()
    return {"success": True, "received": received}

def cancel_inbound_order(iid):
    with get_db() as db:
        o = db.execute("SELECT * FROM inbound_orders WHERE id=?", (iid,)).fetchone()
        if not o:
            return {"success": False, "error": "入库单不存在"}
        if o["status"] == "received":
            return {"success": False, "error": "已收货的入库单不可取消"}
        db.execute("UPDATE inbound_orders SET status='cancelled' WHERE id=?", (iid,))
        db.commit()
    return {"success": True}

# ===== Transfer Orders (v89) =====
def transfer_order_create(product_id, product_name, from_wh, to_wh, quantity, operator_id="", note="", items=None):
    # v107.146: 支持多行明细(items=[{product_id,product_name,quantity}]) — 引擎表单多行提交
    from db.connection import _gen_no
    ono = _gen_no("TF")
    with get_db() as db:
        db.execute("INSERT INTO transfer_orders (order_no,product_id,product_name,from_warehouse_id,to_warehouse_id,quantity,operator_id,note) VALUES (?,?,?,?,?,?,?,?)", (ono, product_id or 0, product_name or '', from_wh, to_wh, quantity or 0, operator_id, note))
        oid = db.execute("SELECT last_insert_rowid()").fetchone()[0]
        if items:
            # v683：明细带「单位 / 折算比 / 折小量」。单位为空 ⇒ 三列都不写
            #   ⇒ 与改动前逐字一致（老前端、舟谱导入零影响）。
            from db.queries.units import ratio_to_base as _r2b, base_qty_of as _bq_of
            for it in items:
                _cols = ["transfer_id", "product_id", "product_name", "quantity", "unit_price", "amount"]
                _vals = [oid, it.get('product_id') or 0, it.get('product_name') or '',
                         it.get('quantity') or 0, it.get('unit_price') or 0,
                         (it.get('quantity') or 0) * (it.get('unit_price') or 0)]
                _u = str(it.get('unit') or '').strip()
                if _u:
                    _cols.append("unit"); _vals.append(_u)
                    _pid = int(it.get('product_id') or 0)
                    _pd = db.execute(
                        "SELECT unit, medium_unit, medium_ratio, large_unit, large_ratio "
                        "  FROM products WHERE id=?", (_pid,)).fetchone() if _pid else None
                    _rr = float(_r2b(dict(_pd), _u) or 0) if _pd else 0.0
                    if _rr > 0:
                        _bq2 = _bq_of(it.get('quantity') or 0, _rr)
                        if _bq2 is not None:
                            _cols += ["base_ratio", "base_qty"]; _vals += [_rr, _bq2]
                    else:
                        # 🔴 换算比算不出 ⇒ 只留单位、不折算，并且**要留痕**：
                        #    拿 1 去顶会把「一箱」当「一个」，库存少一大截。
                        logging.getLogger("hergent").warning(
                            "[v683] 调拨明细单位换算不出：product_id=%s unit=%s —— 该行按原数量记账", _pid, _u)
                db.execute("INSERT INTO transfer_order_items (%s) VALUES (%s)" % (
                    ",".join(_cols), ",".join("?" * len(_vals))), _vals)
        db.commit()
    return {"success": True, "order_no": ono, "id": oid}

# v478：调拨单列表的**服务端排序白名单** + 日期/商品关键字筛选（对齐采购 v470 / 销售 v473）。
#   🔴 排序必须在 SQL 里做：本列表服务端分页。前端对当前页重排翻页即散架。
#   🔴 必须是白名单：`order_by` 来自 query（用户可控），直接拼 = 注入面。未登记键回落 `to_.id DESC`。
#   🔴 尾缀 `, to_.id DESC` 是决定性 tiebreaker：同值行翻页会重复/丢失（分页表经典事故）。
#   ⚠️ `from_wh_name`/`to_wh_name` = JOIN 的 `w1.name`/`w2.name`；`product_name` = `to_.product_name`；
#      `note` 不入白名单（自由文本不排，前端也不会把它当可排序列）。
#   ⚠️ 参数顺序保持 `(status, limit, offset, ...)`：兼容 `routers/inventory.py:226`（keyword 调）
#      与 `tools/v449-listfix-harness.py:93` 的**位置传参** `("", 1, 1)`，不可把新参数插到 limit/offset 前。
_TRANSFER_ORDER_SQL = {
    'id':           'to_.id',
    'order_no':     'to_.order_no',
    'product_name': 'to_.product_name',
    'quantity':     'to_.quantity',
    'status':       'to_.status',
    'created_at':   'to_.created_at',
    'from_wh_name': 'w1.name',
    'to_wh_name':   'w2.name',
}

def _transfer_order_where(status="", date_from="", date_to="", keyword="", operator_id=""):
    """返回 `(where_including_WHERE, params)`。全部默认空 = 不筛 ⇒ 既有调用方零影响。

    · `date_from`/`date_to`：按 `created_at` 的 `YYYY-MM-DD` 前缀筛（>= 当天 00:00:00 / <= 当天 23:59:59）。
    · `keyword`：匹配 `order_no` OR `product_name`（LIKE %kw%）。
    """
    where, params = [], []
    if status:
        where.append("to_.status=?")
        params.append(status)
    if date_from:
        where.append("to_.created_at >= ?")
        params.append(date_from + " 00:00:00")
    if date_to:
        where.append("to_.created_at <= ?")
        params.append(date_to + " 23:59:59")
    if keyword:
        k = f"%{keyword}%"
        where.append("(to_.order_no LIKE ? OR to_.product_name LIKE ?)")
        params.extend([k, k])
    # v526（P1-1 第二期）：行级隔离 —— 销售员只看自己建的调拨单。`operator_id` 存用户 id 字符串。
    if operator_id:
        where.append("to_.operator_id=?")
        params.append(operator_id)
    w = (" WHERE " + " AND ".join(where)) if where else ""
    return w, params

def transfer_order_list(status="", limit=200, offset=0, date_from="", date_to="",
                        keyword="", order_by="", order_dir="", operator_id=""):
    """调拨单列表（只读投影）。v478：+ 服务端排序 + 日期/商品关键字筛选。
    v526：+ `operator_id` 行级隔离（销售员只看自己建的单；默认空 = 不筛 ⇒ 既有调用方零影响）。"""
    with get_db() as db:
        w, p = _transfer_order_where(status, date_from, date_to, keyword, operator_id)
        _expr = _TRANSFER_ORDER_SQL.get((order_by or '').strip())
        _dir = 'ASC' if str(order_dir or '').strip().lower() == 'asc' else 'DESC'
        _osql = (f" ORDER BY {_expr} {_dir}, to_.id DESC") if _expr else " ORDER BY to_.id DESC"
        return [dict(r) for r in db.execute(
            f"SELECT to_.*, w1.name as from_wh_name, w2.name as to_wh_name "
            f"FROM transfer_orders to_ "
            f"LEFT JOIN warehouses w1 ON to_.from_warehouse_id=w1.id "
            f"LEFT JOIN warehouses w2 ON to_.to_warehouse_id=w2.id "
            f"{w}{_osql} LIMIT ? OFFSET ?", list(p) + [limit, offset]).fetchall()]


def transfer_order_count(status="", date_from="", date_to="", keyword="", operator_id=""):
    """调拨单总数（服务端分页用）。v478 起与 `transfer_order_list` 共用 `_transfer_order_where`，
       保证「筛选后的总数」与列表行数口径逐字一致（否则分页器页数算错）。v526：+ `operator_id` 行级隔离。"""
    with get_db() as db:
        w, p = _transfer_order_where(status, date_from, date_to, keyword, operator_id)
        return db.execute(f"SELECT COUNT(*) FROM transfer_orders to_ {w}", p).fetchone()[0]


def transfer_order_counts(date_from="", date_to="", keyword="", operator_id=""):
    """v498：调拨列表「状态页签」各档计数。

    🔴 口径与 `purchases.py::purchase_order_list` / `sales.py::sale_order_list` 的
       counts 逐字同构：**忽略 status、保留其余筛选**（日期 / 关键字都进），
       否则切一个页签其它页签的数字跟着漂移。`status` 故意**不进签名** ——
       调用方（`routers/psi.py`）要的就是「当前选中的状态不参与计数」。
    ⚠️ 只追加新函数，`transfer_order_list` / `transfer_order_count` 的签名与返回
       **逐字不动**（`routers/inventory.py:226` 与 v449 harness 的位置传参都指着它们）。
    返回 `{draft: n, completed: n, cancelled: n, all: sum}`（未出现的状态不设键，
       前端按 `|| 0` 读；`all` = 各档之和）。
    """
    with get_db() as db:
        w, p = _transfer_order_where("", date_from, date_to, keyword, operator_id)
        counts = {r['status']: int(r['n'] or 0) for r in db.execute(
            f"SELECT to_.status, COUNT(*) n FROM transfer_orders to_ {w} GROUP BY to_.status",
            p).fetchall()}
        counts['all'] = sum(counts.values())
        return counts


def transfer_order_get(tid):
    # 🔴 v449 修 `to_.*`：别名声明是 `to_`，原写 `SELECT to.*` —— SQLite 把 `to` 当**关键字 TO**
    #   ⇒ `sqlite3.OperationalError: near "to": syntax error`（与同族 `transfer_order_list` 同病）。
    #   本函数在 v449 之前**从未被任何端点调用**（`transfer_orders` 生产 0 张 + 前端无调拨页）
    #   ⇒ 这层缺陷与上一层的 tuple 拼接叠在一起，一起被 v449 新调拨页首次触发时暴露。
    with get_db() as db:
        r = db.execute("SELECT to_.*, w1.name as from_wh_name, w2.name as to_wh_name FROM transfer_orders to_ LEFT JOIN warehouses w1 ON to_.from_warehouse_id=w1.id LEFT JOIN warehouses w2 ON to_.to_warehouse_id=w2.id WHERE to_.id=?", (tid,)).fetchone()
        return dict(r) if r else None

class _TransferPostingError(Exception):
    """v449：调拨过账失败 —— **必须抛异常而不是 return**，见 `transfer_order_complete`。"""
    pass


def transfer_order_complete(tid, operator_id=""):
    """调拨过账：逐行「调出仓 −qty」+「调入仓 +qty」，**同一事务**。

    🔴 v449 修了本函数三处既有真实缺陷（此前无人踩到，因为 `transfer_orders` 生产 0 张）：
      ① **死导入**：原先写 `from inventory import inventory_adjust`，而 `server/inventory.py`
         **根本不存在**（真身在 `db/queries/inventory.py`）⇒ 每次调用都
         `ModuleNotFoundError`，即该端点**必然 500**。
      ② **`None` 上做成员判断**：`inventory_adjust` 成功时返回 **`None`**（不是 dict），
         而原代码写 `if "error" in r1:` ⇒ `TypeError: argument of type 'NoneType'
         is not iterable` —— **成功路径反而崩**。（`purchase_return_create` 与
         `return_order_create` 里都是 `isinstance(x, dict) and "error" in x`，只有这里写歪。）
      ③ 🔴 **最严重的：失败时 `return` 会提交半截调拨**。本函数体在
         `with get_db_tx() as db:` 里，而 `get_db_tx` 是「正常退出即 commit」——
         原代码 `if "error" in r1: return r1` 从 with 块**正常返回** ⇒ 事务被提交：
         调出仓的货**已经扣掉**，调入仓却没加 ⇒ **货凭空消失**，而接口返回的是一个
         error（调用方以为"没成功、库存没动"）。改成 `raise` 让事务整体回滚。

    🔴 v532c P1-1：**调出腿改为批次感知扣减**（`gross_deduct`），不再用 `inventory_adjust(-qty)`。
       `inventory_adjust` 的扣减是 `SELECT id,quantity FROM inventory
       WHERE product_id=? AND warehouse_id=?` 的 **`fetchone()`** —— 不看 `batch_no`、
       只取第一条。一个 `(product_id, warehouse_id)` 组合有**多批次行**时（生产实证存在：
       `inventory` 里就有「最早那批 quantity=0、合计>0」的组合），调拨**任何数量**都会报
       「库存不足：需要10，可用0」，而货其实在库 —— 老板建的第一张调拨单必然撞上。
       调入腿仍是 `inventory_adjust(+qty)`：正数量调整没有批次歧义（新增/累加到既有行）。

       ⚠️ 为什么用 `gross_deduct` 而不是 `fefo_deduct`（以 `db/queries/inventory.py` 源码为准）：
         · `gross_deduct(db, pid, wh, qty, ref_type=, ref_id=, batch_no=)` —— **不过滤效期**，
           逐批扣、可跨批、每批带 `quantity>=?` 原子守卫；不自开事务、不 commit，
           返回 `{'success':True,'used':[...]}` / `{'error':...,'used':[]}`。
         · `fefo_deduct` 套了 `SALEABLE_BATCH_COND`（**排除过期批次**）——那是**销售出库**
           的口径。调拨是**自己仓到自己仓的实物搬动**，不是销售：过期奶该走报损，
           但它**仍然占着仓位**，调拨它不该被"可售"口径挡住。用 fefo 会让「调不动过期批次」
           变成又一个假性库存不足。⇒ 调拨归 `gross_deduct`（非销售出库）这一族。
           （顺带：它的排序键与 fefo 逐字相同 ⇒ 仍然是「最早到期先出」，符合低温奶的常识。）
    """
    with get_db_tx() as db:
        # v525d：审批流引入 `approved` 中间态 —— 走审批的调拨单终审后落到 `approved`，
        #   过账（真正移库）必须认这个态，否则审批通过的单永远过不了账（死在状态机）。
        #   无审批的调拨单仍是 `draft`，一并放开。
        r = db.execute("SELECT * FROM transfer_orders WHERE id=? AND status IN ('draft','approved')", (tid,)).fetchone()
        # v532c P2-6：这里**曾经是事务内 `return`**（与上面 ③ 同款反模式）。当前它前面只有
        #   SELECT，不会留下半截数据 —— 但同一个函数里两种失败写法并存，就是下一次改动的坑：
        #   后来者在中间插一句 UPDATE，这行立刻变成「提交了半个调拨」。统一成 `raise`。
        if not r:
            raise _TransferPostingError("调拨单不存在或已完成")
        d = dict(r)
        # 🔴 v449 修既有真实缺陷：这里原本写的是 `from inventory import inventory_adjust`
        #    —— **`server/inventory.py` 根本不存在**（`inventory_adjust` 的真身在
        #    `db/queries/inventory.py`）⇒ 本函数每次调用都 `ModuleNotFoundError`，
        #    即 `POST /api/inventory/transfer-orders/{tid}/complete` **必然 500**。
        #    为什么一直没被发现：`transfer_orders` 生产 **0 张**（这条双仓通道
        #    前端从未接过 UI），没有任何调用方踩到它。
        #    ⚠️ 与 `purchase_return_create` 里那句**逐字同源**的导入对照着看：
        #       那边一直是对的，只有这一处写错 —— 典型的手抄一份写歪。
        from db.queries.inventory import inventory_adjust, gross_deduct
        # v107.146: 多行调拨逐行过账; 无明细行时回退单行(兼容旧数据)
        items = db.execute("SELECT * FROM transfer_order_items WHERE transfer_id=?", (tid,)).fetchall()

        def _post_out(pid, wh, qty):
            """调出腿：**批次感知**扣减（v532c P1-1），失败即抛 —— **绝不 return**（见 ③）。

            `gross_deduct` 只在**已开的写事务**里干活（不 commit）—— 这里正在
            `get_db_tx()` 内，符合它的前置条件；出错只返回 `{'error': ...}`，
            由本函数转成异常交给事务回滚。
            """
            rr = gross_deduct(db, pid, wh, qty, ref_type="transfer_out", ref_id=tid)
            if isinstance(rr, dict) and "error" in rr:
                raise _TransferPostingError(rr["error"])

        def _post_in(pid, wh, qty):
            """调入腿：正数量调整没有批次歧义，`inventory_adjust(+qty)` 仍然够用。"""
            rr = inventory_adjust(pid, wh, qty, ref_type="transfer_in", ref_id=tid, db_conn=db)
            if isinstance(rr, dict) and "error" in rr:
                raise _TransferPostingError(rr["error"])

        def _move(pid, from_wh, to_wh, qty):
            """搬一行：调出 −qty → 调入 +qty。**两步之间抛错 = 整单回滚**（见 ③）。"""
            # 数量 <= 0 不产生任何库存动作：无明细行的老单 `transfer_orders.quantity`
            # 可能是 0（建单时未带 items），旧行为是「空转一次也不报错」，这里保持一致。
            if float(qty or 0) <= 0:
                return
            _post_out(pid, from_wh, qty)
            _post_in(pid, to_wh, qty)

        # 先动「调出仓」再动「调入仓」：顺序上先减后加，可以让「不够」在**第一次**就暴露，
        # 而不是等调入仓已经加完才发现调出仓根本没货（那种情况靠回滚兜，不如不进）。
        # v683：过账数量用**折小单位量**（`base_qty`），不是明细行上的档位数量。
        #   🔴 这是本次改造真正的记账点：用户填「2 箱」而库存是瓶，按 2 扣就是把
        #      2 瓶搬过去。历史行 `base_qty=0` ⇒ 回退 `quantity`（旧口径零变化）。
        def _qty_of_row(row):
            try:
                _bq = float((row["base_qty"] if "base_qty" in row.keys() else 0) or 0)
            except Exception:
                _bq = 0.0
            if _bq > 0:
                return _bq
            return float(row["quantity"] or 0)

        if items:
            for it in items:
                _move(it["product_id"], d["from_warehouse_id"], d["to_warehouse_id"], _qty_of_row(it))
        else:
            _move(d["product_id"], d["from_warehouse_id"], d["to_warehouse_id"], float(d["quantity"] or 0))
        db.execute("UPDATE transfer_orders SET status='completed', operator_id=? WHERE id=?", (operator_id, tid))
    return {"success": True}

def return_order_list(status="returned", limit=200, offset=0):
    # v107.139: 改查 return_orders 表(退货单真实存储), JOIN sale_orders 拿原单号 + contacts 拿客户名
    # 原实现查 sale_orders.status=returned 是空表(退货经 return_order_create 写 return_orders 独立表)
    # 🔴 v449 修 `list(p)`：与 `transfer_order_list` 同族同病 —— `p` 是 tuple（`("", ())` /
    #   `(status,)`），原写 `params = p + [limit, offset]` ⇒ `TypeError` ⇒ 本端点必然 500。
    #   生产实测：`GET /api/psi/sale-return-orders` 之外的销售退货列表调用方每次都 500。
    with get_db() as db:
        w, p = ("WHERE ro.status=? ", (status,)) if status else ("", ())
        params = list(p) + [limit, offset]
        rows = db.execute(
            "SELECT ro.*, so.order_no AS sale_order_no, c.name AS customer_name "
            "FROM return_orders ro LEFT JOIN sale_orders so ON ro.sale_order_id=so.id "
            "LEFT JOIN contacts c ON ro.contact_id=c.id " + w +
            "ORDER BY ro.id DESC LIMIT ? OFFSET ?", params
        ).fetchall()
        return [dict(r) for r in rows]

# ══════════════════════════════════════════════════════════════════════════════
#  v500（2026-10-15）：销售退货单列表 —— `return_orders` 的**真列表出口**
# ══════════════════════════════════════════════════════════════════════════════
#  🔴 为什么必须另起一组函数，而不改 `return_order_list` 的签名：
#     `return_order_list(status='returned', …)` 是 `routers/sales.py::GET /return-orders`
#     的**唯一实现**，而那个端点的调用方（旧壳 / 小程序 / 舟谱导入器）依赖它
#     「默认 status='returned'」的既有行为。给它加 `order_type` / `total` / `counts`
#     会**顺带改掉**那些既有消费方看到的东西 —— 那是 v443 那类"改 A 坏 B"的事故。
#     ⇒ 新端点 `GET /api/psi/sale-return-orders` 专用新函数，既有函数**一个字符不动**。
#
#  🔴 为什么要这一组：`return_orders` 此前**没有带分页/计数/筛选**的列表出口。
#     前端「自提退单 / 车销退单」两个入口筛的是 `sale_orders.status='returned'`，
#     而那个 `returned` **全系统无人写**（生产实测：`sale_orders` 22505 行里
#     0 行 returned）⇒ 两个入口**建完退货单就看不见**，一直是空的。

def _sale_return_where(db, status='', order_type='', date_from='', date_to='', keyword='',
                       customer_id=0):
    """v500：销售退货单筛选条件（`list` / `count` / `counts` **共用一份**）。

    🔴 `status` 是**黑名单**语义（与采购退货 `_purchase_return_where` 同构）：
       `'draft'` = 只看草稿；非 `'draft'` = 全部**已确认**。不能写 `='confirmed'`
       白名单 —— 存量行 `status` 可能是空串 / NULL，白名单会让历史退货**全部消失**。
    🔴 `order_type` 是**精确相等**：`'self_pickup'`（自提退单）/ `'vehicle_sale'`（车销退单）。
       ⚠️ **不**把空 `order_type` 的老行塞进任何一边：那会让两个入口都多出
       「说不清是哪一类」的行，而这类行在 v449 之前根本不存在（老退货单没有类型）。
       空值行只在**不带 order_type** 的通用视图里出现（前端两个入口都带 ⇒ 看不到）。
    🔴 日期口径：`order_date` 在老行里被写成 `'%Y-%m-%d %H:%M:%S'`（建单时的
       `time.strftime` 兜底），新行是 `'%Y-%m-%d'` ⇒ 一律取 **`substr(…,1,10)`** 比较，
       否则新老行的日期筛选结果会不一致（同一天的新单能筛到、老单筛不到）。
    """
    where, params = [], []
    ot = str(order_type or '').strip()
    if ot:
        where.append("COALESCE(ro.order_type,'')=?")
        params.append(ot)
    st = str(status or '').strip()
    if st:
        if st == 'draft':
            where.append("COALESCE(ro.status,'confirmed')='draft'")
        else:
            where.append("COALESCE(ro.status,'confirmed')!='draft'")
    _cid = int(customer_id or 0)
    if _cid:
        where.append("ro.contact_id=?")
        params.append(_cid)
    _df = str(date_from or '').strip()
    if _df:
        where.append("substr(COALESCE(ro.order_date,''),1,10)>=?")
        params.append(_df)
    _dt = str(date_to or '').strip()
    if _dt:
        where.append("substr(COALESCE(ro.order_date,''),1,10)<=?")
        params.append(_dt)
    _kw = str(keyword or '').strip()
    if _kw:
        try:
            cols = {r[1] for r in db.execute("PRAGMA table_info(return_orders)").fetchall()}
        except Exception:
            cols = set()
        # 关键字 = 「人 / 事 / 号 / 原单号」四路：客户名、退货原因、本单号、原销售单号。
        parts = ["COALESCE(c.name,'') LIKE ?", "COALESCE(ro.reason,'') LIKE ?",
                 "COALESCE(so.order_no,'') LIKE ?"]
        kp = [f"%{_kw}%", f"%{_kw}%", f"%{_kw}%"]
        if "order_no" in cols:
            parts.append("COALESCE(ro.order_no,'') LIKE ?")
            kp.append(f"%{_kw}%")
        where.append("(" + " OR ".join(parts) + ")")
        params.extend(kp)
    return ((" WHERE " + " AND ".join(where)) if where else ""), params


def sale_return_list(status='', limit=200, offset=0, order_type='', date_from='', date_to='',
                     keyword='', customer_id=0):
    """v500：销售退货单列表（查真表 `return_orders`，只读投影）。

    🔴 显式投影 + `COALESCE` 兜底：`order_no`（v500）/ `warehouse_id` / `order_type` /
       `driver_id` / `note`（v449）都是后补的列 ⇒ 老库读得到也不崩。
    🔴 三个名字（客户 / 仓库）与原销售单号都 LEFT JOIN 带出 —— 列表页要显示名字，
       不能让前端逐行再打接口（N+1）。
    """
    with get_db() as db:
        cols = {r[1] for r in db.execute("PRAGMA table_info(return_orders)").fetchall()}

        def _c(name, fallback):
            return ("COALESCE(ro.%s,%s) AS %s" % (name, fallback, name)) if name in cols \
                else ("%s AS %s" % (fallback, name))

        sel = [
            "ro.id", "ro.sale_order_id", "ro.contact_id", "ro.total_amount",
            "ro.reason", "ro.operator_id",
            "COALESCE(ro.status,'confirmed') AS status",
            _c("order_no", "''"),
            _c("order_date", "''"),
            _c("order_type", "''"),
            _c("quality_status", "''"),
            _c("note", "''"),
            _c("driver_id", "''"),
            ("COALESCE(ro.warehouse_id,0) AS warehouse_id" if "warehouse_id" in cols
             else "0 AS warehouse_id"),
            "COALESCE(c.name,'') AS customer_name",
            "COALESCE(w.name,'') AS warehouse_name",
            "COALESCE(so.order_no,'') AS src_order_no",
        ]
        w, p = _sale_return_where(db, status, order_type, date_from, date_to, keyword, customer_id)
        sql = (
            "SELECT %s FROM return_orders ro "
            " LEFT JOIN contacts c ON ro.contact_id=c.id "
            " LEFT JOIN warehouses w ON ro.warehouse_id=w.id "
            " LEFT JOIN sale_orders so ON ro.sale_order_id=so.id "
            "%s ORDER BY ro.id DESC LIMIT ? OFFSET ?" % (",".join(sel), w))
        return [dict(r) for r in db.execute(
            sql, tuple(list(p) + [int(limit or 200), int(offset or 0)])).fetchall()]


def sale_return_count(status='', order_type='', date_from='', date_to='', keyword='',
                      customer_id=0):
    """v500：销售退货单「筛选后总数」（服务端分页用）。与 list / counts 共用 `_sale_return_where`。"""
    with get_db() as db:
        w, p = _sale_return_where(db, status, order_type, date_from, date_to, keyword, customer_id)
        return int(db.execute(
            "SELECT COUNT(*) FROM return_orders ro "
            "LEFT JOIN contacts c ON ro.contact_id=c.id "
            "LEFT JOIN sale_orders so ON ro.sale_order_id=so.id" + w, p).fetchone()[0] or 0)


def sale_return_counts(order_type='', date_from='', date_to='', keyword='', customer_id=0):
    """v500：销售退货列表「状态页签」各档计数（全部 / 草稿 / 已确认）。

    🔴 与 `purchase_return_counts` / `transfer_order_counts` **逐字同构**：
       **忽略 status、保留其余筛选** ⇒ 切页签时各档数字一动不动。
    🔴 分档键只有 `draft` / `confirmed`，且与列表的黑名单筛选同构 ⇒
       「页签显示 n 张、点进去也确实是 n 张」。
    返回 `{draft: n, confirmed: n, all: sum}`（未出现的档不设键，前端按 `|| 0` 读）。
    """
    with get_db() as db:
        w, p = _sale_return_where(db, '', order_type, date_from, date_to, keyword, customer_id)
        counts = {r['st']: int(r['n'] or 0) for r in db.execute(
            "SELECT CASE WHEN COALESCE(ro.status,'confirmed')='draft' "
            "            THEN 'draft' ELSE 'confirmed' END AS st, COUNT(*) n "
            "FROM return_orders ro "
            "LEFT JOIN contacts c ON ro.contact_id=c.id "
            "LEFT JOIN sale_orders so ON ro.sale_order_id=so.id" + w + " GROUP BY st",
            p).fetchall()}
        counts['all'] = sum(counts.values())
        return counts


