def get_approval_workflow(module, trigger_value):
    db = _connect(); c = db.cursor()
    c.execute("SELECT * FROM approval_workflows WHERE module=? AND is_active=1 ORDER BY CAST(trigger_value AS REAL) DESC", (module,))
    rows = [dict(r) for r in c.fetchall()]
    for r in rows:
        try:
            if float(trigger_value) >= float(r['trigger_value']): db.close(); return r
        except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}")
    db.close(); return None

# ===== Document State Machine =====
VALID_STATES = {"draft":["submitted"],"submitted":["in_approval","approved","rejected"],"in_approval":["approved","rejected","returned"],"approved":["executed","voided"],"rejected":["draft"],"returned":["draft"],"executed":[],"voided":[]}
VALID_DOC_TYPES = {"purchase_req","purchase_order","sale_order","expense","payment","refund","transfer","exchange","freebie","display_fee","demand_plan","sales_contract"}

def doc_state_set(ref_type, ref_id, workflow_id, new_state, current_step=0, total_steps=0):
    if ref_type not in VALID_DOC_TYPES:
        return {"error": f"Invalid document type: {ref_type}"}
    db = _connect(); c = db.cursor()
    c.execute("SELECT current_state FROM document_states WHERE ref_type=? AND ref_id=?", (ref_type,ref_id))
    row = c.fetchone(); old_state = row['current_state'] if row else 'draft'
    if old_state != new_state and new_state not in VALID_STATES.get(old_state,[]):
        db.close(); return {"error": f"Invalid state transition: {old_state} -> {new_state}"}
    sub_at = f"datetime('now','localtime')" if new_state == 'submitted' else f"COALESCE((SELECT submitted_at FROM document_states WHERE ref_type='{ref_type}' AND ref_id={ref_id}),datetime('now','localtime'))"
    c.execute(f"INSERT OR REPLACE INTO document_states(ref_type,ref_id,workflow_id,current_state,current_step,total_steps,submitted_at,updated_at) VALUES(?,?,?,?,?,?,{sub_at},datetime('now','localtime'))", (ref_type,ref_id,workflow_id,new_state,current_step,total_steps))
    db.commit(); db.close(); return {"success":True,"old_state":old_state,"new_state":new_state}

def doc_state_get(ref_type, ref_id):
    db = _connect(); c = db.cursor()
    c.execute("SELECT * FROM document_states WHERE ref_type=? AND ref_id=?", (ref_type,ref_id))
    row = c.fetchone(); db.close()
    return dict(row) if row else {"current_state":"draft","current_step":0,"total_steps":0}

def doc_submit_for_approval(ref_type, ref_id, trigger_value):
    wf = get_approval_workflow(ref_type, trigger_value)
    if not wf:
        doc_state_set(ref_type, ref_id, 0, "approved")
        return {"success":True,"auto_approved":True}
    steps = approval_step_list(wf['id']); total = len(steps)
    doc_state_set(ref_type, ref_id, wf['id'], "submitted", 1, total)
    return {"success":True,"workflow":wf,"steps":steps}

def doc_approve(ref_type, ref_id, approver_name, action="approve", comment=""):
    db = _connect(); c = db.cursor()
    ds = doc_state_get(ref_type, ref_id)
    if ds['current_state'] not in ("submitted","in_approval"): db.close(); return {"error":"Document not pending approval"}
    wf_id = ds['workflow_id']; current = ds['current_step']; total = ds['total_steps']

    # Check branch_logic for countersign
    wf = c.execute("SELECT branch_logic FROM approval_workflows WHERE id=?", (wf_id,)).fetchone()
    branch_logic = wf[0] if wf else "sequential"

    c.execute("INSERT INTO approval_history(ref_type,ref_id,workflow_id,step_order,approver_name,action,comment) VALUES(?,?,?,?,?,?,?)", (ref_type,ref_id,wf_id,current,approver_name,action,comment))
    db.commit()
    if action == "reject":
        doc_state_set(ref_type, ref_id, wf_id, "rejected", current, total); db.close()
        return {"success":True,"action":"rejected"}
    if action == "return":
        doc_state_set(ref_type, ref_id, wf_id, "returned", current, total); db.close()
        return {"success":True,"action":"returned"}

    if branch_logic == "countersign":
        # Check if all approvers on this step have approved
        all_approved = c.execute(
            "SELECT COUNT(*) as total_approvers, SUM(CASE WHEN action='approve' THEN 1 ELSE 0 END) as approved_count "
            "FROM approval_history WHERE ref_type=? AND ref_id=? AND step_order=? AND workflow_id=?",
            (ref_type, ref_id, current, wf_id)
        ).fetchone()
        step_approvers = c.execute(
            "SELECT COUNT(*) FROM approval_steps WHERE workflow_id=? AND step_order=? AND is_active=1",
            (wf_id, current)
        ).fetchone()[0] if branch_logic == "countersign" else 1

        if all_approved and all_approved[0] and step_approvers and all_approved[1] < step_approvers:
            db.close()
            return {"success":True,"action":"voted","message":f"已投票({all_approved[1]}/{step_approvers})，等待其他审批者"}

    next_step = current + 1
    if next_step > total:
        doc_state_set(ref_type, ref_id, wf_id, "approved", total, total)
        db.close(); return {"success":True,"action":"fully_approved"}
    doc_state_set(ref_type, ref_id, wf_id, "in_approval", next_step, total)
    db.close(); return {"success":True,"action":"advanced","message":f"Advanced to step {next_step}/{total}"}

def doc_get_pending_approvals(approver_role="", approver_user_id=0):
    db = _connect(); c = db.cursor()
    c.execute("SELECT ds.*,aw.name as workflow_name,aw.module FROM document_states ds LEFT JOIN approval_workflows aw ON ds.workflow_id=aw.id WHERE ds.current_state IN ('submitted','in_approval') ORDER BY ds.submitted_at DESC")
    rows = [dict(r) for r in c.fetchall()]; db.close(); return rows

def doc_get_approval_history(ref_type, ref_id):
    db = _connect(); c = db.cursor()
    c.execute("SELECT * FROM approval_history WHERE ref_type=? AND ref_id=? ORDER BY created_at DESC", (ref_type,ref_id))
    rows = [dict(r) for r in c.fetchall()]; db.close(); return rows

def doc_check_escalations():
    db = _connect(); c = db.cursor()
    c.execute("SELECT ds.*,aw.escalation_hours FROM document_states ds JOIN approval_workflows aw ON ds.workflow_id=aw.id WHERE ds.current_state IN ('submitted','in_approval') AND aw.escalation_hours>0")
    rows = [dict(r) for r in c.fetchall()]
    escalated = []
    for r in rows:
        try:
            submitted_dt = datetime.strptime(r['submitted_at'][:19], "%Y-%m-%d %H:%M:%S" if "T" not in str(r['submitted_at']) else "%Y-%m-%dT%H:%M:%S")
            if datetime.now() > submitted_dt + timedelta(hours=int(r.get('escalation_hours',0))):
                doc_state_set(r['ref_type'], r['ref_id'], r['workflow_id'], "in_approval", r['current_step']+1, r['total_steps'])
                escalated.append({"ref_type":r['ref_type'],"ref_id":r['ref_id']})
        except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}")
    db.commit(); db.close(); return {"escalated":len(escalated),"items":escalated}

