# ===== Multi-Tenant =====
def tenant_create(name, subdomain="", contact_name="", contact_phone="", plan="free", max_users=5):
    # Always use master DB for tenant management
    master_db = sqlite3.connect(DB_PATH); master_db.row_factory = sqlite3.Row; c = master_db.cursor()
    c.execute("INSERT OR IGNORE INTO tenants(name,subdomain,contact_name,contact_phone,plan,max_users) VALUES(?,?,?,?,?,?)", (name,subdomain or name.lower().replace(" ","-"),contact_name,contact_phone,plan,max_users))
    master_db.commit(); tid = c.lastrowid; master_db.close()
    # Create tenant database
    tenant_db_init(tid)
    # v635：新租户顺手建好 AI 隔离 home + 副驾 api_server 端口。
    # 🔴 为什么必须在这里做（不是等用户第一次配渠道）：
    #    租户创建是**一次性**动作，而 web 副驾按租户路由到各自实例
    #    （hermes_tenants.gateway_api），没有 api_server 配置的租户会被代理
    #    **直接 503**（有意不回落根实例）。新客户开完号就该能问 AI。
    #    网关进程本身由 scheduler 的保活（每 60 秒 ensure_running）拉起。
    # 软失败：开号链路不能因为 AI 侧出问题而中断（租户已建，AI 以后可补）。
    try:
        from hermes_tenants import ensure_home as _ensure_home
        _ensure_home(tid)
    except Exception as e:                                        # noqa: BLE001
        print(f"[tenant_create] 初始化租户 AI home 失败 tid={tid}: {e}")
    return tid

def tenant_list(active_only=True):
    db = _connect(); c = db.cursor()
    if active_only: c.execute("SELECT * FROM tenants WHERE is_active=1 ORDER BY name")
    else: c.execute("SELECT * FROM tenants ORDER BY name")
    rows = [dict(r) for r in c.fetchall()]; db.close(); return rows


def tenant_master_all(active_only=False):
    """🔴 **直连主库**读 `tenants` 全量（绕过租户上下文）。读不到返回 `None`。

    与 `tenant_list()` 的关键区别：`tenant_list()` 走 `_connect()`，在
    `set_tenant_context()` 之后读到的是**租户库自己的影子 `tenants` 表** ——
    生产实测 `tenant_1.db` / `tenant_10.db` 里那张表**都是 0 行**，
    于是「租户属性」（名字 / `readonly` / `subdomain`）会被静默读成**"没有这个租户"**，
    而且不报任何错（v352 踩到）。

    ⇒ 凡做**跨租户**判断或读**租户属性**（调度器遍历全部租户、外发渠道门禁、
    演示租户识别），一律用本函数，不要用 `tenant_list()`。

    返回 `None` 与返回 `[]` 语义不同：`None` = **读失败（未知）**，
    调用方应据此按最保守方向处理；`[]` = 确实一个租户都没登记。
    """
    try:
        con = sqlite3.connect(DB_PATH); con.row_factory = sqlite3.Row
        try:
            sql = "SELECT * FROM tenants" + (" WHERE is_active=1" if active_only else "")
            return [dict(r) for r in con.execute(sql + " ORDER BY id")]
        finally:
            con.close()
    except Exception as e:
        logging.getLogger("hergent").warning(f"tenant_master_all failed: {e}")
        return None


# 管理后台用：分页 + 搜索 + 排序读主库 tenants（v262 补齐 P1-5）
_TENANT_ORDER_COLS = {
    "id": "id", "name": "name", "plan": "plan", "max_users": "max_users",
    "created_at": "created_at", "is_active": "is_active",
}


def tenant_list_page(active_only=False, status="", q="", order_by="", order_dir="asc",
                     limit=0, offset=0):
    """→ `(rows, total)`，`total` 为**过滤后**条数。

    🔴 与 `tenant_list()` 的关键区别：本函数**直连主库只读、绕过租户上下文**。
    `tenant_list()` 走 `_connect()`，在 `set_tenant_context()` 之后读到的是**租户库自己的
    `tenants` 表**（生产 `tenant_1.db` 里躺着 6 行主库早已没有的历史租户）—— 见本文件顶部
    告警与 `_tenant_registry_snapshot` 的同类处理。分页/总数统计绝不能受上下文影响。

    `status`：`on` / `off` / 其它=不过滤。**必须支持 `off`** —— 否则「已停用」筛选只能
    在前端对"当前页"过滤，与 `total` 对不上（分页器会显示错的总数）。`active_only`
    仅为向后兼容保留，`status` 非空时以其为准。

    `order_by` 走白名单映射（杜绝拼接入 SQL）；`limit <= 0` 表示不分页（返回全部）。
    """
    where, args = [], []
    if status == "on":
        where.append("is_active=1")
    elif status == "off":
        where.append("is_active=0")
    elif active_only:
        where.append("is_active=1")
    if q:
        like = "%" + str(q) + "%"
        where.append("(name LIKE ? OR contact_name LIKE ? OR contact_phone LIKE ?)")
        args.extend([like, like, like])
    tail = (" WHERE " + " AND ".join(where)) if where else ""

    col = _TENANT_ORDER_COLS.get(str(order_by or ""), "name")
    direction = "DESC" if str(order_dir or "").lower() == "desc" else "ASC"

    con = sqlite3.connect("file:%s?mode=ro" % DB_PATH, uri=True)
    try:
        con.row_factory = sqlite3.Row
        total = int(con.execute("SELECT COUNT(*) FROM tenants" + tail, args).fetchone()[0])
        sql = ("SELECT * FROM tenants" + tail
               + " ORDER BY " + col + " " + direction + ", id ASC")
        qargs = list(args)
        if limit and int(limit) > 0:
            sql += " LIMIT ? OFFSET ?"
            qargs += [int(limit), max(0, int(offset))]
        rows = [dict(r) for r in con.execute(sql, qargs).fetchall()]
        return rows, total
    finally:
        con.close()

def tenant_get(tid):
    db = _connect(); c = db.cursor()
    c.execute("SELECT * FROM tenants WHERE id=?", (tid,)); row = c.fetchone(); db.close(); return dict(row) if row else None

def tenant_update(tid, name=None, plan=None, max_users=None, is_active=None, contact_name=None, contact_phone=None):
    db = _connect(); c = db.cursor(); updates = []; params = []
    if name: updates.append("name=?"); params.append(name)
    if plan: updates.append("plan=?"); params.append(plan)
    if max_users is not None: updates.append("max_users=?"); params.append(max_users)
    if is_active is not None: updates.append("is_active=?"); params.append(is_active)
    if contact_name is not None: updates.append("contact_name=?"); params.append(contact_name)
    if contact_phone is not None: updates.append("contact_phone=?"); params.append(contact_phone)
    if updates: params.append(tid); c.execute("UPDATE tenants SET "+",".join(updates)+" WHERE id=?", params); db.commit()
    db.close()

# ===== 租户成员与用量（2026-09-12 补齐）=====
# 背景：server.py 的 /api/tenants/{tid}/members(GET/POST/DELETE) 与 /{tid}/usage(GET)
# 调用的 tenant_member_list / tenant_member_add / tenant_member_remove /
# tenant_usage_stats **四个函数在本仓库里从未存在过**（全局 grep 无定义）→ 这 4 个端点
# 自 v88 起恒 500。成员关系只存主库 user_tenants；租户库的 users 表与登录无关。
_TENANT_USAGE_TABLES = ("products", "sale_orders", "purchase_orders", "inventory", "forecast_orders")


def tenant_db_file(tid):
    """租户库文件路径。

    命名规则必须与 db.connection.set_tenant_context 保持一致（同目录 tenant_<id>.db），
    否则用量统计会指向一个不存在的文件、静默返回全 0 —— 看起来"统计正常"其实全是假的。
    """
    return os.path.join(DB_DIR, f"tenant_{int(tid)}.db")


def tenant_member_list(tid):
    """租户成员列表：主库 users ⨝ user_tenants。

    ⚠️ 只查主库，**不要**用 get_db()（会跟随调用者的租户上下文连到 tenant_N.db，
    那里查不到成员关系）。
    """
    conn = _connect()
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    c.execute(
        "SELECT u.id, u.username, u.display_name, u.role, u.is_active, u.phone, u.created_at "
        "FROM users u JOIN user_tenants ut ON ut.user_id = u.id "
        "WHERE ut.tenant_id = ? ORDER BY u.id",
        (int(tid),),
    )
    rows = [dict(r) for r in c.fetchall()]
    conn.close()
    return rows


def tenant_member_add(tid, username, role="user"):
    """把一个**已存在**的账号加入租户（成员授权，不是建号）。

    为什么不建号：调用方只传 username/role、没有密码，凭空建出的账号无法登录，
    只会留下一堆僵尸用户；要建号请走 POST /api/platform/onboard。

    `role` 参数只做**守卫**、不做赋值：users.role 是**全局**角色（主库单表），在这里
    改它会连带影响该账号在其它租户里的权限。传 boss/admin 直接拒绝，避免有人以为
    「加成员时能顺手提权」。
    """
    username = (username or "").strip()
    if not username:
        return {"success": False, "error": "账号不能为空"}
    _role = (role or "").strip().lower()
    if _role in ("boss", "admin", "superadmin"):
        return {"success": False, "error": "成员管理不能授予管理员角色（如需管理员请走「客户开通」）"}
    conn = _connect()
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    row = c.execute("SELECT id FROM users WHERE username=?", (username,)).fetchone()
    if not row:
        conn.close()
        return {"success": False, "error": f"账号不存在：{username}（请先在「客户开通」里建号）"}
    uid = int(row["id"])
    if c.execute("SELECT 1 FROM user_tenants WHERE user_id=? AND tenant_id=?", (uid, int(tid))).fetchone():
        conn.close()
        return {"success": True, "user_id": uid, "username": username, "tenant_id": int(tid), "already": True}
    c.execute("INSERT INTO user_tenants (user_id, tenant_id) VALUES (?,?)", (uid, int(tid)))
    conn.commit()
    conn.close()
    return {"success": True, "user_id": uid, "username": username, "tenant_id": int(tid)}


def tenant_member_remove(tid, uid):
    """把账号移出租户。

    拒绝移除**最后一个**成员：移除后该租户将无人可登录（平台管理员也只能靠
    「客户开通」重建），这类手滑锁死没有回头路。要腾空租户请先加新成员。
    """
    tid, uid = int(tid), int(uid)
    conn = _connect()
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    remain = int(c.execute("SELECT COUNT(*) FROM user_tenants WHERE tenant_id=?", (tid,)).fetchone()[0])
    if remain <= 1:
        conn.close()
        return {"success": False, "error": "这是该租户的最后一个成员，移除后将无人能登录；如需清空请先添加新成员"}
    c.execute("DELETE FROM user_tenants WHERE user_id=? AND tenant_id=?", (uid, tid))
    removed = int(c.rowcount)
    conn.commit()
    conn.close()
    if not removed:
        return {"success": False, "error": "该账号不属于此租户"}
    return {"success": True, "removed": removed}


def tenant_usage_stats(tid):
    """租户用量：成员数/上限、租户库体积、核心业务表行数。

    租户库用**只读 URI**（mode=ro）打开：统计接口绝不能因为一次误写改到客户数据，
    也不会在租户库缺失时凭空建出一个空文件。表不存在即跳过，不抛异常。
    """
    tid = int(tid)
    out = {"tenant_id": tid, "member_count": 0, "max_users": 0,
           "db_exists": False, "db_size_mb": 0.0, "data_stats": {}}
    conn = _connect()
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    row = c.execute("SELECT max_users FROM tenants WHERE id=?", (tid,)).fetchone()
    if row:
        out["max_users"] = int(row["max_users"] or 0)
    out["member_count"] = int(c.execute("SELECT COUNT(*) FROM user_tenants WHERE tenant_id=?", (tid,)).fetchone()[0])
    conn.close()

    path = tenant_db_file(tid)
    if not os.path.exists(path):
        return out
    out["db_exists"] = True
    size = 0
    for suffix in ("", "-wal", "-shm"):
        try:
            if os.path.exists(path + suffix):
                size += os.path.getsize(path + suffix)
        except OSError:
            pass
    out["db_size_mb"] = round(size / 1048576.0, 2)
    try:
        tc = sqlite3.connect(f"file:{path}?mode=ro", uri=True)
        try:
            have = {r[0] for r in tc.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()}
            for t in _TENANT_USAGE_TABLES:
                if t in have:
                    out["data_stats"][t] = int(tc.execute(f"SELECT COUNT(*) FROM {t}").fetchone()[0])
        finally:
            tc.close()
    except sqlite3.Error as e:
        # 只读打开失败（库被锁/文件损坏）不该让整个用量接口 500 —— 返回已拿到的部分。
        out["data_stats_error"] = str(e)
    return out


def platform_stats():
    """平台聚合统计（管理后台总览卡用，v257）。

    全部走主库 + 文件体积统计，不触碰任何租户业务数据。
    时间口径统一用 created_at 的日期前缀（datetime('now','localtime') 格式 YYYY-MM-DD HH:MM:SS）。
    """
    conn = _connect()
    conn.row_factory = sqlite3.Row
    c = conn.cursor()

    tenants = c.execute("SELECT id, plan, is_active, created_at FROM tenants").fetchall()
    total_tenants = len(tenants)
    active_tenants = sum(1 for t in tenants if t["is_active"])
    inactive_tenants = total_tenants - active_tenants

    plan_dist = {}
    for t in tenants:
        p = t["plan"] or "free"
        plan_dist[p] = plan_dist.get(p, 0) + 1

    today = datetime.now().strftime("%Y-%m-%d")
    # 本期「近 7 天」= today-6 .. today（**真 7 天**，含今天）。
    # 🔴 修正（2026-09-24）：原实现用 today-7 ⇒ 实际窗口是 **8 天**，与标签「近 7 天」、
    #    与前端筛选（`daysAgo(6)`）都不一致 ⇒ 总览 KPI 与下钻到注册流水的条数**对不上**；
    #    且与下面的环比窗口（7 天）**不等长** ⇒ 环比天然偏高。
    week_ago = (datetime.now() - timedelta(days=6)).strftime("%Y-%m-%d")
    yesterday = (datetime.now() - timedelta(days=1)).strftime("%Y-%m-%d")
    # 上一个 7 天窗口：today-13 .. today-7（与本期**等长且不重叠**）
    prev_from = (datetime.now() - timedelta(days=13)).strftime("%Y-%m-%d")
    prev_to = (datetime.now() - timedelta(days=7)).strftime("%Y-%m-%d")
    new_today = 0
    new_this_week = 0
    new_yesterday = 0
    new_prev_week = 0
    for t in tenants:
        ca = (t["created_at"] or "")[:10]
        if ca == today:
            new_today += 1
        if ca >= week_ago:
            new_this_week += 1
        if ca == yesterday:
            new_yesterday += 1
        if prev_from <= ca <= prev_to:
            new_prev_week += 1

    total_users = int(c.execute("SELECT COUNT(*) FROM users").fetchone()[0])
    conn.close()

    # 库体积：主库 + 全部租户库（含 -wal/-shm 临时文件）
    total_bytes = 0
    try:
        if os.path.exists(DB_PATH):
            total_bytes += os.path.getsize(DB_PATH)
    except OSError:
        pass
    if os.path.isdir(DB_DIR):
        for fn in os.listdir(DB_DIR):
            if fn.startswith("tenant_") and fn.endswith(".db"):
                for suffix in ("", "-wal", "-shm"):
                    p = os.path.join(DB_DIR, fn + suffix)
                    try:
                        if os.path.exists(p):
                            total_bytes += os.path.getsize(p)
                    except OSError:
                        pass
    total_db_size_mb = round(total_bytes / 1048576.0, 2)

    # 近 30 天每日注册数（v262，供总览趋势图）。直连主库只读，避开租户上下文。
    # 失败时返回空列表（前端据此不画图），并留 WARNING —— 不静默伪装成"没有注册"。
    daily_registrations = []
    try:
        _mc = sqlite3.connect("file:%s?mode=ro" % DB_PATH, uri=True)
        try:
            start = (datetime.now() - timedelta(days=29)).strftime("%Y-%m-%d")
            got = {r[0]: int(r[1]) for r in _mc.execute(
                "SELECT substr(created_at,1,10) AS d, COUNT(*) AS n FROM invite_uses "
                "WHERE substr(created_at,1,10) >= ? GROUP BY d", (start,)).fetchall() if r[0]}
            for i in range(29, -1, -1):
                d = (datetime.now() - timedelta(days=i)).strftime("%Y-%m-%d")
                daily_registrations.append({"date": d, "count": got.get(d, 0)})
        finally:
            _mc.close()
    except Exception as e:
        logging.getLogger("hergent").warning(f"daily_registrations 统计失败: {e}")
        daily_registrations = []

    return {
        "total_tenants": total_tenants,
        "active_tenants": active_tenants,
        "inactive_tenants": inactive_tenants,
        "new_today": new_today,
        "new_this_week": new_this_week,
        "new_yesterday": new_yesterday,
        "new_prev_week": new_prev_week,
        "total_users": total_users,
        "total_db_size_mb": total_db_size_mb,
        "daily_registrations": daily_registrations,
        "plan_distribution": plan_dist,
    }

# ===== API Tokens =====
def api_token_create(user_id, name, permissions="read", expires_days=365):
    db = _connect(); c = db.cursor()
    token = "hergent_" + secrets.token_hex(24)
    expires = datetime.now() + timedelta(days=expires_days)
    c.execute("INSERT INTO api_tokens(user_id,token,name,permissions,expires_at) VALUES(?,?,?,?,?)", (user_id,token,name,permissions,expires.strftime("%Y-%m-%d")))
    db.commit(); tid = c.lastrowid; db.close(); return {"id":tid,"token":token}

def api_token_list(user_id=0):
    db = _connect(); c = db.cursor()
    if user_id: c.execute("SELECT id,user_id,name,permissions,last_used_at,expires_at,is_active,created_at FROM api_tokens WHERE user_id=? ORDER BY created_at DESC", (user_id,))
    else: c.execute("SELECT id,user_id,name,permissions,last_used_at,expires_at,is_active,created_at FROM api_tokens ORDER BY created_at DESC")
    rows = [dict(r) for r in c.fetchall()]; db.close(); return rows

def api_token_validate(token):
    db = _connect(); c = db.cursor()
    c.execute("SELECT * FROM api_tokens WHERE token=? AND is_active=1 AND (expires_at IS NULL OR expires_at>=date('now'))", (token,))
    row = c.fetchone()
    if row: c.execute("UPDATE api_tokens SET last_used_at=datetime('now','localtime') WHERE id=?", (row['id'],)); db.commit()
    db.close(); return dict(row) if row else None

def api_token_revoke(tid):
    db = _connect(); c = db.cursor()
    c.execute("UPDATE api_tokens SET is_active=0 WHERE id=?", (tid,)); db.commit(); db.close()

# ===== Webhooks =====
def webhook_create(name, url, events, secret=""):
    db = _connect(); c = db.cursor()
    c.execute("INSERT INTO webhooks(name,url,events,secret) VALUES(?,?,?,?)", (name,url,",".join(events) if isinstance(events,list) else events,secret or secrets.token_hex(16)))
    db.commit(); wid = c.lastrowid; db.close(); return wid

def webhook_list():
    db = _connect(); c = db.cursor()
    c.execute("SELECT * FROM webhooks WHERE is_active=1 ORDER BY created_at DESC")
    rows = [dict(r) for r in c.fetchall()]; db.close(); return rows

def webhook_delete(wid):
    db = _connect(); c = db.cursor()
    c.execute("UPDATE webhooks SET is_active=0 WHERE id=?", (wid,)); db.commit(); db.close()

def webhook_log(wid, event, status_code, response_body):
    db = _connect(); c = db.cursor()
    c.execute("INSERT INTO webhook_logs(webhook_id,event,status_code,response_body) VALUES(?,?,?,?)", (wid,event,status_code,str(response_body)[:500]))
    db.commit(); db.close()

def webhook_logs_list(wid=0, limit=50):
    db = _connect(); c = db.cursor()
    if wid: c.execute("SELECT * FROM webhook_logs WHERE webhook_id=? ORDER BY created_at DESC LIMIT ?", (wid,limit))
    else: c.execute("SELECT * FROM webhook_logs ORDER BY created_at DESC LIMIT ?", (limit,))
    rows = [dict(r) for r in c.fetchall()]; db.close(); return rows

def webhook_fire(event, payload):
    import json, urllib.request, threading
    hooks = webhook_list()
    for h in hooks:
        if event in (h.get('events') or "").split(","):
            def _fire(wid, url, secret, evt, data):
                try:
                    body = json.dumps({"event":evt,"data":data,"timestamp":datetime.now().isoformat()}).encode()
                    req = urllib.request.Request(url, data=body, headers={"Content-Type":"application/json","X-Webhook-Secret":secret,"User-Agent":"Hergent-ERP/1.0"})
                    resp = urllib.request.urlopen(req, timeout=10)
                    webhook_log(wid, evt, resp.status, resp.read().decode()[:200])
                except Exception as ex:
                    webhook_log(wid, evt, 0, str(ex)[:200])
            threading.Thread(target=_fire, args=(h['id'],h['url'],h['secret'],event,payload), daemon=True).start()

# ===== System Health =====
def system_health():
    import os
    db = _connect(); c = db.cursor()
    tables = c.execute("SELECT name FROM sqlite_master WHERE type='table'").fetchall()
    counts = {}
    for t in tables:
        try: counts[t['name']] = c.execute(f"SELECT COUNT(*) FROM [{t['name']}]").fetchone()[0]
        except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}")
    db_path = os.environ.get("ERP_DB_PATH", os.path.join(os.path.dirname(os.path.abspath(__file__)), "erp.db"))
    db_size = os.path.getsize(db_path) if os.path.exists(db_path) else 0
    db.close()
    return {"db_size_mb":round(db_size/1024/1024,2),"table_count":len(tables),"table_counts":counts,"last_backup":backup_history_list(1)[0] if backup_history_list(1) else None}

