def attendance_clock_in(employee_name, date="", note=""):
    db = _connect(); c = db.cursor()
    today = date or datetime.now().strftime("%Y-%m-%d")
    now = datetime.now().strftime("%H:%M:%S")
    existing = c.execute("SELECT id FROM attendance WHERE employee_name=? AND date=?", (employee_name, today)).fetchone()
    if existing: db.close(); return {"error": "今日已打卡"}
    c.execute("INSERT INTO attendance(employee_name,clock_in,date,status,note) VALUES(?,?,?,?,?)", (employee_name, now, today, "present", note))
    db.commit(); aid = c.lastrowid; db.close(); return {"success": True, "id": aid, "clock_in": now}

