import json as _json
def delivery_route_create(name, driver, vehicle_id, date, stops, notes=""):
    db = _connect(); c = db.cursor()
    c.execute("INSERT INTO delivery_routes(name,driver,vehicle_id,date,stops,notes) VALUES(?,?,?,?,?,?)", (name, driver, vehicle_id, date, _json.dumps(stops), notes))
    db.commit(); rid = c.lastrowid
    for i, stop in enumerate(stops):
        c.execute("INSERT INTO delivery_stops(route_id,stop_order,contact_name,address,order_ids) VALUES(?,?,?,?,?)", (rid, i+1, stop.get("name",""), stop.get("address",""), ",".join(map(str, stop.get("order_ids", [])))))
    db.commit(); db.close(); return rid

def delivery_route_list(date="", status=""):
    db = _connect(); c = db.cursor()
    where = []; params = []
    if date: where.append("date=?"); params.append(date)
    if status: where.append("status=?"); params.append(status)
    w = " AND ".join(where) if where else "1=1"
    c.execute(f"SELECT * FROM delivery_routes WHERE {w} ORDER BY date DESC, created_at DESC LIMIT 50", params)
    routes = [dict(r) for r in c.fetchall()]
    if routes:
        route_ids = [r['id'] for r in routes]
        placeholders = ','.join('?' for _ in route_ids)
        all_stops = c.execute(
            f"SELECT * FROM delivery_stops WHERE route_id IN ({placeholders}) ORDER BY route_id, stop_order",
            route_ids
        ).fetchall()
        stops_by_route = {}
        for s in all_stops:
            s = dict(s)
            stops_by_route.setdefault(s['route_id'], []).append(s)
        for r in routes:
            r['stops'] = stops_by_route.get(r['id'], [])
    db.close(); return routes

def delivery_stop_update(stop_id, status, note=""):
    db = _connect(); c = db.cursor()
    delivered_at = datetime.now().strftime("%Y-%m-%d %H:%M:%S") if status == "delivered" else None
    c.execute("UPDATE delivery_stops SET status=?, delivered_at=COALESCE(?,delivered_at), note=COALESCE(note,'')||? WHERE id=?", (status, delivered_at, " | "+note if note else "", stop_id))
    db.commit()
    stop = c.execute("SELECT route_id FROM delivery_stops WHERE id=?", (stop_id,)).fetchone()
    if stop:
        pending = c.execute("SELECT COUNT(*) as cnt FROM delivery_stops WHERE route_id=? AND status!='delivered'", (stop['route_id'],)).fetchone()
        if pending['cnt'] == 0: c.execute("UPDATE delivery_routes SET status='completed' WHERE id=?", (stop['route_id'],))
    db.commit(); db.close()

# === Delivery Route Optimization (v75) ===
import math
def _haversine_km(lat1, lng1, lat2, lng2):
    """Calculate distance in km between two GPS points using Haversine formula."""
    R = 6371.0
    dlat = math.radians(lat2 - lat1)
    dlng = math.radians(lng2 - lng1)
    a = math.sin(dlat/2)**2 + math.cos(math.radians(lat1)) * math.cos(math.radians(lat2)) * math.sin(dlng/2)**2
    return R * 2 * math.atan2(math.sqrt(a), math.sqrt(1-a))

def optimize_delivery_route(route_id):
    """Reorder delivery stops using nearest-neighbor greedy algorithm."""
    db = _connect(); c = db.cursor()
    stops = [dict(r) for r in c.execute("SELECT * FROM delivery_stops WHERE route_id=? ORDER BY stop_order", (route_id,)).fetchall()]
    if len(stops) <= 2: db.close(); return {"optimized": False, "message": "需要至少3个有GPS坐标的停靠点", "stops": stops}
    # If any stop has no GPS, sort by address string
    if not all(s.get("lat") and s.get("lng") for s in stops):
        stops.sort(key=lambda s: s.get("address", ""))
        for i, s in enumerate(stops):
            c.execute("UPDATE delivery_stops SET stop_order=? WHERE id=?", (i+1, s["id"]))
        db.commit(); db.close()
        return {"optimized": True, "method": "地址排序", "stops": [dict(r) for r in c.execute("SELECT * FROM delivery_stops WHERE route_id=? ORDER BY stop_order", (route_id,)).fetchall()]}
    old_order = [s["contact_name"] or s["address"] for s in stops]
    # Nearest neighbor: start from first stop, greedily pick nearest unvisited
    unvisited = stops[1:]
    ordered = [stops[0]]
    current = stops[0]
    total_dist = 0
    while unvisited:
        nearest = min(unvisited, key=lambda s: _haversine_km(current["lat"], current["lng"], s["lat"], s["lng"]))
        total_dist += _haversine_km(current["lat"], current["lng"], nearest["lat"], nearest["lng"])
        ordered.append(nearest)
        unvisited.remove(nearest)
        current = nearest
    new_order = [s["contact_name"] or s["address"] for s in ordered]
    # Update stop_order in DB
    for i, s in enumerate(ordered):
        c.execute("UPDATE delivery_stops SET stop_order=? WHERE id=?", (i+1, s["id"]))
    db.commit(); db.close()
    return {"optimized": True, "method": "最近邻路径优化", "old_order": old_order, "new_order": new_order, "estimated_km": round(total_dist, 2), "stops": ordered}

def optimize_visit_route(date=None):
    """Optimize visit order for today's planned visits using nearest-neighbor Haversine."""
    if date is None:
        date = datetime.now().strftime("%Y-%m-%d")
    db = _connect(); c = db.cursor()
    visits = [dict(r) for r in c.execute(
        "SELECT v.*, c.name as contact_name FROM visit_logs v JOIN contacts c ON v.contact_id=c.id "
        "WHERE v.visit_date=? ORDER BY v.id", (date,)
    ).fetchall()]
    if len(visits) < 2: db.close(); return {"optimized": False, "message": "当天拜访计划不足2个，无需优化", "visits": visits}

    # Filter to visits with GPS data
    gps_visits = [v for v in visits if v.get("lat") and v.get("lng")]
    if len(gps_visits) < 2:
        db.close(); return {"optimized": False, "message": "缺少GPS坐标（至少需要2个有GPS的拜访记录）", "visits": visits}

    # Nearest neighbor from first stop
    unvisited = gps_visits[1:]
    ordered = [gps_visits[0]]
    current = gps_visits[0]
    total_km = 0
    while unvisited:
        nearest = min(unvisited, key=lambda s: _haversine_km(current["lat"], current["lng"], s["lat"], s["lng"]))
        total_km += _haversine_km(current["lat"], current["lng"], nearest["lat"], nearest["lng"])
        ordered.append(nearest)
        unvisited.remove(nearest)
        current = nearest

    old_order = [v.get("contact_name", v.get("location", "")) for v in gps_visits]
    new_order = [v.get("contact_name", v.get("location", "")) for v in ordered]
    db.close()
    return {"optimized": True, "method": "最近邻路径优化", "old_order": old_order, "new_order": new_order, "estimated_km": round(total_km, 2), "visits": ordered}

