# ===== Supplier Scorecards (供应商评估) =====
def supplier_scorecard_create(supplier_id, supplier_name="", period="", delivery=5, quality=5, price=5, service=5, comments=""):
    db = _connect(); c = db.cursor()
    if not period: period = datetime.now().strftime("%Y-%m")
    if not supplier_name and supplier_id:
        s = c.execute("SELECT name FROM contacts WHERE id=?", (supplier_id,)).fetchone()
        if s: supplier_name = s['name']
    total = (delivery+quality+price+service)/4
    c.execute("INSERT INTO supplier_scorecards(supplier_id,supplier_name,period,delivery_score,quality_score,price_score,service_score,total_score,comments) VALUES(?,?,?,?,?,?,?,?,?)", (supplier_id,supplier_name,period,delivery,quality,price,service,round(total,1),comments))
    db.commit(); sid = c.lastrowid; db.close(); return sid

def supplier_scorecard_list(supplier_id=0):
    db = _connect(); c = db.cursor()
    if supplier_id: c.execute("SELECT * FROM supplier_scorecards WHERE supplier_id=? ORDER BY period DESC LIMIT 50", (supplier_id,))
    else: c.execute("SELECT * FROM supplier_scorecards ORDER BY period DESC, total_score DESC LIMIT 100")
    rows = [dict(r) for r in c.fetchall()]; db.close(); return rows

def supplier_scorecard_stats(supplier_id):
    db = _connect(); c = db.cursor()
    c.execute("SELECT AVG(delivery_score) as avg_delivery, AVG(quality_score) as avg_quality, AVG(price_score) as avg_price, AVG(service_score) as avg_service, AVG(total_score) as avg_total, COUNT(*) as periods FROM supplier_scorecards WHERE supplier_id=?", (supplier_id,))
    row = c.fetchone(); db.close(); return dict(row) if row else {}

# ===== Contract Management (合同管理) =====
def erp_contract_create(name, ctype="sale", contact_id=0, contact_name="", start_date="", end_date="", total_amount=0, terms="", milestones=""):
    db = _connect(); c = db.cursor()
    contract_no = f"CT-{datetime.now().strftime('%Y%m%d')}-{secrets.token_hex(3).upper()}"
    c.execute("INSERT INTO erp_contracts(contract_no,name,contract_type,contact_id,contact_name,start_date,end_date,total_amount,terms,milestones) VALUES(?,?,?,?,?,?,?,?,?,?)", (contract_no,name,ctype,contact_id,contact_name,start_date,end_date,total_amount,terms,milestones))
    db.commit(); cid = c.lastrowid; db.close(); return cid

def erp_contract_list(ctype="", status=""):
    db = _connect(); c = db.cursor()
    where = []; params = []
    if ctype: where.append("contract_type=?"); params.append(ctype)
    if status: where.append("status=?"); params.append(status)
    w = " AND ".join(where) if where else "1=1"
    c.execute(f"SELECT * FROM erp_contracts WHERE {w} ORDER BY created_at DESC LIMIT 100", params)
    rows = [dict(r) for r in c.fetchall()]; db.close(); return rows

def erp_contract_update(cid, **kw):
    db = _connect(); c = db.cursor()
    allowed = ["name","contract_type","contact_name","start_date","end_date","total_amount","paid_amount","status","terms","milestones","files"]
    sets = [f"{k}=?" for k in allowed if k in kw]
    if not sets: db.close(); return
    sets.append("updated_at=datetime('now','localtime')")
    params = [kw[k] for k in allowed if k in kw] + [cid]
    c.execute(f"UPDATE erp_contracts SET {','.join(sets)} WHERE id=?", params)
    db.commit(); db.close()

def erp_contract_get(cid):
    db = _connect(); c = db.cursor()
    c.execute("SELECT * FROM erp_contracts WHERE id=?", (cid,))
    row = c.fetchone(); db.close(); return dict(row) if row else None

