def knowledge_article_create(title, category="", content="", tags="", author=""):
    db = _connect(); c = db.cursor()
    c.execute("INSERT INTO knowledge_articles(title,category,content,tags,author) VALUES(?,?,?,?,?)", (title,category,content,tags,author))
    db.commit(); kid = c.lastrowid; db.close(); return kid

def knowledge_article_list(category="", keyword="", limit=50):
    db = _connect(); c = db.cursor()
    where = ["is_published=1"]; params = []
    if category: where.append("category=?"); params.append(category)
    if keyword: where.append("(title LIKE ? OR content LIKE ? OR tags LIKE ?)"); kw=f"%{keyword}%"; params.extend([kw,kw,kw])
    w = " AND ".join(where)
    c.execute(f"SELECT id,title,category,tags,author,view_count,created_at FROM knowledge_articles WHERE {w} ORDER BY created_at DESC LIMIT ?", params+[limit])
    rows = [dict(r) for r in c.fetchall()]; db.close(); return rows

def knowledge_article_get(kid):
    db = _connect(); c = db.cursor()
    c.execute("UPDATE knowledge_articles SET view_count=view_count+1 WHERE id=?", (kid,)); db.commit()
    c.execute("SELECT * FROM knowledge_articles WHERE id=?", (kid,))
    row = c.fetchone(); db.close(); return dict(row) if row else None

def knowledge_article_update(kid, **kw):
    db = _connect(); c = db.cursor()
    allowed = ["title","category","content","tags","author","is_published"]
    sets = [f"{k}=?" for k in allowed if k in kw]
    if not sets: db.close(); return
    sets.append("updated_at=datetime('now','localtime')")
    params = [kw[k] for k in allowed if k in kw] + [kid]
    c.execute(f"UPDATE knowledge_articles SET {','.join(sets)} WHERE id=?", params)
    db.commit(); db.close()

def knowledge_categories():
    db = _connect(); c = db.cursor()
    c.execute("SELECT DISTINCT category FROM knowledge_articles WHERE category!='' AND is_published=1 ORDER BY category")
    rows = [r['category'] for r in c.fetchall()]; db.close(); return rows

