# ===== Performance Indexes =====
def _create_indexes():
    db = _connect(); c = db.cursor()
    indexes = [
        "CREATE INDEX IF NOT EXISTS idx_sale_orders_order_date ON sale_orders(order_date)",
        "CREATE INDEX IF NOT EXISTS idx_sale_orders_customer_id ON sale_orders(customer_id)",
        "CREATE INDEX IF NOT EXISTS idx_sale_orders_status ON sale_orders(status)",
        "CREATE INDEX IF NOT EXISTS idx_purchase_orders_order_date ON purchase_orders(order_date)",
        "CREATE INDEX IF NOT EXISTS idx_purchase_orders_supplier_id ON purchase_orders(supplier_id)",
        "CREATE INDEX IF NOT EXISTS idx_purchase_orders_status ON purchase_orders(status)",
        "CREATE INDEX IF NOT EXISTS idx_sale_order_items_order_id ON sale_order_items(order_id)",
        "CREATE INDEX IF NOT EXISTS idx_sale_order_items_product_id ON sale_order_items(product_id)",
        "CREATE INDEX IF NOT EXISTS idx_inventory_product_id ON inventory(product_id)",
        "CREATE INDEX IF NOT EXISTS idx_inventory_warehouse_id ON inventory(warehouse_id)",
        "CREATE INDEX IF NOT EXISTS idx_contacts_type ON contacts(type)",
        "CREATE INDEX IF NOT EXISTS idx_contacts_name ON contacts(name)",
        "CREATE INDEX IF NOT EXISTS idx_receivables_contact_id ON receivables(contact_id)",
        "CREATE INDEX IF NOT EXISTS idx_receivables_status ON receivables(status)",
        "CREATE INDEX IF NOT EXISTS idx_products_category ON products(category)",
        "CREATE INDEX IF NOT EXISTS idx_expense_orders_order_date ON expense_orders(order_date)",
    ]
    for sql in indexes:
        try: c.execute(sql)
        except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}")
    db.commit(); db.close()

try:
    _create_indexes()
except Exception as e:
    logging.getLogger("hergent").debug(f"skipping row: {e}")



# === Vehicle Stock Management (车仓库存) ===
def vehicle_stock_load(vehicle_id, product_id, quantity, operator_id=''):
    """Load stock from main warehouse (id=1) to vehicle."""
    from db.queries.inventory import inventory_adjust
    # Reduce main warehouse
    inventory_adjust(product_id, 1, -quantity, ref_type='vehicle_load', ref_id=vehicle_id)
    # Increase vehicle stock (warehouse_id = 1000 + vehicle_id)
    vwh = 1000 + vehicle_id
    with get_db() as db:
        db.execute("INSERT OR IGNORE INTO warehouses (id,name,is_default) VALUES (?,?,0)",(vwh, f'车辆#{vehicle_id}'))
        db.commit()
    inventory_adjust(product_id, vwh, quantity, ref_type='vehicle_load', ref_id=vehicle_id)

def vehicle_stock_return(vehicle_id, operator_id=''):
    """Return all remaining stock from vehicle to main warehouse."""
    from db.queries.inventory import inventory_adjust
    vwh = 1000 + vehicle_id
    with get_db() as db:
        items = db.execute("SELECT * FROM inventory WHERE warehouse_id=? AND quantity>0",(vwh,)).fetchall()
        for it in items:
            inventory_adjust(it['product_id'], 1, it['quantity'], ref_type='vehicle_return', ref_id=vehicle_id)
            inventory_adjust(it['product_id'], vwh, -it['quantity'], ref_type='vehicle_return', ref_id=vehicle_id)
        db.commit()

def vehicle_stock_query(vehicle_id):
    """Query current stock on vehicle."""
    vwh = 1000 + vehicle_id
    with get_db() as db:
        rows = db.execute(
            "SELECT p.name,p.spec,p.unit,inv.quantity,inv.cost_price FROM inventory inv JOIN products p ON inv.product_id=p.id WHERE inv.warehouse_id=? AND inv.quantity>0",
            (vwh,)).fetchall()
        return [dict(r) for r in rows]

