# === v84: Demo Seed Data ===

def register_user_and_tenant(company_name, phone, password, plan="free"):
    """Atomic self-service registration. Creates user + tenant + tenant DB + membership.
    Returns (user_dict, tenant_id, error_message)."""
    import secrets
    from core import _hpw, _validate_password

    # Validate password
    ok, msg = _validate_password(password)
    if not ok:
        return None, 0, msg

    # Generate unique subdomain from company name
    subdomain = company_name.lower().replace(" ", "-").replace("(", "").replace(")", "").replace("（","").replace("）","")[:30]

    # Create user in master DB
    username = "admin_" + subdomain[:20]
    master_db = sqlite3.connect(DB_PATH)
    master_db.row_factory = sqlite3.Row
    try:
        c = master_db.cursor()
        # Check username uniqueness
        existing = c.execute("SELECT id FROM users WHERE username=?", (username,)).fetchone()
        if existing:
            username = username + "_" + secrets.token_hex(2)
        existing_tenant = c.execute("SELECT id FROM tenants WHERE name=? OR subdomain=?", (company_name, subdomain)).fetchone()
        if existing_tenant:
            master_db.close()
            return None, 0, "该公司名已注册"

        # Create user
        c.execute("INSERT INTO users (username, password_hash, display_name, role, password_changed) VALUES (?,?,?,?,?)",
            (username, _hpw(password), company_name[:50], "boss", 1))
        uid = c.lastrowid
        master_db.commit()

        # Create tenant
        c.execute("INSERT OR IGNORE INTO tenants (name, subdomain, contact_name, contact_phone, plan, max_users) VALUES (?,?,?,?,?,?)",
            (company_name, subdomain, company_name, phone, plan, 5 if plan == "free" else (50 if plan == "pro" else 999)))
        tid = c.lastrowid
        master_db.commit()

        # Link user to tenant
        c.execute("""CREATE TABLE IF NOT EXISTS user_tenants (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            tenant_id INTEGER NOT NULL,
            UNIQUE(user_id, tenant_id)
        )""")
        c.execute("INSERT OR IGNORE INTO user_tenants (user_id, tenant_id) VALUES (?,?)", (uid, tid))
        master_db.commit()
    finally:
        master_db.close()

    # Create tenant database
    tenant_db_init(tid)

    # ⚠️ 2026-09-12 产品决策：新注册租户**不再预置任何演示数据**。
    # 此处原先 set_tenant_context(tid) 后调 seed_demo_data()，给每个新租户灌
    # 10 客户 / 5 供应商 / 15 商品 / 5 销售单 / 3 采购单。取消的三条理由：
    #   ① 口径不符 —— 那批是早期快消 demo（冰红茶、海飞丝、卫龙辣条），低温奶经销商
    #      注册后第一眼看到的是**别人的、别的行业的商品**，第一印象即产品不可信；
    #   ② 与"上传第一份数据激活"引导冲突 —— 库里已有数据就不触发空状态引导，
    #      客户没有下手的地方，反而不知道该干什么；
    #   ③ 污染真实数据 —— 客户随后导入自己的客户/商品时，这批假记录会混进统计、
    #      报单与返利口径，且没有任何字段能区分"这是假数据"。
    # 演示环境**不受影响**：demo 租户的数据由独立脚本 seed_demo.py 直连租户库手工
    # INSERT 生成，从不经过本函数；erp_db.seed_demo_data() 保留供 seed_demo.py /
    # 运维手工重建演示库使用，但已无生产代码调用（如需再改，先全局 grep 调用点）。
    # tenant_db_init() 仍会写入 6 条币种 —— 那是必需的基础配置，不是假数据。

    # Generate session token for auto-login
    session_token = str(__import__('uuid').uuid4())
    master_db = sqlite3.connect(DB_PATH)
    master_db.row_factory = sqlite3.Row
    try:
        c = master_db.cursor()
        c.execute("INSERT OR REPLACE INTO sessions (token, user_id, created_at, expires_at) VALUES (?,?,datetime('now','localtime'),datetime('now','+24 hours','localtime'))",
            (session_token, uid))
        master_db.commit()
    finally:
        master_db.close()

    user = {"id": uid, "username": username, "display_name": company_name, "role": "boss", "password_changed": 1}
    return user, tid, ""

# === v86: IFRS 15 Revenue Recognition (5-step model) ===

def _init_ifrs15_tables():
    with get_db() as db:
        db.executescript("""
            CREATE TABLE IF NOT EXISTS performance_obligations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                contract_id INTEGER NOT NULL DEFAULT 0,
                description TEXT DEFAULT '',
                standalone_selling_price REAL DEFAULT 0,
                transaction_price_allocated REAL DEFAULT 0,
                recognized_amount REAL DEFAULT 0,
                recognition_method TEXT DEFAULT 'point_in_time',
                status TEXT DEFAULT 'pending',
                satisfied_at TEXT,
                created_at TEXT DEFAULT (datetime('now','localtime'))
            );
            CREATE TABLE IF NOT EXISTS contract_assets_liabilities (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                ref_type TEXT NOT NULL,
                ref_id INTEGER NOT NULL,
                contract_id INTEGER DEFAULT 0,
                balance_type TEXT DEFAULT 'contract_asset',
                amount REAL DEFAULT 0,
                description TEXT DEFAULT '',
                recognized_at TEXT DEFAULT (datetime('now','localtime'))
            );
            CREATE TABLE IF NOT EXISTS revenue_contracts (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                customer_id INTEGER NOT NULL,
                name TEXT DEFAULT '',
                total_price REAL DEFAULT 0,
                currency TEXT DEFAULT 'CNY',
                start_date TEXT,
                end_date TEXT,
                status TEXT DEFAULT 'active',
                note TEXT DEFAULT '',
                created_at TEXT DEFAULT (datetime('now','localtime'))
            );
        """)
        db.commit()

def revenue_contract_create(customer_id, name="", total_price=0, start_date="", end_date="", note=""):
    _init_ifrs15_tables()
    with get_db_tx() as db:
        cid = db.execute(
            "INSERT INTO revenue_contracts (customer_id, name, total_price, start_date, end_date, note) VALUES (?,?,?,?,?,?)",
            (customer_id, name, total_price, start_date, end_date, note)
        ).lastrowid
        db.commit()
    return cid

def revenue_contract_list(customer_id=0):
    _init_ifrs15_tables()
    with get_db() as db:
        w, p = ("WHERE customer_id=?", (customer_id,)) if customer_id else ("", [])
        return [dict(r) for r in db.execute(
            f"SELECT rc.*, c.name as customer_name FROM revenue_contracts rc JOIN contacts c ON rc.customer_id=c.id {w} ORDER BY rc.id DESC", p
        ).fetchall()]

def revenue_contract_get(cid):
    _init_ifrs15_tables()
    with get_db() as db:
        r = db.execute(
            "SELECT rc.*, c.name as customer_name FROM revenue_contracts rc JOIN contacts c ON rc.customer_id=c.id WHERE rc.id=?", (cid,)
        ).fetchone()
        if not r: return None
        obligations = [dict(o) for o in db.execute("SELECT * FROM performance_obligations WHERE contract_id=? ORDER BY id", (cid,)).fetchall()]
        result = dict(r)
        result["obligations"] = obligations
        result["total_allocated"] = sum(o["transaction_price_allocated"] for o in obligations)
        result["total_recognized"] = sum(o["recognized_amount"] for o in obligations)
        return result

def obligation_create(contract_id, description, standalone_selling_price, recognition_method="point_in_time"):
    """Step 2: Define a performance obligation in a contract."""
    _init_ifrs15_tables()
    with get_db_tx() as db:
        oid = db.execute(
            "INSERT INTO performance_obligations (contract_id, description, standalone_selling_price, recognition_method) VALUES (?,?,?,?)",
            (contract_id, description, standalone_selling_price, recognition_method)
        ).lastrowid
        db.commit()
    return oid

def allocate_transaction_price(contract_id):
    """Step 4: Allocate transaction price to obligations by relative SSP (standalone selling price)."""
    _init_ifrs15_tables()
    with get_db_tx() as db:
        contract = db.execute("SELECT * FROM revenue_contracts WHERE id=?", (contract_id,)).fetchone()
        if not contract: return {"error": "合同不存在"}
        obligations = [dict(o) for o in db.execute("SELECT * FROM performance_obligations WHERE contract_id=?", (contract_id,)).fetchall()]
        if not obligations: return {"error": "请先添加履约义务"}

        total_ssp = sum(o["standalone_selling_price"] for o in obligations)
        if total_ssp <= 0: return {"error": "独立售价之和必须大于0"}

        total_price = contract["total_price"]
        allocated = []
        for o in obligations:
            # Relative SSP allocation
            share = round(total_price * o["standalone_selling_price"] / total_ssp, 2)
            db.execute("UPDATE performance_obligations SET transaction_price_allocated=? WHERE id=?", (share, o["id"]))
            allocated.append({"id": o["id"], "description": o["description"], "ssp": o["standalone_selling_price"], "allocated": share})

        # Handle rounding difference — add to largest obligation
        allocated_sum = sum(a["allocated"] for a in allocated)
        diff = round(total_price - allocated_sum, 2)
        if diff != 0 and allocated:
            sorted_alloc = sorted(allocated, key=lambda x: x["ssp"], reverse=True)
            sorted_alloc[0]["allocated"] = round(sorted_alloc[0]["allocated"] + diff, 2)
            db.execute("UPDATE performance_obligations SET transaction_price_allocated=? WHERE id=?", (sorted_alloc[0]["allocated"], sorted_alloc[0]["id"]))

        db.commit()
    return {"contract_id": contract_id, "total_price": total_price, "total_ssp": total_ssp, "allocations": allocated}

def recognize_revenue(obligation_id, recognized_amount=0, period=""):
    """Step 5: Recognize revenue for a performance obligation (point-in-time or over-time)."""
    _init_ifrs15_tables()
    if not period: period = __import__('datetime').datetime.now().strftime("%Y-%m")

    with get_db_tx() as db:
        obl = db.execute("SELECT * FROM performance_obligations WHERE id=?", (obligation_id,)).fetchone()
        if not obl: return {"error": "履约义务不存在"}
        obl = dict(obl)
        contract = db.execute("SELECT * FROM revenue_contracts WHERE id=?", (obl["contract_id"],)).fetchone()

        # Determine recognition amount
        if recognized_amount <= 0:
            # Full recognition of allocated transaction price
            recognized_amount = obl["transaction_price_allocated"] - obl["recognized_amount"]

        if recognized_amount <= 0:
            return {"error": "该履约义务已完全确认"}

        new_recognized = round(obl["recognized_amount"] + recognized_amount, 2)
        is_fully_recognized = new_recognized >= obl["transaction_price_allocated"] - 0.01

        db.execute("UPDATE performance_obligations SET recognized_amount=?, status=?, satisfied_at=datetime('now','localtime') WHERE id=?",
            (new_recognized, "satisfied" if is_fully_recognized else "partial", obligation_id))

        # Generate journal entries
        date_str = period + "-01"
        entries = [
            {"code": "1121", "name": "合同资产" if obl["recognition_method"] == "over_time" else "应收账款",
             "debit": recognized_amount, "credit": 0, "summary": f"确认收入 #{obligation_id}: {obl['description']}"},
            {"code": "6001", "name": "主营业务收入",
             "debit": 0, "credit": recognized_amount, "summary": f"确认收入 #{obligation_id}: {obl['description']}"},
        ]
        if contract:
            if obl["recognition_method"] == "over_time" and obl["recognized_amount"] == 0:
                # First over-time recognition: reclass from contract liability
                pass

        generate_journal_entry("revenue_recognition", obligation_id, date_str, entries, db_conn=db)

        # Record contract asset/liability for over-time recognition
        if obl["recognition_method"] == "over_time" and not is_fully_recognized:
            db.execute("INSERT INTO contract_assets_liabilities (ref_type, ref_id, contract_id, balance_type, amount, description) VALUES (?,?,?,?,?,?)",
                ("obligation", obligation_id, obl["contract_id"], "contract_asset", recognized_amount, f"合同资产-{obl['description']}"))

        db.commit()

    return {"obligation_id": obligation_id, "description": obl["description"], "recognized": recognized_amount,
            "total_recognized": new_recognized, "allocated": obl["transaction_price_allocated"],
            "status": "satisfied" if is_fully_recognized else "partial"}

def get_ifrs15_contract_summary(period=""):
    """Get IFRS 15 revenue waterfall for a period."""
    _init_ifrs15_tables()
    if not period: period = __import__('datetime').datetime.now().strftime("%Y-%m")
    with get_db() as db:
        contracts = [dict(r) for r in db.execute(
            "SELECT rc.*, c.name as customer_name FROM revenue_contracts rc JOIN contacts c ON rc.customer_id=c.id WHERE rc.status='active'"
        ).fetchall()]
        total_contracted = sum(c["total_price"] for c in contracts)
        details = []
        for ct in contracts:
            obs = [dict(o) for o in db.execute("SELECT * FROM performance_obligations WHERE contract_id=?", (ct["id"],)).fetchall()]
            ct_alloc = sum(o["transaction_price_allocated"] for o in obs)
            ct_recognized = sum(o["recognized_amount"] for o in obs)
            details.append({
                "contract_id": ct["id"], "name": ct["name"], "customer": ct["customer_name"],
                "total_price": ct["total_price"], "allocated": ct_alloc, "recognized": ct_recognized,
                "unrecognized": round(ct["total_price"] - ct_recognized, 2),
                "progress_pct": round(ct_recognized / ct["total_price"] * 100, 1) if ct["total_price"] > 0 else 0
            })
        total_recognized = sum(d["recognized"] for d in details)
        return {
            "period": period,
            "contract_count": len(contracts),
            "total_contracted": total_contracted,
            "total_recognized": total_recognized,
            "total_unrecognized": round(total_contracted - total_recognized, 2),
            "details": details
        }

# === v87: RMA Depth — reason codes, disposition routing, refund ===

def _init_rma_tables():
    with get_db() as db:
        db.executescript("""
            -- v525b: 补 auditor_id / audit_time 供审批流终审落审核人
            CREATE TABLE IF NOT EXISTS return_orders (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                sale_order_id INTEGER,
                contact_id INTEGER,
                total_amount REAL DEFAULT 0,
                reason TEXT DEFAULT '',
                status TEXT DEFAULT 'confirmed',
                operator_id TEXT DEFAULT '',
                order_date TEXT,
                quality_status TEXT DEFAULT 'pending',
                auditor_id TEXT DEFAULT '',
                audit_time TEXT DEFAULT ''
            );
            CREATE TABLE IF NOT EXISTS return_order_items (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                return_id INTEGER,
                product_id INTEGER,
                quantity REAL DEFAULT 0,
                unit_price REAL DEFAULT 0,
                amount REAL DEFAULT 0
            );
            CREATE TABLE IF NOT EXISTS return_reason_codes (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                code TEXT NOT NULL UNIQUE,
                name TEXT NOT NULL,
                category TEXT DEFAULT 'customer_return',
                is_active INTEGER DEFAULT 1
            );
            CREATE TABLE IF NOT EXISTS return_dispositions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                return_id INTEGER NOT NULL,
                product_id INTEGER,
                quantity REAL DEFAULT 0,
                disposition TEXT DEFAULT 'quarantine',
                note TEXT DEFAULT '',
                operator_id TEXT DEFAULT '',
                created_at TEXT DEFAULT (datetime('now','localtime'))
            );
            CREATE TABLE IF NOT EXISTS return_authorizations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                return_id INTEGER NOT NULL,
                authorized_by TEXT DEFAULT '',
                auth_status TEXT DEFAULT 'pending',
                auth_note TEXT DEFAULT '',
                created_at TEXT DEFAULT (datetime('now','localtime'))
            );
        """)
        db.commit()
    # Seed reason codes if empty
    _seed_return_reasons()

def _seed_return_reasons():
    with get_db() as db:
        cnt = db.execute("SELECT COUNT(*) FROM return_reason_codes").fetchone()[0]
        if cnt > 0: return
        reasons = [
            ("R01","商品破损","quality"),
            ("R02","过期/临期","quality"),
            ("R03","包装不良","quality"),
            ("R04","错发/多发","logistics"),
            ("R05","客户拒收","customer_return"),
            ("R06","质量问题-异物","quality"),
            ("R07","质量问题-变质","quality"),
            ("R08","与样品不符","quality"),
            ("R09","价格争议","commercial"),
            ("R10","重复下单","commercial"),
        ]
        for code, name, cat in reasons:
            db.execute("INSERT OR IGNORE INTO return_reason_codes (code, name, category) VALUES (?,?,?)", (code, name, cat))
        db.commit()

def return_reason_list():
    _init_rma_tables()
    with get_db() as db:
        return [dict(r) for r in db.execute("SELECT * FROM return_reason_codes WHERE is_active=1 ORDER BY code").fetchall()]

def rma_create(sale_order_id, items, reason_code="", reason_note="", operator_id=""):
    """Create RMA with structured reason code and authorization workflow.
    Items: [{product_id, quantity, unit_price}]
    Returns: {rma_id, rma_no, status, disposition_summary}

    G12 (2026-07-25): 不再在创建阶段回增库存。原缺陷：rma_create 同步调
    return_order_create（其内部 inventory_adjust 加库存），审批通过后又走
    disposition restock 再加一次 → 库存翻倍；拒绝时已加库存不回滚。
    现改为：创建仅生成退货单(草稿)+授权记录，库存动作全部延后到 disposition
    审批后执行（approve-before-execute）。退货单建为 'pending' 待审批态。"""
    _init_rma_tables()

    # Validate reason code
    reason_label = reason_note
    if reason_code:
        with get_db() as db:
            rc = db.execute("SELECT name FROM return_reason_codes WHERE code=? AND is_active=1", (reason_code,)).fetchone()
            if rc: reason_label = f"[{reason_code}] {rc['name']}" + (f": {reason_note}" if reason_note else "")

    # Generate RMA number
    rma_no = "RMA" + datetime.now().strftime("%Y%m%d") + str(int(datetime.now().timestamp()) % 10000).zfill(4)

    # 单事务：建退货单(不回增库存) + 明细 + 授权记录，原子化。
    total = sum(it.get("unit_price", 0) * it.get("quantity", 0) for it in items)
    with get_db_tx() as db:
        so = db.execute("SELECT * FROM sale_orders WHERE id=?", (sale_order_id,)).fetchone()
        if not so:
            return {"error": "订单不存在"}
        return_id = db.execute(
            "INSERT INTO return_orders (sale_order_id,contact_id,total_amount,reason,status,operator_id,order_date) "
            "VALUES (?,?,?,?,?,?,datetime('now','localtime'))",
            (sale_order_id, so['customer_id'], total, reason_label, 'pending', operator_id)).lastrowid
        for it in items:
            pid = it.get('product_id', 0)
            qty = it.get('quantity', 0)
            price = it.get('unit_price', 0)
            if not pid or qty <= 0:
                continue
            db.execute(
                "INSERT INTO return_order_items (return_id,product_id,quantity,unit_price,amount) VALUES (?,?,?,?,?)",
                (return_id, pid, qty, price, qty * price))
        auth_id = db.execute(
            "INSERT INTO return_authorizations (return_id, auth_status) VALUES (?, 'pending')",
            (return_id,)).lastrowid
        # Auto-authorize for small returns (< ¥500)
        if total < 500:
            db.execute("UPDATE return_authorizations SET auth_status='approved', authorized_by='auto', auth_note='小额自动审批' WHERE id=?", (auth_id,))

    return {
        "success": True, "rma_id": return_id, "rma_no": rma_no,
        "reason_code": reason_code, "reason_label": reason_label,
        "total": total,
        "auth_required": total >= 500,
        "message": f"RMA #{rma_no} 已创建，{'需要审批' if total >= 500 else '已自动审批'}"
    }

def rma_list(limit=100, status=""):
    _init_rma_tables()
    with get_db() as db:
        w = "WHERE ro.status=?" if status else ""
        p = (status, limit) if status else (limit,)
        try:
            rows = [dict(r) for r in db.execute(
                f"SELECT ro.*, ra.auth_status, ra.authorized_by FROM return_orders ro "
                f"LEFT JOIN return_authorizations ra ON ro.id=ra.return_id {w} ORDER BY ro.id DESC LIMIT ?", p
            ).fetchall()]
        except Exception as e:
            # return_authorizations table may not exist (migration) — fallback to plain query
            logging.getLogger("hergent").debug(f"skipping row: {e}")
            rows = [dict(r) for r in db.execute(
                f"SELECT * FROM return_orders {w} ORDER BY id DESC LIMIT ?", p
            ).fetchall()]
        return rows

def rma_authorize(rma_id, approved=True, auth_by="", auth_note=""):
    """Authorize or reject an RMA."""
    with get_db_tx() as db:
        ra = db.execute("SELECT * FROM return_authorizations WHERE return_id=? ORDER BY id DESC LIMIT 1", (rma_id,)).fetchone()
        if not ra:
            return {"error": "RMA授权记录不存在"}
        new_status = "approved" if approved else "rejected"
        db.execute("UPDATE return_authorizations SET auth_status=?, authorized_by=?, auth_note=? WHERE id=?",
            (new_status, auth_by, auth_note, ra["id"]))
        # If rejected, update return order status
        if not approved:
            db.execute("UPDATE return_orders SET status='rejected' WHERE id=?", (rma_id,))
        db.commit()
    return {"rma_id": rma_id, "auth_status": new_status}

def return_disposition_create(rma_id, items):
    """Route returned items to disposition: restock, quarantine, scrap, return_to_supplier, rework.
    items: [{product_id, quantity, disposition, note}]

    G12 (2026-07-25): ①前置审批校验——仅已批准(approved)的 RMA 可执行处置，
    拒绝/待审批的一律报错（approve-before-execute）；②幂等——同 rma_id+product_id
    的 restock 已存在则跳过，不重复加库存；③restock 失败抛错回滚整批。"""
    _init_rma_tables()
    results = []
    with get_db_tx() as db:
        # 审批门：未批准不得执行库存动作。
        ra = db.execute(
            "SELECT auth_status FROM return_authorizations WHERE return_id=? ORDER BY id DESC LIMIT 1",
            (rma_id,)).fetchone()
        if not ra:
            return {"error": "RMA授权记录不存在，无法处置"}
        if ra["auth_status"] != "approved":
            return {"error": f"RMA 未获批准（当前 {ra['auth_status']}），禁止执行处置/入库"}
        from db.queries.inventory import inventory_adjust
        for it in items:
            disp = it.get("disposition", "quarantine")
            pid = it.get("product_id")
            qty = it.get("quantity", 0)
            # 幂等：同 rma+product 的该 disposition 已执行过则跳过（尤其 restock 防重复加库存）。
            dup = db.execute(
                "SELECT id FROM return_dispositions WHERE return_id=? AND product_id=? AND disposition=?",
                (rma_id, pid, disp)).fetchone()
            if dup:
                results.append({"disposition_id": dup["id"], "disposition": disp,
                                "quantity": qty, "skipped": "已处置过，幂等跳过"})
                continue
            did = db.execute(
                "INSERT INTO return_dispositions (return_id, product_id, quantity, disposition, note) VALUES (?,?,?,?,?)",
                (rma_id, pid, qty, disp, it.get("note", ""))
            ).lastrowid
            if disp == "restock":
                # Restock: add back to inventory（审批后唯一库存入口，纳入同事务）
                r = inventory_adjust(pid, 1, qty, ref_type="rma_restock", ref_id=rma_id, db_conn=db)
                if isinstance(r, dict) and r.get("error"):
                    raise ValueError(f"RMA restock 回增库存失败(商品{pid}): {r['error']}")
            elif disp == "scrap":
                pass  # Inventory already reduced during return
            # For quarantine/supplier return/rework: record only
            results.append({"disposition_id": did, "disposition": disp, "quantity": qty})
        db.execute("UPDATE return_orders SET status='dispositioned' WHERE id=?", (rma_id,))
    return {"rma_id": rma_id, "dispositions": len(results), "details": results}

def rma_refund_create(rma_id, amount=0, method="原路退回", idempotency_key=None):
    """Create a refund for an approved RMA."""
    # Q3 (2026-07-25): client idempotency key — replaying a refund returns the
    # original refund instead of double-refunding the same RMA.
    if idempotency_key:
        ex = idempotency_get(idempotency_key)
        if ex and ex[0] == 'rma_refund':
            return {"rma_id": rma_id, "refund_id": ex[1], "amount": amount, "method": method, "idempotent": True}
    with get_db_tx() as db:
        ro = db.execute("SELECT * FROM return_orders WHERE id=?", (rma_id,)).fetchone()
        if not ro: return {"error": "退货单不存在"}

        ro = dict(ro)
        if not amount:
            amount = ro.get("total_amount", 0)

        # Check authorization
        ra = db.execute("SELECT auth_status FROM return_authorizations WHERE return_id=? AND auth_status='approved'", (rma_id,)).fetchone()
        if not ra and amount >= 500:
            return {"error": "该退货单未获审批，无法退款"}

        # Create refund payment
        db.execute("""CREATE TABLE IF NOT EXISTS refunds (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            rma_id INTEGER, contact_id INTEGER, amount REAL,
            method TEXT DEFAULT 'cash', status TEXT DEFAULT 'pending',
            created_at TEXT DEFAULT (datetime('now','localtime'))
        )""")
        rid = db.execute("INSERT INTO refunds (rma_id, contact_id, amount, method, status) VALUES (?,?,?,?,'completed')",
            (rma_id, ro["contact_id"], amount, method)).lastrowid

        # AR 冲减（G12 修正）：receivables 有 CHECK(amount>=0)，负值冲减被约束拒绝。
        # 正确口径=冲减该客户未付 AR 余额（amount/paid_amount 同减，净额减少 amount）。
        remaining = amount
        for ar in db.execute(
                "SELECT id,amount,paid_amount FROM receivables WHERE contact_id=? AND type='ar' "
                "AND status!='paid' AND amount>0 ORDER BY id", (ro["contact_id"],)).fetchall():
            if remaining <= 0:
                break
            cut = min(remaining, ar["amount"])
            new_amount = ar["amount"] - cut
            new_paid = min(ar["paid_amount"], new_amount)
            new_status = 'paid' if new_amount <= 0 else ('partial' if new_paid > 0 else 'unpaid')
            db.execute("UPDATE receivables SET amount=?,paid_amount=?,status=? WHERE id=?",
                       (new_amount, new_paid, new_status, ar["id"]))
            remaining -= cut

        # G12 (2026-07-25): refund 必须写 cash_flow（原缺陷：只写 refunds+负AR，
        # 资金账与现金账脱节）。退款=现金流出(expense)，并同步扣减账户余额。
        # accounts/cash_flow 表按存在性兜底（测试库可能未建），存在才更新余额。
        account = "现金"
        tbl = {r[0] for r in db.execute("SELECT name FROM sqlite_master WHERE type='table'")}
        bal_after = 0
        if 'accounts' in tbl:
            db.execute("UPDATE accounts SET current_balance=current_balance-? WHERE name=?", (amount, account))
            bal = db.execute("SELECT current_balance FROM accounts WHERE name=?", (account,)).fetchone()
            bal_after = bal['current_balance'] if bal else 0
        if 'cash_flow' in tbl:
            db.execute(
                "INSERT INTO cash_flow (account,type,amount,balance_after,contact_id,ref_type,ref_id,category,note) "
                "VALUES (?,?,?,?,?,?,?,?,?)",
                (account, 'expense', amount, bal_after,
                 ro["contact_id"], 'rma_refund', rma_id, '退货退款', f"RMA#{rma_id} {method}"))

        db.execute("UPDATE return_orders SET status='refunded' WHERE id=?", (rma_id,))
        db.commit()
    if idempotency_key:
        idempotency_put(idempotency_key, 'rma_refund', rid, '')
    return {"rma_id": rma_id, "refund_id": rid, "amount": amount, "method": method, "idempotent": False}

# === v87: Quality Management Depth — AQL sampling, supplier quality ===

_AQL_TABLE = {
    # (lot_size_min, lot_size_max): { sample_size_letter: (sample_size, Ac, Re) }
    # Based on ANSI/ASQ Z1.4, normal inspection, level II
    # Ac=Accept, Re=Reject for each AQL level
    0.065: {  # AQL=0.065%
        "J": (80, 0, 1), "K": (125, 0, 1), "L": (200, 0, 1),
        "M": (315, 0, 1), "N": (500, 0, 1),
    },
    0.25: {  # AQL=0.25%
        "G": (32, 0, 1), "H": (50, 0, 1), "J": (80, 0, 1),
        "K": (125, 0, 1), "L": (200, 0, 1), "M": (315, 1, 2),
    },
    0.65: {  # AQL=0.65%
        "F": (20, 0, 1), "G": (32, 0, 1), "H": (50, 0, 1),
        "J": (80, 1, 2), "K": (125, 2, 3), "L": (200, 3, 4),
    },
    1.0: {  # AQL=1.0%
        "F": (20, 0, 1), "G": (32, 1, 2), "H": (50, 1, 2),
        "J": (80, 2, 3), "K": (125, 3, 4), "L": (200, 5, 6), "M": (315, 7, 8),
    },
    2.5: {  # AQL=2.5% (commonly used for FMCG)
        "E": (13, 0, 1), "F": (20, 1, 2), "G": (32, 2, 3),
        "H": (50, 3, 4), "J": (80, 5, 6), "K": (125, 7, 8), "L": (200, 10, 11), "M": (315, 14, 15),
    },
    4.0: {  # AQL=4.0%
        "E": (13, 1, 2), "F": (20, 2, 3), "G": (32, 3, 4),
        "H": (50, 5, 6), "J": (80, 7, 8), "K": (125, 10, 11), "L": (200, 14, 15),
    },
}

# Lot size → sample size code letter (Level II)
_LOT_SIZE_CODE = [
    (2, 8, "A"), (9, 15, "B"), (16, 25, "C"), (26, 50, "D"),
    (51, 90, "E"), (91, 150, "F"), (151, 280, "G"), (281, 500, "H"),
    (501, 1200, "J"), (1201, 3200, "K"), (3201, 10000, "L"), (10001, 35000, "M"),
    (35001, 150000, "N"), (150001, 500000, "P"),
]

def aql_sample_plan(lot_size, aql=2.5):
    """Get ANSI/ASQ Z1.4 sample plan: sample size, accept, reject numbers."""
    # Determine code letter from lot size
    code_letter = "A"
    for lo, hi, code in _LOT_SIZE_CODE:
        if lo <= lot_size <= hi:
            code_letter = code
            break

    # Get sample plan from AQL table
    aqls = sorted(_AQL_TABLE.keys())
    best_aql = 2.5
    for a in aqls:
        if a == aql or abs(a - aql) < 0.01:
            best_aql = a; break
        if a > aql:
            best_aql = a; break  # Use next higher AQL (more strict)

    plan = _AQL_TABLE.get(best_aql, _AQL_TABLE[2.5])
    if code_letter in plan:
        sample_size, accept, reject = plan[code_letter]
    else:
        # Find closest available code letter
        codes = sorted(plan.keys())
        for c in codes:
            if c >= code_letter:
                sample_size, accept, reject = plan[c]; break
        else:
            sample_size, accept, reject = list(plan.values())[-1]

    return {
        "lot_size": lot_size, "aql": best_aql, "code_letter": code_letter,
        "sample_size": sample_size, "accept": accept, "reject": reject,
        "decision_rule": f"抽{sample_size}件, 不合格≤{accept}则接收, ≥{reject}则拒收"
    }

def inspection_with_aql(plan_id, lot_size, defects_found):
    """Execute inspection with AQL sampling decision."""
    _init_qms_tables()  # v706：读之前先 ensure（懒建表，否则首次访问 no such table）
    with get_db() as db:
        plan = db.execute("SELECT * FROM inspection_plans WHERE id=?", (plan_id,)).fetchone()
        if not plan: return {"error": "检验计划不存在"}
        plan = dict(plan)

    aql = float(plan.get("aql_level", "2.5").replace("normal","2.5").replace("tightened","1.0").replace("reduced","4.0") or 2.5)
    sample = aql_sample_plan(lot_size, aql)

    passed = defects_found <= sample["accept"]
    decision = "accept" if passed else ("reject" if defects_found >= sample["reject"] else "resample")

    return {
        "inspection_plan": plan["name"], "lot_size": lot_size,
        "sample_size": sample["sample_size"], "aql": sample["aql"],
        "accept": sample["accept"], "reject": sample["reject"],
        "defects_found": defects_found, "passed": passed, "decision": decision,
        "rule": sample["decision_rule"]
    }

def get_supplier_quality_summary(supplier_id=0, limit=50):
    """Supplier quality scorecard with NCR count, rejection rate."""
    with get_db() as db:
        w = "WHERE po.supplier_id=?" if supplier_id else ""
        p = [supplier_id] if supplier_id else []
        rows = [dict(r) for r in db.execute(
            f"SELECT c.name as supplier_name, COUNT(ncr.id) as ncr_count, "
            f"COALESCE(SUM(CASE WHEN ncr.severity='critical' THEN 1 ELSE 0 END),0) as critical_count, "
            f"COALESCE(SUM(CASE WHEN ncr.status='closed' THEN 1 ELSE 0 END),0) as closed_count, "
            f"COALESCE(AVG(CASE WHEN ncr.severity='critical' THEN 3 WHEN ncr.severity='major' THEN 2 ELSE 1 END),0) as avg_severity "
            f"FROM contacts c "
            f"LEFT JOIN purchase_orders po ON po.supplier_id=c.id "
            f"LEFT JOIN non_conformances ncr ON ncr.source_ref_id=po.id AND ncr.source='purchase_order' "
            f"WHERE c.type='supplier' {w} GROUP BY c.id, c.name ORDER BY ncr_count DESC LIMIT ?",
            p + [limit]
        ).fetchall()]
    return rows

# === v86: WMS Depth — putaway strategy, pick path optimization, cross-dock ===

def _init_wms_depth_tables():
    """WMS 深度功能（上架/补货）的懒建表。幂等。

    🔴 v465f：`bin_locations` 的 DDL 原本只在 **13518 行**，而那行被误放进了
       `check_scheduled_price_lists()` 的函数体里 ⇒ 全新库（新租户）**没有这张表**，
       `putaway_strategy` / `wms_pick_face_needs` 会对新库直接 `no such table`。
       这里补齐两张库位表（与生产库结构逐字一致），使 WMS 读取在新库上自愈。
       ⚠️ 13518 那处错误位置**本轮不动**（属 `check_scheduled_*` 的问题，另行处理）。
    """
    with get_db() as db:
        db.executescript("""
            CREATE TABLE IF NOT EXISTS bin_locations (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                warehouse_id INTEGER DEFAULT 1,
                code TEXT NOT NULL,
                zone TEXT DEFAULT '',
                description TEXT DEFAULT '',
                is_active INTEGER DEFAULT 1,
                UNIQUE(warehouse_id, code)
            );
            CREATE TABLE IF NOT EXISTS slotting_rules (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                warehouse_id INTEGER DEFAULT 1,
                zone TEXT DEFAULT '',
                velocity_class TEXT DEFAULT 'B',
                bin_type TEXT DEFAULT 'standard',
                priority INTEGER DEFAULT 5,
                note TEXT DEFAULT ''
            );
            CREATE TABLE IF NOT EXISTS bin_occupancy (
                bin_id INTEGER NOT NULL,
                product_id INTEGER NOT NULL,
                quantity REAL DEFAULT 0,
                last_updated TEXT DEFAULT (datetime('now','localtime')),
                UNIQUE(bin_id, product_id)
            );
        """)
        db.commit()

def putaway_strategy(product_id, warehouse_id=1):
    """Recommend the best bin location for a product based on ABC class, zone match, and occupancy.
    Returns: {bin_id, bin_code, zone, strategy_reason}"""
    import math
    _init_wms_depth_tables()
    with get_db() as db:
        # Get product ABC class
        try:
            abc_row = db.execute(
                "SELECT abc_class FROM abc_analysis_results WHERE product_id=? ORDER BY analysis_date DESC LIMIT 1",
                (product_id,)).fetchone()
            abc_class = abc_row["abc_class"] if abc_row else "B"
        except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}"); abc_class = "B"

        # Get product dimensions / velocity
        try:
            prod = db.execute("SELECT name, category FROM products WHERE id=?", (product_id,)).fetchone()
            category = prod["category"] if prod else ""
        except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}"); category = ""

        # Find matching zone based on velocity + category
        velocity_zone = {"A": "fast", "B": "medium", "C": "slow"}.get(abc_class, "medium")

        # Get all bin locations with occupancy
        bins = [dict(r) for r in db.execute(
            "SELECT bl.*, COALESCE(SUM(bo.quantity),0) as total_qty FROM bin_locations bl "
            "LEFT JOIN bin_occupancy bo ON bl.id=bo.bin_id "
            "WHERE bl.warehouse_id=? GROUP BY bl.id ORDER BY bl.zone, bl.code",
            (warehouse_id,)).fetchall()]

        if not bins:
            return {"error": "仓库无可用库位"}

        # Score each bin
        scored = []
        for b in bins:
            score = 0
            # Zone match: prefer same velocity zone
            bzone = (b.get("zone") or "").lower()
            if velocity_zone in bzone or bzone == velocity_zone: score += 50
            elif "fast" in bzone and velocity_zone == "medium": score += 10
            elif "medium" in bzone and velocity_zone == "slow": score += 10

            # Occupancy penalty: prefer empty bins for fast movers
            occupancy_pct = b["total_qty"] / 100 if b["total_qty"] < 100 else 0.95
            if abc_class == "A": score -= int(occupancy_pct * 40)
            elif abc_class == "B": score -= int(occupancy_pct * 20)

            # Zone priority boost
            if bzone == "pick_face": score += 30  # pick face for fast items
            if abc_class == "A" and bzone == "pick_face": score += 20

            scored.append({"bin": b, "score": score})

        scored.sort(key=lambda x: x["score"], reverse=True)
        best = scored[0]
        return {
            "product_id": product_id, "warehouse_id": warehouse_id,
            "abc_class": abc_class, "velocity_zone": velocity_zone,
            "recommended_bin_id": best["bin"]["id"],
            "recommended_bin_code": best["bin"]["code"],
            "recommended_zone": best["bin"]["zone"],
            "score": best["score"],
            "reason": f"ABC={abc_class}类, 库区={best['bin']['zone']}, 占用率={best['bin']['total_qty']:.0f}"
        }

def pick_path_optimize(wave_id):
    """Optimize pick path for a wave using nearest-neighbor heuristic.
    Returns ordered list of bin locations with total distance."""
    import math
    with get_db() as db:
        # Get wave items with bin locations
        items = [dict(r) for r in db.execute(
            "SELECT wi.*, bl.code as bin_code, bl.zone "
            "FROM pick_wave_items wi "
            "JOIN bin_locations bl ON wi.bin_id=bl.id "
            "WHERE wi.wave_id=? AND wi.status='pending'",
            (wave_id,)).fetchall()]

        if not items:
            return {"error": "波次无可拣货项"}

        # Use bin code to estimate coordinates (e.g., A-01-02 → zone A, aisle 1, bin 2)
        def bin_coords(bin_code):
            parts = (bin_code or "Z-00-00").replace("-", " ").replace("_"," ").split()
            x = 0; y = 0
            try:
                if len(parts) >= 2:
                    # Zone letter → x offset
                    zone_letter = parts[0][0].upper() if parts[0] else 'Z'
                    x = (ord(zone_letter) - ord('A')) * 10
                if len(parts) >= 2:
                    y = int(parts[1]) if parts[1].isdigit() else int(parts[1], 36) % 100
            except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}")
            return (x, y)

        def dist(a, b):
            return math.sqrt((a[0]-b[0])**2 + (a[1]-b[1])**2)

        # Nearest-neighbor path from origin
        coords = [(bin_coords(it["bin_code"]), i, it) for i, it in enumerate(items)]
        path = []
        current = (0, 0)  # start at dock
        remaining = coords[:]
        total_dist = 0.0

        while remaining:
            # Find nearest remaining bin
            nearest_idx = min(range(len(remaining)), key=lambda i: dist(current, remaining[i][0]))
            nearest = remaining.pop(nearest_idx)
            total_dist += dist(current, nearest[0])
            path.append({
                "position": len(path) + 1,
                "bin_code": nearest[2]["bin_code"],
                "zone": nearest[2].get("zone", ""),
                "item_id": nearest[2]["id"],
                "product_name": nearest[2].get("product_name", ""),
                "quantity": nearest[2].get("quantity", 0),
            })
            current = nearest[0]

        return {
            "wave_id": wave_id, "items_total": len(items),
            "path": path, "estimated_distance": round(total_dist, 1),
            "method": "nearest-neighbor"
        }

def cross_dock_opportunities(warehouse_id=1):
    """Identify cross-dock opportunities: inbound POs that can go directly to outbound SOs.
    Returns list of matches where the same product is arriving and being ordered."""
    with get_db() as db:
        # 在途进货：尚未收货的采购单明细。
        #   🔴 v465f 修两处致命错（叠加起来被下面的 try/except 吞成**静默空表** ⇒ 恒 0 条）：
        #      ① 列名：`poi.purchase_order_id` → 实际是 **`order_id`**（两表同构，
        #         见 14147/14149 行 atp_calculate 的正确写法）。
        #      ② 状态词：`status='confirmed'` → 生产库里根本没有该状态（实际只有
        #         draft/received/cancelled）。本系统「在途采购量」既有口径 =
        #         `draft/confirmed/pending_approval`（server.py 两处在途量 SQL）。
        #   另：`contacts` 改 **LEFT JOIN** —— supplier_id 缺失（0/已删）时 INNER JOIN 会
        #   把整行丢掉（tenant 1 的两张 draft 单正好如此）；补 `product_name` 供前端显示。
        try:
            inbound = [dict(r) for r in db.execute(
                "SELECT poi.*, p.name as product_name, po.order_date, po.order_no, c.name as supplier_name "
                "FROM purchase_order_items poi "
                "JOIN purchase_orders po ON poi.order_id=po.id "
                "LEFT JOIN products p ON poi.product_id=p.id "
                "LEFT JOIN contacts c ON po.supplier_id=c.id "
                "WHERE po.status IN ('draft','confirmed','pending_approval') "
                "ORDER BY po.order_date LIMIT 50"
            ).fetchall()]
        except Exception as e:
            logging.getLogger("hergent").warning(f"query failed: {e}")
            inbound = []

        # 待发订单：已就绪、尚未发货的销售单明细。
        #   状态词取本系统「可发货」既有口径 `draft/confirmed`（sales.py 发货闸门同款）；
        #   已发货/签收(delivered/signed)、终态(cancelled/rejected) 不在其列。
        #   列名 `soi.sale_order_id` → 实际是 **`order_id`**。
        try:
            outbound = [dict(r) for r in db.execute(
                "SELECT soi.*, p.name as product_name, so.order_date, so.order_no, ct.name as customer_name "
                "FROM sale_order_items soi "
                "JOIN sale_orders so ON soi.order_id=so.id "
                "LEFT JOIN products p ON soi.product_id=p.id "
                "LEFT JOIN contacts ct ON so.customer_id=ct.id "
                "WHERE so.status IN ('draft','confirmed') "
                "ORDER BY so.order_date LIMIT 100"
            ).fetchall()]
        except Exception as e:
            logging.getLogger("hergent").warning(f"query failed: {e}")
            outbound = []

        opportunities = []
        for ib in inbound:
            ib_qty = ib.get("quantity", 0)
            if ib_qty <= 0: continue
            for ob in outbound:
                if ib.get("product_id") == ob.get("product_id") and ob.get("quantity", 0) > 0:
                    match_qty = min(ib_qty, ob["quantity"])
                    opportunities.append({
                        "product_id": ib["product_id"],
                        "product_name": ib.get("product_name", ""),
                        "inbound_po": ib.get("order_no", ""),
                        "inbound_supplier": ib.get("supplier_name", ""),
                        "inbound_qty_available": ib_qty,
                        "outbound_so": ob.get("order_no", ""),
                        "outbound_customer": ob.get("customer_name", ""),
                        "outbound_qty_needed": ob["quantity"],
                        "match_qty": match_qty,
                        "savings": "免上架+免拣货, 缩短处理时间",
                    })

        return {
            "warehouse_id": warehouse_id,
            "inbound_items": len(inbound),
            "outbound_items": len(outbound),
            "cross_dock_opportunities": len(opportunities),
            "opportunities": opportunities[:20]
        }

# === v84: Tax Engine — multi-jurisdiction, withholding, configurable rates ===

def _init_tax_tables():
    try:
        with get_db() as db:
            db.executescript("""
                CREATE TABLE IF NOT EXISTS tax_jurisdictions (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    country TEXT NOT NULL DEFAULT 'CN',
                    region TEXT DEFAULT '',
                    tax_type TEXT NOT NULL DEFAULT 'vat',
                    rate REAL NOT NULL DEFAULT 0,
                    effective_from TEXT NOT NULL DEFAULT '2020-01-01',
                    effective_to TEXT DEFAULT '2099-12-31',
                    is_active INTEGER DEFAULT 1
                );
                CREATE TABLE IF NOT EXISTS tax_codes (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    name TEXT NOT NULL,
                    rate REAL NOT NULL DEFAULT 0,
                    description TEXT DEFAULT '',
                    jurisdiction_id INTEGER DEFAULT 0,
                    is_active INTEGER DEFAULT 1
                );
            """)
            db.commit()
    except Exception: pass  # table may not exist yet (migration)

def get_applicable_tax(jurisdiction='CN', transaction_date=None, product_category=''):
    """Determine applicable tax rate by jurisdiction, date, and product category.
    Returns (rate, tax_type, jurisdiction_string).
    Falls back to 13% CN VAT if no specific match."""
    _init_tax_tables()
    if not transaction_date:
        transaction_date = datetime.now().strftime("%Y-%m-%d")
    with get_db() as db:
        # Exact match: country + region + tax_type + date range
        r = db.execute(
            "SELECT rate, tax_type, country, region FROM tax_jurisdictions "
            "WHERE country=? AND is_active=1 AND effective_from<=? AND (effective_to='' OR effective_to>=?) "
            "ORDER BY region DESC LIMIT 1",
            (jurisdiction, transaction_date, transaction_date)
        ).fetchone()
        if r:
            region = f"{r['country']}-{r['region']}" if r.get("region") else r["country"]
            return r["rate"] / 100.0, r["tax_type"], region
        # Fallback: any active rate for this country
        r = db.execute(
            "SELECT rate, tax_type, country FROM tax_jurisdictions "
            "WHERE country=? AND is_active=1 LIMIT 1",
            (jurisdiction,)
        ).fetchone()
        if r:
            return r["rate"] / 100.0, r["tax_type"], r["country"]
    # Hard fallback: 13% CN VAT
    return 0.13, "vat", "CN"

def calculate_withholding_tax(amount, vendor_type='', jurisdiction='CN'):
    """Calculate withholding tax (预扣税) based on vendor type and jurisdiction.
    Common WHT rates: professional_services=10%, dividends=5%, royalties=10%, interest=20%."""
    rates = {
        "professional_services": 0.10,
        "dividends": 0.05,
        "royalties": 0.10,
        "interest": 0.20,
        "rent": 0.10,
        "commission": 0.10,
        "management_fee": 0.10,
    }
    rate = rates.get(vendor_type, 0.0)
    return round(amount * rate, 2), rate

def get_tax_report_v2(month='', jurisdiction='CN'):
    """Tax report using configurable jurisdiction rates (replaces hardcoded 13%).
    Backward compatible — defaults to 13% CN VAT if tax_jurisdictions table is empty."""
    if not month: month = datetime.now().strftime("%Y-%m")
    _init_tax_tables()
    # Seed default jurisdiction if empty
    with get_db() as db:
        cnt = db.execute("SELECT COUNT(*) FROM tax_jurisdictions").fetchone()[0]
        if cnt == 0:
            try:
                db.executescript("""
                    INSERT INTO tax_jurisdictions (country, region, tax_type, rate) VALUES ('CN','','vat',13);
                    INSERT INTO tax_jurisdictions (country, region, tax_type, rate) VALUES ('CN','','vat_small',3);
                    INSERT INTO tax_jurisdictions (country, region, tax_type, rate) VALUES ('CN','','vat_zero',0);
                    INSERT INTO tax_jurisdictions (country, region, tax_type, rate) VALUES ('HK','','vat',0);
                """)
                db.commit()
            except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}")

    rate, tax_type, juris = get_applicable_tax(jurisdiction, month + "-01")

    with get_db() as db:
        sales = db.execute(
            "SELECT COALESCE(SUM(total_amount),0) FROM sale_orders WHERE substr(order_date,1,7)=? AND status IN ('delivered','signed')",
            (month,)).fetchone()[0]
        purchases = db.execute(
            "SELECT COALESCE(SUM(total_amount),0) FROM purchase_orders WHERE substr(order_date,1,7)=? AND status='confirmed'",
            (month,)).fetchone()[0]

    output_tax = round(sales * rate)
    input_tax = round(purchases * rate)
    return {
        "month": month, "jurisdiction": juris, "tax_type": tax_type, "rate_pct": round(rate * 100, 1),
        "sales": sales, "purchases": purchases,
        "output_tax": output_tax, "input_tax": input_tax,
        "payable": round((sales - purchases) * rate)
    }

def tax_jurisdiction_list():
    _init_tax_tables()
    with get_db() as db:
        return [dict(r) for r in db.execute("SELECT * FROM tax_jurisdictions WHERE is_active=1 ORDER BY country, region").fetchall()]

def tax_jurisdiction_save(country, tax_type, rate, region=''):
    _init_tax_tables()
    with get_db_tx() as db:
        jid = db.execute("INSERT INTO tax_jurisdictions (country, region, tax_type, rate) VALUES (?,?,?,?)",
            (country.upper(), region, tax_type, rate)).lastrowid
        db.commit(); return jid

# === v84: Financial Close Workbench ===

def period_close_checklist(month=""):
    """Return close checklist with pass/fail status for each required step."""
    init_deferred_tables()  # v706：读之前先 ensure（懒建表，否则首次访问 no such table）
    if not month: month = datetime.now().strftime("%Y-%m")
    items = []
    # 1. Depreciation run
    try:
        r = get_config("last_depreciation_month")
        items.append({"step": "固定资产折旧", "status": "passed" if r == month else "pending",
                       "detail": f"最近折旧月份: {r or '无'}", "action": "run_depreciation"})
    except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}"); items.append({"step": "固定资产折旧", "status": "pending", "detail": "检查失败", "action": "run_depreciation"})

    # 2. Currency revaluation
    try:
        r = get_config("last_revaluation_date")
        items.append({"step": "外币重估", "status": "passed" if r and r.startswith(month[:7]) else "pending",
                       "detail": f"最近重估: {r or '无'}", "action": "run_revaluation"})
    except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}"); items.append({"step": "外币重估", "status": "pending", "detail": "检查失败", "action": "run_revaluation"})

    # 3. Bad debt provision
    try:
        r = get_config("last_bad_debt_month")
        items.append({"step": "坏账计提", "status": "passed" if r == month else "pending",
                       "detail": f"最近计提: {r or '无'}", "action": "run_bad_debt"})
    except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}"); items.append({"step": "坏账计提", "status": "pending", "detail": "检查失败", "action": "run_bad_debt"})

    # 4. Bank reconciliation
    try:
        with get_db() as db:
            unreconciled = db.execute("SELECT COUNT(*) FROM bank_transactions WHERE reconciled=0").fetchone()[0]
        items.append({"step": "银行对账", "status": "passed" if unreconciled == 0 else "pending",
                       "detail": f"未对账交易: {unreconciled}条", "action": "open_bank_reconciliation"})
    except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}"); items.append({"step": "银行对账", "status": "pending", "detail": "检查失败", "action": "open_bank_reconciliation"})

    # 5. Deferred revenue/expense recognition
    try:
        with get_db() as db:
            deferred_pending = db.execute("SELECT COUNT(*) FROM deferred_revenue WHERE status='active' AND total_periods>recognized_periods").fetchone()[0]
        items.append({"step": "递延收入确认", "status": "passed" if deferred_pending == 0 else "pending",
                       "detail": f"未确认递延: {deferred_pending}笔", "action": "run_deferred"})
    except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}"); items.append({"step": "递延收入确认", "status": "pending", "detail": "检查失败", "action": "run_deferred"})

    # 6. Sub-ledger vs GL reconciliation
    try:
        with get_db() as db:
            ar_gl = db.execute("SELECT COALESCE(SUM(COALESCE(debit,0)-COALESCE(credit,0)),0) FROM journal_entries WHERE account_code LIKE '1122%'").fetchone()[0] or 0
            ar_sub = db.execute("SELECT COALESCE(SUM(amount-paid_amount),0) FROM receivables WHERE type='ar' AND status!='paid'").fetchone()[0] or 0
            ar_diff = abs(ar_gl - ar_sub)
            ap_gl = db.execute("SELECT COALESCE(SUM(COALESCE(credit,0)-COALESCE(debit,0)),0) FROM journal_entries WHERE account_code LIKE '2202%'").fetchone()[0] or 0
            ap_sub = db.execute("SELECT COALESCE(SUM(amount-paid_amount),0) FROM receivables WHERE type='ap' AND status!='paid'").fetchone()[0] or 0
            ap_diff = abs(ap_gl - ap_sub)
        ok = ar_diff < 1.0 and ap_diff < 1.0
        items.append({"step": "子账总账对账", "status": "passed" if ok else "pending",
                       "detail": f"AR差异¥{ar_diff:,.2f} AP差异¥{ap_diff:,.2f}" + ("" if ok else " — 需调整"), "action": "reconcile_gl_sl"})
    except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}"); items.append({"step": "子账总账对账", "status": "pending", "detail": "对账检查失败", "action": "reconcile_gl_sl"})

    # 7. Already closed check
    try:
        already = is_period_closed(month)
        items.append({"step": "关账状态", "status": "passed" if not already else "closed",
                       "detail": "已关账" if already else "未关账", "action": None})
    except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}"); items.append({"step": "关账状态", "status": "pending", "detail": "状态检查失败", "action": None})

    all_passed = all(it["status"] in ("passed", "closed") for it in items)
    return {"month": month, "items": items, "ready_to_close": all_passed}

def period_close_preview(month=""):
    """Preview the journal entries that would be generated by closing the period.
    Does NOT write any data."""
    if not month: month = datetime.now().strftime("%Y-%m")
    entries = []
    with get_db() as db:
        try:
            _ = db.execute("SELECT 1 FROM journal_entries LIMIT 1").fetchone()
        except Exception as e: logging.getLogger("hergent").debug(f"skipping row: {e}"); return {"month": month, "preview_entries": [], "entry_count": 0, "note": "journal_entries表不存在"}
        # Income account balances → current year profit
        revenue = db.execute(
            "SELECT COALESCE(SUM(COALESCE(credit,0)-COALESCE(debit,0)),0) FROM journal_entries WHERE account_code LIKE '6%' AND substr(date,1,7)=?",
            (month,)).fetchone()[0] or 0
        # Expense account balances → current year profit
        expense = db.execute(
            "SELECT COALESCE(SUM(COALESCE(debit,0)-COALESCE(credit,0)),0) FROM journal_entries WHERE account_code LIKE '6%' AND account_code NOT LIKE '6001%' AND account_code NOT LIKE '6401%' AND substr(date,1,7)=?",
            (month,)).fetchone()[0] or 0
        # COGS
        cogs = db.execute(
            "SELECT COALESCE(SUM(COALESCE(debit,0)-COALESCE(credit,0)),0) FROM journal_entries WHERE account_code LIKE '6401%' AND substr(date,1,7)=?",
            (month,)).fetchone()[0] or 0

    # Revenue → Year Profit
    if abs(revenue) > 0.01:
        entries.append({"account_code": "6001", "account_name": "主营业务收入", "debit": abs(revenue), "credit": 0, "summary": f"关账结转 {month}"})
        entries.append({"account_code": "4103", "account_name": "本年利润", "debit": 0, "credit": abs(revenue), "summary": f"关账结转 {month}"})

    # Expenses → Year Profit
    total_exp = expense + cogs
    if abs(total_exp) > 0.01:
        entries.append({"account_code": "4103", "account_name": "本年利润", "debit": abs(total_exp), "credit": 0, "summary": f"关账结转 {month}"})
        entries.append({"account_code": "6401+C6", "account_name": "成本/费用类", "debit": 0, "credit": abs(total_exp), "summary": f"关账结转 {month}"})

    return {"month": month, "preview_entries": entries, "entry_count": len(entries)}

def period_close_execute(month=""):
    """Execute period close after all checklist items pass."""
    if not month: month = datetime.now().strftime("%Y-%m")

    # Gate: check checklist
    checklist = period_close_checklist(month)
    if not checklist.get("ready_to_close"):
        failed = [it for it in checklist["items"] if it["status"] == "pending"]
        return {"success": False, "error": "关账前置检查未通过", "failed_items": [f["step"] for f in failed]}

    if is_period_closed(month):
        return {"success": False, "error": f"期间 {month} 已关闭"}

    # Execute close (delegate to existing period_close in db/queries/finance.py)
    try:
        from db.queries.finance import period_close as _pc
        result = _pc(month)
        return {"success": True, "month": month, "result": result}
    except Exception as e:
        return {"success": False, "error": str(e)[:200]}

def period_close_status(limit=12):
    """Return close status for recent periods.

    v302（2026-09-28）修「必崩 500」：原实现查了表里**根本不存在**的 `closed_at` 列。
      · 关账状态由 `status` 字段表达（'open' / 'closed'，见 `set_accounting_period` 与
        `is_period_closed`）；建表语句 v131d 里**就没有** `closed_at`，且全仓**没有任何写入方**
        ⇒ 它是个凭空造出来的列 ⇒ 去掉，改为返回真实存在的 `created_at`。
      · 真正的结转事实另在 `period_closures` 表（见 `db/queries/finance.period_close`）。

    v302 同时修掉「守卫形同虚设」：旧代码 try 只包住 `SELECT 1 ... LIMIT 1`，
      那句只验「表在不在」、验不了「列在不在」；而真正会崩的 SELECT 在 try **之外**
      ⇒ 列缺失时直接抛 500，守卫一次都没起作用。现改为把整段查询纳入 try。
    """
    try:
        with get_db() as db:
            rows = db.execute(
                "SELECT month, status, created_at FROM accounting_periods ORDER BY month DESC LIMIT ?",
                (limit,)).fetchall()
            return [dict(r) for r in rows]
    except Exception as e:
        # v302：记 warning 而非 debug —— 原先用 debug 会把真实故障吞成「静默失效」
        logging.getLogger("hergent").warning(f"period_close_status 查询失败: {e}")
        return []

