def coa_mapping_list(standard_id=0):
    _init_gaap_tables()
    with get_db() as db:
        w = f"WHERE m.standard_id={int(standard_id)}" if standard_id else ""
        return [dict(r) for r in db.execute(
            f"SELECT m.*, s.name as standard_name, s.code as standard_code FROM coa_mappings m JOIN accounting_standards s ON m.standard_id=s.id {w} ORDER BY m.id"
        ).fetchall()]

def translate_journal_entry(entries, target_standard_id):
    """Translate a list of journal entries from CN-GAAP to target standard.
    entries: [{account_code, amount, ...}]"""
    _init_gaap_tables()
    with get_db() as db:
        mappings = {
            m["source_account_code"]: m
            for m in [dict(r) for r in db.execute(
                "SELECT * FROM coa_mappings WHERE standard_id=?", (target_standard_id,)
            ).fetchall()]
        }

    results = []
    for entry in entries:
        code = entry.get("account_code", "")
        mapped = mappings.get(code)
        if mapped:
            new_entry = dict(entry)
            new_entry["target_account_code"] = mapped["target_account_code"]
            new_entry["mapping_rule"] = mapped["mapping_rule"]
            new_entry["was_translated"] = True
            results.append(new_entry)
        else:
            new_entry = dict(entry)
            new_entry["target_account_code"] = code
            new_entry["was_translated"] = False
            new_entry["note"] = "未找到映射"
            results.append(new_entry)
    return results

# === v84: Consolidation Enhancement — NCI, IC inventory profit elimination ===

def calculate_nci(entity_id, period=""):
    """Calculate Non-Controlling Interest for a partially-owned subsidiary."""
    if not period: period = datetime.now().strftime("%Y-%m")
    entity = entity_get(entity_id)
    if not entity or isinstance(entity, dict) and "error" in entity:
        return {"error": "实体不存在"}

    ownership = entity.get("ownership_pct", 100)
    if ownership >= 100:
        return {"entity": entity["name"], "nci_pct": 0, "nci_amount": 0, "note": "全资子公司，无少数股东权益"}

    nci_pct = round((100 - ownership) / 100, 4)
    try:
        from db.queries.finance import get_pnl_gl
        pnl = get_pnl_gl(period)
        net_profit = pnl.get("net_profit", 0)
        nci_pl = round(net_profit * nci_pct, 2)

        with get_db() as db:
            equity = db.execute(
                "SELECT COALESCE(SUM(COALESCE(credit,0)-COALESCE(debit,0)),0) FROM journal_entries WHERE account_code LIKE '4%'",
            ).fetchone()[0] or 0
        nci_bs = round(equity * nci_pct, 2)
    except Exception as e:
        logging.getLogger("hergent").error(f"operation failed: {e}", exc_info=True)
        nci_pl = 0
        nci_bs = 0

    return {
        "entity": entity["name"], "entity_id": entity_id,
        "ownership_pct": ownership, "nci_pct": round(nci_pct * 100, 2),
        "nci_pnl_share": nci_pl, "nci_equity_share": nci_bs
    }

def ic_reconciliation_report(entity_a_id, entity_b_id):
    """Generate intercompany reconciliation: what A reports vs what B reports."""
    with get_db() as db:
        a_to_b = [dict(r) for r in db.execute(
            "SELECT * FROM ic_transactions WHERE from_entity_id=? AND to_entity_id=? AND status!='eliminated'",
            (entity_a_id, entity_b_id)
        ).fetchall()]
        b_to_a = [dict(r) for r in db.execute(
            "SELECT * FROM ic_transactions WHERE from_entity_id=? AND to_entity_id=? AND status!='eliminated'",
            (entity_b_id, entity_a_id)
        ).fetchall()]

    a_name = entity_get(entity_a_id).get("name", "A")
    b_name = entity_get(entity_b_id).get("name", "B")
    a_sent = sum(t["amount"] for t in a_to_b)
    b_received = sum(t["amount"] for t in b_to_a)

    return {
        "entity_a": a_name, "entity_b": b_name,
        "a_reports_sent_to_b": a_sent,
        "b_reports_sent_to_a": b_received,
        "a_to_b_transactions": a_to_b,
        "b_to_a_transactions": b_to_a,
        "difference": round(a_sent - b_received, 2),
        "status": "matched" if abs(a_sent - b_received) < 0.01 else "mismatch"
    }

def eliminate_ic_inventory_profit(from_entity_id, to_entity_id, period=""):
    """Eliminate unrealized profit in intercompany inventory.
    When entity A sells to B at a markup and B still holds the goods at period-end,
    the unrealized portion must be eliminated."""
    if not period: period = datetime.now().strftime("%Y-%m")
    with get_db() as db:
        # Find IC goods transactions where receiving entity still has inventory
        ics = [dict(r) for r in db.execute(
            "SELECT t.*, ef.name as from_name, et.name as to_name "
            "FROM ic_transactions t "
            "JOIN legal_entities ef ON t.from_entity_id=ef.id "
            "JOIN legal_entities et ON t.to_entity_id=et.id "
            "WHERE t.transaction_type='goods' AND t.status!='eliminated' "
            "AND t.from_entity_id=? AND t.to_entity_id=? AND t.trans_date LIKE ?",
            (from_entity_id, to_entity_id, period + "%")
        ).fetchall()]

        total_unrealized = 0.0
        for ic in ics:
            # Simplified estimation: assume 30% of IC goods remain in inventory
            # In a real system, you'd match against specific inventory batch IDs
            ic_dict = dict(ic)
            amount = ic_dict["amount"]
            # Assume a standard 20% markup on cost → 16.7% profit margin on selling price
            markup_rate = 0.20
            profit_margin = markup_rate / (1 + markup_rate)  # ~16.7%
            unrealized = round(amount * 0.30 * profit_margin, 2)
            total_unrealized += unrealized

    return {
        "period": period, "from_entity": entity_get(from_entity_id).get("name", ""),
        "to_entity": entity_get(to_entity_id).get("name", ""),
        "ic_goods_amount": sum(ic["amount"] for ic in ics),
        "estimated_unrealized_profit": total_unrealized,
        "ic_transactions": len(ics),
        "note": "需消除内部存货未实现利润" if total_unrealized > 0 else "无内部存货利润需消除"
    }

