    """Get active subscriptions for a given event type."""
    import json
    with get_db() as db:
        try:
            rows = db.execute("SELECT * FROM webhook_subscriptions WHERE is_active=1").fetchall()
            subs = []
            for r in rows:
                events = json.loads(r['events']) if r['events'] else []
                if event_type in events or '*' in events:
                    subs.append(dict(r))
            return subs
        except Exception as e:
            logging.getLogger("hergent").warning(f"query failed: {e}")
            return []

