def cron_toggle(tid, user_id):
    cron_ensure_tables()
    with get_db_tx() as db:
        task = db.execute("SELECT is_active FROM cron_tasks WHERE id=? AND user_id=?", (tid, user_id)).fetchone()
        if not task:
            return False
        new_state = 0 if task["is_active"] else 1
        db.execute("UPDATE cron_tasks SET is_active=? WHERE id=?", (new_state, tid))
        db.commit()
        return True

