def print_template_list(doc_type=""):
    """List print templates, optionally filtered by doc_type."""
    with get_db() as conn:
        if doc_type:
            rows = conn.execute("SELECT * FROM print_templates WHERE doc_type=? ORDER BY is_default DESC, id", (doc_type,)).fetchall()
        else:
            rows = conn.execute("SELECT * FROM print_templates ORDER BY doc_type, is_default DESC, id").fetchall()
        return [dict(r) for r in rows]


def print_template_get(tid):
    """Get a single print template by ID."""
    with get_db() as conn:
        row = conn.execute("SELECT * FROM print_templates WHERE id=?", (tid,)).fetchone()
        return dict(row) if row else None


def print_template_create(name, doc_type, paper_size, template_html, fields_json="[]", is_default=0):
    """Create a new print template. Returns the new template ID."""
    with get_db_tx() as conn:
        if is_default:
            conn.execute("UPDATE print_templates SET is_default=0 WHERE doc_type=?", (doc_type,))
        cur = conn.execute(
            "INSERT INTO print_templates (name,doc_type,paper_size,template_html,fields_json,is_default) VALUES (?,?,?,?,?,?)",
            (name, doc_type, paper_size, template_html, fields_json, is_default)
        )
        conn.commit()
        return cur.lastrowid


def print_template_update(tid, name=None, doc_type=None, paper_size=None, template_html=None, fields_json=None, is_default=None):
    """Update an existing print template. Only updates provided fields."""
    with get_db_tx() as conn:
        sets = []
        vals = []
        if name is not None: sets.append("name=?"); vals.append(name)
        if doc_type is not None: sets.append("doc_type=?"); vals.append(doc_type)
        if paper_size is not None: sets.append("paper_size=?"); vals.append(paper_size)
        if template_html is not None: sets.append("template_html=?"); vals.append(template_html)
        if fields_json is not None: sets.append("fields_json=?"); vals.append(fields_json)
        if is_default is not None:
            sets.append("is_default=?"); vals.append(is_default)
            if is_default:
                t = conn.execute("SELECT doc_type FROM print_templates WHERE id=?", (tid,)).fetchone()
                if t:
                    conn.execute("UPDATE print_templates SET is_default=0 WHERE doc_type=? AND id!=?", (t[0], tid))
        sets.append("updated_at=datetime('now','localtime')")
        vals.append(tid)
        conn.execute("UPDATE print_templates SET " + ",".join(sets) + " WHERE id=?", vals)
        conn.commit()


def print_template_delete(tid):
    """Delete a print template by ID."""
    with get_db_tx() as conn:
        conn.execute("DELETE FROM print_templates WHERE id=?", (tid,))
        conn.commit()


def print_template_duplicate(tid, new_name=None):
    """Duplicate an existing template. Returns the new template ID."""
    t = print_template_get(tid)
    if not t:
        return None
    name = new_name or (t['name'] + ' (副本)')
    return print_template_create(name, t['doc_type'], t['paper_size'], t['template_html'], t.get('fields_json', '[]'), 0)


