def _align_forecast_schema(db):
    """v94b: align PRE-EXISTING forecast tables (created by an earlier deploy with a
    different column naming) to the v94 contract. Idempotent: ADD COLUMN tolerates
    'duplicate column name' via _safe_migrate-style per-statement execution; the
    UPDATE backfills are no-ops once the new columns are populated. Never drops or
    renames old columns — zero data-loss risk on 0-row prod tables."""
    stmts = [
        # forecast_periods: old order_start_date/order_end_date -> order_start/order_end
        "ALTER TABLE forecast_periods ADD COLUMN order_start TEXT DEFAULT ''",
        "ALTER TABLE forecast_periods ADD COLUMN order_end TEXT DEFAULT ''",
        "UPDATE forecast_periods SET order_start=order_start_date WHERE (order_start='' OR order_start IS NULL) AND order_start_date IS NOT NULL",
        "UPDATE forecast_periods SET order_end=order_end_date WHERE (order_end='' OR order_end IS NULL) AND order_end_date IS NOT NULL",
        # forecast_orders: old reviewer_notes -> notes; add reviewed_at/confirmed_at
        "ALTER TABLE forecast_orders ADD COLUMN notes TEXT DEFAULT ''",
        "ALTER TABLE forecast_orders ADD COLUMN reviewed_at TEXT DEFAULT ''",
        "ALTER TABLE forecast_orders ADD COLUMN confirmed_at TEXT DEFAULT ''",
        "UPDATE forecast_orders SET notes=reviewer_notes WHERE (notes='' OR notes IS NULL) AND reviewer_notes IS NOT NULL",
        # kpi_targets: old target_name/target_type/target_value -> name/type/value
        "ALTER TABLE kpi_targets ADD COLUMN name TEXT DEFAULT ''",
        "ALTER TABLE kpi_targets ADD COLUMN type TEXT DEFAULT 'sales_amount'",
        "ALTER TABLE kpi_targets ADD COLUMN value REAL DEFAULT 0",
        "UPDATE kpi_targets SET name=target_name WHERE (name='' OR name IS NULL) AND target_name IS NOT NULL",
        "UPDATE kpi_targets SET type=target_type WHERE (type='sales_amount' OR type IS NULL) AND target_type IS NOT NULL",
        "UPDATE kpi_targets SET value=target_value WHERE (value=0 OR value IS NULL) AND target_value IS NOT NULL",
        # rebate_rules: old schema has extra is_active; new code ignores it. Ensure
        # the columns the new code writes all exist (they do in old schema too).
        "ALTER TABLE rebate_rules ADD COLUMN is_active INTEGER DEFAULT 1",
    ]
    for sql in stmts:
        try:
            db.execute(sql)
        except Exception as e:
            err = str(e)
            # Tolerate: column already exists, or source column absent (fresh v94 DB
            # has no order_start_date etc. — backfill UPDATE then simply no-ops).
            if _is_idempotent_migration_error(err) or 'no such column' in err:
                continue
            raise


def _v94b_forecast_cols():
    if _migration_applied('v94b_forecast_cols'):
        return
    try:
        with get_db() as db:
            _align_forecast_schema(db)
            db.execute(
                "INSERT OR REPLACE INTO _migrations (name, status, executed_at) "
                "VALUES ('v94b_forecast_cols', 'ok', datetime('now','localtime'))")
            db.commit()
    except Exception as e:
        _record_migration('v94b_forecast_cols', 'failed', str(e))
        import sys
        print(f"[Migration] FAILED v94b_forecast_cols: {str(e)[:200]}", file=sys.stderr, flush=True)


