# ---- 预报周期 ----

def period_validate(name, order_start, order_end, arrival):
    """期次硬校验 —— **唯一实现**，POST /periods 与 PATCH /periods/{pid} 共用。

    为什么放 db 层而不是路由层：任何客户端（Web / 小程序 / 脚本）都必须过同一道闸门，
    端点埋点可被旧版前端或直接调接口绕过。违规 raise ValueError(中文原因)，由端点转 400。

    硬规则（不满足 = 数据必错）：
      · 名称去空白后非空 —— 无名称的期次在下拉里无法分辨（下拉限宽 150px）
      · 三个日期必须是合法 ISO 日期（YYYY-MM-DD）
      · order_start <= order_end —— 反了则窗口为空，该期的报单永远查不到
      · arrival >= order_end —— 到货早于下单截止业务上不可能；且达成按**到货月**归属
        （见 Forecast.vue v116），错了会直接算错返利月
    ⚠️ 软规则（同名期次 / 与已有 open 期次窗口重叠）**故意不在此拦截**：前者只是显示难分辨、
      后者靠全站双口径归属已能缓解，二者都不该挡住用户建期次。前端以非阻塞提示呈现。
    """
    from datetime import date as _date
    name = (name or "").strip()
    if not name:
        raise ValueError("请填写期次名称")
    if len(name) > 80:
        raise ValueError("期次名称过长（最多 80 个字）")
    _ds = {}
    for _k, _lab in (("order_start", "下单开始"), ("order_end", "下单截止"), ("arrival", "预计到货")):
        _v = ({"order_start": order_start, "order_end": order_end, "arrival": arrival}[_k] or "").strip()
        if not _v:
            raise ValueError(f"请填写{_lab}日期")
        try:
            _ds[_k] = _date.fromisoformat(_v)
        except ValueError:
            raise ValueError(f"{_lab}日期格式不对（应为 2026-08-25 这样）")
    if _ds["order_start"] > _ds["order_end"]:
        raise ValueError(f"下单开始日期不能晚于下单截止日期（{_ds['order_start']} > {_ds['order_end']}）")
    if _ds["arrival"] < _ds["order_end"]:
        raise ValueError(f"预计到货日期不能早于下单截止日期（{_ds['arrival']} < {_ds['order_end']}）")
    return name


def forecast_period_update(pid, name=None, order_start=None, order_end=None, arrival=None):
    """修改期次名称 / 日期。**仅 open 期次可改**（closed 已定稿，改窗口会让历史口径漂移）。

    为什么必须存在：期次此前只有 create / close / delete 三条路径 —— 名字打错只能
    「关闭 → 删除」，而删除会**级联删掉该期次的全部报单/明细/审核定稿/付款/订单**且不可恢复。
    即「引导用户建期次」原先等于「引导一个不可逆操作」。本函数补上可逆路径。

    返回 {"changed": {字段: [旧值, 新值]}, "period": {...更新后的行...}}。
    changed 只含**真的变了**的字段（留痕铁律：只记真实变化，同值重提不留痕）。
    期次不存在 raise ValueError（端点转 404）；非 open raise ValueError（端点转 400）。
    """
    with get_db_tx() as db:
        _ensure_forecast_tables(db)
        row = db.execute("SELECT * FROM forecast_periods WHERE id=?", (pid,)).fetchone()
        if not row:
            raise ValueError("期次不存在或已删除")
        cur = dict(row)
        if (cur.get("status") or "open") != "open":
            raise ValueError("已关闭的期次不能修改（关闭即定稿）。如需调整请新建期次")
        # 缺省字段沿用现值 ⇒ 支持「只改名称」或「只改日期」
        _name = cur.get("name") or "" if name is None else name
        _os = (cur.get("order_start") or "") if order_start is None else order_start
        _oe = (cur.get("order_end") or "") if order_end is None else order_end
        # 旧表存的是 arrival_date；新表另有 arrival 别名的历史用法，按列存在性取
        _cols = {r[1] for r in db.execute("PRAGMA table_info(forecast_periods)")}
        _cur_arr = ""
        for _c in ("arrival_date", "arrival"):
            if _c in _cols and cur.get(_c):
                _cur_arr = cur.get(_c)
                break
        _ar = _cur_arr if arrival is None else arrival
        _name = period_validate(_name, _os, _oe, _ar)
        _os, _oe, _ar = _os.strip(), _oe.strip(), _ar.strip()
        changed = {}
        if _name != (cur.get("name") or ""):
            changed["name"] = [cur.get("name") or "", _name]
        _old_by_col = {"order_start": cur.get("order_start") or "",
                       "order_end": cur.get("order_end") or "",
                       "arrival": _cur_arr}
        for _k, _nv in (("order_start", _os), ("order_end", _oe), ("arrival", _ar)):
            if _nv != _old_by_col[_k]:
                changed[_k] = [_old_by_col[_k], _nv]
        if changed:
            db.execute("UPDATE forecast_periods SET name=?, order_start=?, order_end=?, arrival_date=? WHERE id=?",
                       (_name, _os, _oe, _ar, pid))
            # 旧库（v94 之前）带 NOT NULL 的 order_start_date / order_end_date 同步写，
            # 否则后续按旧列读取的路径会看到过期窗口（与 create 的双写同理）
            if "order_start_date" in _cols:
                db.execute("UPDATE forecast_periods SET order_start_date=?, order_end_date=? WHERE id=?",
                           (_os, _oe, pid))
        out = db.execute("SELECT * FROM forecast_periods WHERE id=?", (pid,)).fetchone()
        return {"changed": changed, "period": dict(out) if out else cur}


def forecast_period_prev_id(order_start, exclude_id=0):
    """找「上一期」—— 返回报单窗口在 `order_start` **之前**、且最近的那一期的 id；没有则 0。

    v273（2026-09-25）：新建期次自动沿用上一期商品清单时，需要知道「上一期是谁」。
    入口在 `routers/forecast.py::create_period`（手工新建）与 `scheduler.py::_auto_period_open`
    （到点自动建表），两条路都调本函数，**不各写一份**。

    🔴 锚点必须是 **`order_start`（业务时间序）**，**不能是 `id`**：
       期次的 id 是「创建顺序」，与「报单窗口的先后」不是同一个序 —— 先建 9/30 的期次、
       再补建 9/26 的期次，按 id 取「上一期」会拿到 9/30 那一期（**未来**），
       结果是「把未来的清单沿用到过去」。同族判据见 `topics/forecast-order-domain.md`
       的「归属键」一节：期次的语义键是窗口，不是 id。

    ⚠️ 严格 `<`（**不含相等**）：同一个 order_start 允许多期（自动建表用「报单日前一天~报单日」、
       手工建表常用「下单开始=下单截止=报单日」，两套窗口约定不同 —— v242 已记录过这个差异）。
       相等时无法判定谁在前 ⇒ **宁可不沿用**，交给用户显式点「复制」或空态行的「从上一期复制清单」。

    与 `forecast_period_copy`（源期次由用户显式指定）的分工见本文件 `forecast_period_copy` docstring。
    """
    try:
        _os = str(order_start or "").strip()
        _ex = int(exclude_id or 0)
    except (TypeError, ValueError):
        return 0
    if not _os:
        return 0
    with get_db() as db:
        row = db.execute(
            "SELECT id FROM forecast_periods WHERE order_start < ? AND id != ? "
            "ORDER BY order_start DESC, id DESC LIMIT 1",
            (_os, _ex)).fetchone()
    return int(row[0]) if row else 0


# ===================== v365 停单 → 期次自动新建的排除依据 =====================
#
# 用户在「到货节奏」里把某天点成「不到货」（v364 的 rebate_arrival_skips）之后，
# 除了少一次到货，**那天对应的报单期次也不该再被自动建出来**。
# 本函数是「停单日」的**唯一读取口** —— 三个调用方（调度器 / 报单自动化预览 /
# 智能报单表预览）共用，避免各写一份 SQL 后口径漂移。
def rebate_arrival_skip_map(conn=None, d_from=None, d_to=None):
    """读全部品牌规则的「不到货」停单日 → {rule_id(int): set("YYYY-MM-DD")}。

    🔴 **为什么返回「日期集合」而不是「哪个月」**：期次的排除判定是
       `期次.arrival_date == 停单日` 的**等值比较**，而期次的**报单窗口可能落在上一个月**
       —— 生产实证：到货 10-05 的期次，报单日是 10-01、开放 9/30。
       所以绝不能按「期次所在月」去查停单记录，只能把相关月份的停单日**并成日期集合**。

    d_from / d_to：可选日期范围（含边界）。给了就只返回该范围内的停单日
      （按月粗过滤 —— 每条记录自带 `ym`，够用且不必解析全表）；
      不给 = 全量（调用方自己保证 horizon 够大）。
    ⚠️ 表不存在（老租户库尚未跑启动补丁）⇒ 返回 `{}`，**不抛** ——
       少一张表不该让「报单自动化」整页 500（与 `rebate_rules._load_month_skips` 同族）。
    """
    yms = None
    try:
        if d_from or d_to:
            _a, _b = str(d_from or d_to), str(d_to or d_from)
            if _a > _b:
                _a, _b = _b, _a
            yms = set()
            _y, _m = int(_a[:4]), int(_a[5:7])
            _ey, _em = int(_b[:4]), int(_b[5:7])
            while (_y, _m) <= (_ey, _em):
                yms.add("%04d-%02d" % (_y, _m))
                _y, _m = (_y + 1, 1) if _m == 12 else (_y, _m + 1)
    except (TypeError, ValueError, IndexError):
        yms = None

    try:
        if conn is not None:
            rows = conn.execute(
                "SELECT rule_id, ym, skip_dates FROM rebate_arrival_skips").fetchall()
        else:
            with get_db() as _db:
                rows = _db.execute(
                    "SELECT rule_id, ym, skip_dates FROM rebate_arrival_skips").fetchall()
    except Exception:
        return {}

    out = {}
    for r in rows:
        try:
            rid = int(r[0])
        except (TypeError, ValueError):
            continue
        if rid <= 0:
            continue
        _ym = str(r[1] or "")
        if yms is not None and _ym not in yms:
            continue
        for it in str(r[2] or "").split(","):
            it = it.strip()
            if not it or (yms is not None and it[:7] not in yms):
                continue
            try:                       # 只收合法 ISO 日期，脏值直接跳过（不会误伤真实排程）
                datetime.strptime(it[:10], "%Y-%m-%d")
            except (TypeError, ValueError):
                continue
            out.setdefault(rid, set()).add(it[:10])
    return out


def forecast_period_create(name, order_start, order_end, arrival):
    """创建预报订货周期。语义：order_start~order_end 为填报窗口，arrival 为到货日。
    双写旧列(order_start_date等)：生产库存在 v94 之前的旧表，那些列带 NOT NULL
    约束，只写新列会 IntegrityError。旧列在新库不存在，故按列存在性动态拼 SQL。
    """
    # 2026-09-16：硬校验下沉到 db 层（唯一实现，与 forecast_period_update 共用）。
    # 此前 POST /periods 后端**零业务校验**，只有前端那句「四个字段非空」的 toast ——
    # 直接调接口就能建出「到货早于下单截止」这种必然算错返利月的期次。
    name = period_validate(name, order_start, order_end, arrival)
    order_start, order_end, arrival = order_start.strip(), order_end.strip(), arrival.strip()
    with get_db_tx() as db:
        cols = {r[1] for r in db.execute("PRAGMA table_info(forecast_periods)")}
        if 'order_start_date' in cols:
            cur = db.execute(
                "INSERT INTO forecast_periods (name,order_start,order_end,arrival_date,order_start_date,order_end_date) "
                "VALUES (?,?,?,?,?,?)",
                (name, order_start, order_end, arrival, order_start, order_end))
        else:
            cur = db.execute(
                "INSERT INTO forecast_periods (name,order_start,order_end,arrival_date) VALUES (?,?,?,?)",
                (name, order_start, order_end, arrival))
        return cur.lastrowid


def _period_copy_products(db, src_pid, dst_pid):
    """把源期次的**商品清单**复制到目标期次 —— **唯一实现**，copy 与 seed 共用。

    🔴 **只带 `forecast_import_products` 这一个桶**。刻意**不碰**报单明细 / 加单 / 定稿 / 付款：
    加单（`routers/forecast_submissions.py:462`）与定稿（`erp_db.py:15200`）的归属键是
    `(period_start, period_end)` **日期窗口**，不是期次 id —— 复制过来会让两期**共用同一份**
    数据（窗口重叠即串期），而且同屏不报任何错。客户列 / 户头（`report_mapping`）是全局的，
    本来就不按期次，无需复制。

    幂等：目标已有同 (period_id, product_id) 的行则跳过（INSERT OR IGNORE），
    不覆盖用户在目标期次里已改过的登记。
    返回 {"added", "src_count"}；`src_count - added` 即被跳过的条数。
    """
    _cols = {r[1] for r in db.execute("PRAGMA table_info(forecast_import_products)")}
    # origin 列由 v184 迁移补上；这里仍按存在性拼 SQL，保证迁移未跑到的库也能复制（只是无来源标记）
    _has_origin = "origin" in _cols
    _ico = ", origin" if _has_origin else ""
    _icv = ", 'seeded'" if _has_origin else ""
    # v202（2026-09-19）：**模板行序必须一起带过来**。
    #   🔴 不带的话，「从上一期复制清单」得到的是一批 sort_no=0 的行 ⇒ 前端只能把它们排在
    #      「有导入序的商品」之后，于是**复制过来的清单整体沉到最底部**、且互相之间没有顺序
    #      （退化成 id 序）—— 用户看到的是「照上一期建的这期，商品顺序全乱」。
    #   同样按存在性拼 SQL：迁移未跑到的库照常能复制（只是无顺序，行为同改动前）。
    _has_sort = "sort_no" in _cols
    _sco = ", sort_no" if _has_sort else ""
    _scv = ", sort_no" if _has_sort else ""
    _before = db.execute(
        "SELECT COUNT(*) FROM forecast_import_products WHERE period_id=?", (dst_pid,)
    ).fetchone()[0]
    _src_n = db.execute(
        "SELECT COUNT(*) FROM forecast_import_products WHERE period_id=?", (src_pid,)
    ).fetchone()[0]
    # ⚠️ imported_at / imported_by **原样带过**：它们记的是「这批清单最初是谁、什么时候导进来的」，
    #    复制不改变这个事实，而 origin='seeded' 已标明「在本期它不是直接导入的」——
    #    保留原值才能回答「这期的品最初从哪来」。
    db.execute(
        "INSERT OR IGNORE INTO forecast_import_products "
        "(period_id, order_date, product_id, product_name, barcode, action, "
        " imported_at, imported_by, source_file" + _ico + _sco + ") "
        "SELECT ?, order_date, product_id, product_name, barcode, action, "
        "       imported_at, imported_by, source_file" + _icv + _scv + " "
        "FROM forecast_import_products WHERE period_id=?",
        (dst_pid, src_pid),
    )
    _after = db.execute(
        "SELECT COUNT(*) FROM forecast_import_products WHERE period_id=?", (dst_pid,)
    ).fetchone()[0]
    return {"added": int(_after - _before), "src_count": int(_src_n or 0)}


def forecast_period_copy(src_pid, name, order_start, order_end, arrival):
    """复制期次：**新建**一个期次 + 把源期次的商品清单带过来。
    返回 {"id", "name", "copied", "src_id", "src_name", "src_status"}。

    与 `forecast_period_seed` 的分工：
    - `copy` = **建新期次**（入口：往期预报列表每行的「复制」）
    - `seed` = 往**已存在**的期次里填清单（入口：空期次的「从上一期复制清单」）

    源**可以是已关闭期次**（不限 open）—— 「照着满意的那一期建下一期」正是主场景。
    硬校验复用 `period_validate`（唯一实现），前端不再写第二份。
    """
    name = period_validate(name, order_start, order_end, arrival)
    order_start, order_end, arrival = order_start.strip(), order_end.strip(), arrival.strip()
    with get_db_tx() as db:
        _ensure_forecast_tables(db)
        _row = db.execute("SELECT * FROM forecast_periods WHERE id=?", (src_pid,)).fetchone()
        if not _row:
            raise ValueError("源期次不存在或已删除")
        _src = dict(_row)
        # 与 forecast_period_create 同构：v94 之前的旧表 order_start_date/order_end_date 带
        # NOT NULL，只写新列会 IntegrityError，故按列存在性双写
        _cols = {r[1] for r in db.execute("PRAGMA table_info(forecast_periods)")}
        if "order_start_date" in _cols:
            _cur = db.execute(
                "INSERT INTO forecast_periods (name,order_start,order_end,arrival_date,order_start_date,order_end_date) "
                "VALUES (?,?,?,?,?,?)",
                (name, order_start, order_end, arrival, order_start, order_end))
        else:
            _cur = db.execute(
                "INSERT INTO forecast_periods (name,order_start,order_end,arrival_date) VALUES (?,?,?,?)",
                (name, order_start, order_end, arrival))
        _npid = _cur.lastrowid
        _res = _period_copy_products(db, src_pid, _npid)
        return {"id": _npid, "name": name, "copied": _res["added"],
                "src_id": int(src_pid), "src_name": _src.get("name") or "",
                "src_status": _src.get("status") or "open"}


def forecast_period_seed(target_pid, src_pid):
    """把源期次的商品清单**填入**已存在的目标期次（不清空目标已有内容）。
    返回 {"added", "skipped", "before", "after", "target_*", "src_*"}。

    ⚠️ **不要求目标为空**：目标只要是 open 期次即可。目标里已有的登记按
    (period_id, product_id) 幂等跳过 —— 同一条码不会被复制成第二行，也不会覆盖
    用户在目标期次里改过的登记。已关闭期次拒绝写入（关闭即定稿）。
    """
    _t = int(target_pid or 0)
    _s = int(src_pid or 0)
    if _t <= 0 or _s <= 0:
        raise ValueError("期次参数不对")
    if _t == _s:
        raise ValueError("源期次与目标期次是同一个")
    with get_db_tx() as db:
        _ensure_forecast_tables(db)
        _trow = db.execute("SELECT * FROM forecast_periods WHERE id=?", (_t,)).fetchone()
        if not _trow:
            raise ValueError("目标期次不存在或已删除")
        _srow = db.execute("SELECT * FROM forecast_periods WHERE id=?", (_s,)).fetchone()
        if not _srow:
            raise ValueError("源期次不存在或已删除")
        _t = dict(_trow)
        _s = dict(_srow)
        if (_t.get("status") or "open") != "open":
            raise ValueError("已关闭的期次不能填入清单（关闭即定稿）。如需调整请新建期次")
        _before = db.execute(
            "SELECT COUNT(*) FROM forecast_import_products WHERE period_id=?", (int(_t["id"]),)
        ).fetchone()[0]
        _res = _period_copy_products(db, int(_s["id"]), int(_t["id"]))
        # v282（2026-09-26）：**多带一个 `src_count` 出来**。
        #   🔴 为什么必须有它：调用方要区分两种「added=0」——
        #      ① 源期次自己有 N 个商品，但目标已有同 (period_id, product_id) ⇒ 全被幂等跳过（正常）
        #      ② **源期次自己就是 0 个商品** ⇒ 复制过去也是空的（**缺陷，且会逐期传染**）
        #   而原返回值里 `skipped = src_count - added`，两 case 下 **skipped 都是 0**
        #   ⇒ 从 `added`/`skipped` 根本分辨不出来。v273 的自动沿用正是踩在这里：
        #     生产 09-26 建 #19 时沿用了一个空期次，打印「0 个商品」、零告警，
        #     直到用户打开报单页发现全白。详见 forecast-order-domain.md §沿用上一期。
        return {"added": _res["added"], "skipped": max(0, _res["src_count"] - _res["added"]),
                "src_count": int(_res["src_count"] or 0),
                "before": int(_before or 0),
                "after": int(_before or 0) + _res["added"],
                "target_id": int(_t["id"]), "target_name": _t.get("name") or "",
                "src_id": int(_s["id"]), "src_name": _s.get("name") or ""}


def forecast_period_list():
    with get_db() as db:
        return [dict(r) for r in db.execute("SELECT * FROM forecast_periods ORDER BY id DESC").fetchall()]


# ---------------------------------------------------------------------------
# v213-B1（2026-09-20）：**期次归属条件** —— 唯一实现。
# ---------------------------------------------------------------------------
# 规则只有一条：`period_id` 精确命中；`period_id=0` 的历史行（早期导入/小程序）回退日期窗口。
# 2026-09-15 引入，用来修「两个期次窗口重叠时同一笔报单被相邻两期同时计入 / 保存 A 期把
# B 期的数据一并删掉」。当时在**多处各写了一份字符串**，风险是「改一处、忘一处」——
# 而同一条规则一旦分叉，就会出现「汇总算的是期次 9、行底却按另一个窗口」这类同屏打架。
# 现收敛为**唯一来源**：需要哪个表别名就传哪个（`forecast_period_scope_sql("s")`）。
#
# ⚠️ 已知的**同形副本**（不同形状/角色，本轮**未动**，属后续统一项）：
#     · erp_db.py:15753  `s.period_id=p.id OR (... BETWEEN p.order_start AND p.order_end)`（关联子查询形）
#     · datasource_adapter.py  `role!='导入' AND (...)`（外发口径，多一个角色过滤）
#     · scheduler.py 催单归属、routers/forecast_config.py（别名 fs）、
#       routers/forecast_submissions.py:201（单日期变体 `(period_id=0 AND order_date=?)`）
def forecast_period_scope_sql(alias=""):
    """期次归属条件的 SQL 片段（占位符顺序：pid, window_start, window_end）。

    alias：表别名（如 "s" / "r" / "fs"），空串表示不带别名。
    """
    p = (alias + ".") if alias else ""
    return "(%speriod_id=? OR (%speriod_id=0 AND %sorder_date BETWEEN ? AND ?))" % (p, p, p)


# 不带别名（用于 `forecast_submissions` 单表上下文）
FORECAST_PERIOD_SCOPE_SQL = forecast_period_scope_sql()
# 带角色前缀：本期『导入』数据的作用域 —— 幂等清理与内容指纹共用（见各自注释）。
# v741：『主管调整』（减单负数行）与导入行同域，必须一起清、一起进指纹。
FORECAST_IMPORT_SCOPE_SQL = "role IN ('导入','主管调整') AND " + FORECAST_PERIOD_SCOPE_SQL


# v215（2026-09-20）：**本期清单**的商品 id 集合 —— 报单侧的唯一判据来源。
# 用户拍板原话：「报单商品的判定基准不是商品档案，因为商品档案中的商品并非每一个
# 都需要报单（例如很多赠品就不需要报单）。因此应该以每一期次内实际包含哪些商品
# 作为报单的基准。」
# 🔴 为什么要收敛成一个函数：这条判据同时被三处需要 ——
#   ① 小程序商品铺开（`routers/data.py::fill_search_products`）
#   ② 报单提交时的本期校验（`routers/forecast_submissions.py`）
#   ③ Web 端汇总表的导入登记行底（本文件 `forecast_submission_summary`）
#   三处各写一份 SQL 就是「同一规则三处实现」⇒ 迟早出现「小程序说这个品属于本期、
#   提交时说不属于」的自相矛盾。故一律走这里 + `forecast_period_scope_sql`。
def forecast_period_product_ids(period_id):
    """返回本期清单（`forecast_import_products`）内的商品 id 集合（`set[int]`）。

    ⚠️ 返回**空集合**有三种成因，语义完全不同，**调用方必须自己决定怎么处理**：
      · 该期确实还没登记任何商品（用户还没导入模板）；
      · 期次不存在 / 期次号非法；
      · 登记表还没建（存量租户库，首次请求走 `_ensure_forecast_tables` 才建）。
      三者都**不该**被解释成「所有商品都不属于本期」—— 调用方通常应据此
      **fail-open（不过滤）**，否则「还没配清单的期次」会突然完全报不了单，
      一次改动就打断在用的流程。
    """
    try:
        pid = int(period_id or 0)
    except (TypeError, ValueError):
        return set()
    if pid <= 0:
        return set()
    p = forecast_period_get(pid) or {}
    ws = p.get("order_start") or ""
    we = p.get("order_end") or ""
    if ws and we:
        cond, args = forecast_period_scope_sql("r"), (pid, ws, we)
    else:
        # 期次查不到窗口：退化为单口径精确命中。**绝不退化成"全表"** ——
        # 那样一次期次数据异常就会把全部商品档案当成"本期清单"，判据形同失效。
        cond, args = "r.period_id=?", (pid,)
    try:
        with get_db() as db:
            return {int(r[0]) for r in db.execute(
                "SELECT r.product_id FROM forecast_import_products r "
                "WHERE (%s) AND r.product_id>0" % cond, args).fetchall()}
    except Exception:
        # 登记表是增益信息：查不到不得让上游（报单/铺开）失败
        return set()


def forecast_order_board():
    """预报订单历史看板：按期次聚合报单人数、总件数、下单金额、是否定稿。

    兼容「无期次、按报单日期直存」的真实使用场景：当期预报在未选期次时会自动
    生成合成期次『今日报单』(order_start=order_end=今天)，保存即写入该日期的报单，
    而不会落库 forecast_periods 记录。因此看板在按期次聚合之外，还要把未被任何
    期次区间覆盖的报单日期补成一行，保证保存过的预报单一定能在往期预报里看到。
    """
    with get_db() as db:
        _ensure_forecast_tables(db)
        db.commit()

        # v355：整个看板**共用一个「今天」** —— 逐行各取一次会在跨零点的那一瞬间让
        # 同一张表里两行按不同日期判定「过期」，而这两行会被拿去讲同一句话。
        from datetime import date as _date
        _today = _date.today().isoformat()

        def _agg(start, end, single=False, pid=0):
            # 2026-09-15：有期次号时按期次精确归属（period_id=0 的历史行回退日期区间），
            # 与 /summary、催单、首页 TOP3 统一同一口径。原实现纯按 order_date BETWEEN ——
            # 期次窗口重叠时同一笔报单会被**相邻两期同时计入**，看板两行的件数/金额都虚高。
            if pid > 0:
                cond = forecast_period_scope_sql("s")
                params = (pid, start, end)
            elif single:
                cond, params = "s.order_date = ?", (start,)
            else:
                cond, params = "s.order_date BETWEEN ? AND ?", (start, end)
            agg = db.execute(
                "SELECT COUNT(DISTINCT s.store_name) AS reporter_count, "
                "SUM(i.quantity) AS total_qty, SUM(i.amount) AS total_amount, "
                "COUNT(DISTINCT s.id) AS submission_count "
                "FROM forecast_submission_items i JOIN forecast_submissions s ON i.submission_id=s.id "
                # v199（2026-09-19）口径对齐：原写 `s.status != 'rejected'`，漏了 recalled。
                #   本函数的注释（见上方 docstring）自述「与 /summary、催单、首页 TOP3 **统一同一口径**」,
                #   而 summary 早就用 `NOT IN ('rejected','recalled')` ⇒ 撤回的报单在汇总表里不算，
                #   在这里却仍算进「报单人数 / 总件数 / 提交数」——**同一期在两张页面上数字对不上**。
                #   这是「实现没达成注释宣称的目标」的典型：注释对、代码漏。
                #   ⚠️ 影响面（实测 tenant_1，隔离副本回放）：recalled 仅 1 条（id=187 永诺旗舰店/期次 9/2 明细/29 件/¥0）。
                #      对齐后**往期看板**期次 9：件数 33 → 4、提交数 2 → 1；
                #      「报单人数」**不变**（仍为 1）—— 因为同一客户另有 1 条 pending 提交，
                #      COUNT(DISTINCT store_name) 不因少一条提交而变。这正是 summary 早已采用的口径
                #      （改前两个页面对同一期给出不同件数，改后一致）。
                f"WHERE {cond} AND s.status NOT IN ('rejected','recalled')",
                params,
            ).fetchone()
            agg = dict(agg) if agg else {"reporter_count": 0, "total_qty": 0, "total_amount": 0, "submission_count": 0}
            # 🔴 v319（2026-09-29）**删掉**这里原来的「定稿」判据：
            #     finalized = SELECT 1 FROM forecast_audit_decisions WHERE period_start=? AND period_end=?
            #   它是**恒假判据** —— 读端读的那张表，写入方早已废弃：
            #     · 生产实测 `tenant_1.forecast_audit_decisions` **0 行**，而 5 个期次 status 全是 closed；
            #     · 唯一写它的 `forecast_audit.py::adopt`（"补货建议台"确认）界面自己写着
            #       「历史流程，仅用于追溯」—— 新流程（关闭期次 = 定稿）根本不写它。
            #   ⇒ 历史页「定稿」列**永远显示"未定稿"**，而同屏「状态」列写着「已关闭」——
            #     两列说的是同一件事（关闭 = 定稿），却给出相反结论。用户原话即此矛盾。
            #   附带同族病灶：即便那张表有行，判据键用的是**可改的窗口**（期次改一次 order_end
            #     就永久失配）—— v279 已在加单归属上把它改成 `period_id`，这里漏改。
            #   ⇒ 正解：**定稿就是 `status='closed'`**（全站唯一口径，见 close_period 的 docstring），
            #     由调用方按 `p["status"]` 直接判定，不再绕第三张表。
            return agg

        periods = [dict(r) for r in db.execute("SELECT * FROM forecast_periods ORDER BY id DESC").fetchall()]
        # v184：本期**商品清单条数**（导入登记行数）。用途：复制弹窗要提前告诉用户
        # 「将带过来 N 个商品（不含报单数量 / 加单 / 定稿）」—— 没有这个数就只能等复制完再报。
        # 一条 GROUP BY 覆盖全部期次，**不是**每行一次 COUNT。
        _imp_cnt = {}
        try:
            for _pid, _n in db.execute(
                "SELECT period_id, COUNT(*) FROM forecast_import_products GROUP BY period_id"
            ).fetchall():
                _imp_cnt[int(_pid or 0)] = int(_n or 0)
        except Exception:
            pass  # 表还没建（全新库）⇒ 一律 0，不影响看板
        # v319：本期**加单/减单分配行数**（`forecast_extra_alloc`）。用途：历史页要判断
        #   「这一期到底有没有需要推给业务员的加/减单明细」—— 没有分配行就不该显示
        #   「尚未推送」和推送按钮（那是**假待办**，会让经理去点一个没内容的动作）。
        #   与 _imp_cnt 同手法：一条 GROUP BY 覆盖全部期次，不是每行一次 COUNT。
        _alloc_cnt = {}
        try:
            for _apid, _an in db.execute(
                "SELECT period_id, COUNT(*) FROM forecast_extra_alloc GROUP BY period_id"
            ).fetchall():
                _alloc_cnt[int(_apid or 0)] = int(_an or 0)
        except Exception:
            pass  # 表还没建（v277 之前的库）⇒ 一律 0
        out = []
        covered = []  # [(start, end)] 已被真实期次覆盖的日期区间
        for p in periods:
            start = p.get("order_start") or ""
            end = p.get("order_end") or ""
            if start and end:
                agg = _agg(start, end, pid=int(p.get("id") or 0))
                covered.append((start, end))
            else:
                agg = {"reporter_count": 0, "total_qty": 0, "total_amount": 0, "submission_count": 0}
            _st = (p.get("status") or "open")
            out.append({
                "id": p["id"],
                "name": p.get("name", ""),
                "order_start": start,
                "order_end": end,
                "arrival_date": p.get("arrival_date", ""),
                "status": _st,
                "created_at": p.get("created_at", ""),
                "reporter_count": int(agg.get("reporter_count") or 0),
                "total_qty": float(agg.get("total_qty") or 0),
                "total_amount": float(agg.get("total_amount") or 0),
                "has_data": int(agg.get("submission_count") or 0) > 0,
                # v319：「定稿」= `status == 'closed'`（**全站唯一口径**，与 close_period 的
                #   docstring 同源）。原实现读 `forecast_audit_decisions`（恒 0 行的废弃表）
                #   ⇒ 此列**永远显示"未定稿"**，与同屏「状态」列的「已关闭」自相矛盾。详见 _agg 注释。
                "finalized": _st == "closed",
                # v319 留痕三列 + 推送标记：历史页要能回答「这期谁在何时怎么定的稿」
                #   和「加单/减单通知推出去没有」——自动关单不发通知，故需要单独的推送动作。
                "closed_at": p.get("closed_at") or "",
                "closed_by": p.get("closed_by") or "",
                "closed_mode": p.get("closed_mode") or "",
                "reopened_at": p.get("reopened_at") or "",
                "alloc_pushed_at": p.get("alloc_pushed_at") or "",
                "alloc_count": _alloc_cnt.get(int(p.get("id") or 0), 0),
                "imported_count": _imp_cnt.get(int(p.get("id") or 0), 0),
                # v355（2026-10-01）：「过期未关」—— 报单窗口已过却仍挂在「进行中」。
                #   🔴 这一行就是 v354 那个故障的**读侧**：僵尸期次会挡住自动建表创建下一期，
                #      而它在界面上此前显示为**绿色「进行中」**，与"其实报不了单"正好相反。
                #   判据 = `forecast_period_stale_open`（与报单硬锁同源，含 id>0 护栏）。
                "stale_open": forecast_period_stale_open(p, _today),
            })
        # 未被任何期次区间覆盖的报单日期 -> 合成行，保证保存过的单一定可见
        syn_id = -1
        for (d,) in db.execute(
            "SELECT DISTINCT order_date FROM forecast_submissions ORDER BY order_date DESC"
        ).fetchall():
            if any(s <= d <= e for (s, e) in covered):
                continue
            agg = _agg(d, d, single=True)
            if int(agg.get("submission_count") or 0) == 0:
                continue
            out.append({
                "id": syn_id,
                "name": f"{d} 报单",
                "order_start": d,
                "order_end": d,
                "arrival_date": "",
                "status": "open",
                "created_at": d,
                "reporter_count": int(agg.get("reporter_count") or 0),
                "total_qty": float(agg.get("total_qty") or 0),
                "total_amount": float(agg.get("total_amount") or 0),
                "has_data": True,
                # 合成行没有 forecast_periods 记录 ⇒ 无从「关闭」，也就永远不是定稿态。
                # （原实现读空表 ⇒ 恰好也是 False ⇒ 此处**行为不变**，只是把"碰巧对"变成"如实"。）
                "finalized": False,
                "closed_at": "", "closed_by": "", "closed_mode": "",
                "reopened_at": "", "alloc_pushed_at": "",
                "alloc_count": 0,
                "imported_count": 0,  # 合成期次没有 forecast_periods 记录，也就没有按期次登记的清单
                # v355：合成行的 `status` 硬编码 'open'、`order_end` 是那个**历史**报单日期
                #   ⇒ 只看日期必然命中「过期」。但它不是期次（没有 forecast_periods 记录），
                #   「关闭」对它无从谈起，也永远不会挡住自动建表 ⇒ 恒 False。
                #   （`forecast_period_stale_open` 内的 id>0 护栏是同一件事的第二道保险。）
                "stale_open": False,
            })
            syn_id -= 1
        out.sort(key=lambda x: (x.get("order_start") or ""), reverse=True)
        return out


def forecast_period_current():
    """当前进行中的期次：优先「今天落在报单窗口内」的；没有再回退「最新创建的 open 期次」。

    2026-09-07 修复：原实现为 `ORDER BY id DESC` 取 id 最大的 open 期次。当多个期次同时
    status='open'（含窗口已过但未关闭的旧期次）时，会选中「id 最大但窗口已过」的那期，
    导致 Web 端汇总表默认打开错误区间 —— 典型症状：小程序报单后 Web 端看不到数据。
    根因是两端口径不一致：小程序提交取「今天在窗口内」期次的 order_start 落 order_date
    （见 routers/forecast_submissions.py），而 Web 端默认期次却按 id 最大取，可能取到
    另一期，按其窗口查询自然查不到。
    现与小程序 forecast_open_periods() 对齐：先取今天在窗口内的，再回退最新 open。
    """
    with get_db() as db:
        from datetime import date as _date
        today = _date.today().isoformat()
        r = db.execute(
            "SELECT * FROM forecast_periods WHERE status='open' AND order_start<=? AND order_end>=? "
            "ORDER BY order_start DESC LIMIT 1",
            (today, today),
        ).fetchone()
        if not r:
            r = db.execute(
                "SELECT * FROM forecast_periods WHERE status='open' ORDER BY id DESC LIMIT 1"
            ).fetchone()
        return dict(r) if r else None


def forecast_period_default():
    """Web 端期次列表的「默认选中」期次（2026-09-12 新增，**仅展示用**）。

    为什么另开一个函数而不是放宽 forecast_period_current()：
    后者语义严格（只认 open 期次），且被**写路径**依赖 ——
      · routers/forecast_audit.py:449 未指定期次时自动挂靠当前期次（落 period_id）
      · hermes_core.py:711 open_forecast_period 工具
    放宽它会静默改变这两处的落库归属，属破坏性变更。故保持原函数不变，
    本函数只在它返回空时**再兜底**，供 GET /api/forecast/periods 的 current 字段使用。

    触发场景：所有期次都已 closed（测试期 / 管理员忘记新建下一期）。
    原行为 current=None → 前端 curPeriod=0 → 汇总表兜底成「今天~今天」→ 打开即空表，
    被误判成「小程序报上来的数据没同步」。典型症状就是 2026-09-12 那次核查。

    兜底顺序：
      1) forecast_period_current()：今天在报单窗口内的 open → 最新 open（保持原口径）
      2) 最近**有报单数据**的期次：关闭状态下也能让默认视图看到历史数据
      3) 最新创建的期次（不限状态）：万不得已也有个默认项，避免空表
    """
    r = forecast_period_current()
    if r:
        return r
    with get_db() as db:
        try:
            # 2026-09-15：优先按期次精确归属（period_id=0 的历史行回退日期区间），
            # 避免窗口重叠时把「其实属于别期」的报单误当成本期有数据。
            row = db.execute(
                "SELECT p.* FROM forecast_periods p WHERE EXISTS ("
                "  SELECT 1 FROM forecast_submissions s"
                "  WHERE (s.period_id=p.id OR (s.period_id=0 AND s.order_date BETWEEN p.order_start AND p.order_end))"
                "    AND s.status NOT IN ('rejected','recalled')"
                ") ORDER BY p.order_start DESC, p.id DESC LIMIT 1"
            ).fetchone()
        except Exception:
            # 兜底查询失败（老库缺 forecast_submissions 表）不应连累接口，降级到下一档
            row = None
        if not row:
            row = db.execute(
                "SELECT * FROM forecast_periods ORDER BY id DESC LIMIT 1"
            ).fetchone()
        return dict(row) if row else None


def forecast_period_close(pid, by="", mode="manual"):
    """关闭期次（= 定稿）。返回是否**真的发生了 open → closed 的状态跃迁**。

    🔴 为什么要把这个布尔返回出来（v318）：
       「关闭期次」现在是**加单/减单通知的唯一推送出口**（原先挂在 `save-matrix` 上）。
       通知必须在「真的从 open 变成 closed」时发 —— 否则重复点「确认关闭」（或前端重试、
       两个经理同时点）会把同一件事推两遍，收件箱被刷屏。
       ⇒ 判据必须是**状态跃迁**，不是「接口被调了一次」。返回 False（本来就已 closed）
         时调用方**不推送**；这正是幂等性所在，而不是靠通知层的 24 小时去重窗口兜底
         （那个窗口会把「关→重开→再关」这第二次**真·定稿**也一起折叠掉）。

    ⚠️ 返回 False 的两种情况（都不报错、都幂等）：期次不存在 / 本来就已经是 closed。
       调用方若需要区分，自行先查 `forecast_period_get(pid)`。

    🆕 v319（2026-09-29）：落「谁关的 / 几点关的 / 怎么关的」三列（见 v319 迁移注释）。
       `by`   —— 操作人显示名；自动关单传 '系统'。
       `mode` —— 'manual'（人在界面点「确定定稿」）| 'auto'（**到点**自动关单）|
                 'auto_reap'（v355：窗口**已过**却仍是 open ⇒ 自愈回收，见
                 `scheduler._reap_stale_open_periods`）。
                 🔴 后两者都无人操作、`closed_by` 都是「系统」，**只有 mode 分得清**
                    「到点正常关的」与「过期被回收的」⇒ 界面（`ForecastHistory.closeHint`）
                    据此给出不同解释，两处必须同批改、不可只改一侧。
       🔴 两处调用方**必须如实传** `mode`：它决定界面怎么解释这一期，也决定要不要提示
          「加单通知尚未推送」—— 自动关单**不发通知**（不经端点、没有操作人），
          所以那些期次的 `alloc_pushed_at` 会停在空串，由人确认后再推。
       ⚠️ 留痕**只在真跃迁（open→closed）时写**：重复点「确认关闭」不该把 `closed_at`
          刷新成最后一次点击的时刻，更不该把 `closed_by` 改成最后一个点的人
          （原实现无条件 UPDATE，值相同所以看不出问题；一旦这几列有值就会立刻变成缺陷）。
    """
    with get_db_tx() as db:
        row = db.execute("SELECT status FROM forecast_periods WHERE id=?", (pid,)).fetchone()
        if not row:
            return False
        was = (dict(row).get("status") or "open")
        if was == "closed":
            return False                     # 幂等：不动 status，也不刷新留痕
        db.execute(
            "UPDATE forecast_periods SET status='closed', closed_at=?, closed_by=?, closed_mode=? "
            "WHERE id=?",
            (datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
             str(by or ""), str(mode or "manual"), pid))
        return True


def forecast_period_mark_alloc_pushed(pid):
    """v319：记下「本期加单/减单通知已推送」的时刻（`alloc_pushed_at`）。

    🔴 为什么需要它：v318 把推送出口定在「关闭期次」端点，但**生产上期次的关闭主要来自
       自动关单**（`scheduler._auto_period_close` 直调 db 层、不经端点、没有操作人）
       ⇒ 那些期次的加单/减单通知**一条都没发**（实测 2026-09-29 期次 #21 即如此），
       而界面上完全看不出来 —— 经理以为"已经通知下去了"。
       ⇒ 现在：自动关单只落 `closed_mode='auto'`，`alloc_pushed_at` 保持空；
          历史页对「已关闭 + 有加单分配 + 尚未推送」的期次显示「尚未推送」+ 手动推送按钮，
          **由人确认那一次才真正发出去**（用户 2026-09-29 拍板）。

    ⚠️ 与 `closed_at` 是**两件事**：关闭是状态、推送是动作。自动关单改了状态但没做动作，
       所以不能拿 `closed_at` 当"已推送"的判据（这正是本条要解决的静默）。

    返回：是否写成功（期次不存在 ⇒ False）。
    """
    with get_db_tx() as db:
        row = db.execute("SELECT id FROM forecast_periods WHERE id=?", (pid,)).fetchone()
        if not row:
            return False
        db.execute("UPDATE forecast_periods SET alloc_pushed_at=? WHERE id=?",
                   (datetime.now().strftime("%Y-%m-%d %H:%M:%S"), pid))
        return True


def forecast_period_reopen(pid, mode="full"):
    """重开已关闭的期次 —— 关闭的**唯一**补救路径（v219）。v319 拆成两个语义。

    为什么必须有（缺口③）：`forecast_period_close` 是**单向**的，而
    `forecast_period_delete` 只接受已关闭期次（open 期次禁止删除）⇒
    **关闭一旦点下，此前没有任何路径能回到可编辑状态**：误点一次即永久锁死，
    且同屏不报任何错。补上本函数后「关闭 = 定稿」才是可逆操作。

    🔴 v319（2026-09-29，用户拍板）：**一个动作拆成两个**。
    病根：v219 的「重开」同时做了两件性质完全不同的事 ——
      ① 让**授权角色**能修这一期的数（编辑解锁）
      ② 让**销售的小程序**重新看到这一期、继续报单（报单通道重开）
    而真实场景里绝大多数只要 ①（**改一个错数**），却被迫把 ② 一起打开：
    老板以为只是「改个历史数」，实际把报单通道重新开了。
    v305 的「授权改单」(`allow_closed`) 本是为绕开这点补的，但它在界面上**没有对应的动作** ——
    用户看不到「我要改这期」这个按钮，仍然只能去点「重开」。⇒ 现在落成两个入口：

      · `mode='unlock'`（**解锁编辑**）—— 只写 `reopened_at`，`status` **保持 closed**。
        销售照旧报不了单（后台写入口的 `status!='open'` 闸不动），授权角色可经 v305 通道改数。
        **副作用最小**，「我只要改个数」的正确选择。
      · `mode='full'`（**恢复报单**）—— 写 `reopened_at` + `status='open'`。
        ⚠️ 销售的小程序报单通道**重新打开**，与 v219 行为完全一致（旧调用方不传 mode ⇒ 默认这个）。

    🔴 两个 mode 都写 `reopened_at` —— 它是**自动关单的豁免键**（见 v319 迁移注释）。
       语义 = 「人已经把这期拿回来处理过，自动路径别插手」。没有它，`full` 重开会在
       2~5 分钟内被调度器重新关掉（生产 2026-09-27 实测两次）。

    ⚠️ **只对已关闭期次落 `reopened_at`**：若期次本来就是 `open`，它天然可编辑、
       无需豁免 —— 此时写进去会种下「本期永不被自动关单」的静默副作用
       （用户点了个看起来无害的按钮，结果这一期再也不会自动关）。⇒ 已 open 时只返回 True。

    ⚠️ 语义边界：重开**只恢复「可编辑 / 可报单」**，不恢复任何数据 ——
    删除走的 `forecast_period_delete` 是级联 DELETE（不可恢复），与本函数无关。

    返回：False = 期次不存在；True = 成功（含幂等：本来就 open）。
    """
    with get_db_tx() as db:
        p = db.execute("SELECT id, status FROM forecast_periods WHERE id=?", (pid,)).fetchone()
        if not p:
            return False
        was = (dict(p).get("status") or "open")
        if was == "open":
            return True                      # 幂等：本来就 open ⇒ 既不改 status 也不种豁免
        now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        if str(mode or "full") == "unlock":
            # 解锁编辑：**只**记「人接管了」，status 一动不动（销售照旧报不了单）
            db.execute(
                "UPDATE forecast_periods SET reopened_at=? WHERE id=?", (now, pid))
            return True
        db.execute(
            "UPDATE forecast_periods SET status='open', reopened_at=? WHERE id=?", (now, pid))
        return True


def forecast_period_stale_open(period, today=None):
    """「过期未关」唯一判据 —— 报单窗口已过、却仍挂着 open 的期次。返回 bool。

    🔴 为什么需要它（v355，2026-10-01）：自动建表有一道硬闸「本租户已有任何 open 期次
      ⇒ 跳过」（防两期并存、小程序取错期）。于是在「对已关闭的期次点过『恢复报单』」之后，
      那一期会**永远停在 open**（v319 的豁免让自动关单不碰它，排程又只编排今天及以后
      ⇒ 连想关的机会都没有），把此后每一期都建不出来 —— 而界面上**零提示**
      （生产实测：连着两天没人察觉，只靠"报单页是空的"发现）。
      `scheduler._reap_stale_open_periods` 是**写侧**的自愈回收；本函数是**读侧**的同一判据，
      供界面把「这一期过期了、正挡着下一期」当面说出来。

    判据**与 `forecast_period_writable` 同源**（全站唯一的报单硬锁）：
      `status == 'open'` 且 `order_end < 今天` ⇒ 该期次早已不可写。
    ⚠️ 日期粒度取 `order_end` 前 10 字符（该列可能带时刻，如 '2026-09-29 21:00'）——
      与 scheduler 回收用的 `substr(order_end,1,10) < ?` **逐字一致**，不引入新粒度。

    🔴 判据里必须带 `id > 0`：`forecast_order_board()` 会给「未被任何期次覆盖的报单日期」
      补**合成行**（id<0），其 `status` 硬编码 'open'、`order_end` 就是那个历史日期
      ⇒ 只看日期**必然**命中。但合成行没有 forecast_periods 记录，「关闭」无从谈起，
      也永远不会挡住自动建表。判据自带这道护栏 ⇒ 任何调用方都不会把它误报成僵尸期次。
    """
    d = period if isinstance(period, dict) else (dict(period) if period else {})
    try:
        if int(d.get("id") or 0) <= 0:
            return False                       # 合成行 / 无期次记录 ⇒ 不是僵尸
    except (TypeError, ValueError):
        return False
    if str(d.get("status") or "open") != "open":
        return False
    oe = str(d.get("order_end") or "")[:10]
    if len(oe) < 10:
        return False                           # 没窗口 ⇒ 判不出来就不判（不猜）
    if today is None:
        from datetime import date as _date
        today = _date.today().isoformat()
    return oe < str(today)[:10]


def forecast_period_writable(pid, db_conn=None, allow_closed=False):
    """报单写入口「截止硬锁」统一判据：期次可写返回 (True, '')；否则 (False, 文案)。

    锁条件（仅当 pid>0 才判；pid<=0 视为「未归属」，由调用方各自决定，例如 save-matrix
    的 v244 闸门已拦、导入恒 pid>0）：
      · 期次不存在                → 已删除/非法
      · status != 'open'          → 已定稿/关闭（关闭即定稿）
      · order_end < 今天          → 已过报单截止时间（无论是否已被自动关单）
    与前端 `periodClosed`（status='closed' 或 order_end<今天）**同源口径**，后端是真正的
    硬锁：前端禁用只是 UX，绕不过服务端。

    为什么必须有日期窗口这一道：自动关单（scheduler._auto_period_close）按 auto_close_time
    把过期 open 期次置为 closed，但**只在自动化开启且到点时才跑**；若自动化未开或尚未到点，
    期次会停在「open 但已过期」的状态，save-matrix / 导入仍能写 —— 这正是用户要堵的洞。

    🔴 v305（2026-09-28）：新增 `allow_closed` —— **授权改单**通道（用户 2026-09-28 拍板）。
    背景（用户报障原话）：「关单后要支持主管/文员等有 web 端权限的人能够改单」。
    此前关单后**唯一**路径是 `forecast_period_reopen`（重开期次），副作用是
    **销售又能报单了**（见 `forecast_period_reopen` 注释）—— 为了改一个错数而整期重开，
    代价明显过大。

    `allow_closed=True` 时：**跳过 status 与 order_end 两道锁**，但**仍判期次是否存在**
    （期次不存在 ⇒ 写进去就是 `period_id` 指向虚空，正是 v244 要消灭的孤儿数据）。
    ⚠️ 本参数**只放宽「能不能写」**，不改变任何归属口径；「关闭 = 停止销售报单」的语义
    由调用方（`save_matrix` 只对授权角色传 True）保证，**本函数不做角色判断** ——
    权限裁决必须留在路由层（那里才有 `u`），数据层只认布尔闸。
    """
    try:
        _pid = int(pid or 0)
    except (TypeError, ValueError):
        _pid = 0
    if _pid <= 0:
        return (True, "")
    if db_conn is None:
        # 🔴 2026-09-23 修（v259 顺带修既有缺陷）：`get_db()` 是 **@contextmanager 生成器函数**
        #    （db/connection.py），直接调用拿到的是**上下文管理器对象**，不是连接。
        #    原写法 `conn = get_db()` ⇒ 后面 `conn.execute()` 先 AttributeError，
        #    `finally` 里的 `conn.close()` 又 AttributeError 并**覆盖**前者
        #    （Python 中 finally 抛出的异常会替换 try 里的异常，只留 __context__ 指向它），
        #    所以栈看起来像"只错在 close"，极易误判成 close 的问题。
        #    后果：本函数所有**不传 db_conn** 的调用方，在 period_id>0 时**一律 500** ——
        #    实测 `POST /{sid}/recall`（撤回）就是这样，撤回任何挂在期次上的单都报
        #    "Internal server error"，而拒绝原因（期次已定稿/已截止）一次都没送到用户面前。
        #    ⇒ 修法：递归一次把**真连接**传下去，下方主干只认 db_conn，不再自己开连接。
        with get_db() as _c:
            return forecast_period_writable(_pid, db_conn=_c, allow_closed=allow_closed)
    row = db_conn.execute(
        "SELECT id, status, order_end FROM forecast_periods WHERE id=?", (_pid,)
    ).fetchone()
    if not row:
        return (False, "该报单期次不存在或已被删除，无法保存")
    p = dict(row)
    if allow_closed:
        # 🔴 v305：授权改单 —— 期次**确认存在**之后，两道锁一并让开。
        #   闸口放在这里而不是函数开头：期次不存在时仍必须拒（否则写出的行 period_id 指向虚空，
        #   正是 v244 要消灭的孤儿数据）。调用方对「授权」负全责，见 docstring。
        return (True, "")
    if (p.get("status") or "open") != "open":
        # 🔴 v319 文案修正：原文案是「如需改动请到「往期预报」里先点「重开」」——
        #   而「重开」会把**销售的小程序报单通道一起重新打开**（副作用远大于"改个数"），
        #   且自动化开着时 2~5 分钟内就被重新关掉（生产实测）。⇒ 改成指向两个真正走得通的
        #   通道：① v319 新增的「解锁编辑」（status 不动、销售照旧报不了单）
        #            ② v305 的「授权改单」（主管/管理员在汇总表直接改，保存即留痕）。
        return (False, "该期次已定稿（关闭），不能再修改。如需改动：请在「往期预报」里对该期次点"
                       "「解锁编辑」，或由主管/管理员在汇总表直接改单（保存后留痕）")
    oe = (p.get("order_end") or "").strip()
    if oe:
        today = datetime.now().strftime("%Y-%m-%d")
        if oe < today:
            # ⚠️ 同理：原写「请联系管理员重开本期」——重开会重开销售报单通道；
            #    改指向「授权改单」，那才是"只要改数"的正确路径。
            return (False, f"该期次报单已于 {oe} 截止，无法再报单或修改。如需改动："
                           f"请由主管/管理员在汇总表直接改单（保存后留痕）")
    return (True, "")


def forecast_period_delete(pid):
    """级联删除预报期次及其全部数据（仅允许已关闭期次）。

    报单(forecast_submissions)按期次归属删除（period_id=pid；period_id=0 的历史行
    回退 order_date 区间比对）—— 2026-09-15 前是纯按日期区间删，两个期次窗口重叠时
    会把属于别期的报单**一并删掉**；订单(forecast_orders)按 period_id；
    审核定稿(forecast_audit_decisions)与付款(forecast_period_payments)按期次区间。
    删除前若仍为 open 则拒绝，避免误删正在使用的周期。
    """
    with get_db_tx() as db:
        p = db.execute("SELECT * FROM forecast_periods WHERE id=?", (pid,)).fetchone()
        if not p:
            return False
        p = dict(p)
        if (p.get("status") or "open") == "open":
            raise ValueError("进行中的期次不能删除，请先关闭该期次")
        s = p.get("order_start") or ""
        e = p.get("order_end") or ""
        if s and e:
            # 2026-09-15：只删**真正属于本期次**的报单（period_id=pid），
            # period_id=0 的历史行回退日期区间比对 —— 与全站归属口径同源。
            # 原实现纯按 order_date BETWEEN：当别的期次与本期窗口重叠时，
            # 删本期会把**属于别期的报单一并删掉**（不可逆的数据丢失）。
            # v213-B1：条件改取唯一常量（原先这里是第 2 份手抄副本）。
            _del_cond = FORECAST_PERIOD_SCOPE_SQL
            _del_params = (pid, s, e)
            for (sid,) in db.execute(
                f"SELECT id FROM forecast_submissions WHERE {_del_cond}", _del_params
            ).fetchall():
                db.execute("DELETE FROM forecast_submission_items WHERE submission_id=?", (sid,))
            db.execute(f"DELETE FROM forecast_submissions WHERE {_del_cond}", _del_params)
            # 外围关联表可能在某些租户尚未建出，存在才删，避免误 500
            _del_if_tbl(db, "forecast_audit_decisions",
                         "DELETE FROM forecast_audit_decisions WHERE period_start=? AND period_end=?", (s, e))
            _del_if_tbl(db, "period_payments",
                         "DELETE FROM period_payments WHERE period_start=? AND period_end=?", (s, e))
        db.execute("DELETE FROM forecast_orders WHERE period_id=?", (pid,))
        db.execute("DELETE FROM forecast_periods WHERE id=?", (pid,))
        return True


def _del_if_tbl(db, tbl, sql, params):
    """仅当表存在时才执行删除，防止个别租户缺表导致级联删除 500。"""
    exists = db.execute(
        "SELECT 1 FROM sqlite_master WHERE type='table' AND name=?", (tbl,)
    ).fetchone()
    if exists:
        db.execute(sql, params)


def forecast_period_get(pid):
    """按 id 取单期次（含 status/窗口），不存在返回 None。"""
    try:
        pid = int(pid)
    except (TypeError, ValueError):
        return None
    with get_db() as db:
        r = db.execute("SELECT * FROM forecast_periods WHERE id=?", (pid,)).fetchone()
        return dict(r) if r else None


def forecast_open_periods():
    """小程序报单页拉取：status='open' 且今天落在 [order_start, order_end] 的期次。
    返回精简字段（避免泄露无关列），按 order_start 升序。"""
    from datetime import date as _date
    today = _date.today().isoformat()
    with get_db() as db:
        rows = db.execute(
            "SELECT id, name, order_start, order_end, arrival_date, status "
            "FROM forecast_periods "
            "WHERE status='open' AND ? BETWEEN order_start AND order_end "
            "ORDER BY order_start ASC",
            (today,),
        ).fetchall()
        return [dict(r) for r in rows]


def forecast_open_periods_all():
    """小程序报单页「期次列表」专用：返回所有 status='open' 的期次，并标注 in_window。

    与 forecast_open_periods() 的区别（2026-09-06 新增）：
    - 原函数只返回「今天落在 [order_start, order_end] 内」的期次，用于**提交时自动选期次**
      （forecast_submissions 第 81 行），语义必须严格 —— 保持不变，否则补报会落到过期期次。
    - 本函数仅用于列表展示：Web 端期次管理里 status 仍为 open 的期次全部列出（含单日窗口已过期的），
      解决「Web 端显示 4 个期次、小程序只显示 1 个」的不一致。
      典型场景：单日期期次（order_start = order_end = 某天），那天过后日期过滤把它挡掉，
      但管理员未在 Web 端关闭，状态仍是 open。
    - 排序：今天在窗口内的排最前（保证默认选中项是有效可报期次），其余按 order_start 升序。
    - 安全：提交接口对期次仍有二次校验（status=open 且今天在窗口内），
      前端即便选中已过窗口的期次，提交时会被 400 拒绝，不会写脏数据。
    """
    from datetime import date as _date
    today = _date.today().isoformat()
    with get_db() as db:
        rows = db.execute(
            "SELECT id, name, order_start, order_end, arrival_date, status "
            "FROM forecast_periods "
            "WHERE status='open' "
            "ORDER BY order_start ASC, id ASC"
        ).fetchall()
    out = []
    for r in rows:
        d = dict(r)                      # Row 无 .get()，先转 dict
        s = d.get("order_start") or ""
        e = d.get("order_end") or ""
        d["in_window"] = bool(s and e and s <= today <= e)
        out.append(d)
    # 窗口内优先；同组内按 order_start 升序
    out.sort(key=lambda x: (0 if x["in_window"] else 1, x.get("order_start") or ""))
    return out


# ---- 预报列方案（v108.30：按 user_id 隔离，跨设备同步） ----
# 运行时幂等建表，不依赖 init_db 启动时机（生产库可能未走 init_db）。
def _ensure_col_schemes_tbl(db):
    db.execute(
        "CREATE TABLE IF NOT EXISTS forecast_col_schemes "
        "(user_id TEXT NOT NULL PRIMARY KEY, schemes TEXT DEFAULT '[]', updated_at TEXT DEFAULT (datetime('now','localtime')))"
    )


def forecast_col_schemes_get(user_id):
    """返回该用户的列方案数组（[] 表示无）。"""
    with get_db() as db:
        _ensure_col_schemes_tbl(db)
        r = db.execute("SELECT schemes FROM forecast_col_schemes WHERE user_id=?", (user_id,)).fetchone()
        if not r:
            return []
        try:
            return json.loads(r["schemes"] or "[]")
        except Exception:
            return []


def forecast_col_schemes_save(user_id, schemes):
    """整体覆盖保存该用户的列方案数组（upsert）。"""
    if not isinstance(schemes, list):
        schemes = []
    blob = json.dumps(schemes, ensure_ascii=False)
    with get_db_tx() as db:
        _ensure_col_schemes_tbl(db)
        if db.execute("SELECT 1 FROM forecast_col_schemes WHERE user_id=?", (user_id,)).fetchone():
            db.execute(
                "UPDATE forecast_col_schemes SET schemes=?, updated_at=datetime('now','localtime') WHERE user_id=?",
                (blob, user_id))
        else:
            db.execute(
                "INSERT INTO forecast_col_schemes (user_id, schemes, updated_at) VALUES (?,?,datetime('now','localtime'))",
                (user_id, blob))


# ---- 预报订单 ----

def forecast_order_create(period_id, submitter_name, submitter_type, product_name, quantity, unit='箱', unit_price=0):
    """提交一条预报。unit_price=0 时按商品名精确匹配 products 取采购价作参考价；
    查不到则为 0（绝不复用其他商品的价格，避免静默错配）。"""
    with get_db_tx() as db:
        if not unit_price:
            p = db.execute("SELECT purchase_price FROM products WHERE name=? AND is_active=1 LIMIT 1",
                           (product_name,)).fetchone()
            if p:
                unit_price = p['purchase_price'] or 0
        cur = db.execute(
            "INSERT INTO forecast_orders (period_id,submitter_name,submitter_type,product_name,quantity,unit,unit_price) "
            "VALUES (?,?,?,?,?,?,?)",
            (period_id, submitter_name, submitter_type, product_name, quantity, unit, unit_price))
        return cur.lastrowid


def forecast_order_list(period_id):
    with get_db() as db:
        rows = [dict(r) for r in db.execute(
            "SELECT * FROM forecast_orders WHERE period_id=? ORDER BY id", (period_id,)).fetchall()]
        return {"orders": rows}


def forecast_order_review(oid, reviewer_qty, notes=''):
    """审核：记录审核量(reviewer_qty=采购决策量)，状态→reviewed。重复审核覆盖同字段，幂等。"""
    with get_db_tx() as db:
        db.execute(
            "UPDATE forecast_orders SET reviewer_qty=?,notes=?,status='reviewed',reviewed_at=datetime('now','localtime') WHERE id=?",
            (reviewer_qty, notes, oid))


def forecast_order_confirm(oid):
    """确认：→confirmed。幂等：已 confirmed 的记录不会被重复改写确认时间。"""
    with get_db_tx() as db:
        db.execute(
            "UPDATE forecast_orders SET status='confirmed',confirmed_at=datetime('now','localtime') WHERE id=? AND status!='confirmed'",
            (oid,))


def forecast_submitter_stats(period_id):
    with get_db() as db:
        return [dict(r) for r in db.execute(
            "SELECT submitter_name, COUNT(*) AS order_count, SUM(quantity) AS total_qty, "
            "ROUND(SUM(COALESCE(reviewer_qty,quantity)*unit_price),2) AS total_amount "
            "FROM forecast_orders WHERE period_id=? GROUP BY submitter_name ORDER BY submitter_name",
            (period_id,)).fetchall()]


# ---- KPI 目标与达成 ----

def kpi_target_create(month, name, type='sales_amount', value=0, unit='元', brand=''):
    """双写旧列(target_name/target_type/target_value)：兼容生产 NOT NULL 旧表。"""
    with get_db_tx() as db:
        cols = {r[1] for r in db.execute("PRAGMA table_info(kpi_targets)")}
        if 'target_name' in cols:
            cur = db.execute(
                "INSERT INTO kpi_targets (month,name,type,value,unit,brand,target_name,target_type,target_value) "
                "VALUES (?,?,?,?,?,?,?,?,?)",
                (month, name, type, value, unit, brand, name, type, value))
        else:
            cur = db.execute("INSERT INTO kpi_targets (month,name,type,value,unit,brand) VALUES (?,?,?,?,?,?)",
                             (month, name, type, value, unit, brand))
        return cur.lastrowid


def kpi_target_list(month):
    with get_db() as db:
        return [dict(r) for r in db.execute("SELECT * FROM kpi_targets WHERE month=? ORDER BY id", (month,)).fetchall()]


def kpi_achievement_calc(month):
    """月度达成（只读）：销售额=当月已发货+已签收销售单总额（与财务确认收入口径一致）。"""
    with get_db() as db:
        r = db.execute(
            "SELECT COALESCE(SUM(total_amount),0) AS actual, COUNT(*) AS order_count FROM sale_orders "
            "WHERE strftime('%Y-%m', order_date)=? AND status IN ('delivered','signed')", (month,)).fetchone()
        actual = round(r['actual'] or 0, 2)
        t_row = db.execute(
            "SELECT COALESCE(SUM(value),0) AS t FROM kpi_targets WHERE month=? AND type='sales_amount'",
            (month,)).fetchone()
        target = t_row['t'] or 0
        return {"month": month, "actual": actual, "order_count": r['order_count'],
                "target": target, "rate": round(actual / target * 100, 1) if target > 0 else 0}


# ---- 厂家返利规则与试算 ----

def rebate_rule_create(brand, rule_type, threshold=0, rebate_rate=0, rebate_amount=0, bonus_amount=0):
    with get_db_tx() as db:
        cur = db.execute(
            "INSERT INTO rebate_rules (brand,rule_type,threshold,rebate_rate,rebate_amount,bonus_amount) VALUES (?,?,?,?,?,?)",
            (brand, rule_type, threshold, rebate_rate, rebate_amount, bonus_amount))
        return cur.lastrowid


def rebate_rule_list():
    with get_db() as db:
        return [dict(r) for r in db.execute("SELECT * FROM rebate_rules ORDER BY id DESC").fetchall()]


def rebate_calculate_month(month):
    """按规则试算当月厂家返利（只读不落库）。
    基数=当月已发货/签收订单中该品牌商品明细金额合计；未达 threshold 不返利。
    金额累加后统一 round(2)，避免浮点尾差。"""
    result = {"month": month, "rules": [], "total_rebate": 0}
    with get_db() as db:
        for rule in db.execute("SELECT * FROM rebate_rules ORDER BY id").fetchall():
            rule = dict(rule)
            row = db.execute(
                "SELECT COALESCE(SUM(soi.amount),0) AS base FROM sale_order_items soi "
                "JOIN sale_orders so ON soi.order_id=so.id "
                "JOIN products p ON soi.product_id=p.id "
                "WHERE p.brand=? AND strftime('%Y-%m', so.order_date)=? AND so.status IN ('delivered','signed')",
                (rule.get('brand', ''), month)).fetchone()
            base = round(row['base'] or 0, 2)
            threshold = rule.get('threshold') or 0
            met = base >= threshold
            rebate = round(base * (rule.get('rebate_rate') or 0) / 100.0
                           + (rule.get('rebate_amount') or 0) + (rule.get('bonus_amount') or 0), 2) if met else 0
            result['rules'].append({**rule, 'base_amount': base, 'rebate': rebate, 'threshold_met': met})
            result['total_rebate'] = round(result['total_rebate'] + rebate, 2)
    return result


# ---- 银行流水（预报付款核对） ----
# 说明：以下三个函数中的 bank_statement_list 遮蔽(shadow)了 db/queries/finance.py
# 的同名旧函数。旧函数操作 bank_statements 对账单头、签名为 (bank_account_id=0)；
# 而两个真实调用方（routers/forecast.py、hermes_core.py）均按 status 语义调用，
# 与旧签名不兼容。新实现走独立的 bank_flows 流水表（避免给租户库 bank_statements
# 加列造成 schema 漂移）。旧函数仍可通过 finance 模块直接访问。

def bank_statement_import(flow_date, amount, direction='in', counterparty='', description=''):
    """导入一条银行流水。幂等：同日期+金额+对手方+摘要且未匹配的，不重复导入。"""
    with get_db_tx() as db:
        dup = db.execute(
            "SELECT id FROM bank_flows WHERE flow_date=? AND amount=? AND counterparty=? AND description=? AND status='imported'",
            (flow_date, amount, counterparty, description)).fetchone()
        if dup:
            return dup['id']
        cur = db.execute(
            "INSERT INTO bank_flows (flow_date,amount,direction,counterparty,description) VALUES (?,?,?,?,?)",
            (flow_date, amount, direction, counterparty, description))
        return cur.lastrowid


def bank_statement_match(sid, ref_type, ref_id):
    """把流水匹配到业务单据（如 prepayment/expense）。幂等：重复匹配仅更新引用。"""
    with get_db_tx() as db:
        db.execute(
            "UPDATE bank_flows SET ref_type=?,ref_id=?,status='matched',matched_at=datetime('now','localtime') WHERE id=?",
            (ref_type, ref_id, sid))


def bank_statement_list(status='', bank_account_id=0):
    """银行流水列表。status: '' 全部 / 'imported'|'unmatched' 未匹配 / 'matched' 已匹配。
    bank_account_id 参数仅为兼容旧签名保留，当前忽略。"""
    with get_db() as db:
        if status in ('imported', 'unmatched'):
            rows = db.execute("SELECT * FROM bank_flows WHERE status='imported' ORDER BY flow_date DESC, id DESC").fetchall()
        elif status == 'matched':
            rows = db.execute("SELECT * FROM bank_flows WHERE status='matched' ORDER BY flow_date DESC, id DESC").fetchall()
        else:
            rows = db.execute("SELECT * FROM bank_flows ORDER BY flow_date DESC, id DESC").fetchall()
        return [dict(r) for r in rows]


