# === v88: Global Search (backend implementation) ===
# The /api/search endpoint (routers/search.py) was registered but the DB layer
# was never implemented — this caused a 500 on every global search. The FTS5
# indexes (products_fts / contacts_fts) are already populated; we query them
# with a prefix MATCH (so partial CJK typing like "红" matches "红枣") and fall
# back to LIKE for non-indexed entities (orders, journal entries).
def global_search(q, types="products,contacts,sales,purchases", limit=20):
    """Cross-entity search. Returns a grouped dict consumed by the frontend
    dropdown:
        {products:[...], contacts:[...], sale_orders:[...],
         purchase_orders:[...], invoices:[...]}
    Read-only; scoped to the current tenant DB context.
    """
    if not q:
        return {}
    q = q.strip()
    if not q:
        return {}
    try:
        limit = max(1, min(int(limit or 20), 100))
    except Exception:
        limit = 20
    tl = [t.strip().lower() for t in types.split(",") if t.strip()]
    results = {}

    # Safe FTS5 prefix query: keep alnum + CJK (CJK is .isalnum()==True),
    # drop operators/spaces, append '*' for prefix matching.
    safe = "".join(ch for ch in q if ch.isalnum())
    fts_q = (safe + "*") if safe else None

    with get_db() as db:
        cur = db.cursor()

        if "products" in tl or "product" in tl:
            rows = []
            seen = set()
            if fts_q:
                try:
                    for r in cur.execute(
                        "SELECT p.id, p.name, p.spec, p.barcode, p.brand "
                        "FROM products_fts JOIN products p ON p.id=products_fts.product_id "
                        "WHERE products_fts MATCH ? ORDER BY rank LIMIT ?",
                        (fts_q, limit),
                    ).fetchall():
                        rows.append(r); seen.add(r[0])
                except Exception:
                    pass
            # LIKE fallback — reliable for CJK substrings and any FTS5 gap.
            if len(rows) < limit:
                like = f"%{q}%"
                for r in cur.execute(
                    "SELECT id, name, spec, barcode, brand FROM products "
                    "WHERE name LIKE ? OR spec LIKE ? OR barcode LIKE ? "
                    "OR alias LIKE ? OR pinyin LIKE ? LIMIT ?",
                    (like, like, like, like, like, limit),
                ).fetchall():
                    if r[0] not in seen:
                        rows.append(r); seen.add(r[0])
            results["products"] = [
                {"id": r[0], "name": r[1], "spec": r[2],
                 "barcode": r[3], "brand": r[4]} for r in rows[:limit]
            ]

        if "contacts" in tl or "contact" in tl:
            rows = []
            seen = set()
            if fts_q:
                try:
                    for r in cur.execute(
                        "SELECT c.id, c.name, c.phone, c.type "
                        "FROM contacts_fts JOIN contacts c ON c.id=contacts_fts.contact_id "
                        "WHERE contacts_fts MATCH ? ORDER BY rank LIMIT ?",
                        (fts_q, limit),
                    ).fetchall():
                        rows.append(r); seen.add(r[0])
                except Exception:
                    pass
            if len(rows) < limit:
                like = f"%{q}%"
                for r in cur.execute(
                    "SELECT id, name, phone, type FROM contacts "
                    "WHERE name LIKE ? OR phone LIKE ? OR pinyin LIKE ? LIMIT ?",
                    (like, like, like, limit),
                ).fetchall():
                    if r[0] not in seen:
                        rows.append(r); seen.add(r[0])
            results["contacts"] = [
                {"id": r[0], "name": r[1], "phone": r[2], "type": r[3]}
                for r in rows[:limit]
            ]

        if "sale_orders" in tl or "sales" in tl or "sale" in tl:
            like = f"%{q}%"
            rows = cur.execute(
                "SELECT id, order_no, status FROM sale_orders "
                "WHERE order_no LIKE ? OR note LIKE ? "
                "ORDER BY order_date DESC LIMIT ?",
                (like, like, limit),
            ).fetchall()
            results["sale_orders"] = [
                {"id": r[0], "order_no": r[1], "status": r[2]} for r in rows
            ]

        if "purchase_orders" in tl or "purchases" in tl or "purchase" in tl:
            like = f"%{q}%"
            rows = cur.execute(
                "SELECT id, order_no, status FROM purchase_orders "
                "WHERE order_no LIKE ? OR note LIKE ? "
                "ORDER BY order_date DESC LIMIT ?",
                (like, like, limit),
            ).fetchall()
            results["purchase_orders"] = [
                {"id": r[0], "order_no": r[1], "status": r[2]} for r in rows
            ]

        if "invoices" in tl or "invoice" in tl or "accounts" in tl:
            like = f"%{q}%"
            rows = cur.execute(
                "SELECT id, entry_no, memo FROM journal_entries "
                "WHERE entry_no LIKE ? OR memo LIKE ? LIMIT ?",
                (like, like, limit),
            ).fetchall()
            results["invoices"] = [
                {"id": r[0], "voucher_no": r[1], "summary": r[2]} for r in rows
            ]

    return results


# ===== v105 A2: 审核中心信任分级 + 执行辅助 =====

def get_trust_level(task_type):
    """读取某任务类型的信任级别, 默认 L3(必审)."""
    try:
        with get_db() as db:
            row = db.execute(
                "SELECT level, undoable, undo_window_min FROM review_trust_levels WHERE task_type=?",
                (task_type,)
            ).fetchone()
        if row:
            return dict(row)
    except Exception:
        pass
    return {"level": "L3", "undoable": 0, "undo_window_min": 0}


def set_trust_level(task_type, level, undoable=0, undo_window_min=0):
    """配置某任务类型的信任级别, 返回最新记录."""
    level = level if level in ("L1", "L2", "L3") else "L3"
    with get_db() as db:
        db.execute(
            "INSERT INTO review_trust_levels (task_type, level, undoable, undo_window_min, updated_at) "
            "VALUES (?,?,?,?,datetime('now','localtime')) "
            "ON CONFLICT(task_type) DO UPDATE SET level=excluded.level, "
            "undoable=excluded.undoable, undo_window_min=excluded.undo_window_min, "
            "updated_at=datetime('now','localtime')",
            (task_type, level, int(undoable), int(undo_window_min))
        )
        db.commit()
        row = db.execute(
            "SELECT * FROM review_trust_levels WHERE task_type=?", (task_type,)
        ).fetchone()
    return dict(row) if row else {"task_type": task_type, "level": level}


def execute_advice(task_type, payload, user=None):
    """按任务类型真正执行 AI 建议. 当前支持 forecast_purchase → 生成采购单.

    返回 {executed: bool, entity_type, entity_id, detail} 或 None(无对应执行器).
    """
    if task_type == 'forecast_purchase':
        try:
            from routers.purchase import create_from_forecast_advice
            res = create_from_forecast_advice(payload or {}, user or {})
            oid = (res or {}).get("id") or 0
            return {"executed": True, "entity_type": "purchase_orders",
                    "entity_id": oid, "detail": res}
        except Exception as e:
            logging.getLogger("hergent").error(f"execute_advice forecast_purchase failed: {e}")
            return {"executed": False, "entity_type": "purchase_orders",
                    "entity_id": 0, "error": str(e)}
    return None


def create_advice_log(task_type, payload, reasoning="", ai_source="", ai_confidence=0.0,
                       priority="normal", before=None, user=None):
    """v105: 创建一条 AI 建议并依信任级别决定状态.

    - L1 免审: 直接执行 + status='approved'
    - L2 先斩后奏: 直接执行 + status='executed' (undoable 由信任配置决定)
    - L3 必审: status='pending', 等待人审
    返回新建记录 id.
    """
    if isinstance(payload, (dict, list)):
        payload_json = json.dumps(payload, ensure_ascii=False)
    else:
        payload_json = payload if isinstance(payload, str) else ""
    before_json = json.dumps(before, ensure_ascii=False) if before is not None else ""
    conf = float(ai_confidence or 0)
    cfg = get_trust_level(task_type)
    level = cfg.get("level", "L3")

    status = "pending"
    result_entity_type = ""
    result_entity_id = 0
    did_execute = False

    if level in ("L1", "L2"):
        res = execute_advice(task_type, payload, user)
        if res and res.get("executed"):
            did_execute = True
            status = "approved" if level == "L1" else "executed"
            result_entity_type = res.get("entity_type", "")
            result_entity_id = res.get("entity_id", 0) or 0
        else:
            # 执行失败则降级为待审, 避免静默丢失
            status = "pending"
            if res and res.get("error"):
                reasoning = (reasoning + f"\n[执行失败:{res.get('error')}]").strip()

    # 已执行写执行时间, 否则写空串 (避免 COALESCE 空参数语法错误)
    executed_at_sql = "datetime('now','localtime')" if did_execute else "''"

    with get_db() as db:
        cur = db.execute(
            "INSERT INTO ai_advice_log "
            "(task_type, advice_text, payload_json, before_json, ai_source, ai_confidence, "
            "priority, status, result_entity_type, result_entity_id, executed_at, created_at) "
            "VALUES (?,?,?,?,?,?,?,?,?,?," + executed_at_sql + ",datetime('now','localtime'))",
            (task_type, reasoning, payload_json, before_json, ai_source, conf,
             priority, status, result_entity_type, result_entity_id)
        )
        aid = cur.lastrowid
        db.commit()
    return aid


def undo_advice(advice_id):
    """v105: 撤销一条已执行(先斩后奏)的建议. 当前支持撤销草稿态采购单."""
    with get_db() as db:
        row = db.execute(
            "SELECT * FROM ai_advice_log WHERE id=?", (advice_id,)
        ).fetchone()
        if not row:
            return {"success": False, "detail": "记录不存在"}
        d = dict(row)
        # 仅 L2 且已执行且未过期可撤销
        if d.get("status") != "executed":
            return {"success": False, "detail": "仅「先斩后奏」(L2)且已执行的建议可撤销"}
        cfg = get_trust_level(d.get("task_type", ""))
        if not cfg.get("undoable"):
            return {"success": False, "detail": "该任务类型未开启可撤销"}
        if d.get("result_entity_type") == "purchase_orders" and d.get("result_entity_id"):
            oid = int(d["result_entity_id"])
            po = db.execute("SELECT status FROM purchase_orders WHERE id=?", (oid,)).fetchone()
            if po and po["status"] in ("draft", "pending_approval"):
                db.execute("UPDATE purchase_orders SET status='cancelled' WHERE id=?", (oid,))
            elif po:
                return {"success": False, "detail": f"采购单已处于 {po['status']} 状态, 无法撤销"}
        db.execute(
            "UPDATE ai_advice_log SET status='undone', modified_by_user='__undo__' WHERE id=?",
            (advice_id,)
        )
        db.commit()
    return {"success": True, "detail": "已撤销"}


