def _ensure_forecast_tables(db):
    """惰性建表（兼容 v107 之前创建的租户库——init_db 只在主库跑迁移，租户库需请求时兜底）。"""
    db.execute(
        """CREATE TABLE IF NOT EXISTS forecast_submissions(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id INTEGER NOT NULL,
            role TEXT DEFAULT '',
            store_id INTEGER DEFAULT 0,
            store_name TEXT DEFAULT '',
            store_kind TEXT DEFAULT 'store',
            order_date TEXT DEFAULT (CURRENT_DATE),
            status TEXT DEFAULT 'pending',
            total_qty INTEGER DEFAULT 0,
            total_amount REAL DEFAULT 0,
            note TEXT DEFAULT '',
            period_id INTEGER DEFAULT 0,
            updated_by TEXT DEFAULT '',
            updated_at TEXT DEFAULT '',
            created_at TEXT DEFAULT (CURRENT_TIMESTAMP)
        )"""
    )
    # A7 (2026-08): 老库补 period_id 列（小程序按 order_date 建期次时落库，供 accuracy 命中率关联）
    try:
        db.execute("ALTER TABLE forecast_submissions ADD COLUMN period_id INTEGER DEFAULT 0")
    except Exception:
        pass  # 列已存在
    # v224（2026-09-21）：「一店一期一单、期次关闭前可修改」的留痕列。
    # 为什么必须有：改成**同一单被覆盖**后，「谁最后改的」就无法再从 user_id 看出来
    # （user_id 有意保持=**首报人**，不随修改漂移，否则历史单的归属会在两人改同一店时反复易主）。
    # 于是「最后修改人/时间」另存两列 —— 与 init_db 的权威定义保持同列同序。
    # ⚠️ `CREATE TABLE IF NOT EXISTS` **不给已存在的表补列**（本项目铁律）⇒ 存量库必须 ALTER。
    # v294（2026-09-27）：补 `store_kind` —— 报单对象的**类型轴**（'store' | 'warehouse'）。
    #   为什么必须有：`store_id` 是一个**跨域**数字列 —— 门店行装的是 `contacts.id`，
    #   本人仓行装的是 `warehouses.id`。两个 id 空间各自从 1 开始、可以撞号，
    #   而 v224 的幂等键是 `(store_id, period_id)` ⇒ 同一期次里「门店 5」与「仓库 5」
    #   会**互相覆盖**（后来报的那单静默吞掉先报的那单，两单都在界面上显示"提交成功"）。
    #   这正是用户提的「ID 前加编号」要解决的问题；这里用**显式类型列**表达同一件事 ——
    #   等价于把 'ZT5' / 'DB5' 拆成 (kind, id) 两列，既消歧又不用改 `store_id` 的类型
    #   （改类型要动所有读端，风险远大于收益）。
    #   SQLite 的 `ADD COLUMN ... DEFAULT 'store'` 会让存量行**读到** 'store'（不重写表），
    #   故历史上全部报单（都是门店）自动归位，无需回填脚本。
    for _col, _ddl in (("updated_by", "TEXT DEFAULT ''"), ("updated_at", "TEXT DEFAULT ''"),
                       ("store_kind", "TEXT DEFAULT 'store'")):
        try:
            db.execute("ALTER TABLE forecast_submissions ADD COLUMN %s %s" % (_col, _ddl))
        except Exception:
            pass  # 列已存在
    db.execute(
        """CREATE TABLE IF NOT EXISTS forecast_submission_items(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            submission_id INTEGER NOT NULL,
            product_id INTEGER NOT NULL,
            product_name TEXT DEFAULT '',
            spec TEXT DEFAULT '',
            unit TEXT DEFAULT '件',
            quantity INTEGER DEFAULT 0,
            price REAL DEFAULT 0,
            amount REAL DEFAULT 0,
            barcode TEXT DEFAULT '',
            ordering_entity TEXT DEFAULT ''
        )"""
    )
    try:
        db.execute("ALTER TABLE forecast_submission_items ADD COLUMN barcode TEXT DEFAULT ''")
    except Exception:
        pass  # 列已存在
    # v163: 下单主体（户头）—— 同一商品（同条码）可被两个户头下单，商品档案只有一个
    # `ordering_entity` 字段装不下两个，故权威值落在**明细行**上（来源：导入时按行解析
    # 商品名内嵌的主体标注，见 routers/import_router.py::_execute_forecast_cross）。
    try:
        db.execute("ALTER TABLE forecast_submission_items ADD COLUMN ordering_entity TEXT DEFAULT ''")
    except Exception:
        pass  # 列已存在
    # 舟谱模板单位映射：条码→单位（人工维护，生成模板时优先级最高）
    db.execute(
        """CREATE TABLE IF NOT EXISTS forecast_barcode_units(
            barcode TEXT PRIMARY KEY,
            unit TEXT NOT NULL,
            product_name TEXT DEFAULT '',
            updated_at TEXT DEFAULT (datetime('now','localtime')))"""
    )
    # v199（2026-09-19）：客户列隐藏名册 —— 「删掉一个客户列」这件事的**持久化载体**。
    # 🔴 为什么需要它：客户列的来源是 `all_units`（下面 forecast_submission_summary 里的
    #   **全历史聚合名册**，不按期次、不按角色），而「保存汇总表」save_matrix 的作用域是
    #   **本期 role='导入' 的记录** —— 两者交集为空，中间**没有任何一处记下"这列不要了"**。
    #   实测后果：删列 → 保存无报错 → 刷新后列自动回来，反复无效（用户 2026-09-19 报障）。
    #   且当时**界面没有任何路径**能删掉一列：撤回（recalled）不在排除名单、驳回（rejected）
    #   功能已于 2026-09-07 删除、保存也不落隐藏记录 ⇒ 完全闭环。
    # ✅ 口径**故意与 all_units 同为租户级**（不是 user_id 级）：
    #   若按用户隔离，同一张表不同账号看到的列不一致，就又造出第二套"读端 ≠ 写端"的口径。
    #   与 `forecast_col_schemes`（user_id 主键的"按用户列方案"尝试）区分开 ——
    #   🔴 v411 更正：那张表**并没有被删除**。`_ensure_col_schemes_tbl` /
    #      `forecast_col_schemes_get` / `forecast_col_schemes_save` 三个函数与建表语句
    #      在**本文件里都还在**（首行建表 + `def` 三处，grep 可证），首行上面那句
    #      "已被删除"写于它被弃用之后、但没人真去 DROP，属**过期注释**。
    #      它当前的真实状态是「**全仓零调用**」：没有端点暴露、前端走的也是 localStorage
    #      的同名键（`forecast_col_schemes_<user_id>`），所以它**不构成本模块的口径来源**。
    #      v411 的列偏好落 `ui_col_prefs`（租户级、主键 page），**不复用**这张表：
    #      ① 它按 user_id 隔离，与本仓「列口径 = 租户级」相反；② 它名带 `forecast_` 却要
    #      服务采购/结算页，命名骗人。详见 `db/queries/ui_prefs.py` 的 docstring。
    #   本表只解决"哪些客户列不再显示"。
    # 语义：表里存在的 store_name ⇒ 从名册中隐去（**不删任何报单数据**，只影响列集合）。
    #   加回列 = 保存时 customers 里带上该名字 ⇒ save_matrix 反向 DELETE（可逆，随时反悔）。
    db.execute(
        """CREATE TABLE IF NOT EXISTS forecast_hidden_units(
            store_name TEXT PRIMARY KEY,
            hidden_at TEXT DEFAULT (datetime('now','localtime')),
            hidden_by TEXT DEFAULT '')"""
    )
    # v179（2026-09-16）：导入登记台账 —— 「本期导入的商品」是主表行底的第二来源。
    # 用户诉求原话：「模版里有多少产品，导入后就只有那么多产品」。主表行底原先 = 全量在售
    #   商品档案（实测 275 行），用户拿模版批量建了 159 个商品后仍看到 275 行全 0，
    #   无法确认「我这 159 个到底进来没有」。新行底 = 本表 ∪ 有报单的商品
    #   （见 erp_db.forecast_submission_summary 的 imported_product_ids）。
    # 🔴 **独立成表，绝不写进 forecast_submission_items** —— 那是业务报单表，返利/业绩/
    #   定稿/导出舟谱都在读它；往里塞 0 数量行 = 把「建档台账」伪装成「报单」，
    #   每个下游消费方都要重审一遍（违反「同一份数据拆多个桶 → 先列桶×消费方矩阵」）。
    # 幂等口径：UNIQUE(period_id, product_id) —— 同一条码重复导入只更新元信息。
    db.execute(
        """CREATE TABLE IF NOT EXISTS forecast_import_products(
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            period_id INTEGER NOT NULL DEFAULT 0,
            order_date TEXT DEFAULT '',
            product_id INTEGER NOT NULL,
            product_name TEXT DEFAULT '',
            barcode TEXT DEFAULT '',
            action TEXT DEFAULT '',
            imported_at TEXT DEFAULT (datetime('now','localtime')),
            imported_by TEXT DEFAULT '',
            source_file TEXT DEFAULT '',
            sort_no INTEGER DEFAULT 0,
            UNIQUE(period_id, product_id)
        )"""
    )
    # v184 (2026-09-17)：登记来源（import / seeded）。**租户库靠本函数惰性补列** ——
    # `CREATE TABLE IF NOT EXISTS` 不给已存在的表补列，只加上面的建表语句 = 只在该存量租户上炸。
    # 语义与存量回填理由见 init_db 里的 `v184_forecast_import_origin` 迁移。
    try:
        db.execute("ALTER TABLE forecast_import_products ADD COLUMN origin TEXT DEFAULT 'import'")
    except Exception:
        pass  # 列已存在
    # v202（2026-09-19）：导入模板行序。与上面 origin 同理 —— `CREATE TABLE IF NOT EXISTS`
    #   不给已存在的表补列，故存量租户库必须靠这条惰性 ALTER 补上。
    #   语义（排序键 = 批次基准 + 模板行号）与存量行为（一律 0 = 无顺序信息）见
    #   init_db 里 `v202_forecast_import_sort_no` 迁移的注释。
    try:
        db.execute("ALTER TABLE forecast_import_products ADD COLUMN sort_no INTEGER DEFAULT 0")
    except Exception:
        pass  # 列已存在
    db.execute(
        """CREATE TABLE IF NOT EXISTS employee_stores(
            employee_id INTEGER NOT NULL,
            store_id INTEGER NOT NULL,
            PRIMARY KEY (employee_id, store_id)
        )"""
    )
    # W1: 周期定稿表（与 forecast_audit.py 的 _ensure_audit_decisions schema 保持一致），
    # 确保 summary 在 JOIN 前表必然存在（不依赖先跑过 adopt）。
    db.execute(
        """CREATE TABLE IF NOT EXISTS forecast_audit_decisions (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            period_start TEXT, period_end TEXT,
            product_id INTEGER, product_name TEXT DEFAULT '', unit TEXT DEFAULT '件',
            requested_qty REAL DEFAULT 0, suggested_qty REAL DEFAULT 0, final_qty REAL DEFAULT 0,
            verdict TEXT DEFAULT '', adopted INTEGER DEFAULT 1,
            decided_at TEXT DEFAULT (datetime('now','localtime')), decided_by TEXT DEFAULT ''
        )"""
    )
    # 2026-08-27：期次确认标记（业务经理在汇总表保存即完成审批；老板进汇总表看数据，小公司无需独立审批流）。
    # 与 forecast_audit_decisions 同级惰性建表，确保 summary 在 JOIN/查询前表必然存在。
    db.execute(
        """CREATE TABLE IF NOT EXISTS forecast_period_confirm (
            period_start TEXT NOT NULL,
            period_end TEXT NOT NULL,
            confirmed_by TEXT DEFAULT '',
            confirmed_at TEXT DEFAULT '',
            PRIMARY KEY (period_start, period_end)
        )"""
    )
    # v190（2026-09-18）：行级预报补充值表（extra_qty 加单(箱) / case_price 手工单价(元/箱)）。
    # 建在这里的理由与上面两张表**完全相同**：summary 会 LEFT JOIN 它 —— 表不存在就是
    #   `no such table`，整条汇总直接崩。它此前**只**由 init_db 的 v108 迁移创建，
    #   等于「迁移没跑到的租户库直接炸」，属于顺手补上的存量隐患。
    db.execute(
        """CREATE TABLE IF NOT EXISTS forecast_extra_qty (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            period_start TEXT DEFAULT '',
            period_end TEXT DEFAULT '',
            product_id INTEGER DEFAULT 0,
            product_name TEXT DEFAULT '',
            unit TEXT DEFAULT '',
            extra_qty REAL DEFAULT 0,
            case_price REAL DEFAULT NULL,
            UNIQUE(period_start, period_end, product_id)
        )"""
    )
    # 存量租户库补列（`CREATE TABLE IF NOT EXISTS` 不给已存在的表补列 —— 本项目铁律）。
    try:
        db.execute("ALTER TABLE forecast_extra_qty ADD COLUMN case_price REAL DEFAULT NULL")
    except Exception:
        pass  # 列已存在


def _norm_store_kind(v):
    """报单对象**类型轴**归一（v294）：只认 'warehouse'，其余一律 'store'。

    'store' 是**安全默认**：存量行全部是门店（`store_kind` 由 ALTER 的 DEFAULT 补齐），
    任何脏值 / None / 大小写差异回落成它都不会改变历史语义。
    写成独立函数而不是散在调用点，是因为它同时决定**幂等键**（见 create_submission）
    —— 两处若各写一份 `== 'warehouse'`，改一处漏一处就是「同一单被判成两次新建」。
    """
    return "warehouse" if str(v or "").strip().lower() == "warehouse" else "store"


def forecast_submission_create(user, role, store, items, note="", order_date="", period_id=0, db_conn=None):
    """创建一条预报提交（含明细）。items: [{product_id, product_name, spec, unit, quantity, price, barcode?}]
    order_date 可选：指定报单归属日期（Excel 导入周期对齐用），默认今天。
    period_id 可选：报单归属期次（accuracy 命中率关联键；小程序/矩阵保存按解析期次落库）。
    store 可选带 `kind`（'store' | 'warehouse'，v294）—— 决定 `store_id` 落在哪个 id 空间；
    缺省 'store'（Excel 导入 / Web 矩阵等全部既有调用方零改动）。
    db_conn 可选：传入外部事务连接时复用（由调用方统一 commit/rollback，实现原子保存），
    否则自行开启独立事务（保持原行为）。"""
    uid = int(user.get("id") or 0)
    store_id = int(store.get("id") or 0) if isinstance(store, dict) else int(store or 0)
    store_name = store.get("name", "") if isinstance(store, dict) else str(store or "")
    store_kind = _norm_store_kind(store.get("kind") if isinstance(store, dict) else "")
    from datetime import date as _date
    od = (order_date or "").strip() or _date.today().isoformat()
    total_qty = sum(int(i.get("quantity") or 0) for i in items)
    total_amount = sum(float(i.get("amount") or 0) for i in items)
    pid = int(period_id or 0)

    def _insert(db):
        _ensure_forecast_tables(db)
        cur = db.execute(
            "INSERT INTO forecast_submissions (user_id, role, store_id, store_name, store_kind, order_date, status, total_qty, total_amount, note, period_id) "
            "VALUES (?,?,?,?,?,?,?,?,?,?,?)",
            (uid, role, store_id, store_name, store_kind, od, "pending", total_qty, total_amount, note, pid),
        )
        sid = cur.lastrowid
        for it in items:
            bc = str(it.get("barcode") or "").strip()
            db.execute(
                "INSERT INTO forecast_submission_items (submission_id, product_id, product_name, spec, unit, quantity, price, amount, barcode, ordering_entity) "
                "VALUES (?,?,?,?,?,?,?,?,?,?)",
                (sid, int(it.get("product_id") or 0), it.get("product_name", ""), it.get("spec", ""),
                 it.get("unit", "件"), int(it.get("quantity") or 0),
                 float(it.get("price") or 0), float(it.get("amount") or 0), bc,
                 str(it.get("ordering_entity") or "").strip()),
            )
        return sid

    if db_conn is not None:
        sid = _insert(db_conn)
    else:
        with get_db_tx() as db:
            sid = _insert(db)
    return {"success": True, "submission_id": sid, "total_qty": total_qty, "total_amount": total_amount}


def forecast_submission_replace(sid, user, role, store, items, note="", order_date="", period_id=0):
    """v224（2026-09-21）：**原位替换**一条预报提交 —— 单号（主行 id）保持不变。

    背景（用户拍板）：「一家门店一个期次只能有一单，但在这期期次关闭之前都可以修改」。
      原实现（`routers/forecast_submissions.py` 的 v158 幂等落点）是 **DELETE 旧单 + INSERT 新单**
      ⇒ 每改一次**单号就变一次**。后果对用户是实打实的：
        · 小程序里看到的「单号」在下一次提交之后就查不到了（无法对外引用、无法在列表里对上同一单）；
        · 前端文案「再提交会新增一单」与后端"覆盖"语义相反（本次一并订正为「更新」）。

    分工（重要 —— 本函数与 create 不是替代关系）：
      · `forecast_submission_create` = **新建**，行为一字未改：Web 端 `save-matrix` 与 Excel 导入
        都在用它，二者的语义是「先清掉整个范围、再逐列重建」，不是「改同一单」；
      · 本函数 = **改**，只需小程序 `POST /api/forecast_submissions` 的覆盖分支调用。

    三个必须显式处理的点（都不是显而易见的）：
      ① **`status` 必须复位为 `pending`** —— `forecast_submission_recall` 撤回是
         `UPDATE status='recalled'`（**行还在**，不删行）。新幂等键按 (store, period) 取最新一行
         ⇒ 撤回之后重新报单会命中那条 recalled 行；若只改数量、不复位状态，新报单会
         **继承「已撤回」** ⇒ 不计入本期汇总，而用户看到的是「提交成功」（典型静默失效）。
      ② **`user_id` / `role` 有意不动** —— 保持「首报人」归属稳定。若改成"最后提交人"，
         两人先后改同一门店时，历史单的归属会反复易主；「最后改的人是谁」改由 `updated_by` 承载。
      ③ 单事务内 UPDATE 主行 + 重建明细 —— 与 v158「要么完整覆盖、要么原样不动」同一纪律，
         绝不出现「主行已改、明细没换」或反过来。
    """
    uid = int(user.get("id") or 0)
    store_id = int(store.get("id") or 0) if isinstance(store, dict) else int(store or 0)
    store_name = store.get("name", "") if isinstance(store, dict) else str(store or "")
    # v294：类型轴随单一起覆盖 —— 幂等键含 kind，命中同一行时 kind 必然相同
    # （不同 kind 是两个不同的键、会各自成为独立的一单），此处写回是**收敛**而不是改语义：
    # 万一历史上存在「键相同但 kind 落空」的行，改一次就被纠正回正确值。
    store_kind = _norm_store_kind(store.get("kind") if isinstance(store, dict) else "")
    from datetime import date as _date
    od = (order_date or "").strip() or _date.today().isoformat()
    total_qty = sum(int(i.get("quantity") or 0) for i in items)
    total_amount = sum(float(i.get("amount") or 0) for i in items)
    pid = int(period_id or 0)
    sid = int(sid or 0)
    by = str(user.get("display_name") or user.get("username") or user.get("name") or "").strip()
    if not by and uid > 0:
        by = "员工%d" % uid

    hit = False
    with get_db_tx() as db:
        _ensure_forecast_tables(db)
        cur = db.execute(
            "UPDATE forecast_submissions SET store_id=?, store_name=?, store_kind=?, order_date=?, status='pending', "
            "total_qty=?, total_amount=?, note=?, period_id=?, updated_by=?, "
            "updated_at=datetime('now','localtime') WHERE id=?",
            (store_id, store_name, store_kind, od, total_qty, total_amount, note, pid, by, sid),
        )
        hit = bool(cur and cur.rowcount > 0)
        if hit:
            db.execute("DELETE FROM forecast_submission_items WHERE submission_id=?", (sid,))
            for it in items:
                bc = str(it.get("barcode") or "").strip()
                db.execute(
                    "INSERT INTO forecast_submission_items (submission_id, product_id, product_name, spec, unit, quantity, price, amount, barcode, ordering_entity) "
                    "VALUES (?,?,?,?,?,?,?,?,?,?)",
                    (sid, int(it.get("product_id") or 0), it.get("product_name", ""), it.get("spec", ""),
                     it.get("unit", "件"), int(it.get("quantity") or 0),
                     float(it.get("price") or 0), float(it.get("amount") or 0), bc,
                     str(it.get("ordering_entity") or "").strip()),
                )
    # 主行不存在（被硬删除 / 传了脏 id）⇒ 退化为新建，绝不静默什么也没发生
    # —— "改成功了"而库里其实没有，是最坏的一种回执。
    # 🔴 必须**在事务之外**调用：`forecast_submission_create` 自己会开一个事务（get_db_tx），
    #    在外层事务未提交时调用它 = 自己把自己锁住。这不是理论风险 ——
    #    2026-09-21 的单测 `tools/v224-replace-semantics-test.py` 断言⑦ 实测复现
    #    `sqlite3.OperationalError: database is locked`（写在 `with` 块里时）。
    #    也就是说这个"兜底"若不改，本身就是一条必然抛错的路径。
    if not hit:
        return forecast_submission_create(user, role, store, items, note=note,
                                          order_date=od, period_id=pid)
    return {"success": True, "submission_id": sid, "total_qty": total_qty,
            "total_amount": total_amount, "updated": True, "updated_by": by}


def forecast_recall_allowed(row, user_id=0, role="", store_scopes=None):
	"""v757：**撤回许可的唯一判据** —— 列表 `can_recall` 与写入口 `recall` 共用。

	三条通路，命中任一即可撤：
	  ① **本人**（`user_id` 相等）—— 与 v224 之前语义一致；
	  ② **管理员元组**（admin/boss/supervisor）—— 代员工撤回；
	  ③ 🔴 **该单在我的报单范围里**（v757 新增）—— 「一店一单」下这是必须的一条。

	为什么必须有第 ③ 条（2026-11-04 真实报障）：
	  v224 把幂等键改成 (store_id, period_id) 后，`forecast_submission_replace`
	  **有意不动 `user_id` / `role`**（保持首报人归属）。后果是：主管先导入一版
	  （`role='导入'`、`user_id=老板`），员工随后在小程序提交 → **原位替换到那一行**
	  ⇒ 这张单名义上永远是「导入单」，员工的 `user_id` 从头到尾没进过库。
	  而主管每次 Web 保存又会清掉 `role IN ('导入','主管调整')` 的行重建
	  ⇒ 连 `updated_by` 的痕迹也留不下。
	  于是导购报的单，「本人」这条判据恒不成立 ⇒ 撤回按钮永远不出现，
	  而她恰恰是这家店**唯一**能报单的人。

	为什么敢按「范围」放：撤回是**软删**（`status='recalled'`，行还在、可再报），
	  不是删除；且报单侧的门禁本来就按「范围」给（`create_submission` 的越权校验
	  用的就是 `report_subject_stores`）—— **能报这单的人就能撤这单**，
	  撤回判据与提交判据同源。生产实测：20 个报单对象**全部一店一人**（1:1），
	  放宽不产生任何跨人越权面。

	⚠️ 本函数是唯一判据：`forecast_submission_list` 的 `can_recall` 与
	   `forecast_submission_recall` 的放行必须都调它。两处各写一份必然分叉，
	   而分叉的表现就是「按钮亮着、点了报错」（v755 修的就是这个形态）。
	"""
	try:
		if int(user_id or 0) > 0 and int(row["user_id"] or 0) == int(user_id or 0):
			return True
	except (TypeError, ValueError, KeyError, IndexError):
		pass
	if role in ("admin", "boss", "supervisor"):
		return True
	try:
		sid = int(row["store_id"] or 0)
	except (TypeError, ValueError, KeyError, IndexError):
		sid = 0
	if sid <= 0:
		return False
	try:
		kind = _norm_store_kind(row["store_kind"])
	except (KeyError, IndexError):
		kind = "store"
	for s in (store_scopes or []):
		# ⚠️ 入参两种形状都要吃（调用方不同，不许挑一种）：
		#   · `forecast_submission_list` 传的是 `(id, kind)` **元组**（它自己已归一过 kind）；
		#   · 路由 / `report_subject_stores` 传的是 `{id, name, kind}` **字典**。
		#   只认一种的后果不是报错而是**静默 False**（`int(元组)` 抛错被 continue 吞掉）
		#   ⇒ 按钮永远不亮，与"判据根本没生效"长得一模一样。v757 第一版就栽在这里。
		if isinstance(s, dict):
			_sid, _kd = s.get("id"), s.get("kind")
		elif isinstance(s, (tuple, list)) and len(s) == 2:
			_sid, _kd = s[0], s[1]
		else:
			_sid, _kd = s, "store"
		try:
			_sv = int(_sid)
		except (TypeError, ValueError):
			continue
		if _sv == sid and _norm_store_kind(_kd) == kind:
			return True
	return False

def forecast_submission_list(user_id, order_date="", limit=50, store_ids=None,
                             store_id=0, store_kind="store", role=""):
    """我的提交（含明细）。

    v227（2026-09-21 · 样单）：新增**可选** `store_id` 精确过滤 —— 小程序「复制生成样单」要把
    「某门店报过的全部单（含明细）」一次取回，用于列出可复制的源期次。
    为什么按门店一次取全、而不是再开一个「按期次取单」的参数：
      「一店一期一单」落地后（v224），**该门店的报单条数 == 该店报过的期次数**，
      量极小 ⇒ 一次取回后由前端本地按期次匹配，用户选源时**零网络等待**。
      （按 period_id 逐次查会把"选源"这一步变成 N 次请求，而 N 天然很小 —— 不划算。）
    ⚠️ **不传**（=0）时行为与改前**逐字一致**。
    ⚠️ 授权不受影响：过滤条件是 `(user_id=? OR store_id IN 授权范围)` **且** `store_id=?`
      ⇒ 传一个不属于自己的门店号只会**查不到**，不会越权。
      （本函数不做 403 —— 越权报错是路由层的事，这里只负责"查得到/查不到"。）

    v224（2026-09-21）：范围由「我报过的」扩为「**我报过的 OR 我负责门店报过的**」。
    为什么必须扩：「一店一期一单」落地后同一门店只有一条单 —— 若甲先报、乙后来改了它
    （改的资格按**门店**给，不按人给），而本函数仍只按 `user_id=?` 过滤，则**乙在
    「我的提交」里看不到他刚改过的那一单**：小程序的结果卡刚说"提交成功"、还引导他点
    「查看我的报单」⇒ 回执与列表自相矛盾。这正属于本项目反复出现的「读端与写端作用域
    不是同一套数据」缺陷。
    ⚠️ 调用方只有小程序（`GET /api/forecast-submissions/my`；Web 端零调用）⇒ 扩范围不动 Web。
    ⚠️ `store_ids` 为空/未传 ⇒ 行为与改前**逐字一致**（只按 user_id），老调用方零影响。

    v294（2026-09-27）：**过滤键从「门店号」升级为「(门店号, 类型)」**。
    因为 `store_id` 是跨域数字列（门店=contacts.id、本人仓=warehouses.id），
    只按数字过滤会让两个 id 空间的同号对象互相命中 —— 见下方 `pairs` 处注释。
    `store_ids` 因此兼容 `[5]`（老形状，等价 kind='store'）与 `[{'id':5,'kind':'warehouse'}]`；
    `store_kind` 仅对 `store_id` 精确过滤生效，缺省 'store'。

    v362（2026-10-03 · 老板报「我的提交里一堆 0 件的空报单」）：**空占位单不进本列表**。
    病根 = `save_matrix` 为「本期无正数量的列」也会建一条单（明细 = 一行
    `product_id=0 / '__列占位__' / 数量 0`），**这是写侧的承重设计**（否则该列刷新即消失），
    不可删数据；漏的是**读侧没把它剔掉** ⇒ 经理在 Web 端保存一次汇总表，
    就有十几条空单落进他账号下，小程序「我的提交」原样列出、还带「撤回」按钮。
    🔴 生产实测（tenant_1）：83 单里 **71 单是空占位单**、全部 `role='导入'`、
       `user_id=2`（boss），集中在 4 个日期 —— 与「每次保存建一批列」逐字吻合。
    ⇒ 判据 = **存在一条「非占位且数量 > 0」的明细**。
      · 为什么不只看 `product_name != '__列占位__'`：那只能证明「有行」，
        不能证明「有量」；而报单侧对数量的唯一实现 `normalize_qty` 已硬判
        `n < 0` 非法、`0` = 未填 ⇒ **真实明细必 `quantity > 0`**，判据精确不误伤。
      · 为什么写在 **SQL 的 WHERE** 而不是 Python 里后过滤：`LIMIT 50` 会先截断，
        前 50 条若恰好全是空单，后过滤就得到「空列表」—— 而真单在第 51 条之后。
        这是本项目反复栽的「先取后滤」坑。
    ⚠️ 与催单口径的关系（已用生产数据验过，**不要顺手改那边**）：`scheduler._forecast_reminder_state`
       的「已报」判据是 `role!='导入'`，而占位单全是 `role='导入'` ⇒ 天然被排除
       （实测期次 #23 的差集为空）。本条过滤只管「列表」，不碰「已报/未报」语义。

    v771（2026-11-05）：逐条新增 `arrival_date`（到货日期），取自 `forecast_periods` 同列。
    ⚠️ 小程序旧版忽略该键亦无副作用；空值归一为 ''，**不参与**任何判据/排序/过滤。
    """
    with get_db() as db:
        _ensure_forecast_tables(db)
        db.commit()
        sids = []
        # v294：把授权范围拆成 **(id, kind) 对**，不能再只按数字过滤。
        #   `store_id` 是**跨域**数字列：门店行装 `contacts.id`、本人仓行装 `warehouses.id`，
        #   两个 id 空间独立自增 ⇒ 「门店 5」与「仓库 5」是不同对象。
        #   只按数字 IN 过滤会双向出错：
        #     · 越权读：甲被授权「门店 5」，能读到乙报的「仓库 5」那单；
        #     · 漏读：甲刚改完「仓库 5」的单，却在「我的提交」里找不到（回执与列表打架）。
        #   ⚠️ 入参兼容两种形状：纯数字（= 老调用方，等价 kind='store'）与 {id, kind} 字典。
        #      这样 Web/脚本等既有调用零改动，而 `/my` 可以直接把 employee_stores_get
        #      的返回原样传进来（读端与写端因此**同源**，不另抄一份映射）。
        pairs = []
        for s in (store_ids or []):
            if isinstance(s, dict):
                _id, _kd = s.get("id"), s.get("kind")
            else:
                _id, _kd = s, "store"
            try:
                sv = int(_id)
            except (TypeError, ValueError):
                continue
            if sv > 0:
                pairs.append((sv, _norm_store_kind(_kd)))
        if pairs:
            conds = " OR ".join(["(store_id=? AND store_kind=?)"] * len(pairs))
            sql = ("SELECT * FROM forecast_submissions "
                   "WHERE (user_id=? OR %s)" % conds)
            params = [user_id] + [x for p in pairs for x in p]
        else:
            sql = "SELECT * FROM forecast_submissions WHERE user_id=?"
            params = [user_id]
        if order_date:
            sql += " AND order_date=?"
            params.append(order_date)
        # v227（2026-09-21 · 样单）：可选按门店精确过滤。非法值一律视为"不过滤"（不抛错）。
        # v294：**同时**按 kind 过滤 —— 只按数字会让「门店 5」命中「仓库 5」的单
        #   （小程序「复制生成样单」会把别人/别的对象的货复制进来，是最难发现的一类脏数据）。
        if store_id:
            try:
                _sv = int(store_id)
            except (TypeError, ValueError):
                _sv = 0
            if _sv > 0:
                sql += " AND store_id=? AND store_kind=?"
                params.append(_sv)
                params.append(_norm_store_kind(store_kind))
        # ── v362（2026-10-03）：剔掉「空占位单」（判据与理由见本函数 docstring）────
        # 🔴 必须落在 SQL 的 WHERE 里：放在 Python 端后过滤会被上面的 LIMIT 先截断
        #    （前 50 条全是空单时，真单在第 51 条之后 → 列表直接空掉）。
        sql += (" AND EXISTS (SELECT 1 FROM forecast_submission_items si "
                "WHERE si.submission_id = forecast_submissions.id "
                "AND si.product_name != '__列占位__' "
                "AND COALESCE(si.quantity, 0) > 0)")
        sql += " ORDER BY id DESC LIMIT ?"
        params.append(limit)
        rows = db.execute(sql, params).fetchall()
        result = []
        for r in rows:
            d = dict(r)
            items = db.execute(
                "SELECT product_id, product_name, spec, unit, quantity, price, amount FROM forecast_submission_items WHERE submission_id=?",
                (d["id"],),
            ).fetchall()
            d["items"] = [dict(i) for i in items]
            result.append(d)
        # v259：逐条补 `can_delete`（本人 **且** 期次仍可写）—— 前端据此决定「这一项能不能左滑删除」。
        #  为什么必须由**服务端**给这个布尔，而不是前端自己判：
        #   ① 本列表范围是「我报的 OR 我负责门店报的」（v224），**不全是本人单**。
        #      前端若按「出现在我的列表里」就给删除入口，督导能抹掉销售的单据 ⇒ 越权。
        #   ② 期次已定稿/已截止时，删除会被路由层**硬拒**；若 UI 照样给出按钮，用户看到的
        #      就是「点了就报错」的假入口（本项目反复出现的缺陷族：入口在、操作被拒）。
        #      ⇒ 判据与 `POST /{sid}/delete` + `forecast_period_writable` **同源**，UI 与服务端不会分叉。
        #  ⚠️ 期次状态**一次批量查**再本地比对，不做逐条 N+1（列表上限 50 条）。
        #  ⚠️ 只**新增**键，不动既有键（Web 端不调用本接口，小程序旧版忽略该键亦无副作用）。
        _today = datetime.now().strftime("%Y-%m-%d")
        _pids = []
        for d in result:
            _p = int(d.get("period_id") or 0)
            if _p > 0 and _p not in _pids:
                _pids.append(_p)
        _pw = {}
        if _pids:
            _ph = ",".join(["?"] * len(_pids))
            for _p in db.execute(
                "SELECT id, status, order_end FROM forecast_periods WHERE id IN (%s)" % _ph, _pids
            ).fetchall():
                _st = (_p["status"] or "open")
                _oe = (_p["order_end"] or "").strip()
                # 与 forecast_period_writable 同一口径：open 且未过报单截止日
                _pw[int(_p["id"])] = (_st == "open" and (not _oe or _oe >= _today))
        # v771（2026-11-05）：「我的预报提交」要在报单日期旁显示**到货日期**。
        #   🔴 必须由服务端补：records 来自 `forecast_submissions`（只有 period_id/order_date），
        #      小程序能调的另一个期次接口 `/open-periods` 只返回 status='open' 的期次 ⇒
        #      已关闭期次（生产 24 期里 23 期是 closed）全部取不到，前端自己按 period_id
        #      拼会大面积空白。故在此**批量**补齐，与填报页 `period.arrival_date` 同列同源。
        #   🔴 用 `SELECT *` 后按列名取值，绝不在 SQL 里硬写新列：不同租户的期次表列数
        #      不一致（v765c 的 `order_end_date` 缺列教训），硬引用会让整个列表接口 500。
        #   🔴 只**新增**键、不动既有键；查不到/空值一律 ''，失败方向＝不展示（不影响原功能）。
        _parr = {}
        if _pids:
            try:
                _ph2 = ",".join(["?"] * len(_pids))
                for _pr in db.execute(
                    "SELECT * FROM forecast_periods WHERE id IN (%s)" % _ph2, _pids
                ).fetchall():
                    _prd = dict(_pr)
                    _parr[int(_prd.get("id") or 0)] = str(_prd.get("arrival_date") or "").strip()
            except Exception:
                _parr = {}
        for d in result:
            _pid = int(d.get("period_id") or 0)
            # v771：period_id<=0 的历史行 / 期次已被删 ⇒ ''，前端整段不渲染
            d["arrival_date"] = _parr.get(_pid, "")
            if _pid <= 0:
                _writable = True                      # 未归属期次：与 forecast_period_writable(pid<=0) 同口径
            else:
                _writable = _pw.get(_pid, False)      # 期次查不到 ⇒ 已删除 ⇒ 不可写（同硬锁口径）
            try:
                _owner = int(d.get("user_id") or 0) == int(user_id)
            except (TypeError, ValueError):
                _owner = False
            d["can_delete"] = bool(_owner and _writable)
            # v758（2026-11-04 已撤回单「继续修改」入口）：把「本单所在期次是否仍可写」
            #   **逐条**暴露给前端 —— 它是那个入口的显示条件。
            #   为什么不另算一遍：`_writable` 已在上面按 `forecast_period_writable`
            #   同口径批量算出（open 且未过截止日）。前端自己判必然与它分叉，
            #   分叉的后果就是「按钮亮着、点了报错」（v259 can_delete / v755 can_recall 同族）。
            d["period_writable"] = bool(_writable)
            # v755：逐条补 `can_recall` —— 撤回按钮的归属闸门，与 `forecast_submission_recall`
            #   判据**逐条同源**：pending 且（本人 或 管理员/老板/督导）且 期次仍可写。
            #   为什么必须由服务端给（2026-11-04 员工报障）：
            #     本列表范围含「我负责门店报过的」单（v224）⇒ 员工会看到**老板/督导导入或代改**
            #     的 pending 单。小程序此前只按 `status==='pending'` 亮撤回按钮 ⇒ 员工点了列表里
            #     别人的单，被后端「仅本人或管理员可撤回」挡回，而他坚信点的是自己的单。
            #   ⇒ 与 `can_delete` 同族：入口是否出现由服务端算，前端不许自己判。
            #   ⚠️ 期次可写这道闸不能省：撤回路由层另有 forecast_period_writable 硬锁，
            #      不带就会在「期次已截止」时再造一个「点了就报错」的假入口。
            # v757：判据收敛到 `forecast_recall_allowed`（与写入口同一函数）。
            #   较 v755 多一条通路：「该单的 (store_id, store_kind) ∈ 我的报单范围」。
            #   为什么（2026-11-04 导购马耀秀报障）：她报进的是主管的导入行，
            #   `user_id` 恒为老板 ⇒ 「本人」永不成立 ⇒ 按钮永远不出现。详见该函数 docstring。
            d["can_recall"] = bool(
                _writable and d.get("status") == "pending"
                and forecast_recall_allowed(d, user_id=user_id, role=role, store_scopes=pairs)
            )
        return result


# B5 修复：AI 建议量较重（每 SKU 调一次预报引擎 + 365 天销量扫描）。
# 用带 TTL 的模块级缓存，汇总/待审反复刷新时复用，避免重复引擎计算（首屏后秒开）。
_forecast_cache = {}
_forecast_cache_lock = threading.Lock()
_FORECAST_TTL = 3600  # 秒，1 小时


def _forecast_product_cached(pid, forecast_days=7):
    """带 TTL 缓存的 forecast_product 包装；低频刷新下 1 小时建议量偏差可接受。"""
    key = (int(pid), int(forecast_days))
    now = time.time()
    with _forecast_cache_lock:
        e = _forecast_cache.get(key)
        if e is not None and (now - e[1]) < _FORECAST_TTL:
            return e[0]
    try:
        from domain.forecast_engine import forecast_product
        f = forecast_product(pid, forecast_days=forecast_days)
    except Exception:
        f = None
    with _forecast_cache_lock:
        _forecast_cache[key] = (f, now)
        if len(_forecast_cache) > 2000:
            _forecast_cache.clear()
    return f


# ---------------------------------------------------------------------------
# v213-B1（2026-09-20）：本期『导入』数据的**作用域条件** —— 唯一来源。
# ---------------------------------------------------------------------------
# 🔴 这是「本期导入数据管得着哪些行」的**唯一判据**，两处必须逐字相同：
#      ① 幂等清理：routers/forecast_submissions.py::save_matrix（先删后建，删的就是这个范围）
#      ② 内容指纹：下方 forecast_matrix_rev（乐观锁要比的就是这个范围）
#    两处各写一份 = 「同一规则两处实现」⇒ 迟早分叉（指纹说「没变」而保存删了别的行，
#    或反过来）。所以**只允许从这里取**，不要在调用方手抄。
#    它由 `forecast_period_scope_sql()`（上方唯一实现）拼出 —— 连归属口径也只有一个来源。
# ⚠️ 本条件在 period_id=0 时会**退化**成 `role='导入' AND period_id=0`（不带日期限定）——
#    见 forecast_matrix_rev 的 Z3 说明。指纹忠实镜像该退化（两边同时生效）；
#    是否收窄属**口径决定**，留用户拍板，改动时**只动这一处**。
# 🔴 v741（2026-11-03）：作用域从「只看导入」扩到「导入 + 主管调整」。
#   主管减单（合计被压到低于门店自报量）落成一条 `role='主管调整'` 的负数明细，
#   它**必须和导入行同生同灭** —— 否则下次保存只删导入行 ⇒ 调整行累积叠加，
#   越改越离谱（同一个「先删后建」幂等口径，见 save_matrix）。
FORECAST_IMPORT_SCOPE_SQL = "role IN ('导入','主管调整') AND " + forecast_period_scope_sql()


def forecast_import_scope_params(period_id, start_date, end_date):
    """`FORECAST_IMPORT_SCOPE_SQL` 的配套参数（顺序 = 占位符出现顺序）。"""
    try:
        pid = int(period_id or 0)
    except (TypeError, ValueError):
        pid = 0
    return (max(0, pid), (start_date or "").strip(), (end_date or "").strip())


def _rev_num(x):
    """指纹用的确定性数值格式：None/空 → '-'，其余取定长小数（抹掉 float 尾部噪声）。"""
    try:
        return "%.6f" % float(x)
    except (TypeError, ValueError):
        return "-"


def forecast_matrix_rev(period_id=0, start_date="", end_date="", db_conn=None):
    """本期交叉表矩阵的**内容指纹**（乐观锁用）+ 最后写入人/时刻。

    返回 {"rev": <16 位十六进制>, "at": "YYYY-MM-DD HH:MM:SS", "by_uid": int,
          "items": n, "extra": k, "hidden": h}
    无法判定时返回 `rev=""`（**fail-open**，见下方「失败语义」）。

    🔴 **作用域 = `FORECAST_IMPORT_SCOPE_SQL`（与 save_matrix 的幂等清理取自同一常量，
       不是各写一份）**：三段内容：

        ① 导入报单（矩阵格子本身）
             `FORECAST_IMPORT_SCOPE_SQL` —— 即 save_matrix 清理时删掉的那批行。
             ⚠️ 这里**不加** `status NOT IN ('rejected','recalled')`：清理语句也没有，而被撤回的
                『导入』行**仍会被清理掉重建** ⇒ 若指纹把它排除在外，「别人撤回了一条」这种改动
                就不会让指纹变化 = 保存会静默覆盖。
             ⚠️ 不按 `i.id` / `s.id` 排序 —— 每次保存都「先删后建」，自增 id 必然全变；
                让 id 参与指纹等于「每保存一次指纹必变」。

        ② 行级补充值（加单(箱) / 本期手工单价）
             `forecast_extra_qty WHERE period_start=? AND period_end=?`
             —— 见 save_matrix 末尾那段 upsert。保存时**会覆盖全部行的 extra_qty/case_price**
                ⇒ 别人只改了单价，本次保存同样冲掉它，必须计入指纹。

        ③ 客户列可见性（删列名册）
             `forecast_hidden_units` **全表**（该表没有期次列，删列是全局生效的）
             —— 见 save_matrix 的 INSERT/DELETE 段。列集合变了 = 矩阵变了。

    ⚠️ **不计入** `forecast_period_confirm`（「谁最后签的」）：每次保存都刷新该标记，纳入指纹
       会让「内容一字未改的重复保存」也判冲突 —— 那是噪音，不是冲突。

    ⚠️ **失败语义 = fail-open**：查不出指纹时返回 `rev=""`，调用方**只在指纹非空时才判冲突**。
       乐观锁是**防误覆盖的体验层**，不是数据完整性闸门（完整性由 save_matrix 的单事务保证）
       ⇒ 宁可放行，也不能因为一次查询失败把用户挡在门外。失败会打 warning。

    ⚠️ **period_id=0 的退化（Z3 特征化）**：`FORECAST_IMPORT_SCOPE_SQL` 在 pid=0 时等价于
       `role='导入' AND period_id=0`（**不带日期限定**）⇒ 指纹会把**全库所有 period_id=0 的
       导入行**都算进来（包括窗口外日期的）。这不是指纹的取舍，而是它**忠实镜像**了清理口径
       —— 保存侧同样会把这些行一并清掉重建。是否收窄属口径决定，见常量处注释。

    db_conn：传入外部连接（save_matrix 的**事务连接**）时复用。在事务内必须走这条 ——
       另开一条连接读同一个 SQLite 文件会与外层写事务互锁。
    """
    _EMPTY = {"rev": "", "at": "", "by_uid": 0, "items": 0, "extra": 0, "hidden": 0}

    def _q(conn):
        s = (start_date or "").strip()
        e = (end_date or "").strip()
        if not (s and e):
            # 没有期次窗口就界定不了作用域 —— 不猜、不报错，直接给「不可判定」
            return dict(_EMPTY)
        _cond = FORECAST_IMPORT_SCOPE_SQL
        _p = forecast_import_scope_params(period_id, s, e)
        h = hashlib.sha256()
        # ① 矩阵格子：按**内容**排序取规范序（不能按 id，见 docstring）
        n_items = 0
        for r in conn.execute(
            "SELECT s.store_name AS g, i.product_id AS p, i.product_name AS nm, i.spec AS sp, "
            "i.unit AS u, i.quantity AS q, i.price AS pr "
            "FROM forecast_submissions s JOIN forecast_submission_items i ON i.submission_id=s.id "
            "WHERE " + _cond + " ORDER BY g, p, nm, sp, u, q, pr",
            _p,
        ).fetchall():
            h.update(("I\x1f%r\x1f%r\x1f%r\x1f%r\x1f%r\x1f%r\x1f%r\n" % (
                r["g"] or "", int(r["p"] or 0), r["nm"] or "", r["sp"] or "", r["u"] or "",
                int(r["q"] or 0), _rev_num(r["pr"]))).encode("utf-8"))
            n_items += 1
        # ② 行级补充值（加单(箱) / 手工单价）
        n_extra = 0
        for r in conn.execute(
            "SELECT product_id AS p, product_name AS nm, unit AS u, extra_qty AS eq, case_price AS cp "
            "FROM forecast_extra_qty WHERE period_start=? AND period_end=? ORDER BY p, nm, u",
            (s, e),
        ).fetchall():
            h.update(("E\x1f%r\x1f%r\x1f%r\x1f%r\x1f%r\n" % (
                int(r["p"] or 0), r["nm"] or "", r["u"] or "",
                _rev_num(r["eq"]), "NULL" if r["cp"] is None else _rev_num(r["cp"]))).encode("utf-8"))
            n_extra += 1
        # ③ 列可见性名册（全表；该表无期次列）
        n_hidden = 0
        for r in conn.execute("SELECT store_name AS g FROM forecast_hidden_units ORDER BY g").fetchall():
            h.update(("H\x1f%r\n" % (r["g"] or "")).encode("utf-8"))
            n_hidden += 1
        at, by_uid = "", 0
        # ⚠️ **时区**：`created_at` 是 **UTC** —— 表定义 `DEFAULT (CURRENT_TIMESTAMP)`（v107 遗留），
        #    而本项目**其它**时间戳一律 localtime（同事务的 `forecast_period_confirm.confirmed_at`、
        #    以及 ai_channels / forecast_engine / wastage_tracker / einvoice_engine / bpm_engine …）。
        #    这个值会**显示给用户**（冲突对话框：「谁在几点改过」）⇒ 直接下发 UTC 会让经销商看到
        #    一个**早 8 小时**的时间，把下午发生的事看成上午，误判成「与我无关」。
        #    转换只作用在**本函数新下发的 `matrix_at`** 上：不改表定义、不动存量数据、
        #    不影响任何其它读 `created_at` 的地方（那属于既有口径问题，不在本批范围）。
        #    来源：真机取证 v213-prod-verify R3d/R4d 先抓到（库里 10:41 vs 实际 18:41），
        #    随后把「必须是本地时间」补成离线判据 I1c2（可机械复现，不靠人眼比时区）。
        #    脏值/空值 → `datetime()` 返回 NULL → `at` 为空 → 前端说「刚才」（fail-safe）。
        _last = conn.execute(
            "SELECT datetime(s.created_at, 'localtime') AS ca, s.user_id AS uid FROM forecast_submissions s "
            "WHERE " + _cond + " ORDER BY s.created_at DESC, s.id DESC LIMIT 1",
            _p,
        ).fetchone()
        if _last:
            at = _last["ca"] or ""
            try:
                by_uid = int(_last["uid"] or 0)
            except (TypeError, ValueError):
                by_uid = 0
        return {"rev": h.hexdigest()[:16], "at": at, "by_uid": by_uid,
                "items": n_items, "extra": n_extra, "hidden": n_hidden}

    if db_conn is not None:
        try:
            return _q(db_conn)
        except Exception as e:
            logging.getLogger("hergent").warning("[matrix_rev] 指纹计算失败（放行）: %s", e)
            return dict(_EMPTY)
    try:
        with get_db() as db:
            _ensure_forecast_tables(db)
            db.commit()
            return _q(db)
    except Exception as e:
        logging.getLogger("hergent").warning("[matrix_rev] 指纹计算失败（放行）: %s", e)
        return dict(_EMPTY)


def forecast_submission_summary(order_date="", start_date="", end_date="", period_id=0):
    """汇总总表：SKU+单位跨角色聚合，附来源明细。支持单日 order_date 或日期区间 start_date~end_date（周期视图用）。

    2026-09-12 期次精确归属（修复跨期重叠重复计入）：
      传 period_id 时改用双口径 —— 优先 s.period_id 精确命中，period_id=0 的历史数据
      （早期导入/小程序）回退 order_date 日期窗口。解决「整月期 + 单日期次窗口重叠时，
      同一笔报单在两个期次视图各算一遍」的问题。
      口径与 routers/forecast_config.py::accuracy 的 A7 双口径保持一致，避免多处统计对不上。

    🔴 v372（2026-10-03）：**四个参数全空时，兜底由「今天」改为「默认期次」**。
      原兜底 `s.order_date = 今天` 在真实业务下**几乎恒为空表**，原因是口径错位：
        报单落库时 `order_date` 一律取**期次的 `order_start`**
        （见 routers/forecast_submissions.py 的期次解析段），而 `order_start` 通常**早于**今天
        （实测 tenant_1 期次 #23：order_start=10-02、order_end=10-03，21 单全部记在 10-02）。
        于是「今天」这个日期在 `forecast_submissions.order_date` 里**一条都不存在**。
      · 症状：**小程序「预报汇总总表」打开即空**（它只传 date、从不传 period_id），
        而 Web 端同一份数据看得到 —— Web 端 6 处调用**全部显式传 start+end+period_id**。
      · 修法：全空时取 `forecast_period_default()` 的期次，之后**完全走既有的 period_id 双口径
        分支**（与 Web 端逐字同源），不新写第二份选期次/拼 SQL 的逻辑。
      · ⚠️ 本兜底**只服务读路径**。别把它抄到写路径：`forecast_period_default()` 会选中
        **已关闭**的期次，写路径照抄会把数据挂到用户看不见的期次 —— 这正是
        `routers/import_router.py` v193（2026-09-18）的事故（154 个商品挂到已关闭的 9 期）。
        写路径要归属期次时只认 `forecast_period_current()`（仅 open），见该处注释。
    """
    try:
        period_id = int(period_id or 0)
    except (TypeError, ValueError):
        period_id = 0
    # ---- v372（2026-10-03）：四个参数全空 ⇒ 兜底到「默认期次」而不是「今天」 ----
    # 见本函数 docstring 的 v372 段：「今天」在 order_date 里几乎恒不存在（报单记的是期次
    # order_start），原兜底因此恒返回空表 —— 小程序「预报汇总总表」打开即空。
    # 🔴 选期次**不在这里新写**：复用 `forecast_period_default()`（唯一实现，Web 端
    #    `GET /api/forecast/periods` 的 current 字段也用它），保证两端口径同源。
    #    设好 period_id 后，下方的既有逻辑会自行补全窗口并走 period_id 双口径分支。
    # ⚠️ 取不到（老库无 forecast_periods 表 / 无任何期次）时**降级回原行为**，不抛异常。
    if not (period_id or order_date or start_date or end_date):
        try:
            _dp = forecast_period_default()
        except Exception:
            _dp = None          # 兜底查询失败不应连累读接口（与 forecast_period_default 内同范式）
        if _dp:
            try:
                period_id = int(_dp.get("id") or 0)
            except (TypeError, ValueError):
                period_id = 0
    # 只给 period_id 不给窗口时，自行补全期次窗口（detail/decision_join/confirmed 仍按日期键）
    if period_id and not (start_date and end_date):
        _p = forecast_period_get(period_id)
        if _p:
            start_date = start_date or _p.get("order_start") or ""
            end_date = end_date or _p.get("order_end") or ""
    if period_id and start_date and end_date:
        date_cond = forecast_period_scope_sql("s")   # v213-B1：唯一来源（原先此处是第 3 份手抄副本）
        date_params = [period_id, start_date, end_date]
    elif order_date:
        date_cond, date_params = "s.order_date=?", [order_date]
    elif start_date and end_date:
        date_cond, date_params = "s.order_date BETWEEN ? AND ?", [start_date, end_date]
    elif start_date:
        date_cond, date_params = "s.order_date>=?", [start_date]
    elif end_date:
        date_cond, date_params = "s.order_date<=?", [end_date]
    else:
        from datetime import date as _date
        date_cond, date_params = "s.order_date=?", [_date.today().isoformat()]
    with get_db() as db:
        _ensure_forecast_tables(db)
        db.commit()
        # W1 优化：周期定稿流（护城河）的 final_qty 直接 LEFT JOIN 进汇总，
        # 前端无需二次拼装/额外请求即可在交叉表显示「已定稿」量。
        decision_join = ""
        decision_params = []
        # v190：case_price 也要随行下发（本期手工单价；NULL = 未录入 ⇒ 前端回退按档案进价自动算）。
        #   ⚠️ 两条分支（有/无日期窗口）必须给出**同一字段集** —— 否则「查询带不带窗口」会决定
        #   单价列存不存在，又是一处「同一规则两处实现」。
        final_qty_expr = "NULL AS final_qty, 0 AS extra_qty, NULL AS case_price"
        if start_date and end_date:
            decision_join = (
                " LEFT JOIN forecast_audit_decisions d "
                "ON d.product_id = i.product_id AND d.product_name = i.product_name "
                "AND d.unit = i.unit AND d.period_start = ? AND d.period_end = ?"
                " LEFT JOIN forecast_extra_qty e "
                "ON e.product_id = i.product_id AND e.period_start = ? AND e.period_end = ?"
            )
            decision_params = [start_date, end_date, start_date, end_date]
            # v190：case_price = 本期手工录入的「单价(进价/箱)」。**不加 COALESCE** ——
            #   必须让「未录入」保持 NULL：COALESCE(...,0) 会把它变成 0 元/箱，
            #   前端判「0 元/箱」与「没录价」就得靠猜（「零值即健康」类陷阱）。
            final_qty_expr = ("MAX(d.final_qty) AS final_qty, COALESCE(MAX(e.extra_qty),0) AS extra_qty, "
                              "MAX(e.case_price) AS case_price")
        # ⚠️ 参数顺序必须与 SQL 中 ? 的出现顺序一致：decision_join 的 ON 条件在 FROM/JOIN 段，
        #    位于 WHERE 之前 —— 所以 decision_params 必须在 date_params 前面。
        #    （2026-09-12 修正：此前两者值恰好相同 [start,end]，顺序写反也侥幸正确；
        #      date_cond 改三参数双口径后错位暴露，导致带 period_id 查询返回空。）
        summary_params = list(decision_params) + list(date_params)
        # 2026-09-13 单位/名称对齐 Web 主档（用户口径：小程序提报单位跟 Web 端对齐）：
        #   提报明细里的 name/spec/unit 是填报当时的快照，可能与主档不一致（实测 96 组中 29 组不同，
        #   多为主档单位仍是默认值「件」而提报为真实单位「组/条/包/板/提」）。
        #   这里统一以主档为准（主档为空才回退提报值），带来两个效果：
        #     ① Web 端显示的单位与商品主档/用户在 Web 选择的单位一致；
        #     ② 同一 product_id 的分组键收敛为唯一一行，修复此前「同商品因名称/单位不同被拆成多行，
        #        前端按 product_id 单键索引时后一行覆盖前一行」导致的数量静默丢失
        #        （实测同一商品 12 件被「同款名+渠道后缀名」的 300 件覆盖）。
        #   数量不做换算 —— **这是有意的列语义，不是缺数据**（v222 订正）：
        #     本查询输出的是「按填报单位原样汇总」（报单数量按**最小销售单位**录入），换算发生在展示层，
        #     唯一实现 = Forecast.vue::perCase/boxesOf（v222 起数据源 = 主档 large_ratio/medium_ratio）。
        #   🔴 原文写「主档 unit_ratio=1/has_multi_unit=0，无可靠换算比例」—— 与事实相反：
        #     实测（tenant_1 / 449 个商品）`large_ratio>0` = **371**、`has_multi_unit=1` = **362**
        #     （差 9 条 = 标志位漏标），换算比**可靠**且早有消费方（domain/pricing_engine.py）。
        #     ⚠️ 日后若真要在 SQL 里换算，**先问清这一列想表达什么**，别引用上面那句旧注释当依据。
        #   product_id=0（主档无此商品）保持提报原值，避免不同商品坍缩成一行。
        _master_name = ("COALESCE(NULLIF((SELECT name FROM products WHERE id=i.product_id),''), i.product_name)")
        _master_spec = ("COALESCE(NULLIF((SELECT spec FROM products WHERE id=i.product_id),''), i.spec)")
        # v233：单位口径 = **报单单位**（`products.order_unit` 优先 → 档案 `unit` → 明细 `unit`）。
        #   唯一实现 = `db.queries.products::order_unit_master_sql`（**别在这里手抄那份 COALESCE**）。
        #   🔴 为什么这一列必须与舟谱模板同源（v217「模板填条、系统显示件」）：
        #     `products.unit` 语义混（生产 285 个启用商品里 61 个 `unit='件'` 而 `large_unit=''`
        #     —— 舟谱档案没录过小单位、导入落了默认值），而「件」在舟谱语义里是**大单位**。
        #     本列此前只读档案 ⇒ 与模板（读明细）不同源 ⇒ 同一商品两处显示的单位差 8 倍量纲。
        #   ⚠️ 读端与写端同源：`products_grid`（routers/data.py）下发的也是同一个 `order_unit`，
        #     前端 `Forecast.vue::perCase` 的换算基准就是本列 —— 改一处必须改另一处。
        _master_unit = order_unit_master_sql("i")
        rows = db.execute(
            "SELECT i.product_id, " + _master_name + " AS product_name, "
            + _master_spec + " AS spec, " + _master_unit + " AS unit, "
            "SUM(i.quantity) AS total_qty, SUM(i.amount) AS total_amount, COUNT(DISTINCT s.user_id) AS people, "
            # v574：「多少**店**报」—— 老板是一人替十几家门店填单（实测 tenant_1 期次 34：
            #   单据 3 张 / store_id 2 个，但 user_id 只有 1 个），所以 `people`（账号数）
            #   恒定显示 1，对该场景毫无信息量。门店数才是他要的口径。
            #   🔴 保留 `people` 不删、不改语义（前端展示切换用 `stores`）—— 静默改字段含义
            #      是「恒空恒 0」类的坑，其它消费方（若日后有）会跟着错。
            #   门店去重键：有 store_id 用 id，历史单据 store_id=0 时退化为门店名；
            #   必须带 store_kind —— 「门店 5」与「本人仓 5」会撞号（v294 先例）。
            "COUNT(DISTINCT CASE WHEN s.store_id > 0 "
            "THEN 'i' || s.store_id || '#' || COALESCE(s.store_kind,'store') "
            "ELSE 'n' || COALESCE(NULLIF(s.store_name,''),'未署名') || '#' || COALESCE(s.store_kind,'store') "
            "END) AS stores, "
            # v163：户头取「明细行优先、商品档案兜底」。明细行是**权威** —— 同一商品（同条码）
            # 可被两个户头下单，商品档案只有一个 ordering_entity 字段，装不下两个。
            # 这里用 MAX() 在分组内取非空值（单户头场景结果与旧口径完全一致）；
            # 多户头的完整分布由下方 `entities` 明细字段给出（同商品多户头时不丢信息）。
            "COALESCE(NULLIF(MAX(i.ordering_entity),''), "
            "(SELECT ordering_entity FROM products WHERE id=i.product_id)) AS ordering_entity, "
            "(SELECT barcode FROM products WHERE id=i.product_id) AS barcode, "
            "(SELECT product_code FROM products WHERE id=i.product_id) AS product_code, "
            "(SELECT dist_price FROM products WHERE id=i.product_id) AS dist_price, "
            "(SELECT sale_price FROM products WHERE id=i.product_id) AS sale_price, "
            "(SELECT purchase_price FROM products WHERE id=i.product_id) AS purchase_price, "
            "(SELECT safety_stock FROM products WHERE id=i.product_id) AS safety_stock, "
            "(SELECT expiry_days FROM products WHERE id=i.product_id) AS expiry_days, "
            + final_qty_expr +
            " FROM forecast_submission_items i JOIN forecast_submissions s ON i.submission_id=s.id "
            + decision_join +
            " WHERE " + date_cond + " AND s.status NOT IN ('rejected','recalled') AND i.product_name != '__列占位__' "
            "GROUP BY i.product_id, " + _master_name + ", " + _master_spec + ", " + _master_unit +
            " ORDER BY total_qty DESC",
            summary_params,
        ).fetchall()
        # 明细同样按主档口径输出，保证与 rows 的分组键一致（否则 sources 匹配不上会丢来源明细）
        detail = db.execute(
            "SELECT s.id AS submission_id, s.role, s.store_name, s.store_id, "
            "COALESCE(s.store_kind,'store') AS store_kind, s.user_id, "
            "i.product_id, " + _master_name + " AS product_name, "
            + _master_spec + " AS spec, " + _master_unit + " AS unit, i.quantity "
            "FROM forecast_submissions s JOIN forecast_submission_items i ON i.submission_id=s.id "
            "WHERE " + date_cond + " AND s.status NOT IN ('rejected','recalled') ORDER BY s.id, i.product_id",
            date_params,
        ).fetchall()
        # 跨期持久的客户名册：即使当期无报单也保留列（与 save_matrix 占位机制互补）。
        # 不按期次过滤，按首次提交顺序稳定排序，保证客户列跨期次不丢。
        # 🔴 v199（2026-09-19）两处修正 —— 原实现「删了又回来」的两个根因：
        #   ① 口径不一致：这里原写 `s.status != 'rejected'`，而本函数主查询（上面 rows/detail/ent_map
        #      三处）用的是 `NOT IN ('rejected','recalled')`。`recalled` 被漏掉 ⇒ **已撤回的报单
        #      仍在名册里锚着列**，而它的数量早就不计入了 ⇒ 迟早出现「有列无数据」的空列。
        #      ⚠️ 当年没暴露，只因「永诺旗舰店」另有一条 pending 行兜着（差集恰为 0）。
        #   ② 无「取消保留」通道：名册只能加、不能减 —— 表里那些历史 store_name 会永远锚住列。
        #      界面侧也确无出路：驳回（rejected）的生产者 _approve/_reject 已于 2026-09-07 删除
        #      ⇒ 全库 rejected=0 行，这个排除条件在当前代码里**恒为真**（等于没过滤）。
        # 现加 `forecast_hidden_units` 反向过滤：用户删掉一列 = 在隐藏名册里落一条，列即消失；
        #   加回列 = save_matrix 反向删除该条（见 routers/forecast_submissions.py::save_matrix）。
        # ✅ 该表由本函数开头第 16407 行的 `_ensure_forecast_tables(db)` 保证存在，
        #    且本函数用的是读写连接（`with get_db() as db`）⇒ NOT EXISTS 不会因缺表而 500。
        all_units = [row[0] for row in db.execute(
            "SELECT store_name, MIN(s.id) AS mn FROM forecast_submissions s "
            "WHERE s.status NOT IN ('rejected','recalled') AND s.store_name IS NOT NULL AND s.store_name != '' "
            "AND NOT EXISTS (SELECT 1 FROM forecast_hidden_units h WHERE h.store_name = s.store_name) "
            "GROUP BY s.store_name ORDER BY mn",
        ).fetchall()]
        # 🔴 v7xx（2026-10-30）列顺序 = 老板指定的事业顺序，不再是「谁先报过谁在前」。
        # 老板原话：「我需要按这个顺序，你调整一下」「从现在开始每期顺序不要变」。
        # 排序只换位置：成员仍由上面这条 SQL（含 hidden 过滤）决定 —— 本步不增不减任何列，
        # 未列入顺序的新客户排在其后（保持原相对顺序），见 db/queries/forecast_unit_order.py。
        # fail-safe：取不到配置 / 读库失败 ⇒ 原样返回（排序坏掉不该让汇总表打不开）。
        all_units = apply_unit_order(all_units)
        # 租户库无 users 表（在主库）——人名在 controller 层补，这里先用 user_id
        # 分组键含 product_name/spec：未匹配主档的商品 product_id=0，仅用 (product_id, unit) 会让不同商品坍缩进同一桶
        by_product = {}
        for d in detail:
            key = (d["product_id"], d["product_name"], d["spec"], d["unit"])
            if key not in by_product:
                by_product[key] = []
            by_product[key].append({
                "role": d["role"], "store": d["store_name"], "store_id": d["store_id"], "user_id": d["user_id"], "qty": d["quantity"],
                # v294：来源明细带**类型轴** —— 前端要能分辨这一行来自「门店 5」还是
                # 「本人仓 5」（两者 id 会撞号；不带类型则两个来源在界面上长得一样）。
                "store_kind": d["store_kind"],
            })
        # v163：户头分布明细 —— 同一商品被多个户头下单时，上面那个 `ordering_entity` 只能取一个，
        # 这里给出**完整分布** [{entity, qty}]，供前端对多主体商品显示多个徽标（不丢信息）。
        # 与主查询同条件（date_cond/date_params 逐字复用），保证同屏口径同源。
        ent_map = {}
        try:
            for _er in db.execute(
                "SELECT i.product_id AS pid, i.ordering_entity AS ent, SUM(i.quantity) AS qty "
                "FROM forecast_submission_items i JOIN forecast_submissions s ON i.submission_id=s.id "
                "WHERE " + date_cond + " AND s.status NOT IN ('rejected','recalled') "
                "AND i.ordering_entity != '' AND i.product_name != '__列占位__' "
                "GROUP BY i.product_id, i.ordering_entity ORDER BY qty DESC",
                date_params,
            ).fetchall():
                ent_map.setdefault(int(_er["pid"] or 0), []).append(
                    {"entity": _er["ent"], "qty": _er["qty"]})
        except Exception as e:
            # 户头分布是**增益信息**，查询失败不得让整张汇总表 500（旧租户库可能还没补上该列）。
            logging.getLogger("hergent").warning("[summary] 户头分布查询失败（忽略）: %s", e)
        # v191b（2026-09-18）：单价「**直接延用上一期**」—— 取每个商品在**本期之前**最近一次录入过的
        #   手工单价，随行下发。前端取值链随之变成三级：
        #       本期手工录入 > 最近一次录入（= 沿用，无需重填） > 按商品档案进价自动算
        #   ⚠️ 这是**只读参考值，绝不落库**：保存本期时不会把它写成本期值 —— 否则「用户从没填过」
        #     会变成「用户填过」，既污染历史留痕，也毁掉可撤销性（清空后被自己写回的值又带回来）。
        #   ⚠️ 为什么单独查这一张小表、再在 Python 里合并，而不是塞进主 SQL 的 SELECT 子句：
        #     主查询的 ? 顺序是 [SELECT 段] → [JOIN ON 段] → [WHERE 段]，往 SELECT 里加参数必须插到
        #     decision_params **前面**（本文件在参数错位上踩过坑，见上方 ⚠️ 注释）；单独查既好读又不会错位。
        #   ⚠️ 边界用 `period_start < 本期 start`（**不含本期**）：本期自己的值走 case_price 那一列。
        last_price_map = {}
        if start_date:
            for _lr in db.execute(
                "SELECT product_id, case_price, period_start, period_end FROM forecast_extra_qty "
                "WHERE case_price IS NOT NULL AND case_price > 0 AND period_start < ? "
                "ORDER BY product_id, period_start DESC, period_end DESC",
                [start_date],
            ).fetchall():
                _pid = int(_lr["product_id"] or 0)
                # 已按「最近优先」排序 ⇒ 每个商品的首条即「最近一次录入」，不做累加/取最大值
                if _pid and _pid not in last_price_map:
                    last_price_map[_pid] = {
                        "price": _lr["case_price"],
                        "period_start": _lr["period_start"] or "",
                        "period_end": _lr["period_end"] or "",
                    }
        result_rows = []
        for r in rows:
            d = dict(r)
            # W1: 标记该 SKU 本周期是否已定稿（直接来自 decisions，避免前端二次拼装）
            d["final_qty"] = d.get("final_qty")
            d["forecast_decided"] = d.get("final_qty") is not None
            key = (d["product_id"], d["product_name"], d["spec"], d["unit"])
            d["sources"] = by_product.get(key, [])
            d["entities"] = ent_map.get(int(d.get("product_id") or 0), [])
            # v191b：沿用来源随行下发。**两条分支（有/无日期窗口）给出同一字段集**（同 case_price 的规矩）：
            #   没有可沿用的录入时下发 None / 空串，而不是让字段消失 —— 否则前端要判「字段在不在」。
            _lp = last_price_map.get(int(d.get("product_id") or 0)) or {}
            d["last_case_price"] = _lp.get("price")
            d["last_case_period_start"] = _lp.get("period_start", "")
            d["last_case_period_end"] = _lp.get("period_end", "")
            # ④ AI 建议下单量：复用预报引擎（预测日均 × 7 天补货周期）；仅件单位展示（箱/包换算复杂不硬算）
            d["ai_suggested_qty"] = None
            d["ai_method"] = ""
            if d.get("product_id") and d.get("unit") in ("件", "瓶", "袋", "个"):
                try:
                    f = _forecast_product_cached(int(d["product_id"]), 7)
                    if isinstance(f, dict) and f.get("forecast_total") is not None:
                        d["ai_suggested_qty"] = round(float(f.get("forecast_total", 0)), 1)
                        d["ai_method"] = f.get("method", "")
                except Exception:
                    pass
            result_rows.append(d)
        # 2026-08-27：期次确认标记（经理保存汇总表=审批定稿）。按 start/end 查询，让老板进汇总表一眼看出是否已定稿。
        confirmed = None
        if start_date and end_date:
            cr = db.execute(
                "SELECT confirmed_by, confirmed_at FROM forecast_period_confirm WHERE period_start=? AND period_end=?",
                (start_date, end_date),
            ).fetchone()
            if cr:
                confirmed = {"by": cr["confirmed_by"], "at": cr["confirmed_at"]}
        # v179：本期导入登记的商品 —— 主表行底的第二来源（写入见
        #   routers/import_router.py::_execute_forecast_cross 的登记段）。
        # ⚠️ 筛选条件必须与上面 `date_cond` **同源**（period_id 优先、回退日期窗口）：
        #   否则会出现「汇总算的是期次 9、行底却按另一个日期窗口」—— 同屏两个口径打架。
        # 🔴 2026-09-16 修复：原实现只有单口径 `r.period_id=?`，而上面 `date_cond` 是**双口径**
        #   `(period_id=? OR (period_id=0 AND order_date BETWEEN ? AND ?))` ⇒ 注释写着「同源」、
        #   代码却不同源。可触发的真实序列：全新租户 `forecast_periods` 为空时导入 ⇒
        #   import_router 的 `_period_id` 落 0（current/default 都返回 None）⇒ 登记行 period_id=0；
        #   用户**之后新建期次并在下拉选中** ⇒ summary 带 period_id=N ⇒ `rows` 靠双口径仍能查到，
        #   而 `imported_products` 单口径查不到 ⇒ **行底丢掉全部导入登记商品**，
        #   用户看到的就是「导入过的商品又没了」。故此处必须与 date_cond 逐字同构。
        # 🔴 返回的是**商品行本身**而不是只有 id：`products/grid` 只给「在售」商品，而登记里
        #   会出现**已停用**的商品（实测用户真实文件 2026-09-16：154 个导入商品里 3 个已停用，
        #   另有 2 个有报单的商品也已停用）。只回 id 的话前端在 grid 里查不到这 5 个 →
        #   被**静默丢掉**，用户会以为「我导的商品没进来」。
        imported_products = []
        try:
            # 与上面 date_cond 的分支结构逐条同构（period_id 且窗口齐全 → 双口径）
            if period_id and start_date and end_date:
                # v213-B1：唯一来源（原先此处是第 4 份手抄副本；别名 r 由构造器给出）
                _ic = forecast_period_scope_sql("r")
                _ip = [period_id, start_date, end_date]
            elif period_id:
                _ic, _ip = "r.period_id=?", [period_id]
            elif order_date:
                _ic, _ip = "r.order_date=?", [order_date]
            elif start_date and end_date:
                _ic, _ip = "r.order_date BETWEEN ? AND ?", [start_date, end_date]
            else:
                _ic, _ip = "", []
            if _ic:
                imported_products = [dict(r) for r in db.execute(
                    "SELECT r.product_id AS id,"
                    " COALESCE(NULLIF(p.name,''), r.product_name) AS name,"
                    # v673：**报单快照名**单独下发（与上面的展示名并存，不是替代）。
                    #   由来：本期 187 行里有 20 行的品名写着下单节奏（「单号下单」「（3.7.11…）」），
                    #   而那行字只在**导入模板的快照名**里，商品档案名早被改成了规范品名
                    #   （实测 187 行里 91 行这两个名字不一致）⇒ 「批量设置下单日 → 从品名识别」
                    #   若只看展示名会漏掉这 20 个。前端只把它当识别的第二依据，不展示。
                    " COALESCE(r.product_name,'') AS import_name,"
                    " COALESCE(p.spec,'') AS spec,"
                    " COALESCE(NULLIF(p.unit,''),'件') AS unit,"
                    " COALESCE(NULLIF(p.barcode,''), r.barcode) AS barcode,"
                    " COALESCE(p.product_code,'') AS product_code,"
                    " COALESCE(p.dist_price,0) AS dist_price,"
                    " COALESCE(p.sale_price,0) AS sale_price,"
                    " COALESCE(p.purchase_price,0) AS purchase_price,"
                    # v226b：进价（元/箱）必须随行下发。理由与下面 v184 的到货周期**逐字同构**：
                    #   前端 asProdRow 只搬一份显式白名单，off-archive 行不经过 products/grid
                    #   ⇒ 这里不带，那些行在本期主表「单价(进价/箱)/下单金额」两列**恒显示缺价**，
                    #   而库里明明是有的（与「页面显示 / 导入解析不一致」同一族）。
                    #   ⚠️ 别与上一行 `purchase_price` 混为一谈：那一列是**元/小单位**、
                    #      实测等于标准售价，金额基准**不使用**它（见 db.factory_price_sql 与
                    #      Forecast.vue::factoryPrice 的 v226b 注释）。只增字段，向后兼容。
                    " COALESCE(p.factory_price,0) AS factory_price,"
                    " COALESCE(p.safety_stock,0) AS safety_stock,"
                    " COALESCE(p.expiry_days,0) AS expiry_days,"
                    " COALESCE(p.category,'') AS category, COALESCE(p.brand,'') AS brand,"
                    # v184：到货周期。off-archive 行（已停用/已删除但被本期引用）**不在**
                    #   products/grid 的返回里，而前端 asProdRow 只搬递一份显式白名单
                    #   ⇒ 若这里不带，那些行的「到货周期」列恒显示「—」，
                    #   而库里/导入结果明明是 +3天 —— 正是「页面显示与导入解析不一致」。
                    #   实测沙箱 tenant_9999：期 13 有 5 行属此类（1160/1196/1293/1294/1395）。
                    " COALESCE(p.arrival_lead_days,0) AS arrival_lead_days,"
                    # v670：永辉代码。汇总表新增的「永辉编码」列靠它 —— 这条 SQL 是
                    #   summary 主档行的**唯一来源**，漏了它前端该列恒空（与 v184 到货周期同一个坑）。
                    " COALESCE(p.yonghui_code,'') AS yonghui_code,"
                    # v673：下单日节奏。同样必须随行下发 —— 「今日下单」筛选与「下单日」列
                    #   都要按行判定，off-archive 行不经过 products/grid（v184 到货周期同一个坑）。
                    " COALESCE(p.order_days,'') AS order_days,"
                    " COALESCE(p.is_active,1) AS is_active,"
                    # v202：**模板行序**必须随行下发 —— 前端 buildRowBase 靠它重排行底。
                    #   ⚠️ 不能指望这条 SQL 的返回顺序（视图层要按导入序排，但前端还要与原
                    #     products/grid 的 id DESC 序做稳定合并）⇒ 顺序**既放在 ORDER BY 里，
                    #     也放在字段里**，前端才有能力在「显示全部商品」这类混排场景下自行决定。
                    " COALESCE(r.sort_no,0) AS sort_no"
                    " FROM forecast_import_products r LEFT JOIN products p ON p.id=r.product_id"
                    " WHERE " + _ic + " AND r.product_id>0"
                    # v202：按导入模板的行序返回。两级排序键：
                    #   ① `sort_no>0` 的排在有值的之前（存量行为 0 = 没有顺序信息，不该抢位置）
                    #   ② `sort_no` 升序；同值时用 id 兜底（= 先导入的在前），保证**确定性**
                    #      —— 没有 tiebreaker 的排序在 SQLite 里不承诺稳定顺序。
                    " ORDER BY CASE WHEN COALESCE(r.sort_no,0)>0 THEN 0 ELSE 1 END,"
                    " COALESCE(r.sort_no,0), r.id",
                    _ip,
                ).fetchall()]
        except Exception as e:
            # 登记表是**增益信息**：查不到不得让整张汇总表 500（存量租户库可能还没建该表，
            # 首次请求走 _ensure_forecast_tables 才建）。失败时行底退化回旧口径而已。
            logging.getLogger("hergent").warning("[summary] 导入登记查询失败（忽略）: %s", e)
        return {"date": order_date, "rows": result_rows, "all_units": all_units,
                "confirmed": confirmed, "imported_products": imported_products}


# 2026-09-07 下线：forecast_submission_pending / _approve / _reject 三个函数已删除。
# 原 approve 会「按门店」生成一张采购申请单（reason 写死门店：X）——与经销商真实业务不符：
# 经销商以经销商为单位向厂家下单，本期预报所有门店汇总后一起采购，不存在逐店采购。
# 本期汇总审核/定稿走 Web 端 /api/forecast-audit/audit-period（期次维度）。
# 撤回（recall）保留：报单人撤回自己的预报单，业务上成立。

def forecast_submission_recall(submission_id, user_id=0, role="", store_scopes=None):
    """员工撤回待审批预报单（仅 pending 可撤回）。

    许可判据 = `forecast_recall_allowed()`（唯一实现，与列表 `can_recall` 同源）：
      本人 ／ 管理员元组 ／ **该单在我的报单范围**（v757 新增）。
    `store_scopes` 由路由层用 `report_subject_stores` 解析后传入 —— 与提交越权
    校验**同一个函数**，两处同源。
    """
    with get_db_tx() as db:
        _ensure_forecast_tables(db)
        row = db.execute("SELECT * FROM forecast_submissions WHERE id=?", (submission_id,)).fetchone()
        if not row:
            return {"success": False, "detail": "预报单不存在"}
        if row["status"] != "pending":
            return {"success": False, "detail": f"仅待审批(pending)可撤回，当前 {row['status']}"}
        if not forecast_recall_allowed(row, user_id=user_id, role=role, store_scopes=store_scopes):
            return {"success": False, "detail": "仅本人或管理员可撤回"}
        db.execute(
            "UPDATE forecast_submissions SET status='recalled', note=COALESCE(note,'') || ' | 已撤回' WHERE id=?",
            (submission_id,),
        )
    return {"success": True, "detail": "已撤回"}


def forecast_submission_delete(submission_id, user_id=0, role=""):
    """v259：报单人**本人**删除自己的预报单（连同明细一并硬删除）。

    与 `forecast_submission_recall` 的分工（两者不可互相替代）：
      · 撤回 = 软删：`status='recalled'`，数据仍在、列表里还看得见、汇总不计入，可追溯；
      · 删除 = 硬删：`forecast_submissions` + `forecast_submission_items` 两表物理移除，
        列表里直接消失，不可逆。
      · 撤回允许管理员/老板/督导代劳（他人误报时纠偏）；删除**只允许本人** —— 它是不可
        恢复动作，放开给管理员等于让督导能在「我的提交」里抹掉销售的单据，越权面过大。

    ⚠️ 期次截止硬锁放在**路由层**（与 `/recall` 同一处、同一判据 `forecast_period_writable`），
       不在本函数里：锁是「写入口」语义、与谁调用无关，放在路由层才能保证
       删 / 改 / 撤回三条写路径口径一致（三处各判一次迟早分叉）。
    ⚠️ 本函数**只认本人**，不看 role —— 与上述设计一致；如需放开请改这里并同步
       `can_delete` 的判据（两处必须同源，否则 UI 会给假入口）。
    """
    with get_db_tx() as db:
        _ensure_forecast_tables(db)
        row = db.execute("SELECT * FROM forecast_submissions WHERE id=?", (submission_id,)).fetchone()
        if not row:
            return {"success": False, "detail": "预报单不存在或已被删除"}
        try:
            _owner = int(row["user_id"]) == int(user_id)
        except (TypeError, ValueError):
            _owner = False
        if not _owner:
            return {"success": False, "detail": "仅报单本人可删除该预报单"}
        # 明细先删、主表后删：即便中途失败也不会留下「有明细无主表」的孤儿行
        # （孤儿明细会污染按 period 聚合的汇总口径）。两表在同一事务内，要么都成要么都不成。
        db.execute("DELETE FROM forecast_submission_items WHERE submission_id=?", (submission_id,))
        db.execute("DELETE FROM forecast_submissions WHERE id=?", (submission_id,))
    return {"success": True, "detail": "已删除"}


def employee_stores_set(employee_id, store_ids):
    """绑定员工-门店（先清后写）。

    ⚠️ 2026-09-19 起**已无 UI 调用** —— 「报单人的门店」配置入口已收敛到「报单配置」
    （写 `report_mapping`）。保留本函数仅为脚本 / 旧接口兼容；新代码请勿再调用，
    否则会绕开 `employee_stores_prune_covered` 的收敛逻辑，制造第二份真源。
    对应接口 `PUT /api/forecast-submissions/staff/{id}/stores` 仍在（未删，避免破坏兼容）。
    """
    with get_db_tx() as db:
        _ensure_forecast_tables(db)
        db.execute("DELETE FROM employee_stores WHERE employee_id=?", (employee_id,))
        for sid in store_ids:
            db.execute("INSERT OR IGNORE INTO employee_stores (employee_id, store_id) VALUES (?,?)", (employee_id, sid))
    return {"success": True, "employee_id": employee_id, "store_ids": store_ids}


def employee_stores_prune_covered(employee_id=0):
    """清掉**已被报单配置覆盖**的历史门店授权行（收敛用，幂等，不改可见范围）。

    为什么需要它：`employee_stores` 是历史层，读端取并集（见 `employee_stores_get`）。
    若某门店既在历史层、又在报单配置里，用户在报单配置里**停用**该映射后，
    历史层那行仍会让门店可见 —— 就是「停用无效 / 删了又回来」（v199 同族）。
    所以：一旦某行被 active 映射覆盖（此时删除**不改变可见集合**，因为映射会派生同一 id），
    就把它从历史层移除。历史层因此只保留「尚未纳入报单配置」的部分，
    并由报单配置页的「历史门店授权」提示引导用户补配收敛。

    `employee_id=0` = 清理全部员工（用于一次性收敛/巡检）。
    """
    with get_db_tx() as db:
        _ensure_forecast_tables(db)
        if db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='report_mapping'").fetchone() is None:
            return {"success": True, "removed": 0, "note": "report_mapping 不存在，跳过"}
        w = " AND es.employee_id=?" if employee_id else ""
        params = (int(employee_id),) if employee_id else ()
        # 谓词只写一份：SELECT 数与 DELETE 必须同口径，否则「报 0 条实际删了」或反之。
        # 用 `rowid IN (子查询)` 而不是 `DELETE ... AS es` —— 后者依赖 SQLite 的
        # qualified-table-name 别名语法，写法新、老版本/其他驱动不一定认。
        where = ("EXISTS (SELECT 1 FROM report_mapping rm"
                 " WHERE rm.employee_id=es.employee_id AND rm.counterparty_id=es.store_id"
                 "   AND rm.is_active=1 AND rm.counterparty_type IN ('store','customer')" + w + ")")
        row = db.execute("SELECT COUNT(*) AS c FROM employee_stores es WHERE " + where, params).fetchone()
        n = int(row["c"]) if row else 0
        if n:
            db.execute(
                "DELETE FROM employee_stores WHERE rowid IN ("
                "  SELECT es.rowid FROM employee_stores es WHERE " + where + ")",
                params,
            )
    return {"success": True, "removed": n}


def employee_stores_remove(employee_id, store_id):
    """**收回单条**历史门店授权（`employee_stores` 里的一行）。

    🔴 为什么需要它（2026-09-20）：2026-09-19 把「员工档案 → 分配门店」入口移除、
    收敛到报单配置后，`employee_stores` 只剩**读**（`employee_stores_get` 取并集）
    而没有**写** —— 报单配置页的「历史门店授权」提示条只引导「补配收编」，
    **没有「收回」**。这些门店于是变成「小程序看得到、后台改不掉」：
    用户明确说「我配的一分利 / 一扫光想停掉」时，页面上没有任何按钮可用。
    本函数补上缺的那一半写端。

    ⚠️ 与 `employee_stores_set(employee_id, [])` 的区别：后者是「先清后写」的**全量**语义，
    且对应接口强制 `store_ids` 非空（`if not ids: raise 400`）⇒ 既表达不了
    「只删一行」，也表达不了「清空」。这里做**单行精确删除**，不触碰该员工其它门店。

    防呆：`employee_id<=0` 一律拒绝。历史层里存在 `employee_id=0` 的脏行；
    若放行并在 SQL 里省掉员工条件，一次调用会把**全租户**的历史授权删光。
    返回 `{"success", "removed"}`；`removed=0` = 该行本来就不存在（幂等，不算错）。
    """
    try:
        eid = int(employee_id or 0)
        sid = int(store_id or 0)
    except (TypeError, ValueError):
        return {"success": False, "removed": 0, "detail": "employee_id / store_id 必须为数字"}
    if eid <= 0 or sid <= 0:
        return {"success": False, "removed": 0,
                "detail": "employee_id / store_id 必须为正整数（拒绝空值，避免误删全租户）"}
    with get_db_tx() as db:
        _ensure_forecast_tables(db)
        cur = db.execute(
            "DELETE FROM employee_stores WHERE employee_id=? AND store_id=?", (eid, sid))
        n = int(cur.rowcount or 0)
    return {"success": True, "removed": n, "employee_id": eid, "store_id": sid}


def employee_stores_get(employee_id):
    """查员工的「可报对象」范围（**唯一实现**：小程序下拉 + 报单越权校验共用）。

    🔴 v294（2026-09-27）：本函数的返回**不再只是门店** —— 它同时并入「本人仓」，
    因此每项都带 `kind`（'store' | 'warehouse'）。名字保留（改名要动四个调用点与
    历史注释，收益仅是好看），但语义已是「可报对象」。

    🔴 2026-09-19 口径收敛：**报单配置（report_mapping）是真源**，`employee_stores`
    表退化为**历史兼容层（只读）**。收敛前有两个入口都在配「报单人的门店」——
    员工档案的「门店」弹窗（写 employee_stores）与「报单配置」页（写 report_mapping），
    两者互不感知。实测 tenant_1 两表**零交集**：在报单配置里给张俊峰配了「永辉东津店」，
    小程序却看不到（可见范围只读 employee_stores），因为在报单配置里配完不落到可见范围。
    员工档案侧入口现已移除，写端只剩报单配置一处。

    ⇒ 读端取**并集**，本次收敛**不误删任何人的报单权限**（零数据迁移、零丢失）：
      ① `report_mapping` 中该员工 active 的 store / customer 映射（新真源：配了就可见）
      ② `employee_stores` 表（历史授权；报单配置页「历史门店授权」提示引导补配后自然收敛）
      ③ `report_mapping` 中该员工 active 的 **self_warehouse** 映射 → 并成 `kind='warehouse'`
         （详见下方 v294 段落；`employee_stores` 里不可能有仓，故 ③ 只来自报单配置）
    写端：`employee_stores_set` 已无 UI 调用（保留仅供脚本/兼容，不再是配置入口）。

    ⚠️ 对象集合与写端**同口径**（contacts 里 `type IN ('customer','both')`）——
    「读端来源 ≠ 写端作用域」正是 v199 客户列「删了又回来」的病根，此处刻意对齐。

    🔴 v216（2026-09-20）：**补上「门店未被停用」判据**（`is_active IS NULL OR =1`）。
    此前这个并集**不过滤 `is_active`**，而 `/all-stores`、`/stores` 的 boss/admin 回退分支
    都有 `AND is_active=1` ⇒ 同一个「可报门店」概念两处口径相反：**把门店停用后，
    小程序下拉照样显示它**（用户会以为"停用没生效"）。改后语义收敛为
    「停用门店 = 立刻不可报单」，两个分支逐字同构。
    ⚠️ 本判据**不回溯**已落库的历史报单 —— 停用只影响"还能不能报"，不影响"已经报了什么"。
    """
    try:
        eid = int(employee_id or 0)
    except (TypeError, ValueError):
        eid = 0
    # v317（2026-09-29）：本函数已是**薄壳** —— 全部读逻辑收敛到
    # `_report_subject_stores_impl`。保留原名与原签名（4 个调用点 + 上面整段历史注释
    # 都按「员工」叙述，改名只是好看，收益抵不上动调用点的风险）。
    return _report_subject_stores_impl("employee", eid)


def _report_subject_stores_impl(kind, subject_id):
    """**报单主体 → 可报对象** 的唯一读实现（v317）。语义与历史注释见 `employee_stores_get`。

    `kind` ∈ 'employee' | 'external'；`subject_id` = `hr_employees.id` / `users.id`。
    三处差异（其余逐字同构）：
      ① 过滤列不同：员工读 `report_mapping.employee_id`，外部客户读 `report_mapping.external_user_id`；
      ② **`employee_stores` 历史层只对员工生效** —— 那是 v109 时代「员工 ↔ 门店」的表，
         没有外部客户这一维；对外部主体硬去查它只会得到空集（无害但会误导读者以为查过了）；
      ③ **本人仓只对员工生效** —— 外部客户没有 `hr_employees` 行 ⇒ 没有「个人仓」这个概念。
         对象类型在写端（`report_mapping_create`）也被禁掉，两端同口径。
    """
    try:
        sid = int(subject_id or 0)
    except (TypeError, ValueError):
        sid = 0
    if kind not in ("employee", "external") or sid <= 0:
        # 无主体（boss/admin 或未绑定员工的账号）→ 无个人范围，
        # 由调用方自行回退（/stores 对 boss/admin 回退全量客户）。
        return []
    _emp = (kind == "employee")
    _col = "employee_id" if _emp else "external_user_id"
    with get_db() as db:
        _ensure_forecast_tables(db)
        db.commit()
        # report_mapping 由 `_ensure_tenant_module_tables` 惰性建表；老租户库可能没有。
        # 缺表时只读历史层 —— 不能让一次缺表把「门店列表」整段带崩（小程序首屏依赖它）。
        has_mapping = db.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='report_mapping'"
        ).fetchone()
        if has_mapping:
            # v317：过滤列随主体切换 —— 员工读 `employee_id`、外部客户读 `external_user_id`。
            # ⚠️ `_col` 由上面**代码内常量**决定（不是用户输入）⇒ 无注入面；比较值仍走参数绑定。
            # `employee_stores` 历史层**只对员工并**：外部客户在 v109 那层不存在（见 impl docstring）。
            _legacy = ("  OR c.id IN (SELECT store_id FROM employee_stores WHERE employee_id=?)"
                       if _emp else "")
            rows = db.execute(
                "SELECT c.id AS id, c.name AS name FROM contacts c WHERE c.type IN ('customer','both') "
                # 🔴 v216（2026-09-20）：补上「门店未被停用」判据。
                #    此前这里**不过滤 `is_active`**，而 `/all-stores` 与 `/stores` 的
                #    boss/admin 回退分支**都有** `AND is_active=1` ⇒ 同一个「可报门店」概念
                #    两处口径不一致：把门店在客户档案里停用后，小程序下拉**照样显示它**
                #    （"停用不生效"）。判据取 `IS NULL OR =1`（与回退分支逐字同构：
                #    老数据里 is_active 可能为 NULL，NULL 视为启用）。
                "AND (c.is_active IS NULL OR c.is_active=1) AND ("
                "  c.id IN (SELECT counterparty_id FROM report_mapping"
                "          WHERE " + _col + "=? AND is_active=1"
                "            AND counterparty_type IN ('store','customer'))"
                + _legacy +
                ") ORDER BY c.id",
                ((sid, sid) if _emp else (sid,)),
            ).fetchall()
        else:
            # 缺 `report_mapping` ⇒ 只剩 `employee_stores` 历史层；外部客户没有历史层 ⇒ 空。
            rows = [] if not _emp else db.execute(
                "SELECT c.id AS id, c.name AS name FROM employee_stores es "
                "JOIN contacts c ON c.id=es.store_id "
                "WHERE es.employee_id=? AND c.type IN ('customer','both') "
                "AND (c.is_active IS NULL OR c.is_active=1) ORDER BY c.id",
                (sid,),
            ).fetchall()

        # ---- 🔴 v294（2026-09-27）本人仓并入 ----
        # 为什么此前「配了也永不出现」：上面那段 contacts 子查询把 `counterparty_type`
        # 限死在 ('store','customer')，而「本人仓」映射存的是 **`warehouses.id`**
        # （见 `report_mapping_create` 的 self_warehouse 分支）⇒ 仓库 id 永远匹配不到
        # contacts ⇒ 小程序 `/stores` 下拉里**没有本人仓**，而 `create_submission` 的
        # 越权门禁用的又是**同一个函数**（routers/forecast_submissions.py:164）
        # ⇒ 即使绕过前端直调 API 也是 403。结果就是「一人可同时报门店 + 自己仓的调拨单」
        # 在服务端根本走不通（用户 2026-09-27 报障）。
        #
        # ⚠️ 为什么必须**由报单配置派生**、而不是直接读 `hr_employees.warehouse_id`：
        #    那条映射同时承载「简称(列头)」—— 汇总表列名与舟谱模板都靠它
        #    （见 `db/queries/report_column.py` 的收敛说明）。只读个人仓会造出
        #    「下拉里可选、但落库取不到列名」的第四种口径，正是 v247 刚修掉的
        #    「同一对象裂成两列」。没配映射 = 还没说清它进哪一列 ⇒ 不授权才是同口径的答案，
        #    报单配置页会给出「请先建映射」的提示。
        #
        # ⚠️ 返回项新增 `kind` 字段：这是**类型轴**。调用方不能再把 `id` 当成
        #    「全局唯一的门店号」—— 门店 5 与仓库 5 是两个不同的对象（见
        #    `forecast_submissions.store_kind` 的说明）。
        # v317：**本人仓只对员工** —— 外部客户没有 `hr_employees` 行，不存在「个人仓」这一维；
        # 写端（`report_mapping_create`）同样拒绝，两端同口径（否则会出现
        # 「下拉里有、但谁也建不出来」的假可选项）。
        wh_rows = []
        if has_mapping and _emp:
            wh_rows = db.execute(
                "SELECT w.id AS id, w.name AS name FROM warehouses w "
                "WHERE w.id IN (SELECT counterparty_id FROM report_mapping"
                "               WHERE employee_id=? AND is_active=1"
                "                 AND counterparty_type='self_warehouse')"
                " ORDER BY w.id",
                (sid,),
            ).fetchall()
        # 顺序刻意固定：门店在前（主力）、本人仓在后。两条子查询各自 ORDER BY，
        # 保证同一个员工每次拿到的顺序逐项一致（测试可逐项断言，不依赖巧合）。
        out = [{"id": r["id"], "name": r["name"], "kind": "store"} for r in rows]
        out += [{"id": r["id"], "name": r["name"], "kind": "warehouse"} for r in wh_rows]
        return out


def staff_account_create(employee_id, username, password, display_name, role="staff", tenant_id=None,
                         login_scope=None, external_ref=None):
	"""为员工开登录账号（users 表；网页端与小程序同一个账号）。复用 core 的 bcrypt 哈希格式。返回 user_id 或错误。

	v307：`login_scope` = 该账号允许从哪个端登录（None ⇒ 落 `both`，即**存量行为不变**）。
	v308：`external_ref` 非空 = **外部客户（分销商）账号** ⇒ 跳过员工校验、不关联员工。
	"""
	from core import _hpw, _master_db, normalize_role, role_reject_detail
	# 🔴 2026-09-19 角色白名单（第二道闸；第一道在调用入口 routers/forecast_submissions.py）。
	# 判据只有一份 —— `core.normalize_role`（源头 = `core._DEFAULT_PERMS` + 本租户自定义角色）。
	# 放在 INSERT 紧邻处，是为了让「以后新增调用点」也不会绕过；非法角色按本函数既有
	# `{success, detail}` 形状返回，不新增异常类型。
	if not normalize_role(role):
		return {"success": False, "detail": role_reject_detail(role)}
	conn = _master_db()
	try:
		exists = conn.execute("SELECT id FROM users WHERE username=?", (username,)).fetchone()
		if exists:
			return {"success": False, "detail": f"账号已存在: {username}"}
		# 防重：同一员工不应重复开账号（避免产生多个登录账号 —— 工资条会发错人）。
		# 2026-09-15 三处收紧：
		#  ① 关联判定改走唯一实现 `_emp_link_expr`（与所有读端口径一致）；
		#  ② **去掉 `AND is_active=1`** —— 原条件让「已禁用账号」不算重复，于是禁用后再点
		#     「开通账号」会静默造出第二个账号（前端 `has_account` 也因同一原因重新露出
		#     该入口，两个缺陷互相放大）。禁用 ≠ 没开通，必须拦住；
		#  ③ 必须先有一个**真实存在的员工**，否则会造出「无主账号」（两个关联列都留空/0）——
		#     生产上 `employee_code='9001'/'9002'` 这类脏值正是这么来的。
		_ext = str(external_ref or "").strip()
		_eid = int(employee_id or 0)
		if _ext:
			# v308 **外部客户（分销商）**：他**不是本企业员工** ⇒ 没有、也不该有员工档案。
			#   🔴 原实现在这里硬失败（「请先保存员工档案」）⇒ 外部客户走不通系统里
			#      **唯一**的开账号链路 —— 这正是「分销商没有权限入口」的技术根因。
			#   · 不关联员工（`employee_id` 保持 0），身份留痕写 `external_ref`；
			#   · **跳过**下面「同一员工重复开账号」的防重 —— 那条防重的判据是员工 id，
			#     而外部账号的 employee_id 恒为 0，不跳过会把**所有外部账号互相判成重复**。
			#   🔴 角色闸门：外部账号**只允许 `distributor`**。理由不是偷懒 ——
			#     外部账号的持有人不在本企业人事体系内，给他 `admin` / `boss` 等于
			#     「把后台钥匙发给客户」，且没有任何人事流程能回收。日后要放开其它角色，
			#     改这里一处（判据只此一份）。
			if role != "distributor":
				return {"success": False, "detail": "外部客户账号只能使用「分销商」角色"}
			_eid = 0
		elif _eid <= 0 or not _get_employee(_eid):
			return {"success": False, "detail": "请先保存员工档案，再为其开通登录账号"}
		dup_emp = None if _ext else conn.execute(
			"SELECT id, username, is_active FROM users WHERE " + _emp_link_expr("users") + "=?",
			(_eid,),
		).fetchone()
		if dup_emp:
			return {"success": False,
			        "detail": "该员工已有关联账号：%s（%s）。请在员工档案的账号管理区启用"
			                  "或重置密码，勿重复开通" % (
			                      dup_emp["username"], "启用中" if dup_emp["is_active"] else "已禁用")}
		# v307 登录范围：**显式指定优先**；不传 ⇒ 取该角色的默认值
		#    （v310：`sales`/`distributor`/`staff` 默认「仅小程序」，判据唯一源
		#     = `core.default_login_scope_for_role`，此处不另抄一份名单）。
		#    🔴 非法值的**拒绝**只在路由层做（400）；这里是内部函数，只做收敛 ——
		#      两处各写一套拒绝口径正是"界面显示成功、实际没生效"的温床。
		from core import normalize_login_scope as _norm_scope
		from core import default_login_scope_for_role as _default_scope
		_scope = (_norm_scope(login_scope) if str(login_scope or "").strip()
		          else _default_scope(role))
		# 只写 `employee_id`（权威列），**不再写 `employee_code`** —— 后者是 v4 遗留的 TEXT
		# 拷贝，两个列同时写正是「同一关系两份拷贝」的漂移源（实测生产 mptest 的
		# code='9001' 而 employee_id=0）。此处**停写、保留读**（`_emp_link_expr` 兜存量行）。
		cur = conn.execute(
			"INSERT INTO users (username, password_hash, display_name, role, is_active, phone, employee_id, login_scope, external_ref) VALUES (?,?,?,?,1,?,?,?,?)",
			(username, _hpw(password), display_name, role, username, _eid, _scope, _ext),
		)
		uid = cur.lastrowid
		# 绑定租户：**优先当前租户上下文**（开账号的人正是在这个租户里操作）。
		# 🔴 原实现缺省取「任一 boss/admin 的第一个租户」（`ORDER BY ut.tenant_id LIMIT 1`
		# → 恒为 tenant_1）—— 于是 tenant_10 的老板给自家员工开账号，账号被绑到
		# **tenant_1**：那个人从此登不进自己的租户，而他的工资条会被投进 tenant_1。
		# 只有无租户上下文（平台级调用）才回退旧逻辑。
		if not tenant_id:
			tenant_id = get_tenant_context()
		if not tenant_id:
			row = conn.execute(
				"SELECT ut.tenant_id FROM user_tenants ut JOIN users u ON u.id=ut.user_id WHERE u.role IN ('boss','admin') ORDER BY ut.tenant_id LIMIT 1"
			).fetchone()
			tenant_id = row["tenant_id"] if row else 1
		conn.execute("INSERT OR IGNORE INTO user_tenants (user_id, tenant_id) VALUES (?,?)", (uid, int(tenant_id)))
		conn.commit()
	finally:
		conn.close()
	return {"success": True, "user_id": uid}

# ============================================================
# v211 (2026-09-20): 小程序埋点（自建，落租户库 mp_events）
# ------------------------------------------------------------
# 用户拍板：**后端自建 `/api/track`**，不用微信后台「自定义分析」。
# 理由：埋点的价值是回答「这个功能该不该做/值不值得做」，而那个判断必须能**按租户 ×
# 角色**看；平台侧数据落微信后台，既拿不回来也无法与租户/角色对齐。
# 分工：**写**由 `mp_event_ingest` + `/api/track` 承担，**读**由 `mp_event_stats` 承担
# —— 只写不读的埋点等于没有。
# ============================================================

_MP_EVENT_MAX_BATCH = 50           # 单次上报事件数上限（防单请求灌爆）
_MP_EVENT_MAX_PROPS = 512          # props 序列化后字节上限
_MP_EVENT_MAX_NAME = 64            # 事件名长度上限


def mp_event_ingest(events, user_id=0, username="", role="", tenant_id=0):
	"""批量写入小程序埋点事件。返回 {success, accepted, dropped}。

	🔴 三条都是「会在生产上咬人」的取舍：
	  1) **永不抛异常** —— 埋点是旁路，写入失败必须咽掉，绝不能连累主流程
	     （调用点在每次登录/提交之后，抛出去等于把用户的正常操作弄坏）。
	  2) **服务端只裁剪长度、不做事件名白名单** —— 事件名会随页面/动作一直变，白名单等于
	     把「加一个埋点」变成「前后端各改一次并同步发版」。但**必须**裁长度 + 限批量，
	     否则就是一个无上限的写放大入口。
	  3) `role` 存**当时的角色快照**，不 JOIN 主库现取 —— 角色会变，事后按角色统计只能
	     看当时值，否则「上月会计触发过几次」会随改角色而变。
	"""
	accepted, dropped = 0, 0
	rows = []
	for ev in (events or [])[:_MP_EVENT_MAX_BATCH]:
		try:
			if not isinstance(ev, dict):
				dropped += 1
				continue
			name = str(ev.get("event") or "").strip()[:_MP_EVENT_MAX_NAME]
			if not name:
				dropped += 1
				continue
			props = ev.get("props")
			if props is None or props == "":
				props_s = ""
			else:
				import json as _json
				try:
					props_s = _json.dumps(props, ensure_ascii=False, separators=(",", ":"))
				except Exception:
					props_s = ""
				if len(props_s.encode("utf-8")) > _MP_EVENT_MAX_PROPS:
					dropped += 1
					continue
			try:
				cts = int(ev.get("ts") or 0)
			except (TypeError, ValueError):
				cts = 0
			rows.append((int(tenant_id or 0), int(user_id or 0), str(username or "")[:64],
			             str(role or "")[:32], name,
			             str(ev.get("page") or "")[:64], props_s, cts))
		except Exception:
			dropped += 1
	if not rows:
		return {"success": True, "accepted": 0, "dropped": dropped}
	try:
		with get_db() as db:
			db.executemany(
				"INSERT INTO mp_events (tenant_id, user_id, username, role, event, page, props, client_ts) "
				"VALUES (?,?,?,?,?,?,?,?)", rows)
			db.commit()
		accepted = len(rows)
	except Exception as e:
		# 落库失败明确返回 success=False —— 前端据此保留队列重试，而不是把事件当已送达丢掉。
		return {"success": False, "accepted": 0, "dropped": dropped + len(rows), "detail": str(e)[:200]}
	return {"success": True, "accepted": accepted, "dropped": dropped}


def mp_event_stats(days=7, limit_users=20):
	"""近 N 天埋点汇总：总数 / 按事件 / 按角色 / 按天 / 按人 / 最近 50 条原始事件。只读。

	这是「零可见度」的解药：有了它才能回答「谁在用小程序、卡在哪一步」。
	`limit_users` 限制返回人数（按事件数倒序），避免人多时把响应撑爆。
	"""
	try:
		_d = int(days)
	except (TypeError, ValueError):
		_d = 7
	_d = max(1, min(_d, 180))
	try:
		_lu = max(1, min(int(limit_users), 200))
	except (TypeError, ValueError):
		_lu = 20
	# 判据用 `date(created_at) >= date('now','localtime','-N days')`：created_at 存本地时间
	# 字符串（与全仓一致），先 date() 归一再比，避免「带时刻的字符串直接比」出错。
	_w = "date(created_at) >= date('now','localtime','-%d days')" % _d
	with get_db() as db:
		total = db.execute("SELECT COUNT(*) FROM mp_events WHERE " + _w).fetchone()[0] or 0
		# ⚠️ 一律带**次级排序**（`n DESC` 之后按名称/日期/user_id 升序）：计数并列时 SQLite 的
		# 分组返回顺序不保证稳定，而这是要给人看的报表 —— 同一份数据两次刷新顺序不同，
		# 会被当成「数据变了」（实测：两个各 1 条的事件，谁在前是任意的）。
		by_event = [dict(r) for r in db.execute(
			"SELECT event, COUNT(*) AS n, COUNT(DISTINCT user_id) AS users FROM mp_events "
			"WHERE " + _w + " GROUP BY event ORDER BY n DESC, event").fetchall()]
		by_role = [dict(r) for r in db.execute(
			"SELECT role, COUNT(*) AS n, COUNT(DISTINCT user_id) AS users FROM mp_events "
			"WHERE " + _w + " GROUP BY role ORDER BY n DESC, role").fetchall()]
		by_day = [dict(r) for r in db.execute(
			"SELECT date(created_at) AS day, COUNT(*) AS n, COUNT(DISTINCT user_id) AS users "
			"FROM mp_events WHERE " + _w + " GROUP BY day ORDER BY day").fetchall()]
		by_user = [dict(r) for r in db.execute(
			"SELECT user_id, MAX(username) AS username, MAX(role) AS role, COUNT(*) AS n, "
			"MIN(created_at) AS first_at, MAX(created_at) AS last_at FROM mp_events "
			"WHERE " + _w + " GROUP BY user_id ORDER BY n DESC, user_id LIMIT ?", (_lu,)).fetchall()]
		# 最近 50 条原始事件：排查「某个动作到底有没有被触发」用；缺了就只能看聚合数猜。
		recent = [dict(r) for r in db.execute(
			"SELECT created_at, user_id, username, role, event, page, props FROM mp_events "
			"WHERE " + _w + " ORDER BY id DESC LIMIT 50").fetchall()]
	return {"days": _d, "total": total, "by_event": by_event, "by_role": by_role,
	        "by_day": by_day, "by_user": by_user, "recent": recent}


def timeline_entry_create(etype, title, body_html="", action_type="", action_params_json="", role=""):
    """创建 AI 时间线条目(经营报告/低库存预警/应收逾期等). 返回新条目 id."""
    with get_db() as db:
        db.execute(
            "INSERT INTO timeline_entries (type,title,body_html,action_type,action_params_json,role,created_at) "
            "VALUES (?,?,?,?,?,?,datetime('now','localtime'))",
            (etype, title, body_html, action_type, action_params_json, role)
        )
        db.commit()
        return db.execute("SELECT last_insert_rowid()").fetchone()[0]


def timeline_entry_list(limit=30):
    """按时间倒序列出 AI 时间线条目(最新在前)."""
    with get_db() as db:
        rows = db.execute(
            "SELECT * FROM timeline_entries ORDER BY id DESC LIMIT ?", (int(limit),)
        ).fetchall()
    return [dict(r) for r in rows]


