# v110: role_permissions 主库 → 租户库 迁移（一次性，幂等）
# 背景：role_permissions 原先只在 master(erp.db) 建表，但 get_all_role_permissions() 走 get_db()
# (租户上下文) 读取 —— 导致权限页「保存写租户库 / 导入期读主库」两份内容不一致，
# 主库那份（如 supervisor）在老板保存过一次后即失效。
# 收敛方向=以租户库为准：这里把 master 已有配置灌入各租户库，避免老板配过的自定义角色丢失。
# 注：supervisor 已写进 core._DEFAULT_PERMS，即使本迁移失败也不会再丢（此处仅为兜住其它自定义角色）。
# 🔴 2026-09-19 P0 补完：这条「以租户库为准」当时只做了一半 —— 灌数据做了，但
#    `/api/role-permissions` 仍留在 _TENANT_MASTER_PREFIXES（写主库）、读端仍是进程级全局
#    ROLE_PERMS（读主库）。现在读写都按租户，主库那份从此只是**历史残留**（值等于内置默认，
#    无行为影响）。同时把灌数据收紧成「仅空表」——见下方注释。
if DB_ENGINE == "sqlite":
    try:
        import sqlite3 as _s4
        _master_rows = []
        try:
            from core import _master_db as _mdb
            _mc = _mdb()
            try:
                _master_rows = [dict(r) for r in _mc.execute(
                    "SELECT role_name, permissions FROM role_permissions").fetchall()]
            finally:
                _mc.close()
        except Exception:
            _master_rows = []
        if _master_rows:
            # v206: 走唯一权威枚举（结构校验）。
            for _tp in iter_tenant_db_paths():
                try:
                    _tdb = _s4.connect(_tp)
                    _tdb.execute("""CREATE TABLE IF NOT EXISTS role_permissions (
                        id INTEGER PRIMARY KEY AUTOINCREMENT,
                        role_name TEXT UNIQUE NOT NULL,
                        permissions TEXT DEFAULT '[]',
                        created_at TEXT DEFAULT (datetime('now','localtime'))
                    )""")
                    # 🔴 只在**该租户库这张表还是空的**时才灌入。
                    # 本迁移在 import 期执行 ⇒ 每次重启都会重跑。若无条件 INSERT OR IGNORE，
                    # 老板在权限页里删掉的自定义角色会**在下次重启后自己回来**
                    # （「删了又回来」那一族缺陷：读端来源与写端作用域不是同一套）。
                    # 「空表才灌」= 既保住首次引导，又不覆盖租户的删除动作。
                    _empty = _tdb.execute("SELECT COUNT(*) FROM role_permissions").fetchone()[0] == 0
                    if _empty:
                        for _r in _master_rows:
                            _tdb.execute(
                                "INSERT OR IGNORE INTO role_permissions (role_name, permissions) VALUES (?,?)",
                                (_r["role_name"], _r["permissions"]))
                    _tdb.commit()
                    _tdb.close()
                except Exception:
                    pass
    except Exception:
        pass


# ============================================================
# P1-2 厂家预存款余额 & 周期付款闭环（定稿金额口径）
# ============================================================
def _ensure_payment_tables(conn):
    conn.execute("""CREATE TABLE IF NOT EXISTS supplier_balances (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        supplier_id INTEGER DEFAULT 0, supplier_name TEXT DEFAULT '蒙牛',
        balance REAL DEFAULT 0,
        updated_at TEXT DEFAULT (datetime('now','localtime')), updated_by TEXT DEFAULT '')""")
    conn.execute("""CREATE TABLE IF NOT EXISTS period_payments (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        period_start TEXT, period_end TEXT,
        supplier_id INTEGER DEFAULT 0, supplier_name TEXT DEFAULT '蒙牛',
        order_amount REAL DEFAULT 0, balance REAL DEFAULT 0, gap_amount REAL DEFAULT 0,
        paid_amount REAL DEFAULT 0, status TEXT DEFAULT 'pending',
        paid_at TEXT, decided_by TEXT DEFAULT '',
        created_at TEXT DEFAULT (datetime('now','localtime')))""")


def supplier_balance_upsert(supplier_id, supplier_name, balance, updated_by=""):
    """更新厂家预存款余额（按下单主体/供应商追加一条，取最新）。"""
    with get_db_tx() as conn:
        _ensure_payment_tables(conn)
        conn.execute(
            "INSERT INTO supplier_balances (supplier_id, supplier_name, balance, updated_by) VALUES (?,?,?,?)",
            (int(supplier_id or 0), str(supplier_name or "蒙牛")[:40], float(balance or 0), str(updated_by or "")),
        )
    return {"success": True}


def supplier_balance_list():
    """厂家余额：每供应商最新一条。"""
    with get_db() as conn:
        _ensure_payment_tables(conn)
        conn.commit()
        rows = conn.execute(
            "SELECT supplier_id, supplier_name, balance, updated_at FROM supplier_balances s "
            "WHERE id IN (SELECT MAX(id) FROM supplier_balances GROUP BY supplier_id) ORDER BY id"
        ).fetchall()
        return [dict(r) for r in rows]


def period_payment_save(start, end, supplier_id, supplier_name, order_amount, balance, gap_amount):
    """周期付款记录 upsert（status='pending'，同周期重算即覆盖）。"""
    with get_db_tx() as conn:
        _ensure_payment_tables(conn)
        conn.execute("DELETE FROM period_payments WHERE period_start=? AND period_end=?", (start, end))
        conn.execute(
            "INSERT INTO period_payments (period_start, period_end, supplier_id, supplier_name, order_amount, balance, gap_amount, status) "
            "VALUES (?,?,?,?,?,?,?,'pending')",
            (start, end, int(supplier_id or 0), str(supplier_name or "蒙牛")[:40],
             float(order_amount or 0), float(balance or 0), float(gap_amount or 0)),
        )
    return {"success": True}


def period_payment_confirm(start, end, paid_amount, decided_by=""):
    """付款到账确认（status='paid'）。"""
    with get_db_tx() as conn:
        _ensure_payment_tables(conn)
        conn.execute(
            "UPDATE period_payments SET status='paid', paid_amount=?, paid_at=datetime('now','localtime'), decided_by=? "
            "WHERE period_start=? AND period_end=?",
            (float(paid_amount or 0), str(decided_by or ""), start, end),
        )
    return {"success": True}


def period_payment_get(start, end):
    """查某周期付款记录。"""
    with get_db() as conn:
        _ensure_payment_tables(conn)
        conn.commit()
        row = conn.execute(
            "SELECT * FROM period_payments WHERE period_start=? AND period_end=? LIMIT 1", (start, end)
        ).fetchone()
        return dict(row) if row else None


# ============================================================
# P2-1 返利冲档测算：指标达成 → 当前档/下一档 → 冲档缺口与收益
# ============================================================
def rebate_gap_projection(supplier_id, extra_amount=0):
    """返利冲档测算（厂家采购额口径，purchase_orders）。
    返回 {contract, achieved, current_tier, next_tier, gap_amount, would_reach_next, extra_rebate_estimate}。
    无未结合同/无数据 → None。extra_amount=本期预计追加采购额（如定稿金额）。"""
    if not supplier_id:
        return None
    with get_db() as conn:
        try:
            row = conn.execute(
                "SELECT rc.*, c.name AS supplier_name FROM rebate_contracts rc "
                "LEFT JOIN contacts c ON rc.contact_id=c.id "
                "WHERE rc.settled=0 AND rc.contact_id=? ORDER BY rc.id DESC LIMIT 1",
                (int(supplier_id),),
            ).fetchone()
        except Exception:
            return None
        if not row:
            return None
        rc = dict(row)
        y = str(rc.get("year") or datetime.now().year)
        # 当年采购额（按年过滤；无 order_date 列则全量兜底）
        achieved = 0.0
        try:
            _cols = [r[1] for r in conn.execute("PRAGMA table_info(purchase_orders)").fetchall()]
            if "order_date" in _cols:
                q = ("SELECT COALESCE(SUM(total_amount),0) FROM purchase_orders "
                     "WHERE (supplier_id=? OR contact_id=?) AND order_date LIKE ?")
                achieved = float(conn.execute(q, (int(supplier_id), int(supplier_id), y + "%")).fetchone()[0] or 0)
            else:
                q = "SELECT COALESCE(SUM(total_amount),0) FROM purchase_orders WHERE (supplier_id=? OR contact_id=?)"
                achieved = float(conn.execute(q, (int(supplier_id), int(supplier_id))).fetchone()[0] or 0)
        except Exception:
            achieved = 0.0
        # 解析阶梯
        tiers = []
        tj = rc.get("tiers_json")
        if tj:
            try:
                tiers = json.loads(tj) if isinstance(tj, str) else (tj or [])
            except Exception:
                tiers = []
        if not tiers:
            tiers = [{"min_amount": 0, "max_amount": rc.get("target_amount") or 0, "pct": rc.get("rebate_pct") or 0},
                     {"min_amount": rc.get("target_amount") or 0, "max_amount": 0, "pct": (rc.get("rebate_pct") or 0) * 1.5}]
        tiers = sorted([t for t in tiers if isinstance(t, dict)], key=lambda t: float(t.get("min_amount") or 0))
        def pct_of(amount):
            p = 0.0
            for t in tiers:
                if amount >= float(t.get("min_amount") or 0):
                    p = float(t.get("pct") or 0)
            return p
        cur_pct = pct_of(achieved)
        next_tier = None
        for t in tiers:
            if float(t.get("min_amount") or 0) > achieved:
                next_tier = t
                break
        base = {
            "contract": {"id": rc.get("id"), "supplier_name": rc.get("supplier_name") or f"供应商#{rc.get('contact_id')}",
                         "year": y, "target_amount": rc.get("target_amount") or 0},
            "achieved": round(achieved, 2),
            "current_pct": cur_pct,
            "current_tier_min": max([float(t.get("min_amount") or 0) for t in tiers if achieved >= float(t.get("min_amount") or 0)] or [0]),
        }
        # 供应商链接校验：合同 contact_id 是否有效、是否有采购记录（防绑定错误导致谎报）
        base["linkage_ok"] = True
        base["linkage_warning"] = ""
        try:
            cname = conn.execute("SELECT name FROM contacts WHERE id=?", (int(supplier_id),)).fetchone()
            if not cname:
                base["linkage_ok"] = False
                base["linkage_warning"] = "返利合同绑定的联系人不存在，请先核对/修正返利合同绑定"
            elif achieved <= 0:
                base["linkage_warning"] = "该返利合同绑定的供应商查不到当年采购记录，请核对绑定（可能绑错了供应商）"
        except Exception:
            pass
        if next_tier is None:
            base.update({"next_pct": None, "gap_amount": 0, "would_reach_next": False,
                         "extra_rebate_estimate": 0, "at_max_tier": True})
            return base
        gap = max(0.0, float(next_tier.get("min_amount") or 0) - achieved)
        next_pct = float(next_tier.get("pct") or 0)
        extra = max(0.0, float(extra_amount or 0))
        would = extra >= gap
        est = 0.0
        if would:
            total = achieved + extra
            est = max(0.0, total * (next_pct - cur_pct) / 100.0)
        base.update({"next_pct": next_pct, "next_tier_min": float(next_tier.get("min_amount") or 0),
                     "gap_amount": round(gap, 2), "would_reach_next": would,
                     "extra_rebate_estimate": round(est, 2), "at_max_tier": False})
        return base


def rebate_balances_list():
    """未结返利合同供应商清单 + 当年采购额/达成（返利冲刺面板 /rebate-gap balances 用）。

    返回 [{supplier_id, supplier_name, target_amount, bought_amount, achievement, gap}]，
    无未结合同 → []（前端展示空态而非静默无数据）。缺表降级返回 []。"""
    with get_db() as conn:
        try:
            rows = conn.execute(
                "SELECT rc.contact_id AS supplier_id, COALESCE(c.name,'') AS supplier_name, "
                "rc.target_amount, rc.rebate_pct, rc.year "
                "FROM rebate_contracts rc LEFT JOIN contacts c ON rc.contact_id=c.id "
                "WHERE rc.settled=0 OR rc.settled IS NULL "
                "ORDER BY rc.id DESC"
            ).fetchall()
        except Exception:
            return []
        out = []
        for r in rows:
            sid = int(r["supplier_id"] or 0)
            if sid <= 0:
                continue
            target = float(r["target_amount"] or 0)
            achieved = 0.0
            try:
                _cols = [x[1] for x in conn.execute("PRAGMA table_info(purchase_orders)").fetchall()]
                y = str(r["year"] or datetime.now().year)
                if "order_date" in _cols:
                    achieved = float(conn.execute(
                        "SELECT COALESCE(SUM(total_amount),0) FROM purchase_orders "
                        "WHERE (supplier_id=? OR contact_id=?) AND order_date LIKE ?",
                        (sid, sid, y + "%")).fetchone()[0] or 0)
                else:
                    achieved = float(conn.execute(
                        "SELECT COALESCE(SUM(total_amount),0) FROM purchase_orders WHERE (supplier_id=? OR contact_id=?)",
                        (sid, sid)).fetchone()[0] or 0)
            except Exception:
                achieved = 0.0
            out.append({
                "supplier_id": sid,
                "supplier_name": r["supplier_name"] or f"供应商#{sid}",
                "target_amount": round(target, 2),
                "bought_amount": round(achieved, 2),
                "achievement": (round(achieved / target, 3) if target else None),
                "gap": round(max(0.0, target - achieved), 2),
            })
        return out


# ============================================================ v167 (2026-09-15)
# 删除 `hr_employees.user_id`（v166 加的「员工 → 登录账号」列）。
#
# 为什么删：它**从未有过写入方** —— 账号在主库 `users`、员工在租户库，唯一开账号入口
# `staff_account_create()` 只写主库；而 `salary_send` 读它来做「定向可见」，于是那一支
# 永远走不到（工资条实际一直以空收件人落库 = 全租户可见）。它同时与主库
# `users.employee_id` 互为逆关系 —— 「同一关系两份拷贝」的典型，留着必然漂移。
# 删完后的权威：主库 `users.employee_id`；解析统一走本文件 5930 行附近的
# `_emp_link_expr()` / `resolve_employee_id()` / `employee_account_map()`。
#
# ⚠️ 为什么必须**显式**循环租户库：`_ensure_tenant_module_tables()` 的列对账**只补不删**
#    （主库 schema 是权威源，缺列就补），所以主库删掉后租户库会永久残留一个死列 ——
#    而一个名叫 `user_id` 的死列，下一个读到它的人就会重犯同一个错。
# ⚠️ `ALTER TABLE ... DROP COLUMN` 需 SQLite ≥ 3.35（生产实测 3.37.2）。老环境跳过并告警，
#    功能不受影响（本来就无人读它）。
# 幂等：先 `PRAGMA table_info` 判定列存在才删 —— 新库（建表 DDL 已去掉该列）走不到，
#    不会刷出 FAILED 迁移记录。
_v167_log = logging.getLogger("hergent")
if DB_ENGINE == "sqlite":
    try:
        with get_db() as _db167:
            _have167 = {_x[1] for _x in _db167.execute("PRAGMA table_info(hr_employees)").fetchall()}
            if "user_id" in _have167:
                _db167.execute("ALTER TABLE hr_employees DROP COLUMN user_id")
                _db167.commit()
                _v167_log.info("[v167] master hr_employees.user_id dropped")
    except Exception as _e167:
        _v167_log.warning(f"[v167] master drop failed: {_e167}")
    try:
        import sqlite3 as _s167
        # v206: 走唯一权威枚举（结构校验）。
        for _tp167 in iter_tenant_db_paths():
            try:
                _c167 = _s167.connect(_tp167)
                try:
                    _hv167 = {_x[1] for _x in _c167.execute("PRAGMA table_info(hr_employees)").fetchall()}
                    if "user_id" in _hv167:
                        _c167.execute("ALTER TABLE hr_employees DROP COLUMN user_id")
                        _c167.commit()
                        _v167_log.info(f"[v167] {os.path.basename(_tp167)} hr_employees.user_id dropped")
                finally:
                    _c167.close()
            except Exception as _te167:
                _v167_log.warning(f"[v167] {_tp167} drop failed: {_te167}")
    except Exception:
        pass


# ════════════════════════════════════════════════════════════════════════════
# v449（2026-10-11）：退货主单「独立化」所需的 7 列
# ════════════════════════════════════════════════════════════════════════════
# 🔴 **为什么这一段在文件最末尾**（而不是跟 `v131d_return_orders_quality_status`
#    放一起）：那两段建表**都晚于**它 ——
#      · `purchase_returns` 由上面的 `_safe_migrate_script('v131d_quotations_purchase_returns', …)` 建；
#      · `return_orders` 由**惰性**的 `_init_rma_tables()` 建（不随 `init_db()` 走）。
#    放在前面执行 ⇒ 首次启动必然 `no such table` ⇒ 登记 failed ⇒ **要等下一次重启
#    才补上列**。窗口期内用户建的退货单会**静默存不下退货仓库**（本项目最忌讳的失效
#    形态：界面说保存成功、库里没有）。放这里 + 先 `_init_rma_tables()` 确保建表 ⇒
#    **当次启动即生效**，没有窗口。
#
# 业务背景（老板口径原文）：「退货单不需要选原采购单/销售单，**退货仓库要可以指定**」。
#   旧实现里退货单的客户 / 仓库全部**从原单现推**（`return_order_create` 读
#   `so['customer_id']` / `so['warehouse_id']`；`purchase_return_create` 读
#   `po['supplier_id']` / `po['warehouse_id']`）⇒ 主单自己**不记**仓库，
#   一旦允许「不挂原单」，退货仓库就无处可存。
#   🔴 为什么是**加列**而不是新表：`return_orders` / `purchase_returns` 已经是
#      「退货单」的唯一存储位置（退货列表 / RMA / 报表 / 详情都查它们）。
#      再开一张表会让「退货单」有两个家 —— 列表、RMA、报表必须各查两处，
#      而这类"必须成对修改"的地方**必然漏一处**（本项目已反复验证）。
#   ⚠️ 七条**各自独立具名**：`_safe_migrate` 把「列已存在」视为目标达成（登记 ok），
#      重复执行安全；拆七条而不是一条 `_safe_migrate_script`，是为了某一条失败时
#      不连累其余六条（与 `v131d_return_orders_quality_status` 拆出来的理由逐字同源）。
#   ⚠️ 调用方（`db.queries.sales.return_order_create` / `purchase_return_create`）
#      一律「**列存在且有值才写**」⇒ 万一某条迁移没成，也只是那一个字段不落库，
#      **不会**把建退货单打成 500。
try:
    _init_rma_tables()          # 确保 return_orders / return_order_items 存在
except Exception as _e449:
    print(f"[Migration] v449 前置建表 RMA 失败: {_e449}", file=sys.stderr, flush=True)

_safe_migrate('v449_return_orders_warehouse_id',
              "ALTER TABLE return_orders ADD COLUMN warehouse_id INTEGER DEFAULT 0")
_safe_migrate('v449_return_orders_order_type',
              "ALTER TABLE return_orders ADD COLUMN order_type TEXT DEFAULT ''")
_safe_migrate('v449_return_orders_driver_id',
              "ALTER TABLE return_orders ADD COLUMN driver_id TEXT DEFAULT ''")
_safe_migrate('v449_return_orders_note',
              "ALTER TABLE return_orders ADD COLUMN note TEXT DEFAULT ''")
_safe_migrate('v449_purchase_returns_warehouse_id',
              "ALTER TABLE purchase_returns ADD COLUMN warehouse_id INTEGER DEFAULT 0")
_safe_migrate('v449_purchase_returns_order_date',
              "ALTER TABLE purchase_returns ADD COLUMN order_date TEXT DEFAULT ''")
_safe_migrate('v449_purchase_returns_note',
              "ALTER TABLE purchase_returns ADD COLUMN note TEXT DEFAULT ''")
# v451（2026-10-12，L3）：采购退货单补齐舟谱创建页的三件套 —— **部门** / **审核留痕** /
#   **明细三档单位**，共 6 列（主单 3 + 明细 3）。租户库那一路同步登记在
#   `_ensure_tenant_module_tables` 的列清单里（成对，理由同 v449）。
#   · `department_id` —— 舟谱退货单头有 `*部门`（截图实见）；部门主数据 `departments`
#     早已存在（v4），前端下拉的数据源 `psi_refs(kind='departments')` 也已存在 ⇒
#     这里只缺**落库列**。`0 = 不指定`（与 `purchase_orders.department_id` 同取值域）。
#   · `auditor_id` / `audit_time` —— 「保存并审核」的**留痕两列**，取值域/命名照抄
#     `purchase_orders`（不新造词）。建草稿时两列留空，**过账时**才写。
#   · 明细 `unit` / `base_ratio` —— 与 `purchase_order_items` v409 那两列**同名同义**：
#     `unit` = 用户当时选的那一档单位名、`base_ratio` = 该档 → 小单位的比。
#     🔴 **刻意不抄 `purchase_order_items.base_qty`**：`purchase_return_items.quantity`
#        的既有契约就是**小单位数量**（`purchases.py:101` 明文；下游 `SUM(pri.quantity)`
#        直接当"已退量"用，见 `purchase_order_return_preview`）。若把 `quantity` 改成
#        "所选档位的数量"，**已退量会静默缩水 ratio 倍**（退 5 箱记成退 5 袋），
#        可退量被高估、还能再退一次 —— 真金白银级的错账。故：`quantity` 继续存**折小单位**，
#        `unit`/`base_ratio` 只作**留痕**（反推当时档位数量 = `quantity / base_ratio`）。
#        既有调用方不传 `unit` ⇒ `base_ratio=0` ⇒ 读写与改动前**逐字一致**。
_safe_migrate('v451_purchase_returns_department_id',
              "ALTER TABLE purchase_returns ADD COLUMN department_id INTEGER DEFAULT 0")
_safe_migrate('v451_purchase_returns_auditor_id',
              "ALTER TABLE purchase_returns ADD COLUMN auditor_id TEXT DEFAULT ''")
_safe_migrate('v451_purchase_returns_audit_time',
              "ALTER TABLE purchase_returns ADD COLUMN audit_time TEXT DEFAULT ''")
_safe_migrate('v451_purchase_return_items_unit',
              "ALTER TABLE purchase_return_items ADD COLUMN unit TEXT DEFAULT ''")
_safe_migrate('v451_purchase_return_items_base_ratio',
              "ALTER TABLE purchase_return_items ADD COLUMN base_ratio REAL DEFAULT 0")
# v451：`purchase_return_items` 补 `product_id` —— 「草稿 → 审核」的**前提列**。
#   🔴 为什么必须有：退款单的效果（扣库存 / 冲应付）现在有**两条路径**（建单即过账、
#      审核草稿），而它们共用同一个过账实现 `purchase_return_post(rid)`；后者只能从
#      明细表反读商品。该表原本**只有 `product_name` 没有 `product_id`** ⇒ 过账只能拿
#      名字回查 `products`，商品一改名就**静默跳过扣库存**（正是 `purchase_return_create`
#      里那条「已知残留风险」）。有 `product_id` 之后过账拿 id 直扣，不依赖名字。
#   ⚠️ 只增列、不改任何既有读写：老行 `product_id=0` ⇒ 过账时按老路（名字）兜底，
#      行为与改动前逐字一致。「已退量」的关联键仍是 `product_name`（不动，见 v451 说明）。
_safe_migrate('v451_purchase_return_items_product_id',
              "ALTER TABLE purchase_return_items ADD COLUMN product_id INTEGER DEFAULT 0")
# ── v500（2026-10-15）：退货单「单据编号」两列 ──────────────────────────────────
#   背景一句话：v500 把五个退单入口（采购退货 / 自提退单 / 车销退单 + 两个订单入口的
#   退货页签）从「查 `purchase_orders`/`sale_orders` 的 `status='returned'`」改成查
#   **真退货表** —— 那个 `returned` 全系统无人写（生产实测：两张真表各 0 行可见、
#   采购单 83 行里没有一行 returned），所以那五个入口一直是**恒空**。改查真表之后，
#   列表第一列需要一个业务编号，而 `purchase_returns` / `return_orders` **都没有**。
#
#   🔴 为什么是「加列」而不是「前端拿 id 拼一个号」：拼出来的号只在那一个界面存在，
#      详情页 / 导出 / 对账 / 老板口头报单号时会各拼各的 —— 同一个事实四份表示，
#      早晚打架。编号是**单据的属性**，必须落库。
#   🔴 空串缺省 + 建单时才生成：`_gen_no("PR"/"SR")` 在 INSERT 时算，**存量行留空**，
#      列表对空值回落到 `#<id>`（可降级、不伪造历史号 —— 老退货单当时确实没有编号）。
#   🔴 两条**各自独立具名**（同 v449 七条的理由）：一条失败不连累另一条。
_safe_migrate('v500_purchase_returns_order_no',
              "ALTER TABLE purchase_returns ADD COLUMN order_no TEXT DEFAULT ''")
_safe_migrate('v500_return_orders_order_no',
              "ALTER TABLE return_orders ADD COLUMN order_no TEXT DEFAULT ''")


# === v711: 凭证模板 DB 层 ===
#
# 背景：`routers/voucher_templates.py`（v89 Phase 4）与 `voucher_engine.py` 从上线起
# 就在调 `db.voucher_template_list/create/update/delete/apply`，而这五个函数在 erp_db
# **从来不存在** ⇒ 列表/新建/编辑/删除/播种五个接口全部 500（create/update 还是 100%
# NameError：读了 `body` 却去用未定义的 `d`）。此处补齐。
#
# 🔴 为什么是「请求时惰性建表」而不是在 `init_db()` 加迁移：租户库是从主库复制出来的，
#    init_db 只在主库跑，v706 已确认这种「代码里有表、库里没有」的形状会静默 500。
# 🔴 为什么模板只在 flag `voucher_templates` 打开时才参与自动记账：模板是**用户手填**
#    的会计分录，写错就直接进 `journal_entries`。默认关 = 本次改动对过账结果零影响。

_VT_DDL = (
    """CREATE TABLE IF NOT EXISTS voucher_templates(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        name TEXT NOT NULL,
        event_type TEXT NOT NULL,
        description TEXT DEFAULT '',
        entries_json TEXT NOT NULL DEFAULT '[]',
        conditions_json TEXT DEFAULT '{}',
        is_active INTEGER DEFAULT 1,
        priority INTEGER DEFAULT 0,
        created_at TEXT DEFAULT (datetime('now','localtime'))
    )""",
    "CREATE INDEX IF NOT EXISTS idx_vt_event ON voucher_templates(event_type, is_active)",
    """CREATE TABLE IF NOT EXISTS voucher_template_applies(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        template_id INTEGER NOT NULL,
        event_type TEXT DEFAULT '',
        ref_id INTEGER DEFAULT 0,
        applied_at TEXT DEFAULT (datetime('now','localtime'))
    )""",
    "CREATE INDEX IF NOT EXISTS idx_vta_tpl ON voucher_template_applies(template_id)",
)

_VT_FF_DDL = """CREATE TABLE IF NOT EXISTS feature_flags(
    name TEXT PRIMARY KEY,
    enabled INTEGER DEFAULT 0,
    rollout_pct INTEGER DEFAULT 100,
    user_list TEXT DEFAULT '',
    tenant_list TEXT DEFAULT '',
    created_at TEXT DEFAULT (datetime('now','localtime')),
    updated_at TEXT DEFAULT (datetime('now','localtime'))
)"""

# 存量库里 `feature_flags` 是**早期 schema**（主库权威 DDL 实测只有 6 列，没有
# `updated_at`），而 `feature_flag_list()` / `feature_flag_set()` 的 SELECT / INSERT
# 都引用了 `updated_at` ⇒ 在任何库上这两个函数都必抛 OperationalError
# ⇒ **整个 flag 机制从来没工作过**（不是"关着"，是从没被读到过）。逐列补齐。
_VT_FF_COLS = (
    ("enabled", "INTEGER DEFAULT 0"),
    ("rollout_pct", "INTEGER DEFAULT 100"),
    ("user_list", "TEXT DEFAULT ''"),
    ("tenant_list", "TEXT DEFAULT ''"),
    ("created_at", "TEXT"),
    ("updated_at", "TEXT"),
)


def _ensure_voucher_template_tables(db=None):
    """惰性建表。传 db 时复用调用方连接（自动记账在事务里，不能另开连接写）。"""
    if db is not None:
        for ddl in _VT_DDL:
            db.execute(ddl)
        return
    with get_db_tx() as conn:
        for ddl in _VT_DDL:
            conn.execute(ddl)


def _ensure_feature_flags_table():
    """feature_flags 表惰性建表 + 逐列补齐。

    存量库里这张表是**早期 schema**（缺 `updated_at`，详见 `_VT_FF_COLS` 注释），
    `CREATE TABLE IF NOT EXISTS` 对已存在的表**什么都不做** ⇒ 只建表不补列的话，
    `feature_flag_set()` 照样崩（B 组实测：`table feature_flags has no column named
    updated_at`）。所以按 `PRAGMA table_info` 缺哪列补哪列。
    """
    with get_db_tx() as conn:
        conn.execute(_VT_FF_DDL)
        try:
            have = {r[1] for r in conn.execute("PRAGMA table_info(feature_flags)")}
            for col, ddl in _VT_FF_COLS:
                if col not in have:
                    conn.execute("ALTER TABLE feature_flags ADD COLUMN %s %s" % (col, ddl))
        except Exception as e:
            logging.getLogger("hergent").warning("feature_flags ensure columns failed: %s", e)


def voucher_template_list(event_type="", active_only=False, db_conn=None):
    """凭证模板列表。`db_conn` 非空时复用调用方事务（自动记账路径）。"""
    sql = "SELECT * FROM voucher_templates"
    conds, args = [], []
    if event_type:
        conds.append("event_type=?")
        args.append(event_type)
    if active_only:
        conds.append("is_active=1")
    if conds:
        sql += " WHERE " + " AND ".join(conds)
    sql += " ORDER BY priority DESC, id ASC"

    def _q(conn):
        return [dict(r) for r in conn.execute(sql, args).fetchall()]

    if db_conn is not None:
        try:
            return _q(db_conn)
        except Exception:
            try:
                _ensure_voucher_template_tables(db_conn)
                return _q(db_conn)
            except Exception as e:
                logging.getLogger("hergent").warning("voucher_template_list(in-tx) failed: %s", e)
                return []
    try:
        with get_db() as db:
            return _q(db)
    except Exception:
        pass
    try:
        _ensure_voucher_template_tables()
        with get_db() as db:
            return _q(db)
    except Exception as e:
        logging.getLogger("hergent").warning("voucher_template_list failed: %s", e)
        return []


def voucher_template_create(name, event_type, description="", entries_json="[]",
                            conditions_json="{}", is_active=1, priority=0):
    """新建凭证模板，返回新 id。名称/事件类型为空抛 ValueError（路由层转 400）。"""
    name = (name or "").strip() if isinstance(name, str) else name
    event_type = (event_type or "").strip() if isinstance(event_type, str) else event_type
    if not name:
        raise ValueError("模板名称不能为空")
    if not event_type:
        raise ValueError("事件类型不能为空")
    _ensure_voucher_template_tables()
    with get_db_tx() as db:
        cur = db.execute(
            "INSERT INTO voucher_templates "
            "(name,event_type,description,entries_json,conditions_json,is_active,priority) "
            "VALUES (?,?,?,?,?,?,?)",
            (name, event_type, description or "", entries_json or "[]",
             conditions_json or "{}", 1 if int(is_active or 0) else 0, int(priority or 0)),
        )
        return cur.lastrowid


def voucher_template_update(tid, name=None, event_type=None, description=None,
                            entries_json=None, conditions_json=None,
                            is_active=None, priority=None):
    """更新凭证模板。传 None 的字段**保持原值**（部分更新不会把别的字段清掉）。"""
    _ensure_voucher_template_tables()
    sets, args = [], []
    for col, val in (("name", name), ("event_type", event_type), ("description", description),
                     ("entries_json", entries_json), ("conditions_json", conditions_json)):
        if val is not None:
            sets.append(col + "=?")
            args.append(val)
    if is_active is not None:
        sets.append("is_active=?")
        args.append(1 if int(is_active or 0) else 0)
    if priority is not None:
        sets.append("priority=?")
        args.append(int(priority or 0))
    if not sets:
        return {"success": True, "changed": False}
    args.append(tid)
    with get_db_tx() as db:
        if not db.execute("SELECT id FROM voucher_templates WHERE id=?", (tid,)).fetchone():
            raise ValueError("模板不存在: %s" % tid)
        db.execute("UPDATE voucher_templates SET " + ",".join(sets) + " WHERE id=?", args)
    return {"success": True, "changed": True}


def voucher_template_delete(tid):
    """停用凭证模板（软删除：is_active=0）。

    用软删不是硬删：`voucher_template_applies` 里存着历史引用，硬删会让审计记录指向
    不存在的模板；而模板本身是配置，停用即可阻断后续匹配。
    """
    _ensure_voucher_template_tables()
    with get_db_tx() as db:
        if not db.execute("SELECT id FROM voucher_templates WHERE id=?", (tid,)).fetchone():
            raise ValueError("模板不存在: %s" % tid)
        db.execute("UPDATE voucher_templates SET is_active=0 WHERE id=?", (tid,))
    return {"success": True}


def voucher_template_apply(tpl_id, event_type="", ref_id=0, db_conn=None):
    """记录一次模板命中（审计）。`db_conn` 非空时并入调用方事务。"""
    if db_conn is not None:
        try:
            _ensure_voucher_template_tables(db_conn)
            db_conn.execute(
                "INSERT INTO voucher_template_applies (template_id,event_type,ref_id) "
                "VALUES (?,?,?)", (tpl_id, event_type or "", int(ref_id or 0)),
            )
        except Exception as e:
            logging.getLogger("hergent").warning("voucher_template_apply(in-tx) failed: %s", e)
        return
    try:
        _ensure_voucher_template_tables()
        with get_db_tx() as db:
            db.execute(
                "INSERT INTO voucher_template_applies (template_id,event_type,ref_id) "
                "VALUES (?,?,?)", (tpl_id, event_type or "", int(ref_id or 0)),
            )
    except Exception as e:
        logging.getLogger("hergent").warning("voucher_template_apply failed: %s", e)


def _voucher_entries_for(event_type, context, db_conn=None):
    """按凭证模板生成分录；**任一环节不满足就返回 None**（调用方回落硬编码）。

    三道闸：① flag `voucher_templates` 未开 / 表缺失 / 抛异常 → None；
            ② 无匹配模板 → None；
            ③ 模板算出的分录借贷不平衡或全零 → None + warning。
    第 ③ 条是硬要求：模板由用户手填，填错单边分录会直接写进 `journal_entries`。
    """
    try:
        from voucher_engine import is_voucher_templates_enabled, apply_template
        if not is_voucher_templates_enabled():
            return None
    except Exception:
        return None  # 读不到开关 = 关（fail-safe）
    try:
        entries = apply_template(event_type, context, db_conn=db_conn)
    except Exception as e:
        logging.getLogger("hergent").warning(
            "voucher template %s failed, fallback to hardcoded: %s", event_type, e)
        return None
    if not entries or not isinstance(entries, list):
        return None
    try:
        from db.precision import money_balanced
        norm = []
        dr = cr = 0.0
        for e in entries:
            if not isinstance(e, dict) or not e.get("code"):
                return None
            d = round(float(e.get("debit") or 0), 2)
            c = round(float(e.get("credit") or 0), 2)
            dr += d
            cr += c
            norm.append({"code": str(e.get("code")), "name": e.get("name") or "",
                         "debit": d, "credit": c, "summary": e.get("summary") or ""})
        if dr <= 0 and cr <= 0:
            return None
        if not money_balanced(dr, cr):
            logging.getLogger("hergent").warning(
                "voucher template %s unbalanced (dr=%s cr=%s), fallback to hardcoded",
                event_type, dr, cr)
            return None
    except Exception as e:
        logging.getLogger("hergent").warning("voucher template %s normalize failed: %s",
                                             event_type, e)
        return None
    return norm
